#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <string.h>

// Thread-safe function to log messages to a file descriptor
void safe_log(int fd, const char *msg) {
    if (fd >= 0) {
        dprintf(fd, "%s\n", msg);
    }
}

char* appendSlashIfWithinLimit(const char *inputStr, size_t sizeLimit, int fd) {
    // Check inputs for null and invalid values
    if (!inputStr || sizeLimit < 0) {
        safe_log(fd, "Error: Invalid input. Null or negative size limit.");
        return NULL;
    }

    // If the string is longer than the specified limit, return NULL without appending a slash
    if (strlen(inputStr) > sizeLimit) {
        safe_log(fd, "Warning: String exceeds size limit.");
        return NULL;
    }

    // Allocate space for the new string and copy inputStr into it, appending a forward slash at the end if necessary
    char *newStr = malloc(strlen(inputStr) + (sizeLimit > strlen(inputStr) ? 1 : 0));
    if (!newStr) {
        safe_log(fd, "Error: Failed to allocate memory.");
        return NULL;
    }

    strcpy(newStr, inputStr);
    if (strlen(newStr) < sizeLimit) {
        newStr[strlen(inputStr)] = '/';
    }

    // Return the modified string or NULL in case of memory allocation failure
    return newStr;
}
