#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <iconv.h>
#include <regex.h>

// Thread-safe variable to store error messages
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

int validate_email(const char *inputEmail, size_t sizeLimit) {
    // Basic validation rules (e.g., '@' symbol and domain part) using regex
    regex_t regex;
    int reti;
    regmatch_t match;

    reti = regcomp(&regex, "^[\\w-\\.]+@([\\w|\\d|-]+)\\.(com|org|net|edu|gov|mil|io|biz)$", REG_EXTENDED);
    if (reti) {
        // Handle error in regex compilation
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Failed to compile regular expression.\n");
        pthread_mutex_unlock(&log_mutex);
        return 0;
    }

    if (strlen(inputEmail) > sizeLimit || !regexec(&regex, inputEmail, 0, NULL, 0)) {
        // Handle invalid email or exceeded size limit
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Invalid email address or exceeded size limit.\n");
        pthread_mutex_unlock(&log_mutex);
        return 0;
    }

    regfree(&regex);
    return 1;
}

char* parseAndValidateEmail(const char *inputEmail, size_t sizeLimit, FILE *fd) {
    if (!inputEmail || sizeLimit < 0) {
        // Handle invalid inputs
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Invalid input. Input email or size limit is NULL or less than 0.\n");
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }

    if (validate_email(inputEmail, sizeLimit)) {
        // Allocate memory for the validated email string and copy the input string
        char *validatedEmail = malloc(strlen(inputEmail) + 1);
        strcpy(validatedEmail, inputEmail);
        return validatedEmail;
    } else {
        return NULL;
    }
}
