using System;
using System.IO;
using System.Xml;
using System.Net.Http;
using System.Linq;
using System.Threading.Tasks;
using System.Diagnostics;
using Newtonsoft.Json.Linq;

public class ConfigLoader
{
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly XmlSchemaSet _schema;
    private readonly string _loggingSystem;

    public ConfigLoader(XsdFile xsd, string loggingSystem)
    {
        _schema = new XmlSchemaSet();
        _schema.Add(xsd);
        _loggingSystem = loggingSystem;
    }

    public async Task<string> GetConfigValueAsync(string url, string elementName)
    {
        try
        {
            var attempts = 3;
            while (attempts > 0)
            {
                try
                {
                    var response = await _httpClient.GetAsync(url);
                    response.EnsureSuccessStatusCode();

                    using var stream = await response.Content.ReadAsStreamAsync();
                    var xmlDoc = new XmlDocument();
                    xmlDoc.Load(stream);

                    if (ValidateXmlAgainstSchema(xmlDoc))
                    {
                        return GetElementValueFromXml(elementName, xmlDoc);
                    }
                }
                catch (Exception ex)
                {
                    LogError(_loggingSystem, ex.Message);
                }
                attempts--;
            }

            throw new Exception("Failed to retrieve and validate XML configuration after maximum retries.");
        }
        catch (Exception ex)
        {
            LogError(_loggingSystem, ex.Message);
            throw;
        }
    }

    private bool ValidateXmlAgainstSchema(XmlDocument xmlDoc)
    {
        var validator = new XmlValidator(_schema);
        return validator.Validate(xmlDoc);
    }

    private string GetElementValueFromXml(string elementName, XmlDocument xmlDoc)
    {
        if (xmlDoc == null || string.IsNullOrEmpty(elementName))
            return null;

        var node = xmlDoc.DocumentElement.SelectSingleNode(elementName);
        return node?.InnerText ?? string.Empty;
    }

    private void LogError(string loggingSystem, string message)
    {
        // Implement the actual logging using your preferred logging library and logging system.
        Debug.WriteLine($"{loggingSystem}: {message}");
    }
}
