<?php

class UserAccountManager {
    private $db;
    private $emailValidator;
    private $passwordStrengthChecker;
    private $cache;

    public function __construct(PDO $db, EmailValidator $emailValidator, PasswordStrengthChecker $passwordStrengthChecker, Cache $cache) {
        $this->db = $db;
        $this->emailValidator = $emailValidator;
        $this->passwordStrengthChecker = $passwordStrengthChecker;
        $this->cache = $cache;
    }

    public function manageUserAccount($request) {
        try {
            $data = json_decode($request);
            if (!$data || !isset($data->name, $data->email, $data->password)) {
                throw new Exception('Invalid request format.');
            }

            $id = isset($data->id) ? (int)$data->id : null;
            $subAction = isset($data->sub_action) ? strtolower($data->sub_action) : null;

            if ($id && !$this->validateId($id)) {
                throw new Exception('Invalid user ID.');
            }

            // Fetch and sanitize input data
            $name = filter_var($data->name, FILTER_SANITIZE_STRING);
            $email = filter_var($data->email, FILTER_SANITIZE_EMAIL);
            $password = filter_var($data->password, FILTER_SANITIZE_STRING);

            // Validate email and password
            if (!$this->emailValidator->validate($email)) {
                throw new Exception('Invalid email format.');
            }

            if (!$this->passwordStrengthChecker->check($password)) {
                throw new Exception('Weak password. Please use a stronger one.');
            }

            // Perform operation based on sub_action
            switch ($subAction) {
                case 'create':
                    if ($this->cache->hasUserData($email)) {
                        $userData = $this->cache->getUserData($email);
                        if (!empty($userData)) {
                            throw new Exception('Email already in use.');
                        }
                    } else {
                        // Fetch from the database and cache user data for future requests
                        $this->cache->setUserData($email, $this->getUserByEmail($email));
                    }

                    $userId = $this->insertUser($name, $email, $password);
                    return json_encode(['status' => 'success', 'id' => $userId]);

                case 'update':
                    if ($this->cache->hasUserData($email)) {
                        $userData = $this->cache->getUserData($email);
                        if ($userData['id'] !== $id) {
                            throw new Exception('Requested user ID does not match the email provided.');
                        }
                    } else {
                        // Fetch from the database and cache user data for future requests
                        $this->cache->setUserData($email, $this->getUserByEmail($email));
                    }

                    if ($this->updateUser($id, $name, $password)) {
                        return json_encode(['status' => 'success']);
                    } else {
                        throw new Exception('Failed to update user account.');
                    }

                case 'delete':
                    if ($this->cache->hasUserData($email)) {
                        $userData = $this->cache->getUserData($email);
                        if ($userData['id'] !== $id) {
                            throw new Exception('Requested user ID does not match the email provided.');
                        }
                    } else {
                        // Fetch from the database and cache user data for future requests
                        $this->cache->setUserData($email, $this->getUserByEmail($email));
                    }

                    if ($this->deleteUser($id)) {
                        return json_encode(['status' => 'success']);
                    } else {
                        throw new Exception('Failed to delete user account.');
                    }

                default:
                    throw new Exception('Invalid sub_action provided.');
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
            http_response_code(400); // Bad Request
            return json_encode(['status' => 'error', 'message' => $e->getMessage()]);
        }
    }

    private function validateId($id) {
        return is_int($id) && $id > 0;
    }

    // Database operations go here...
}
