namespace TripleDESDecryptionService
{
    public class DecryptionService
    {
        private readonly Dictionary<(string userType, string messageType), (TripleDESCryptoServiceProvider key, byte[] iv)> _keyVault;
        private readonly Cache<string, string> _cache;
        private readonly RestClient _externalService;
        private const int DefaultCacheSize = 100;
        private const CacheItemPriority DefaultCachePriority = CacheItemPriority.Normal;
        private const TimeSpan DefaultCacheExpiration = new TimeSpan(0, 5, 0);

        public DecryptionService()
        {
            _keyVault = new Dictionary<(string userType, string messageType), (TripleDESCryptoServiceProvider key, byte[] iv)>();
            _cache = new Cache<string, string>(DefaultCacheSize, DefaultCachePriority, DefaultCacheExpiration);
            _externalService = new RestClient("https://your-encryption-service.com"); // Replace with the actual API URL
        }

        public async Task<string> DecryptAsync(string base64EncodedMessage, string userType, string messageType)
        {
            if (!Base64Decode(base64EncodedMessage).CheckValidBase64())
                throw new ArgumentException("Invalid Base64 encoding");

            var keyIvPair = GetKeyAndIV(userType, messageType);

            try
            {
                var decryptedData = TripleDESDecrypt(keyIvPair.key, keyIvPair.iv, Base64Decode(base64EncodedMessage).ToByteArray());
                return decryptedData;
            }
            catch (CryptographicException)
            {
                throw new Exception("Decryption failed");
            }

            // Call the external service if the result is not found in cache or cache has expired.
            var cachedResult = _cache.Get(base64EncodedMessage);
            if (cachedResult != null && DateTimeOffset.UtcNow <= cachedResult.Expiration)
                return cachedResult.Value;

            var response = await CallExternalServiceAsync(userType, messageType, base64EncodedMessage);
            _cache.AddOrUpdate(base64EncodedMessage, response.Data, evictionCallback: (key, value) => DateTimeOffset.UtcNow > value.Expiration);
            return response.Data;
        }

        private (TripleDESCryptoServiceProvider key, byte[] iv) GetKeyAndIV(string userType, string messageType)
        {
            if (!_keyVault.TryGetValue((userType, messageType), out var kvPair))
                throw new KeyNotFoundException($"No key/IV found for userType: {userType}, messageType: {messageType}");

            return kvPair;
        }

        private byte[] TripleDESDecrypt(TripleDESCryptoServiceProvider key, byte[] iv, byte[] encryptedData)
        {
            using (var encryptor = key.CreateDecryptor(key.Key, iv))
            {
                using var ms = new MemoryStream(encryptedData);
                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Read))
                {
                    return cs.ToArray();
                }
            }
        }

        private RestResponse CallExternalServiceAsync(string userType, string messageType, string base64EncodedMessage)
        {
            var request = new RestRequest("decrypt", Method.POST);
            request.AddHeader("user-type", userType);
            request.AddHeader("message-type", messageType);
            request.AddBody(base64EncodedMessage);
            return await _externalService.ExecuteAsync(request);
        }

        private static bool CheckValidBase64(string base64) => Convert.TryFromBase64String(base64, out _);

        private static MemoryStream Base64Decode(string base64EncodedData)
        {
            var data = Convert.FromBase64String(base64EncodedData);
            return new MemoryStream(data);
        }
    }
}
