using EventQueue = boost::lockfree::spsc_queue<NetworkEventStructure*>;
using EventCollection = std::vector<NetworkEventStructure>;

class NetworkMonitoringSystem {
private:
    EventCollection events_;
    EventQueue event_queue_;
    std::fstream data_file_;
    boost::asio::io_service io_service_;
    boost::asio::thread_pool thread_pool_;

    template<typename Archive>
    void serialize(Archive & ar, NetworkEventStructure const & event, const unsigned int) {
        ar & event.first & event.second;
    }

public:
    NetworkMonitoringSystem() : data_file_("events.dat", std::ios::out | std::ios::binary) {
        if (!data_file_.is_open()) {
            throw std::runtime_error("Could not open events file");
        }
        boost::asio::serialization::serialize(data_file_, events_);
    }

    void addEvent(const NetworkEventStructure& event) {
        auto eventPtr = new NetworkEventStructure(event);
        event_queue_.push(eventPtr);
        events_.emplace_back(event);
        BOOST_LOG_TRIVIAL(info) << "Added event: " << event.first << ", type: " << event.second;
    }

    void removeEvent(const NetworkEventStructure& event) {
        auto it = std::find_if(events_.begin(), events_.end(),
                               [&event](const NetworkEventStructure& ev) { return ev == event; });
        if (it != events_.end()) {
            events_.erase(it);
            BOOST_LOG_TRIVIAL(info) << "Removed event: " << event.first << ", type: " << event.second;
        }
    }

    const NetworkEventStructure& getEvent(size_t index) {
        if (index >= events_.size()) {
            throw std::out_of_range("Index out of range");
        }
        return events_[index];
    }

    void save() {
        boost::asio::serialization::serialize(data_file_, events_);
        data_file_.close();
        BOOST_LOG_TRIVIAL(info) << "Saved events to disk";
    }

    void load() {
        if (data_file_.is_open()) {
            data_file_.close();
        }
        data_file_.clear();
        data_file_.open("events.dat", std::ios::in | std::ios::binary);
        if (!data_file_.is_open()) {
            throw std::runtime_error("Could not open events file");
        }
        EventCollection newEvents;
        boost::asio::serialization::serialize(data_file_, newEvents);
        events_.swap(newEvents);
        BOOST_LOG_TRIVIAL(info) << "Loaded events from disk";
    }

    // Implement background tasks, interaction with database, and REST API here...
};
