const int MAX_INSERTIONS = 1000;

void logError(const std::string& message) {
    // Implement logging or monitoring here, for example:
    // std::cout << "[" << std::chrono::system_clock::now().time_since_epoch().count() << "] Error: " << message << '\n';
}

void insertIfNotExists(std::forward_list<std::string>::iterator it, const std::string& str) {
    if (it == myList.end()) return; // Base case for recursion

    if (*it == str) {
        ++insertionCount;
        myList.insertafter(it, str);
        return;
    }

    insertIfNotExists(std::next(it), str);
}

void insertAfterFirstOccurrence(const std::string& findStr, const std::string& insertStr, std::optional<int> maxInsertions = std::nullopt) {
    if (maxInsertions && *maxInsertions < 0) throw std::system_error(std::errc::invalid_argument, "Invalid maximum number of insertions.");

    auto startTime = std::chrono::high_resolution_clock::now();

    int currentInsertions = insertionCount;
    for (auto it = myList.begin(); it != myList.end(); ++it) {
        if (*it == findStr) {
            insertIfNotExists(it, insertStr);
            break;
        }
    }

    auto endTime = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(endTime - startTime).count();

    if (currentInsertions >= (maxInsertions ? *maxInsertions : MAX_INSERTIONS)) {
        logError("Element not found within the maximum allowed insertions.");
    } else {
        logError("Element found and inserted successfully.");
    }
}
