// WebSocket class for handling the stream connection
class WebSocketStreamer {
  constructor(url, interval) {
    this.ws = new WebSocket(url);
    this.interval = interval || 1000; // Default to 1 second if no interval provided
    this.data = [];
    this.throttle = false;
  }

  async start() {
    this.ws.on('open', () => console.log('WebSocket connected'));

    this.ws.on('message', (data) => {
      if (!this.throttle && !this.handleError(JSON.parse(data))) {
        this.data.push(data);
        this.throttle = true;
        setTimeout(() => { this.throttle = false; }, this.interval);
      }
    });

    this.ws.on('error', (err) => console.error(`WebSocket error: ${err}`));

    this.ws.on('close', () => {
      console.log('WebSocket disconnected');
      this.saveDataToDatabase();
    });
  }

  // Method to save data to the database periodically (every interval) or when the stream is closed
  async saveDataToDatabase() {
    if (!this.data.length) return;

    const batchSize = 100;
    let batchCount = 0;

    for (let i = 0; i < this.data.length; i += batchSize) {
      const batch = this.data.slice(i, i + batchSize);

      db.run(`INSERT INTO stream_data (data) VALUES ($data)`, { $data: batch.join() }, function(err) {
        if (err) console.error(`Database error: ${err}`);
      });

      batchCount++;
      if (batchCount === Math.ceil(this.data.length / batchSize)) break;
    }

    this.data = []; // Clear the data array after saving it to the database
  }

  handleError(data) {
    // Handle errors and edge cases such as network errors, API rate limits, and unexpected data formats
    // Log appropriate error messages and attempt to recover from these issues when possible
  }
}

// Function to start the stream collection process
async function run() {
  const url = 'wss://example.com/stream'; // Replace with your WebSocket URL
  const streamer = new WebSocketStreamer(url);

  await streamer.start();

  setInterval(() => {
    streamer.saveDataToDatabase();
  }, streamer.interval);
}

run();
