#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <ctype.h>
#include <pthread.h>
#define MAX_PATH 256
#define MAX_NAME 255

// Helper function to count uppercase letters in a string
size_t countUppercase(const char *str) {
    size_t count = 0;
    while (*str != '\0') {
        if (isupper((unsigned char)*str))
            count++;
        str++;
    }
    return count;
}

// Atomically rename a file using pthread_rwlock_t lock
int atomicRename(const char *filename, const char *newname) {
    pthread_rwlock_t lock;
    pthread_rwlock_init(&lock, NULL);
    pthread_rwlock_wrlock(&lock);
    int res = rename(filename, newname);
    pthread_rwlock_unlock(&lock);
    return res;
}

// Function to validate the directory path and create it if necessary
int isValidPath(const char *path) {
    struct stat sb;
    return stat(path, &sb) == 0 && S_ISDIR(sb.st_mode);
}

// Function for renaming a file with constraints
int renameFileWithConstraints(const char *originalFilename, const char *directoryPath) {
    // Validate input parameters and create directory if needed
    size_t originalNameLen = strlen(originalFilename);
    size_t pathLen = strlen(directoryPath);
    if (originalNameLen + pathLen > MAX_PATH || !originalFilename || !directoryPath)
        return -1; // Invalid input
    char newDir[MAX_PATH];
    strcpy(newDir, directoryPath);
    strcat(newDir, "/");
    strncat(newDir, originalFilename, sizeof(newDir) - 1 - pathLen);
    if (!isValidPath(newDir)) {
        // Create the directory if it doesn't exist
        mkdir(newDir, S_IRWXU | S_IRGRP | S_IXGRP | S_IROTH | S_IXOTH);
        if (errno != 0)
            return -2; // Failed to create directory
    }

    char newFilename[MAX_NAME];
    size_t uppercaseCount = countUppercase(originalFilename);
    snprintf(newFilename, sizeof(newFilename), "%s/%s%s%lu", directoryPath, originalFilename, (uppercaseCount > 5) ? "_EXT" : "_EXT0", uppercaseCount);

    // Atomically rename the file using a lock to ensure thread safety
    int res = atomicRename(originalFilename, newFilename);
    if (res != 0)
        return -3; // Failed to rename the file
    else
        return 0; // Successfully renamed the file
}
