    private readonly KeyManagementSystem _keyManagementSystem;
    private readonly AesGcm _aesGcm;

    public DecryptionService(KeyManagementSystem keyManagementSystem)
    {
        _keyManagementSystem = keyManagementSystem;
        _aesGcm = new AesGcm(new Rfc2561Parameters(new Aescryptographer()));
