    public async Task<byte[]> DecryptAsync(string ciphertext, byte[] iv)
    {
        var key = await RetrieveKeyAsync();
        var paddingScheme = DeterminePaddingScheme(ciphertext);
        var decryptedBytes = _aesGcm.Decrypt(ciphertext, iv, key, paddingScheme);
        return decryptedBytes;
    }

    private async Task<SymmetricKeyParameter> RetrieveKeyAsync()
    {
        // Implement secure token-based authentication and SSL/TLS communication with the external key management system
        // ...
        var key = await _keyManagementSystem.RetrieveKey();
        return new AesKeyParameter(key);
    }

    private PaddingScheme DeterminePaddingScheme(string ciphertext)
    {
        if (IsPKCS7(ciphertext))
            return PaddingScheme.Pkcs7;
        if (IsPKCS5(ciphertext))
            return PaddingScheme.Pkcs5;
        return PaddingScheme.NoPadding;
    }

    private bool IsPKCS7(string ciphertext)
    {
        var lastByte = ciphertext[ciphertext.Length - 1];
        return lastByte == (byte)ciphertext.Length % byte.MaxValue;
    }

    private bool IsPKCS5(string ciphertext)
    {
        // Implement PKCS#5 padding detection logic
        // ...
    }

    private class AesGcm
    {
        public byte[] Decrypt(byte[] cipherText, byte[] iv, SymmetricKeyParameter key, PaddingScheme paddingScheme)
        {
            using (var aes = new AesEngine())
            {
                aes.Key = key.Key;
                aes.IV = iv;

                var decryptor = aes.CreateDecryptor();

                var cipherTextArray = Padding.Remove(cipherText, paddingScheme);

                using (var ms = new MemoryStream(cipherTextArray))
                {
                    using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                    {
                        var plaintextBytes = new byte[cs.ReadByte()];
                        cs.Read(plaintextBytes, 0, plaintextBytes.Length);
                        return plaintextBytes;
                    }
                }
            }
        }
    }

    private enum PaddingScheme
    {
        NoPadding,
        Pkcs7,
        Pkcs5
    }
}
```

