#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <sys/mman.h>
#include <err.h>
#include <string.h>
#include <getopt.h>
#include <stdbool.h>
#include <fcntl.h>
#include <errno.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const char *key;
    unsigned int key_len;
    unsigned char iv[EVP_MAX_IV_LENGTH];
    unsigned int iv_len;
} my_cipher_t;

void *my_cipher_init(const char *mode, const char *key, size_t key_size, const unsigned char *iv, size_t iv_size) {
    EVP_CIPHER_CTX *ctx = NULL;
    ENGINE *engine = NULL;
    int ret;

    engine = OpenSSL_get_default_sha256_engine();
    ctx = EVP_CIPHER_CTX_new();

    if (!ctx) {
        err(EXIT_FAILURE, "Failed to allocate EVP context");
    }

    ret = EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(mode), engine, key, iv);
    if (ret <= 0) {
        err(EXIT_FAILURE, "Failed to initialize cipher: %s", ERR_get_error());
    }

    EVP_CIPHER_CTX_set_key_length(ctx, key_size * 8);
    EVP_CIPHER_CTX_set_iv_length(ctx, iv_size);

    return ctx;
}

void my_cipher_free(my_cipher_t *cipher) {
    if (cipher->ctx != NULL) {
        EVP_CIPHER_CTX_free(cipher->ctx);
    }
}

int my_cipher_encrypt(void *out, const void *in, size_t len, my_cipher_t *cipher) {
    int ret;

    ret = EVP_EncryptUpdate(cipher->ctx, out, NULL, in, len);
    if (ret <= 0) {
        err(EXIT_FAILURE, "Failed to encrypt data: %s", ERR_get_error());
    }

    ret = EVP_EncryptFinal_ex(cipher->ctx, out + ret, NULL);
    if (ret < 0) {
        err(EXIT_FAILURE, "Failed to finalize encryption: %s", ERR_get_error());
    }

    return ret;
}

int my_cipher_decrypt(void *out, const void *in, size_t len, my_cipher_t *cipher) {
    int ret;

    ret = EVP_DecryptUpdate(cipher->ctx, out, NULL, in, len);
    if (ret <= 0) {
        err(EXIT_FAILURE, "Failed to decrypt data: %s", ERR_get_error());
    }

    ret = EVP_DecryptFinal_ex(cipher->ctx, out + ret, NULL);
    if (ret < 0) {
        err(EXIT_FAILURE, "Failed to finalize decryption: %s", ERR_get_error());
    }

    return ret;
}

int main() {
    // Load configuration or retrieve environment variables here

    my_cipher_t cipher;
    const char *mode = "des-cbc";
    const unsigned char key[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
    const unsigned char iv[EVP_MAX_IV_LENGTH] = {0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17};
    size_t key_size = sizeof(key) / sizeof(key[0]);

    cipher.ctx = my_cipher_init(mode, (const char *)key, key_size, iv, sizeof(iv));

    // Perform encryption or decryption using my_cipher_encrypt or my_cipher_decrypt functions

    my_cipher_free(&cipher);

    return 0;
}
```

