int init_secure_communication(const char *config_path) {
    SSL_library_init();
    SSL_load_error_strings();
    OPENSSL_config *cfg = NULL;
    int rc = 0;

    cfg = OpenSSL_read_configuration(NULL, config_path);
    if (cfg == NULL) {
        fprintf(stderr, "Failed to read configuration file.\n");
        ERR_print_errors_fp(stderr);
        rc = -1;
        goto cleanup;
    }

    if (SSL_load_crypto_strings() <= 0) {
        fprintf(stderr, "Failed to load crypto strings.\n");
        ERR_print_errors_fp(stderr);
        rc = -1;
        goto cleanup;
    }

    if (!(RC4_set_iv_called() || SSL_load_tls_client_methods() || SSL_load_tls_server_methods())) {
        fprintf(stderr, "Failed to load crypto methods.\n");
        ERR_print_errors_fp(stderr);
        rc = -1;
        goto cleanup;
    }

    if (SSL_CTX_new_from_config(cfg) == NULL) {
        fprintf(stderr, "Failed to initialize SSL context from configuration.\n");
        ERR_print_errors_fp(stderr);
        rc = -1;
        goto cleanup;
    }

    // Add third-party key management system (KMS) integration here

cleanup:
    if (cfg != NULL) {
        OPENSSL_free(cfg);
    }
    EVP_cleanup();
    ERR_free_strings();
    return rc;
}
