    throw new Error('Invalid input. Expected a non-empty string.');
  }

  const bookCount = {};

  let match;
  while ((match = RE_BOOK.exec(text)) !== null) {
    const bookName = match[1].toLowerCase();
    if (BIBLE_BOOKS['Old Testament'].includes(bookName) || BIBLE_BOOKS['New Testament'].includes(bookName)) {
      bookCount[bookName] = (bookCount[bookName] || 0) + 1;
    }
  }

  // Normalize different spellings
  const normalizedBooks = {
    "joshua": "Joshua",
    "josua": "Joshua",
    "genesis": "Genesis",
    "gen.": "Genesis"
    // Add more here as needed
  };

  Object.keys(normalizedBooks).forEach(key => {
    if (bookCount[key]) {
      bookCount[normalizedBooks[key]] = bookCount[key];
      delete bookCount[key];
    }
  });

  // Filter out verses or references that do not specify a book
  const cleanedText = text.replace(RE_CHAPTER_VERSE, '');
  while ((match = RE_BOOK.exec(cleanedText)) !== null) {
    delete bookCount[match[1].toLowerCase()];
  }

  return bookCount;
}
```

This code includes:
- A constant object `BIBLE_BOOKS` containing the list of books for both Old and New Testament.
- Two regular expressions, one for identifying book names (`RE_BOOK`) and another for extracting chapter/verse references (`RE_CHAPTER_VERSE`).
- The main function `countBooks(text)` which takes a string as input, identifies book names using the `RE_BOOK`, handles case-insensitive matching and normalizes different spellings using the `normalizedBooks` object, filters out verses or references that do not specify a book, and returns an object with the number of times each book appears in the text.

