    log_fn = fn;
}

#define MAX_BUFFER_SIZE (65536) // Adjust as needed for performance optimization

char* expandStringWithSlash(const char *input, size_t limit) {
    if (!input || limit <= 0) {
        if (log_fn) log_fn("Invalid input or limit");
        return NULL;
    }

    size_t inputLength = strlen(input);
    size_t bufferSize = inputLength + (limit >= inputLength ? 1 : limit) + 1; // +1 for trailing null and potential slash

    char *result = malloc(bufferSize * sizeof(char));
    if (!result) {
        if (log_fn) log_fn("Memory allocation failed");
        return NULL;
    }

    size_t i;
    for (i = 0; i < inputLength && i + 1 < bufferSize; ++i)
        result[i] = input[i];

    if (limit > inputLength) {
        memset(result + inputLength, ' ', limit - inputLength);
        result[inputLength + limit - 1] = '\0'; // ensure null-terminated
    }

    size_t trimmedLen = strspn(input, " \t\r\n");
    if (trimmedLen < inputLength) {
        memmove(result, input + trimmedLen, inputLength - trimmedLen);
        result[inputLength - trimmedLen] = '\0'; // ensure null-terminated
    }

    if (limit > strlen(result))
        strcat(result, "/");

    return result;
}

void freeExpandedString(char *str) {
    if (!str || !str[0]) return;
    free(str);
}

