    if (strcmp(result1, expected1) != 0) {
        printf("Test failed: expandStringWithSlash(\"%s\", 5)\nExpected: %s\nReceived: %s\n", input1, expected1, result1);
    } else {
        printf("Test passed: expandStringWithSlash(\"%s\", 5)\n");
    }
    freeExpandedString(result1);

    char *input2 = "Hello World";
    char *expected2 = "Hello World";
    char *result2 = expandStringWithSlash(input2, 10);
    if (strcmp(result2, expected2) != 0) {
        printf("Test failed: expandStringWithSlash(\"%s\", 10)\nExpected: %s\nReceived: %s\n", input2, expected2, result2);
    } else {
        printf("Test passed: expandStringWithSlash(\"%s\", 10)\n");
    }
    freeExpandedString(result2);
}
