const { promisify } = require('bluebird');
const axios = require('axios');
const fs = require('fs');

function uploadFileAndCopyBytes(url, byteCount, bufferChunks) {
  const uploadedUrl = promisify(axios.get)(url).then((response) => response.request.res._headerLocals.response.headers.location);

  const copiedBuffer = Buffer.allocUnsafe(byteCount);

  return Promise.all(bufferChunks.map((chunk, index) => {
    return new Promise((resolve, reject) => {
      let totalBytesCopied = index * chunk.length;
      const length = Math.min(chunk.length, byteCount - totalBytesCopied);
      chunk.copy(copiedBuffer, totalBytesCopied, 0, length);
      totalBytesCopied += length;
      resolve();
    });
  })).then(() => copiedBuffer);
}

function uploadFile(url) {
  const formData = new FormData();
  formData.append('file', fs.readFileSync(url));

  return axios.post('https://example.com/upload', formData, {
    headers: {
      'Content-Type': 'multipart/form-data'
    }
  }).then((response) => response.data.uploadedUrl);
}
