```python
import requests
from functools import lru_cache
import logging
import pymysql

class DataStreamAPI:
    def __init__(self, api_key, base_url):
        self.api_key = api_key
        self.base_url = base_url

    @lru_cache(maxsize=128)  # Cache API responses for performance and memory optimization
    def _get_data(self, stream_id):
        response = requests.get(f'{self.base_url}/{stream_id}', headers={'Authorization': f'Bearer {self.api_key}'})
        if response.status_code != 200:
            logging.error(f"Failed to fetch data from stream '{stream_id}'. Status code: {response.status_code}")
            return None
        return response.json()

    def _validate_field(self, field):
        if not isinstance(field, str) or len(field) <= 0:
            raise ValueError("Invalid field name.")

    def get_data(self, stream_ids, fields=None, database=None):
        if fields is None:
            fields = []

        consolidated_data = {}

        for stream_id in stream_ids:
            data = self._get_data(stream_id)
            if data is None:
                continue

            for field in fields:
                self._validate_field(field)
                if field not in data or data[field] is None:
                    continue

                if stream_id not in consolidated_data:
                    consolidated_data[stream_id] = {}

                consolidated_data[stream_id][field] = data[field]

        if database is not None:
            with pymysql.connect(database) as db:
                cursor = db.cursor()
                for stream_id, data in consolidated_data.items():
                    for field, value in data.items():
                        cursor.execute("INSERT INTO stream_data (stream_id, field, value) VALUES (%s, %s, %s)", (stream_id, field, value))
                db.commit()

        return consolidated_data
```

This code defines a `DataStreamAPI` class that encapsulates the functionality of integrating with a large dataset streaming service API. It has an initializer taking the API key and base URL as parameters. The `_get_data` method fetches data from a specific stream ID using the provided API key, caching the response for performance optimization.

The `get_data` method takes a list of stream IDs and an optional list of fields to retrieve, aggregating the results into a consolidated dictionary. It also includes an argument for logging each operation to an external database. The code uses lazy loading, caching mechanisms, error handling for API rate limits, authentication issues, and network failures, as well as modular design patterns for maintainability.

