[System.Serializable]
public class ValueGenerator
{
    private float minValue;
    private float maxValue;

    public ValueGenerator(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
        SetRange(min, max);
    }

    public float MinValue { get => minValue; set => SetRange(value, maxValue); }
    public float MaxValue { get => maxValue; set => SetRange(minValue, value); }

    public float GetRandomFloat() => UnityEngine.Random.Range(minValue, maxValue);
    public int GetRandomInt() => Mathf.RoundToInt(UnityEngine.Random.Range(minValue, maxValue));
    public Vector3 GetRandomVector3() => new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat());

    private void SetRange(float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Minimum value must be less than maximum value.");
        minValue = Mathf.Clamp(min, 0, float.MaxValue);
        maxValue = Mathf.Clamp(max, 0, float.MaxValue);
    }

    public override string ToString() => $"Min: {minValue}, Max: {maxValue}";

    private static Random seededRandom;

    public void SetSeed(uint seed)
    {
        seededRandom = new Random(seed);
        UnityEngine.Random.InitState((int)seed);
    }

    [System.NonSerialized]
    private static readonly object logLock = new object();
    private static readonly string logFilePath = "Logs/ValueGeneratorLog.json";

    public void LogGeneration(string message)
    {
        lock (logLock)
        {
            var logData = File.Exists(logFilePath) ? JsonConvert.DeserializeObject<List<string>>(File.ReadAllText(logFilePath)) : new List<string>();
            logData.Add($"{DateTime.Now}: {message} [Min: {minValue}, Max: {maxValue}]");
            File.WriteAllText(logFilePath, JsonConvert.SerializeObject(logData));
        }
    }

    ~ValueGenerator()
    {
        if (seededRandom != null) UnityEngine.Random.InitState((int)seededRandom.Next());
    }
}

