using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using Newtonsoft.Json.Linq;
using RestSharp;

public class TripleDESBase64Decryptor
{
    private readonly string _apiKey;
    private readonly string _cachePrefix;
    private readonly TimeSpan _cacheDuration;
    private readonly MemoryCache _cache = new MemoryCache("TripleDES");

    public TripleDESBase64Decryptor(string apiKey, string userType, string messageType, TimeSpan cacheDuration)
    {
        _apiKey = apiKey;
        _cachePrefix = $"{userType}-{messageType}";
        _cacheDuration = cacheDuration;
    }

    public string Decrypt(string base64EncodedMessage)
    {
        // Load key and IV from cache or API based on userType and messageType
        var keyAndIV = GetKeyAndIV();

        using (var des = TripleDES.Create())
        {
            des.Key = Encoding.UTF8.GetBytes(keyAndIV.Item1);
            des.IV = Encoding.UTF8.GetBytes(keyAndIV.Item2);

            var decryptor = new ICryptoTransform(des.CreateDecryptor());
            var data = Convert.FromBase64String(base64EncodedMessage);
