  .factory('FieldRefresher', ['$timeout', '$q', function($timeout, $q) {

    var service = {};
    var cache = {}; // Cache for recent requests
    var fieldNames = ['field1', 'field2', 'field3']; // Fields to refresh
    var timeout = 10000; // Timeout in milliseconds (10 seconds)

    service.refreshFields = function(resourceId, url) {
      var deferred = $q.defer();

      var now = new Date();

      angular.forEach(fieldNames, function(fieldName) {
        if (!cache[fieldName] || (now - cache[fieldName].time > 5000)) { // Check cache and time
          $window.postMessage({action: 'refresh', field: fieldName, id: resourceId, url: url}, '*');
          cache[fieldName] = {time: now};
        }
      });

      $window.addEventListener('message', function(event) {
        if (event.data && event.data.action === 'refreshResponse') {
          if (event.data.success) {
            switch (event.data.field) {
              case 'field1': // Update field1 here
                // ...
                break;
              case 'field2': // Update field2 here
                // ...
                break;
              case 'field3': // Update field3 here
                // ...
                break;
            }
          } else {
            console.error('Failed to refresh field:', event.data.field);
          }
        }
      }, false);

      return $q.promise(function(resolve, reject) {
        var timer = $timeout(function() { // Timeout to handle slow or unresponsive parent windows
          console.error('Timeout while waiting for response');
          reject();
        }, timeout);

        timer.resolve = resolve;
        timer.reject = reject;
      });
    };

    return service;
  }]);
