void ThreadSafeNetworkEventCollection::addEvent(const NetworkEventStructure& event) {
    std::lock_guard<std::mutex> lock(dataMutex_);
    auto ptr = std::make_unique<NetworkEventStructure>(event);
    events_.push_back(std::move(ptr));
}

NetworkEventStructure* ThreadSafeNetworkEventCollection::getEvent(size_t index) const {
    std::lock_guard<std::mutex> lock(dataMutex_);
    if (index >= events_.size())
        throw std::out_of_range("Index out of range");
    return events_[index].get();
