import re
from functools import wraps
import sys

def sequence_number(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        try:
            with open(*args[0], 'r') as f:
                lines = [line.strip() for line in sorted(f)]
                last_line = lines[-1]
                match = re.search(r'seq\s+(\d+)', last_line)
                if match:
                    return int(match.group(1))
        except Exception as e:
            print("Error reading file:", str(e), file=sys.stderr)
            raise
        else:
            raise ValueError("Sequence number not found")
    return wrapper

@sequence_number
