using System;
using System.Xml;
using System.Xml.XPath;
using System.Linq;
using System.Runtime.Serialization;

public class XmlNotFoundException : Exception { }
public class InvalidOperationException : Exception { }
public class ArgumentException : Exception { }

public class Logger
{
    public Action<string> Log;

    public void Error(string message) => Log(message);
}

public XElement FindSingleXmlElement(XmlReader reader, string xPathExpression, Logger logger)
{
    var xmlNamespaceManager = new XmlNamespaceManager(reader.NameTable);
    xmlNamespaceManager.AddNamespace("ns", "your-namespace-uri"); // replace with your namespace URI

    var xpathNavigator = new XPathNavigator(reader, xmlNamespaceManager);

    try
    {
        var nodeSet = xpathNavigator.Select(xPathExpression);

        if (nodeSet.Count == 0)
            throw new XmlNotFoundException();
        else if (nodeSet.Count > 1)
            throw new InvalidOperationException();

        return nodeSet.Item(0).ReadOutElement();
    }
    catch (XPathException ex)
    {
        logger.Error($"An error occurred while evaluating XPath expression: {ex.Message}");
        throw new ArgumentException("Invalid XPath expression", nameof(xPathExpression));
    }
}

public static class XElementExtensions
{
    public static XElement ReadOutElement(this XElement element)
    {
        if (element != null && element.HasElements)
            throw new InvalidOperationException();

        return element;
    }
}
