Here's the code for a `parseAndValidateEmail` function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

#define EMAIL_REGEX "^[\\w-._%+]{1,64}@(?:[\\w-]{1,63}\\.){1,8}[\\w-]{2,63}$"

static void log_error(const char *message) {
    // Implement logging functionality here
    printf("Error: %s\n", message);
}

int parseAndValidateEmail(char **email, const char *input, size_t inputSize) {
    regex_t regex;
    regmatch_t match;

    int rc = regcomp(&regex, EMAIL_REGEX, REG_EXTENDED | REG_ICASE);
    if (rc != 0) {
        log_error("Regular expression compilation failed");
        return -1;
    }

    rc = regexec(&regex, input, 0, NULL, 0);
    regfree(&regex);

    if (rc == 0) {
        *email = malloc(inputSize + 2); // for the null terminator and possible multi-byte characters
        if (*email == NULL) {
            log_error("Memory allocation failed");
            return -1;
        }

        memcpy(*email, input, inputSize);
        (*email)[inputSize] = '\0';
    } else {
        log_error("Invalid email address");
        free(*email);
        *email = NULL;
        return -1;
    }

    return 0;
}

void freeEmail(char **email) {
    if (*email != NULL) {
        free(*email);
        *email = NULL;
    }
}
