        : rxUeInformationTag(tag), rntiTag(rntiTag), crcTag(crcTag) {}

    RxUeInformationTag rxUeInformationTag;
    RntiTag rntiTag;
    CrcIndicationRel8Tag crcTag;
};

std::map<int, std::optional<RntiTag>> ueRntis; // Map to store UE ID and their corresponding RNTI or default value if not present

std::vector<NfapiCricIndicationPdu> initializeCrcIndications(std::vector<int> ueIds, std::vector<uint16_t> rntis, std::vector<bool> crcFlags, int numPdus) {
    if (ueIds.size() != rntis.size() || ueIds.size() != crcFlags.size()) {
        throw std::invalid_argument("Invalid inputs: ueIds, rntis, and crcFlags vectors must have the same size.");
    }

    if (numPdus > ueIds.size()) {
        throw std::runtime_error("Invalid input: numPdus cannot be greater than the number of UEs.");
    }

    std::vector<NfapiCricIndicationPdu> pdus(numPdus);

    for (int i = 0; i < numPdus; ++i) {
        if (ueRntis.find(ueIds[i]) != ueRntis.end()) {
            pdus[i] = NfapiCricIndicationPdu({ RxUeInformationTag{ueIds[i]} }, ueRntis[ueIds[i]], { crcFlags[i] });
        } else {
            // Set a default RNTI if the UE is not present in the system
            pdus[i] = NfapiCricIndicationPdu({ RxUeInformationTag{ueIds[i]} }, RntiTag{0xffff}, { crcFlags[i] });
        }
    }

    return pdus;
}
