using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace AesDecryptionClass
{
    public class AesDecryption
    {
        private readonly IKeyManagementService _keyManagementService;
        private readonly ConcurrentDictionary<string, (Aes Algorithm, byte[] Key, byte[] Iv)> _caches = new ConcurrentDictionary<string, (Aes, byte[], byte[])>();

        public AesDecryption(IKeyManagementService keyManagementService)
        {
            _keyManagementService = keyManagementService;
        }

        private async Task<(byte[] Key, byte[] Iv)> RetrieveKeysAndIVsAsync(string uniqueIdentifier)
        {
            // Implement your key management service logic here.
            var (key, iv) = await _keyManagementService.RetrieveEncryptionKeyAndIVAsync(uniqueIdentifier);

            return (key, iv);
        }

        public byte[] DecryptData(string uniqueIdentifier, byte[] cipherText)
        {
            if (_caches.TryGetValue(uniqueIdentifier, out var cached))
            {
                return DecryptWithCachedKeyAndIV(cached, cipherText);
            }

            Task.Run(async () =>
            {
                var (key, iv) = await RetrieveKeysAndIVsAsync(uniqueIdentifier);
                _caches[uniqueIdentifier] = (Aes.Create(), key, iv);
            });

            return DecryptWithCachedKeyAndIV(_caches[uniqueIdentifier], cipherText);
        }

        private byte[] DecryptWithCachedKeyAndIV((Aes Algorithm, byte[] Key, byte[] Iv) cachedKeysAndIv, byte[] cipherText)
        {
            using var ms = new MemoryStream(cipherText);
            using var cs = new CryptoStream(ms, cachedKeysAndIv.Algorithm.CreateDecryptor(cachedKeysAndIv.Key, cachedKeysAndIv.Iv), CryptoStreamMode.Read);
            return cs.ToArray();
        }

        private void SecurelyEraseData(byte[] data)
        {
            // Implement your secure data erasure logic here.
            Array.Clear(data, 0, data.Length);
        }
    }
}
```

