#include <forward_list>
#include <memory>
#include <stdexcept>
#include <string>
#include <mutex>
#include <iostream>
#include <functional>

// Node class to store node data and attribute map
class Node {
public:
    std::string name;
    std::string value;
    std::string attribute;

    // Constructor
    Node(const std::string& name, const std::string& value, const std::string& attribute) : name(name), value(value), attribute(attribute) {}
};

// A helper class to manage locks for concurrent access
class LockManager {
public:
    std::mutex mutex;
    std::unique_lock<std::mutex> lock;

    void acquire() {
        lock = std::unique_lock<std::mutex>(mutex);
    }

    void release() {
        lock.unlock();
    }
};

// A helper function to find a node in the list matching given name and context
auto findNode(const std::forward_list<Node*>& list, const std::string& nodeName, const std::string& context) -> Node* {
    LockManager lockManager;

    for (auto it = list.begin(); it != list.end(); ++it) {
        lockManager.acquire();

        if ((*it)->name == nodeName && (!context.empty() ? (*it)->attribute == context : true)) {
            lockManager.release();
            return *it;
        }

        lockManager.release();
    }

    return nullptr;
}

// A helper function to log the operation's success or failure
void logOperation(const std::string& message, const std::string& nodeName, const std::string& newValue, const std::string& newAttribute, bool success) {
    if (success) {
        std::cout << "Successfully updated attribute of node '" << nodeName << "' from '" << newAttribute << "' to '" << newAttribute << "'." << std::endl;
    } else {
        std::cout << "Failed to update attribute of node '" << nodeName << "'. Node not found or invalid input." << std::endl;
    }
}

// The main updateNodeAttributes function
void updateNodeAttributes(std::forward_list<Node*>& list, const std::string& nodeName, const std::string& newValue, const std::string& newAttribute, const std::string& context) {
    if (nodeName.empty() || newValue.empty() || newAttribute.empty()) {
        throw std::invalid_argument("Invalid input: empty string(s).");
    }

    auto foundNode = findNode(list, nodeName, context);

    if (foundNode) {
        foundNode->value = newValue;
        foundNode->attribute = newAttribute;
    } else {
        // Create a new node and append it to the list
        auto newNode = std::make_unique<Node>(nodeName, newValue, newAttribute);
        list.push_back(newNode.get());
    }

    logOperation("Updated node attributes", nodeName, newValue, newAttribute, true);
}
