using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using NLog;

namespace MyHashService
{
    public class HashService
    {
        private static readonly Logger _logger = LogManager.GetCurrentClassLogger();
        private IConfiguration _configuration;

        public HashService(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        /// <summary>
        /// Compute the MD5 hash of a given string and return it as a hexadecimal string.
        /// </summary>
        /// <param name="input">The input string.</param>
        public string ComputeMD5Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input), "Input cannot be null or empty.");

            var bytes = Encoding.UTF8.GetBytes(input);
            return ComputeMD5Hash(bytes);
        }

        /// <summary>
        /// Compute the MD5 hash of a given byte array and return it as a hexadecimal string.
        /// </summary>
        /// <param name="input">The input byte array.</param>
        public string ComputeMD5Hash(byte[] input)
        {
            if (input == null || input.Length == 0)
                throw new ArgumentNullException(nameof(input), "Input cannot be null or empty.");

            using (var md5 = MD5.Create())
            {
                var hashedBytes = md5.ComputeHash(input);
                return BitConverter.ToString(hashedBytes).Replace("-", string.Empty).ToLowerInvariant();
            }
        }

        /// <summary>
        /// Compute the MD5 hash of a given byte array and return it as a hexadecimal string using an external API.
        /// </summary>
        /// <param name="input">The input byte array.</param>
        public async Task<string> ComputeMD5HashAsync(byte[] input)
        {
            if (input == null || input.Length == 0)
                throw new ArgumentNullException(nameof(input), "Input cannot be null or empty.");

            try
            {
                using var httpClient = new HttpClient();
                var apiUrl = _configuration["ExternalApi:Url"];
                var apiTimeout = int.Parse(_configuration["ExternalApi:Timeout"]);

                var content = new ByteArrayContent(input);
                var response = await httpClient.PostAsync(apiUrl, content);
                if (!response.IsSuccessStatusCode)
                    throw new Exception($"Failed to get response from the external API.");

                return await response.Content.ReadAsStringAsync();
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to call the external API");
                throw;
            }
        }
    }
}
