#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>
#include <uchar.h>
#include <intltypes.h>

/* Maximum email length for performance and memory considerations */
#define MAX_EMAIL_LENGTH 256

/* Error messages */
enum {
    EMAIL_INVALID,
    SIZE_LIMIT_EXCEEDED,
    NULL_INPUT,
    NEGATIVE_SIZE_LIMIT,
    UNKNOWN_ERROR
};

static const char *error_messages[] = {
    "Invalid email address",
    "Email exceeded size limit",
    "Input is null",
    "Size limit is less than 0",
    "Unknown error"
};

/* Thread-safe logging function */
void thread_safe_log(int fd, const char *message) {
    write(fd, message, strlen(message));
}

/* Validate email address and return a pointer to the validated email if it passes validation */
char *parseAndValidateEmail(const char *inputEmail, size_t sizeLimit, int logFd) {
    /* Check input parameters for null or invalid values */
    if (!inputEmail || sizeLimit < 0) {
        thread_safe_log(logFd, error_messages[NULL_INPUT]);
        return NULL;
    }

    /* Ensure email does not exceed the size limit */
    if (strlen(inputEmail) > sizeLimit) {
        thread_safe_log(logFd, error_messages[SIZE_LIMIT_EXCEEDED]);
        return NULL;
    }

    /* Validate the email address according to standard rules */
    const char *at_symbol = strchr(inputEmail, '@');
    if (!at_symbol || (at_symbol - inputEmail + 1) >= sizeLimit || strcspn(at_symbol + 1, "@.") != 1) {
        thread_safe_log(logFd, error_messages[EMAIL_INVALID]);
        return NULL;
    }

    /* Create a new null-terminated string to store the validated email */
    char validated_email[MAX_EMAIL_LENGTH];
    strncpy(validated_email, inputEmail, sizeLimit);
    validated_email[sizeLimit] = '\0';

    /* Return a pointer to the validated email string or NULL if validation failed */
    return validated_email;
}
