use std::env;
use std::fs::File;
use std::io::{BufReader, Write};
use std::path::PathBuf;
use std::process::{Command, ExitStatus, Stdio};
use std::time::Instant;
use std::sync::Lazy;
use rustc_driver::{catch_with_exit_code, Driver};
use sysinfo::{System, SystemExt};

static ICE_HOOK: Lazy<Box<dyn FnOnce(String)>> = Lazy::new(|| Box::new(|msg| println!("{}", msg)));

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} PATH_TO_FILE", args[0]);
        std::process::exit(1);
    }

    let path = PathBuf::from(&args[1]);

    if path.is_dir() {
        eprintln!("Error: Given path is a directory, not a file");
        std::process::exit(2);
    }

    let mut sys = System::new_with_current_threads();
    let mem_limit_mb = 512; // Set the maximum resident set size limit (in MB)

    let start = Instant::now();
    let mut log = Vec::new();
    let mut rss_before = sys.swap_size_mb();

    let driver = Driver::new()
        .logger(Box::new(|msg| {
            log.push(format!("{}", msg));
            ICE_HOOK(msg)
        }))
        .catch_with(catch_with_exit_code());

    match driver.run(&[
        "rustc",
        "--",
        &path,
    ]) {
        Ok(status) => {
            let end = Instant::now();
            let rss_after = sys.swap_size_mb();

            log.push(format!(
                "Compilation completed in {}s\n",
                end.duration_since(start).as_secs_f64()
            ));
            log.push(format!("Resident set size before: {}\n", rss_before));
            log.push(format!("Resident set size after: {}\n", rss_after));

            if status.success() {
                eprintln!("Compilation succeeded");
                std::process::exit(0);
            } else {
                let errors = status.code().unwrap_or(127);
                early_error(&log, &path, errors);
                std::process::exit(errors);
            }
        }
        Err(_) => {
            if path.exists() {
                eprintln!("Error: The file exists but could not be compiled");
            } else {
                eprintln!("Error: The given file does not exist");
            }
            std::process::exit(3);
        }
    }
}

fn early_error(log: &Vec<String>, path: &PathBuf, exit_code: i32) {
    let start = log.first().unwrap();
    let end = log.last().unwrap();
    let duration_str = format!(
        "Elapsed time: {}",
        end.duration_since(start).as_secs_f64().to_string() + "s"
    );
    let mem_diff = (sysinfo::System::new_with_current_threads().swap_size_mb() as f64 - rss_before as f64) / 1024.0;
    let mem_str = format!("Memory usage: {} MB", mem_diff);

    eprintln!(
        "{}",
        format_args!(
            concat!("# Early error report

Compilation failed.

Start time: {start}
End time:   {end}
Duration:   {duration_str}
Memory usage: {mem_str}
Error code: {}",
            exit_code
        )
    );

    for line in log {
        eprintln!("  {} ", line);
    }
}
```

