use std::process::{Command, Stdio};
use rustc_driver::catch_with_exit_code;
use log::*;
use sync_rc::SyncLazy;
use memory_size::MemorySize;
extern crate simplelog;

struct LoggingHook;

impl Log for LoggingHook {
    fn enabled(&self, _metadata: &log::Metadata) -> bool {
        true
    }

    fn log(&self, record: &Record) {
        if let Some(ref message) = record.args().get("message") {
            // Format and send the log entry to your preferred logging service here
            let formatted_log = format!("{}", message);
            // ...
        }
    }
}

static LOGGING_HOOK: SyncLazy<LoggingHook> = SyncLazy::new();

fn compile() -> i32 {
    let start_time = Instant::now();
    let mut process = Command::new("rustc")
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    let mem_before = MemorySize::resident();

    let result = catch_with_exit_code(|| {
        process.envs_mut().insert("RUSTC_LOG", "rustc=trace".to_owned());
        process.envs_mut().insert("RUSTFLAGS", "-C trace-events= compiler".to_owned());
        // Add any other necessary environment variables or arguments here
        process.arg("-").status()?;
    });

    let mem_after = MemorySize::resident();
    let compilation_time = start_time.elapsed().as_secs_f64();

    info!("Compilation time: {}", compilation_time);
    info!("Memory usage before compilation: {}", mem_before);
    info!("Memory usage after compilation: {}", mem_after);

    if let Err(e) = result {
        error!("Compilation failed with error: {}", e);
        error!(
            "Troubleshooting suggestions:\n- Ensure that the project's root directory is in your $PATH\n- Run `cargo clean` to clear previous build artifacts"
        );
        return 1;
    }

    0
}

fn main() {
    simplelog::CombinedLogger::init(vec![simplelog::TermLogger::new(simplelog::Config::default())])
        .with_module(file!())
        .init();
    set_global_logger(LOGGING_HOOK.clone());

    compile()
}
