function extractBooks(text, biblePart, filterCanonical) {
  const bookCount = {};
  let regex = bibleRegex[biblePart];

  // Iterate through the text and match books using the defined regular expression
  let match;
  while ((match = regex.exec(text)) !== null) {
    const bookName = match[0].toLowerCase();
    if (bookCount[bookName]) {
      bookCount[bookName]++;
    } else {
      bookCount[bookName] = 1;
    }
  }

  // Filter out non-canonical books if specified by user
  if (filterCanonical) {
    const canonicalBooks = bibleTexts[biblePart];
    for (const book in bookCount) {
      if (!canonicalBooks.includes(book)) {
        delete bookCount[book];
      }
    }
  }

  return bookCount;
}
