#include <stdarg.h>
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <semaphore.h>
#include "external_log_service.h" // External Logging Service API header

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t log_semaphore;

void logConditionalMessage(bool condition, const char *format, ...) {
    if (!condition) {
        return;
    }

    // Allocate memory for the formatted message
    va_list args;
    char* buffer = malloc(4096);
    memset(buffer, 0, 4096);

    sem_wait(&log_semaphore);
    pthread_mutex_lock(&log_mutex);

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Log the message using the external logging service API
    int priority = get_priority(); // Assuming this function returns an appropriate integer for the log priority level
    externalLogServiceLog(buffer, priority);

    pthread_mutex_unlock(&log_mutex);
    sem_post(&log_semaphore);

    free(buffer);
}
```
