using System.Xml.XPath.Extensions;

public struct Connection
{
    public string Title { get; set; }
    // Add other properties as needed
}

public delegate void CallbackFunction(string elementValue);

public class XmlParser
{
    public static XmlElement ParseXmlWithPasswordAndCallback(string xml, string password, Connection connection, CallbackFunction callback)
    {
        if (string.IsNullOrEmpty(password))
            throw new ArgumentException("Password cannot be empty or null.");

        if (connection == null || string.IsNullOrEmpty(connection.Title))
            throw new ArgumentException("Connection structure must have a non-empty Title property.");

        if (callback == null)
            throw new ArgumentNullException(nameof(callback));

        var document = new XmlDocument();
        using (var reader = XmlReader.Create(new StringReader(xml)))
            document.Load(reader);

        var navigator = document.CreateNavigator();
        var xpathExpression = $"/*/{connection.Title}/{* : LocalName eq '{connection.Title}' and namespace-uri() = {document.DocumentElement.NamespaceURI}}"; // Using XPath for recursive search

        var matchingElements = navigator.Select(xpathExpression).Cast<XmlNode>().OfType<XmlElement>();

        if (matchingElements.Count() == 0)
            throw new Exception("No element found with the given name.");

        if (matchingElements.Count() > 1)
            throw new Exception("Multiple elements found with the given name.");

        var matchingElement = (XmlElement)matchingElements.First();

        // Perform your custom operation on the matching element here, for example:
        // callback(matchingElement.GetAttribute("my-attribute"));

        var xpathQuery = $"{connection.Title}/{* : LocalName eq '{connection.Title}' and namespace-uri() = {document.DocumentElement.NamespaceURI}}/{name}";
        return navigator.SelectSingleNode(xpathQuery) as XmlElement;
    }
}
