2. TiffParser.c

```c
#include "TiffParser.h"

TiffMetadata parse_tiff_file(const char* file_path) {
    TIFF* tif = tifOpen(file_path, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open the file.\n");
        return (TiffMetadata){0};
    }

    TiffMetadata metadata;
    int current_page = 1;
    while (current_page <= TIFFGetField(tif, TIFFTAG_NUMBEROFPAGE)) {
        if (TIFFReadDirectory(tif) < 0) {
            fprintf(stderr, "Error: Unable to read directory for page %d.\n", current_page);
            cleanup_tiff_parser(tif);
            return (TiffMetadata){0};
        }

        metadata.bits_per_sample = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);
        metadata.sample_per_pixel = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
        metadata.compression_type = TIFFGetField(tif, TIFFTAG_COMPRESSION);

        if (metadata.bits_per_sample < 1 || metadata.bits_per_sample > 16) {
            fprintf(stderr, "Error: Unsupported bits per sample (%d).\n", metadata.bits_per_sample);
            cleanup_tiff_parser(tif);
            return (TiffMetadata){0};
        }

        int extra_samples = TIFFGetField(tif, TIFFTAG_SAMPLEFORMAT);
        metadata.extra_samples_count = (extra_samples >> 8) & 0x3f;
        // Fill individual extra sample information if needed

        metadata.profile_info = TIFFGetASprint(tif, "ImageDescription");

        store_metadata(get_file_identifier(file_path), metadata);
        current_page++;
    }

    cleanup_tiff_parser(tif);
    return metadata;
}

void cleanup_tiff_parser(TIFF* tif) {
    if (tif != NULL) {
        tifClose(tif);
    }
}
