```rust
use std::env;
use std::fs::{self, create_dir_all, remove_dir_all};
use std::path::PathBuf;
use tempfile::Builder as TempBuilder;
use config::{Config, ConfigError};

mod error {
    #[derive(thiserror::Error, Debug)]
    pub enum Error {
        // Define your custom errors here, e.g., PermissionDenied, DiskFull, etc.
        ConfigError(ConfigError),
        IoError(std::io::Error),
        DirectoryAlreadyExists,
    }
}

pub struct ConfigManager {
    base_dir: PathBuf,
}

impl ConfigManager {
    pub fn new() -> Result<Self, Error> {
        let config = Config::builder()
            .add_source(config::File::with_name("config.toml"))
            .build()?;

        let base_dir = config.get_str("base_directory")?.parse::<PathBuf>()?;
        if !fs::metadata(base_dir.as_path())? .is_dir() {
            return Err(Error::ConfigError(ConfigError::File));
        }

        Ok(Self { base_dir })
    }

    pub fn get_base_dir(&self) -> &PathBuf {
        &self.base_dir
    }
}

pub fn create_directory(name: &str) -> Result<(), Error> {
    let mut config = ConfigManager::new()?;
    let base_dir = config.get_base_dir();

    let dir_path = base_dir.join(name);
    if fs::metadata(dir_path.as_path())? .is_ok() {
        // Directory already exists, append a unique identifier and try again.
        let mut id = 1;
        loop {
            let new_dir_path = dir_path.with_extension(format!("{}", id));
            if !fs::metadata(new_dir_path.as_path())? .is_ok() {
                break;
            }
            id += 1;
        }
    }

    create_dir_all(&new_dir_path)?;

    let dir_path_str = new_dir_path.to_string_lossy();
    env::set_var("MYAPP_DIR", &dir_path_str);

    Ok(())
}
```

This Rust code creates a `ConfigManager` structure for handling the configuration file and fetching the base directory path. It also defines an error type, `Error`, to manage potential failure modes gracefully. The `create_directory` function takes a name as input, creates a new directory with the given name, sets an environment variable to the path of the directory (`MYAPP_DIR`), and handles concurrent access efficiently using a loop to append a unique identifier if the directory already exists.

Note that this code does not handle external configuration management systems directly, as it's beyond the scope of this example. However, you can extend the `ConfigManager` implementation to fetch the base directory path from your preferred configuration system (e.g., TOML, YAML, JSON files or environment variables).

