            _schemaSource = configuration.GetValue<string>("SchemaSource");
        }

        public async Task<XmlNode> GetConfigAsync(string url)
        {
            var key = url + HashString(url); // Add a cache key based on the URL to implement caching

            if (_cache.TryGetValue(key, out var cachedConfig))
                return cachedConfig;

            lock (_cache) // Ensure thread-safety when accessing the cache
            {
                if (_cache.ContainsKey(key))
                    return _cache[key];
            }

            _logger.LogInformation("Downloading configuration from {Url}", url);

            var downloadCount = 0;

            async Task<HttpResponseMessage> DownloadConfigAsync()
            {
                if (Interlocked.Increment(ref downloadCount) > _maxDownloads)
                    throw new TooManyRequestsException();

                return await _httpClient.GetAsync(url);
            }

            try
            {
                var response = await DownloadConfigAsync().Retry(_retryAttempts => Math.Min(_retryAttempts, 10), onAttemptError =>
                {
                    if (onAttemptError.Exception is HttpRequestException || onAttemptError.Exception is TaskCanceledException)
                        _logger.LogWarning("Failed to download configuration from {Url}. Retrying in {Delay} seconds.", url, _retryDelay);

                    return TimeSpan.FromSeconds(2) * Math.Pow(2, (decimal)_retryAttempts); // Exponential backoff
                });

                response.EnsureSuccessStatusCode();

                var xml = await response.Content.ReadAsStreamAsync();
                var configDocument = new XmlDocument();
                configDocument.Load(xml);

                if (!ValidateXml(configDocument))
                    throw new Exception("Invalid XML configuration");

                _cache[key] = configDocument;
                return configDocument;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to download or validate configuration from {Url}. Error: {Message}", url, ex.Message);
                throw;
            }
        }

        private bool ValidateXml(XmlDocument xml)
        {
            using (var reader = XmlReader.Create(new StringReader(xml.OuterXml)))
            {
                var schemaSet = new XmlSchemaSet();
                schemaSet.Add(null, _schemaSource);

                var validator = new XmlValidator(schemaSet);
                return validator.Validate(reader) == ValidationResult.Valid;
            }
        }

        private string HashString(string value) => HashAlgorithmFactory.CreateHash("SHA256").ComputeHash(Encoding.UTF8.GetBytes(value)).ToBase64();
    }
}
```

