#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <syslog.h>

typedef struct {
    pthread_mutex_t lock;          // Lock for safe access to the semaphore
    pthread_cond_t cond;           // Condition variable to signal when the semaphore can be posted
    int value;                     // Current value of the semaphore
    int auto_delete;               // Whether to automatically delete the semaphore on completion
    FILE *logfile;                 // Log file for critical operations
} SafeSemaphore;

int safe_semaphore_init(struct SafeSemaphoreConfig *config) {
    if (!config || !config->initial_value || !config->log_file_path) return -1;

    SafeSemaphore *sem = malloc(sizeof(SafeSemaphore));
    if (!sem) {
        syslog(LOG_ERR, "Failed to allocate memory for semaphore");
        return -1;
    }

    sem->value = config->initial_value;
    sem->auto_delete = config->auto_delete;

    // Initialize pthread resources
    if (pthread_mutex_init(&sem->lock, NULL) != 0 ||
        pthread_cond_init(&sem->cond, NULL) != 0) {
        syslog(LOG_ERR, "Failed to initialize pthread resources for semaphore");
        free(sem);
        return -1;
    }

    // Open log file if auto_delete is false
    if (!config->auto_delete) {
        sem->logfile = fopen(config->log_file_path, "w+");
        if (!sem->logfile) {
            syslog(LOG_ERR, "Failed to open log file: %s", config->log_file_path);
            pthread_mutex_destroy(&sem->lock);
            pthread_cond_destroy(&sem->cond);
            free(sem);
            return -1;
        }
    }

    syslog(LOG_INFO, "Successfully initialized semaphore with value: %d", sem->value);

    return (intptr_t) sem;
}

void safe_semaphore_cleanup(struct SafeSemaphoreConfig *config, intptr_t sem) {
    if (!sem || !(SafeSemaphore *) sem) return;

    SafeSemaphore *s = (SafeSemaphore *) sem;

    // Close and free log file if auto_delete is true
    if (s->logfile && config->auto_delete) {
        fclose(s->logfile);
    }

    pthread_mutex_destroy(&s->lock);
    pthread_cond_destroy(&s->cond);
    free(s);
}

void sem_wait(SafeSemaphore *sem) {
    // Wait until semaphore value is greater than 0
    pthread_mutex_lock(&sem->lock);

    while (sem->value <= 0) {
        pthread_cond_wait(&sem->cond, &sem->lock);
    }

    --sem->value;
    syslog(LOG_INFO, "Semaphore waited by thread: %lu", (unsigned long) pthread_self());

    if (sem->logfile) {
        fprintf(sem->logfile, "[WAIT] Thread ID: %lu\n", (unsigned long) pthread_self());
    }

    pthread_mutex_unlock(&sem->lock);
}

void sem_post(SafeSemaphore *sem) {
    // Increase semaphore value and signal waiting threads
    pthread_mutex_lock(&sem->lock);

    ++sem->value;
    syslog(LOG_INFO, "Semaphore posted by thread: %lu", (unsigned long) pthread_self());

    if (sem->logfile) {
        fprintf(sem->logfile, "[POST] Thread ID: %lu\n", (unsigned long) pthread_self());
    }

    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->lock);
}
```

