// ... Your SafeSemaphoreConfig and safe_semaphore_init, safe_semaphore_cleanup functions here ...

void *worker(void *arg) {
    int id = *(int *) arg;
    SafeSemaphore *sem = (SafeSemaphore *) arg2;

    sem_wait(sem); // Wait until the semaphore is available

    printf("Worker %d is running\n", id);

    sleep(id * 5);
    sem_post(sem); // Signal that we're done and release the semaphore

    return NULL;
}

int main() {
    SafeSemaphoreConfig config = { .initial_value = 3, .log_file_path = "/tmp/semaphore.log", .auto_delete = true };
    SafeSemaphore *sem = safe_semaphore_init(&config);

    if (!sem) {
        fprintf(stderr, "Failed to initialize semaphore\n");
        return 1;
    }

    pthread_t threads[4];
    int ids[4] = {0, 1, 2, 3};

    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, worker, &ids[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            safe_semaphore_cleanup(&config, sem);
            return 1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            fprintf(stderr, "Failed to join thread\n");
            safe_semaphore_cleanup(&config, sem);
            return 1;
        }
    }

    safe_semaphore_cleanup(&config, sem);
    return 0;
}
