import json
import logging
import requests
from time import sleep
from functools import wraps
import unittest

# Decorator to automatically retry failed requests up to three times with exponential backoff.
def retry(max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            retries = max_retries
            while True:
                try:
                    return func(*args, **kwargs)
                except requests.exceptions.RequestException as e:
                    if retries <= 0:
                        raise e
                    logging.warning(f"Request failed {retries}: {e}")
                    sleep(2**(max_retries - retries))
                    retries -= 1
        return wrapper
    return decorator

class APIClient:
    def __init__(self, base_url):
        self.base_url = base_url

    @retry
    def get(self, path, **kwargs):
        resp = requests.get(f"{self.base_url}{path}", **kwargs)
        resp.raise_for_status()
        return resp.json()

    @retry
    def post(self, path, json_, **kwargs):
        resp = requests.post(f"{self.base_url}{path}", json=json_, **kwargs)
        resp.raise_for_status()
        return resp.json()

class MockServer:
    def __init__(self):
        self.tokens = {}

    def create_token(self, user_id):
        token = "mock-token-%s" % user_id
        self.tokens[user_id] = token
        return {"access_token": token, "expires_in": 86400}

    def check_token(self, token):
        if token in self.tokens:
            del self.tokens[token]
            return True
        return False

class APIClientTests(unittest.TestCase):
    def setUp(self):
        self.client = APIClient("http://localhost:8000")
        self.server = MockServer()

    def test_create_token(self):
        resp = self.client.post("/auth/login", {"username": "testuser"})
        self.assertEqual(resp["access_token"], "mock-token-testuser")

    def test_expired_token(self):
        self.server.create_token("testuser")
        sleep(8641)  # token expiration + 1 second for safety
        resp = self.client.get("/protected", headers={"Authorization": "Bearer mock-token-testuser"})
        self.assertEqual(resp.status_code, 401)

    def tearDown(self):
        for token in self.server.tokens.values():
            self.client.get("/auth/logout", headers={"Authorization": "Bearer %s" % token})

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    unittest.main()
