```cpp
#include <forward_list>
#include <string>
#include <functional>
#include <mutex>
#include <atomic>
#include <iostream>

class LoggingStream final {
public:
    template<typename T>
    LoggingStream& operator<<(const T& value) {
        data_ << value;
        ++num_operations_;
        return *this;
    }

    void print() const {
        std::cout << "Performed " << num_operations_ << " operations:\n";
        data_.seekg(0);
        data_ << "Before insertion: ";
        for (const auto& str : before_) {
            data_ << str << ' ';
        }
        data_ << '\n';
        data_.seekg(0);
        data_ << "After insertion:  ";
        for (const auto& str : after_) {
            data_ << str << ' ';
        }
        data_ << '\n';
    }

private:
    friend class InsertAfterFirstOccurrence;
    LoggingStream(std::ostream& out) : data_(out), before_(), after_() {}

    std::basic_ostringstream<char> data_;
    std::vector<std::string> before_;
    std::vector<std::string> after_;
    std::atomic<size_t> num_operations_{0};
};

class InsertAfterFirstOccurrence {
public:
    void operator()(const std::forward_list<std::string>& list, const std::string& target, const std::string& value, const std::function<void(const std::string&)>& callback) {
        if (target.empty()) {
            throw std::invalid_argument("Target string cannot be empty.");
        }
        LoggingStream logging(std::cout);
        logging << "Inserting '" << value << "' after the first occurrence of '" << target << "'...";
        auto it = list.begin();
        bool found = false;
        logBefore(it, logging);
        while (it != list.end()) {
            if (*it == target) {
                found = true;
                break;
            }
            ++it;
            logNext(it, logging);
        }
        if (!found) {
            logAddToEnd(list, value, logging);
        } else {
            auto nextIt = std::next(it);
            list.insert(nextIt, value);
            logAfterInsertion(it, nextIt, value, logging);
            if (callback) {
                callback(target);
            }
        }
        logging.print();
    }

private:
    void logBefore(const std::forward_list<std::string>::iterator& it, LoggingStream& logging) const {
        logging << "before: ";
        if (it != list_.end()) {
            for (; it != list_.begin(); --it) {
                logging << *it << ' ';
            }
        }
    }

    void logNext(const std::forward_list<std::string>::iterator& it, LoggingStream& logging) const {
        if (it != list_.end()) {
            logging << *(it++) << ' ';
        }
    }

    void logAddToEnd(const std::forward_list<std::string>& list, const std::string& value, LoggingStream& logging) const {
        logging << "adding to end: '" << value << "'";
        list_.push_back(value);
    }

    void logAfterInsertion(const std::forward_list<std::string>::iterator& it,
                           const std::forward_list<std::string>::iterator& nextIt,
                           const std::string& value, LoggingStream& logging) const {
        logging << "after insertion: ";
        for (; it != list_.end(); ++it) {
            logging << *it << ' ';
        }
    }

    mutable std::mutex mtx_;
    std::forward_list<std::string> list_;
};

void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value, const std::function<void(const std::string&)>& callback) {
    std::unique_ptr<InsertAfterFirstOccurrence> func(new InsertAfterFirstOccurrence());
    func->list_ = list;
    func->operator()(list, target, value, callback);
}
