const axios = require('axios'); // Import axios for making HTTP requests
const { performance } = require('perf_hooks'); // Import perf_hooks for measuring execution time

async function customReduce(arr, initialValue, callback, apiUrl) {
  let currentValue = initialValue;
  const chunkSize = Math.min(Math.floor(arr.length / 10), 10); // Set default chunk size to process data in chunks for better performance

  for (let i = 0; i < arr.length; i += chunkSize) {
    const chunk = arr.slice(i, i + chunkSize);
    const startTime = performance.now();

    try {
      const response = await axios.post(apiUrl, { numbers: chunk });
      currentValue = callback(currentValue, response.data);

      console.log(`API call completed successfully with a latency of ${performance.now() - startTime}ms`);
    } catch (error) {
      console.error(`Error occurred while making API call: ${error}`);
    }
  }

  return currentValue;
}
```

