using System;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Linq;

namespace WebsiteManager
{
    public class WebsiteConfigurer
    {
        private readonly HttpClient _httpClient;
        private const string WebConfigFile = "web.config";

        public WebsiteConfigurer(HttpClient httpClient)
        {
            _httpClient = httpClient;
        }

        public async Task<string> AddAndStartWebsite(string directoryPath, string siteName, string applicationPoolName)
        {
            if (string.IsNullOrWhiteSpace(directoryPath))
                throw new ArgumentException("Directory path is required.", nameof(directoryPath));

            if (!Directory.Exists(directoryPath))
                throw new DirectoryNotFoundException($"The directory '{directoryPath}' was not found.");

            if (!File.Exists(Path.Combine(directoryPath, WebConfigFile)))
                return null;

            var response = await _httpClient.PostAsJsonAsync($"https://iisconfigservice/api/websites", new { DirectoryPath = directoryPath, SiteName = siteName, ApplicationPoolName = applicationPoolName });

            if (!response.IsSuccessStatusCode)
                throw new HttpRequestException($"Failed to add website with status code {response.StatusCode}.");

            return siteName;
        }
    }
}
```

