import java.net.URI;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.Route;
import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Retrofit;
import retrofit2.converter.gson.GsonConverterFactory;

public class UserDataAggregator {
    private static final int MAX_CONNECTIONS = 100;
    private static final Duration RETRY_BACKOFF = Duration.ofSeconds(2);
    private static final Duration JITTER = Duration.ofMillis(100);
    private final Map<String, ApiService> apiServices;
    private final ExecutorService executor;

    public UserDataAggregator() {
        this.apiServices = new HashMap<>();
        this.executor = Executors.newFixedThreadPool(MAX_CONNECTIONS);
    }

    public void addApiService(String apiKey, String baseUrl, String authToken) {
        Retrofit retrofit = new Retrofit.Builder()
                .baseUrl(URI.create(baseUrl))
                .client(new OkHttpClient())
                .addConverterFactory(GsonConverterFactory.create())
                .build();

        ApiService apiService = retrofit.create(ApiService.class);
        apiService.setAuthToken(authToken);
        this.apiServices.put(apiKey, apiService);
    }

    public void fetchUserData(List<String> userIds) {
        PriorityQueue<Runnable> priorityQueue = new PriorityQueue<>(() -> (r1, r2) -> {
            ApiTask task1 = (ApiTask) r1;
            ApiTask task2 = (ApiTask) r2;
            int comparison = Integer.compare(task1.apiService.getResponseTime(), task2.apiService.getResponseTime());
            if (comparison != 0) {
                return comparison;
            }
            return Integer.compare(task1.userId, task2.userId);
        });

        for (String userId : userIds) {
            ApiTask apiTask = new ApiTask(this, userId);
            priorityQueue.add(apiTask);
        }

        while (!priorityQueue.isEmpty()) {
            Runnable task = priorityQueue.poll();
            if (task != null) {
                executor.submit(task);
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    // API service interface and implementation omitted for brevity
}

class ApiTask implements Runnable {
    private final UserDataAggregator aggregator;
    private final String userId;
    private ApiService apiService;
    private int retryCount = 0;

    public ApiTask(UserDataAggregator aggregator, String userId) {
        this.aggregator = aggregator;
        this.userId = userId;
    }

    @Override
    public void run() {
        synchronized (this) {
            if (apiService == null || retryCount >= 5) {
                return;
            }

            Call<UserData> call = apiService.getUserData(userId);
            call.enqueue(new Callback<UserData>() {
                @Override
                public void onResponse(Call<UserData> call, Response<UserData> response) {
                    if (response.isSuccessful()) {
                        // Handle successful response here
                    } else {
                        synchronized (ApiTask.this) {
                            ApiTask.this.retryCount++;
                            apiService = aggregator.getApiServices().get(apiService.getApiKey());
                            if (apiService != null) {
                                ApiTask.this.run();
                            }
                        }
                    }
                }

                @Override
                public void onFailure(Call<UserData> call, Throwable t) {
                    synchronized (ApiTask.this) {
                        ApiTask.this.retryCount++;
                        apiService = aggregator.getApiServices().get(apiService.getApiKey());
                        if (apiService != null) {
                            ApiTask.this.run();
                        }
                    }
                }
            });
        }
    }
}
```

