const { execPromise } = require('child_process');
const fs = require('fs');
const chokidar = require('chokidar');
const colors = require('colors');

async function execCommand(command, args, outputFile, envVars, retries = 3) {
  let attempts = 0;

  return new Promise(async (resolve, reject) => {
    const logger = console[attempts < retries ? 'log' : 'error'];

    try {
      const options = {
        shell: true,
        env: { ...process.env, ...envVars },
        maxBuffer: 1024 * 1024 // 1MB max buffer to avoid memory issues
      };

      const { stdout, stderr } = await execPromise(command, args, options);

      if (stderr) {
        logger(`Error executing command:\n${colors.red(stderr.toString())}`);
      }

      fs.writeFileSync(outputFile, stdout);
      logger(`Command output saved to ${outputFile}`);
      resolve();
    } catch (error) {
      if (attempts < retries) {
        attempts++;
        setTimeout(() => execCommand(command, args, outputFile, envVars, retries), 5000); // Retry every 5 seconds
      } else {
        logger(`Failed to execute command after ${retries} attempts:\n${colors.red(error)}`);
        reject(error);
      }
    }
  });
}

module.exports = { execCommand };
```

This module uses the `child_process`, `fs`, `chokidar`, and `colors` libraries. It defines an `execCommand` function that takes a command, arguments, output file path, environment variables (optional), and retry count (default 3). The function returns a Promise which resolves when the command is executed successfully and writes its output to the specified file or rejects if the command fails after the number of retries.

