#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

// Helper function to check if file exists
int fileExists(const char *path) {
    struct stat buffer;
    return (stat(path, &buffer) == 0);
}

// Helper function to create directory
int makeDir(const char *path) {
    mode_t mode = 0755;
    if (mkdir(path, mode) && errno != EEXIST) return -1;
    return 0;
}

// Helper function to execute command
int execCommand(const char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Failed to fork");
        return 1;
    } else if (pid == 0) {
        // Child process
        if (execlp(command, command, NULL) < 0) {
            perror("Failed to execute command");
            _exit(EXIT_FAILURE);
        }
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) return WEXITSTATUS(status);
    }

    return 1; // Should not reach here
}

// Helper function to validate PDF file
int validatePdf(const char *path) {
    int result = system((const char *)"pdfinfo " + std::string(path));
    if (result != 0) return 1;
    return 0;
}

int convertJpegToPdf(const char *jpegPath, const char *pdfPath, int compressionLevel) {
    // Check if JPEG file exists
    if (!fileExists(jpegPath)) {
        perror("Input JPEG file does not exist");
        return 1;
    }

    // Ensure output directory for PDF exists and create it if necessary
    char *dirPath = strdup(pdfPath);
    size_t lastSlashPos = strlen(dirPath) - 1;
    while (lastSlashPos > 0 && dirPath[lastSlashPos] == '/') {
        lastSlashPos--;
    }
    char *outputDir = strndup(dirPath, lastSlashPos);

    if (!fileExists(outputDir)) {
        if (makeDir(outputDir) != 0) {
            perror("Failed to create output directory");
            free(outputDir);
            free(dirPath);
            return 1;
        }
    }

    // Convert JPEG to PDF using third-party tool with specified compression level
    char *command = (char *) malloc(strlen(jpegPath) + strlen("image2pdf -q ") + sizeof(compressionLevel) + strlen(outputDir) + strlen(pdfPath) + 2);
    sprintf(command, "image2pdf -q %d \"%s\" \"%s/%s\"", compressionLevel, jpegPath, outputDir, pdfPath);

    int result = execCommand(command);
    free(command);

    // Validate PDF file after conversion process
    if (result == 0 && validatePdf(pdfPath) != 0) {
        perror("Output PDF is invalid");
        return 1;
    }

    free(dirPath);
    free(outputDir);

    // Return 0 if the conversion is successful and output PDF meets certain quality criteria, else return 1
    return result;
}
```

