#include <log/LoggingSystem.h> // Replace with your actual logging system header

class ParallelExecutor {
public:
    ParallelExecutor(size_t maxConcurrent, LoggingSystem& log)
        : _maxConcurrent(maxConcurrent), _log(log) {}

    template<typename Function, typename... Args>
    std::future<void> enqueue(Function&& func, Args&&... args) {
        using namespace std;
        auto task = make_shared<packaged_task<void(Args...)>>((Function)std::forward<Function>(func), std::forward<Args>(args)...);
        auto fut = task->get_future();
        unique_lock<mutex> lock(_queue_mutex);
        _commands.emplace([task, this]() mutable {
            _log.debug("Executing command: {}", toString(task->get_deferred()));
            try {
                task->get_deferred()();
            } catch (const exception& e) {
                _log.error("Error executing command: {}", toString(e));
            }
            lock.unlock();
            _notFull.notify_one();
        });
        _notFull.wait(lock);
        return fut;
    }

    void wait() {
        unique_lock<mutex> lock(_queue_mutex);
        while (!_commands.empty())
            _notEmpty.wait(lock);
        _log.info("All commands finished execution.");
    }

private:
    size_t _maxConcurrent;
    LoggingSystem& _log;
    mutex _queue_mutex;
    condition_variable _notEmpty, _notFull;
    queue<function<void()>> _commands;
};

// Example usage
#include <algorithm>
#include <array>
#include <string>
#include <execution>

int command1(int arg1) { return 42 * arg1; }
int command2(int arg2) { return arg2 + 7; }

void executeCommandsInParallel(ParallelExecutor& executor, const std::vector<std::string>& commands, LoggingSystem& log) {
    std::array args = {{3, 4}};
    auto commandList = std::vector<decltype(command1)>({[&](auto& arg) { return bind(command1, arg); }, [&](auto& arg) { return bind(command2, arg); } });
    std::transform(commands.cbegin(), commands.cend(), args.cbegin(), executor.template enqueue<decltype(commandList[0]), decltype(args[0])>, executor);
    executor.wait();
}
```

