/**
 * @function chunkCopy
 * @description Copies a specified number of bytes from a list of buffered data chunks into a new buffer without modifying the original chunks.
 * @param {Buffer[]} chunks - An array of buffered data chunks to be copied.
 * @param {number} start - The starting index for the copy operation.
 * @param {number} end - The ending index (exclusive) for the copy operation.
 * @returns {Promise<Buffer>} A new buffer containing the specified bytes from the provided data chunks.
 */
const chunkCopy = async (chunks, start, end) => {
  const bufLength = end - start;
  let resultBuf = Buffer.alloc(bufLength);

  for (let i = start; i < end && i < chunks.length; ++i) {
    const offset = i - start;
    const chunkStart = offset * chunks[0].length;
    const copyEnd = chunkStart + bufLength;
    resultBuf.fill(chunks[i], chunkStart, copyEnd);
  }

  return resultBuf;
};

/**
 * @function uploadFromUrl
 * @description Upload a file from the given URL to AWS S3 using concurrent requests.
 * @param {string} url - The URL of the file to be uploaded.
 * @param {string} bucketName - The name of the S3 bucket where the file will be stored.
 * @param {string} keyName - The name for the object in S3.
 * @returns {Promise<void>} A promise that resolves when the file is uploaded successfully or rejects if an error occurs.
 */
const uploadFromUrl = async (url, bucketName, keyName) => {
  // Fetch the file from the URL and create read stream
  const response = await fetch(url);
  const stream = response.body;

  // Create a write stream in S3
  const s3WriteStream = s3.createWriteStream({
    Bucket: bucketName,
    Key: keyName
  });

  // Create a pipeline between the read stream and write stream to perform the upload
  await promisify(stream.pipe)(s3WriteStream);
};

// Export the functions for public usage
module.exports = {
  chunkCopy,
  uploadFromUrl
};
