#include <stdio.h>
#include <string.h>
#include <assert.h>

char* appendSlashIfValid(const char *inputStr, size_t limit) {
    // Validate inputStr and ensure it's not a null pointer before proceeding.
    if (!inputStr) {
        fprintf(stderr, "Input string cannot be NULL.\n");
        return "";
    }

    // Check for negative or invalid limits and handle appropriately.
    if (limit < 1) {
        fprintf(stderr, "Invalid limit value: %zu\n", limit);
        return "";
    }

    size_t strLen = strlen(inputStr);

    // If the string is too long or at the limit - 1, don't append a slash.
    if (strLen >= limit)
        return inputStr;

    // Allocate memory for the new string with an extra byte for the '/'.
    char* newStr = malloc(strLen + 2);
    if (!newStr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return "";
    }

    // Copy inputStr to the new string and append a '/' at the end.
    strcpy(newStr, inputStr);
    newStr[strLen] = '/';
    newStr[strLen + 1] = '\0';

    return newStr;
}
