// main.rs
use std::env;
use std::sync::{Arc, RwLock};
use tokio::runtime::Runtime;
use reqwest::Client;
use serde::{Deserialize, Serialize};
use lru_cache::LruCache;
use confy::{Conf, Loader};
use thiserror::Error;

mod api;
mod cache;
mod config;
mod logger;

#[tokio::main]
async fn main() -> Result<(), Error> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        println!("Usage: {} <type> <id>", args[0]);
        return Ok(());
    }

    let config = load_config().unwrap();
    let client = Client::new().bearer_auth(config.api_key.as_str());
    let cache = Arc::new(RwLock::new(cache::LruCache::new(config.cache_size)));

    let rt = Runtime::new().unwrap();
    let fut = api::fetch(&client, &cache, args[1].as_str(), args[2].parse::<i32>().unwrap())
        .in_current_task()
        .fuse();

    rt.block_on(async {
        match fut.await {
            Ok(result) => {
                logger::log(&format!("{} fetched successfully", args[1]));
                println!("{}", serde_json::to_string_pretty(&result).unwrap());
            }
            Err(e) => match e.source() {
                Some(reqwest::Error::Connect(err)) => {
                    logger::log(&format!("Failed to connect: {}", err));
                }
                Some(reqwest::Error::FromResponse(res, _)) => {
                    logger::log(&format!(
                        "Received invalid API response: {} {}",
                        res.status(),
                        res.text().await?.trim()
                    ));
                }
                Some(err) => {
                    logger::log(&format!("Internal error: {}", err));
                }
                None => unreachable!(),
            },
        }
    });

    Ok(())
}
