   void getExtension(char* extension, const char* filename) {
       size_t lastDot = strlen(filename) - 1;
       while (lastDot > 0 && filename[lastDot] == '.') lastDot--;
       if (lastDot == 0) strcpy(extension, "");
       else strncpy(extension, filename + lastDot, sizeof(extension));
   }

   char* generateCompatibleFilename(const char* inputPath) {
       static char timestamp[19];
       time_t rawtime;
       struct tm *timeinfo;

       char extension[5], newExtension[10];
       getExtension(extension, inputPath);
       snprintf(newExtension, sizeof(newExtension), "%03d%s", strlen(extension) > 2 ? strlen(extension) : (strlen(extension) == 0 ? 3 : 0), extension);

       if (!validatePath(inputPath)) return NULL;

       rawtime = time(NULL);
       timeinfo = localtime(&rawtime);
       strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

       SHA256_CTX ctx;
       struct hash_data hash;
       unsigned char rawHash[SHA256_DIGEST_LENGTH];
       unsigned char* filenameData = strdup(inputPath);
       sha256(filenameData, strlen(filenameData), &hash);
       memcpy(rawHash, hash.h, SHA256_DIGEST_LENGTH);

       // Combine timestamp and hash to create the new filename
       size_t newLength = strlen(timestamp) + SHA256_DIGEST_LENGTH * 2;
       char* result = (char*)malloc(newLength + strlen(newExtension));
       if (!result) return NULL;

       memcpy(result, timestamp, strlen(timestamp));
       size_t hashPos = strlen(timestamp);
       for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
           sprintf(&result[hashPos + i * 2], "%02x", rawHash[i]);
       }
       strcat(result, newExtension);

       free(filenameData);
       return result;
   }
