        public AESHelper(byte[] key, byte[] iv)
        {
            using (var aes = Aes.Create())
            {
                aes.Key = key;
                aes.IV = iv;
                _encryptor = aes.CreateEncryptor(aes.Key, aes.IV);
                _decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            }
        }

        public byte[] Decrypt(byte[] ciphertext)
        {
            using (var ms = new MemoryStream(ciphertext))
            {
                using (var cs = new CryptoStream(ms, _decryptor, CryptoStreamMode.Read))
                {
                    return cs.ToArray();
                }
            }
        }
    }

    public string DecryptMessage(string ciphertextBase64, ExternalKeyManagement keyManager, DecryptionParameters decryptionParams)
    {
        try
        {
            var key = decryptionParams.Key;
            var iv = decryptionParams.IV;
            var paddingScheme = decryptionParams.PaddingScheme;

            if (string.IsNullOrEmpty(ciphertextBase64))
                throw new ArgumentException("Ciphertext can't be empty.", nameof(ciphertextBase64));
            if (key == null || iv == null)
                throw new ArgumentNullException(nameof(decryptionParams), "Key and IV are required.");
            if (!Enum.IsDefined(paddingScheme))
                throw new ArgumentOutOfRangeException(nameof(decryptionParams.PaddingScheme), $"Unsupported padding scheme: {decryptionParams.PaddingScheme}");

            var ciphertext = Convert.FromBase64String(ciphertextBase64);
            using (var aesHelper = new AESHelper(key, iv))
            {
                switch (paddingScheme)
                {
                    case PaddingMode.PKCS7:
                        ciphertext = PKCS7Padding.Unpad(ciphertext);
                        break;
                    case PaddingMode.PKCS5:
                        ciphertext = PKCS5Padding.Unpad(ciphertext);
                        break;
