using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace SecureCommunication
{
    public class AesGcmEncryptor : IDisposable
    {
        private readonly Aes _aes;
        private readonly RandomNumberGenerator _rng;
        private readonly ICryptoTransform _encryptor;
        private readonly ICryptoTransform _decryptor;
        private byte[] _key;
        private byte[] _nonce;

        public AesGcmEncryptor(ILogger<AesGcmEncryptor> logger)
        {
            _rng = RandomNumberGenerator.Create();
            _aes = AES.Create();
            _encryptor = _aes.CreateEncoder(_aes.Key, _aes.IV);
            _decryptor = _aes.CreateDecoder(_aes.Key, _aes.IV);
            Logger = logger;
        }

        public AesGcmEncryptor(ILogger<AesGcmEncryptor> logger, byte[] key) : this(logger)
        {
            Key = key;
            _aes.Key = key;
            _encryptor = _aes.CreateEncoder(_key, _rng.GenerateBytes(12));
            _decryptor = _aes.CreateDecoder(_key, _aes.IV);
        }

        public ILogger<AesGcmEncryptor> Logger { get; }

        public byte[] Key { get => _key; set
            {
                if (value == null || value.Length != Aes.KeySize / 8)
                    throw new ArgumentException("Invalid key size.");

                _key = value;
                _aes.Key = _key;
                _encryptor = _aes.CreateEncoder(_key, _rng.GenerateBytes(12));
                _decryptor = _aes.CreateDecoder(_key, _aes.IV);
            } }

        public byte[] Nonce => _nonce ?? (_nonce = _rng.GenerateBytes(12));

        public async Task<byte[]> EncryptAsync(byte[] plainText)
        {
            if (plainText == null || plainText.Length == 0)
                throw new ArgumentException("Plain text cannot be empty or null.");

            var gcm = new GcmBlockEncryption(_encryptor);
            _nonce = Nonce;
            var cipherTextBytes = await gcm.EncryptAsync(plainText, _nonce);
            Logger.LogInformation("Encrypted data: {CipherText}", Convert.ToBase64String(cipherTextBytes));
            return cipherTextBytes;
        }

        public async Task<byte[]> DecryptAsync(byte[] cipherText)
        {
            if (cipherText == null || cipherText.Length == 0)
                throw new ArgumentException("Cipher text cannot be empty or null.");

            var gcm = new GcmBlockEncryption(_decryptor);
            var plainTextBytes = await gcm.DecryptAsync(cipherText, _nonce);
            Logger.LogInformation("Decrypted data: {PlainText}", Convert.ToBase64String(plainTextBytes));
            return plainTextBytes;
        }

        public void Dispose()
        {
            _encryptor?.Dispose();
            _decryptor?.Dispose();
            _aes.Dispose();
            _rng.Dispose();
        }
    }
}
```

