using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using UnityEngine;

public class AsyncFileReaderManager
{
    private int _minValue;
    private int _maxValue;

    public AsyncFileReaderManager(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public override string ToString() => $"Range: [{_minValue}, {_maxValue}]";

    private async Task<(IEnumerable<FileInfo>, ulong)> GetFilesAsync(string directoryPath, long sizeLimit)
    {
        var fileInfos = new List<FileInfo>();
        var totalSize = 0L;

        await Directory.EnumerateFiles(directoryPath, "*", SearchOption.AllDirectories)
            .ParallelForEachAsync(async filePath =>
            {
                try
                {
                    if (File.Exists(filePath))
                    {
                        var fileInfo = new FileInfo(filePath);
                        totalSize += fileInfo.Length;
                        fileInfos.Add(fileInfo);
                    }
                }
                catch (Exception ex)
                {
                    Debug.LogError($"Error reading file: {filePath}, Error: {ex}");
                }
            });

        return (fileInfos, totalSize);
    }

    public async Task<string> ReadFilesAsync(string directoryPath, long sizeLimit)
    {
        if (!Directory.Exists(directoryPath))
        {
            Debug.LogError($"Invalid directory path: {directoryPath}");
            return null;
        }

        var (files, totalSize) = await GetFilesAsync(directoryPath, sizeLimit);

        if (totalSize <= sizeLimit)
        {
            var content = string.Join("\n", files.Select(file => File.ReadAllTextAsync(file.FullName).Result));
            return $"{content}\n".TrimEnd('\n') + Path.DirectorySeparatorChar;
        }

        return null;
    }

    public int RandomInclusive(int min, int max) => UnityEngine.Random.Range(Mathf.Clamp(min, _minValue, _maxValue), Mathf.Clamp(max, _minValue, _maxValue));

    public int RandomExclusive(int min, int max) => UnityEngine.Random.Range(Mathf.Clamp(min + 1, _minValue, _maxValue), Mathf.Clamp(max, _minValue, _maxValue));
}
