TiffImageInfo parseTIFF(const std::vector<uint8_t>& data) {
    tdata_t buf;
    tsize_t size = static_cast<tsize_t>(data.size());
    buf.datatype = TIFF_BYTE;
    buf.data = const_cast<tdata_t::value_type*>(reinterpret_cast<const tdata_t::value_type*>(data.data()));
    buf.count = size;
    buf.planarconfig = 1; // single-image

    TIFF* tiff = TIFFOpen(nullptr, "mem", &buf, 0);
    if (!tiff) {
        throw std::runtime_error("Failed to open TIFF file");
    }

    TIFFGetFieldDefault(tiff, TIFFTAG_SAMPLESPERPIXEL) >> samplePerPixel;
    TIFFGetFieldDefault(tiff, TIFFTAG_BITSPERSAMPLE) >> bitsPerSample;

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        throw std::runtime_error("Unsupported number of bits per sample");
    }

    int imageWidth, imageHeight;
    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &imageWidth);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &imageHeight);

    uint16_t sampleValue;
    std::vector<uint16_t> currentSample;

    tsize_t row = 0;
    while (TIFFReadScanline(tiff, buf.data, static_cast<tsize_t>(imageWidth), row++) > 0) {
        for (size_t col = 0; col < imageWidth; ++col) {
            std::copy_n(buf.data + (row * imageWidth + col) * bitsPerSample / 8, bitsPerSample, std::back_inserter(currentSample));
            switch (bitsPerSample) {
                case 1:
                    sampleValue = currentSample[0] >> (7 - (samplePerPixel % 8)) & ((1 << (samplePerPixel % 8)) - 1);
                    break;
                case 2:
                    sampleValue = (currentSample[0] << 8 | currentSample[1]) >> (16 - (samplePerPixel * 8));
                    break;
                case 4:
                    sampleValue = *(reinterpret_cast<const uint32_t*>(currentSample.data()));
                    sampleValue >>= (32 - (samplePerPixel * 8));
                    break;
                case 8:
                    sampleValue = *reinterpret_cast<const uint64_t*>(currentSample.data());
                    sampleValue >>= (64 - (samplePerPixel * 8));
                    break;
                default:
                    // Bits per sample 16 is not handled here, it can be added in a similar way as 8-bit case
                    throw std::runtime_error("Unsupported number of bits per sample");
            }
            if (samplePerPixel > 1) {
                currentSampleData.push_back(sampleValue);
            } else {
                // Process the extracted information as needed
            }
        }

        // Check for extra samples and handle them accordingly
    }

    TIFFClose(tiff);
    return TiffImageInfo{bitsPerSample, samplePerPixel};
}

