```javascript
const log = (message) => console.log(`[DataCopier] ${message}`);
const timeLog = (message) => log(`${message} - Start: ${new Date().toISOString()}`);
const timeEndLog = () => log(`- End: ${new Date().toISOString()}`);

class DataCopier {
  constructor(logger) {
    this.logger = logger || console;
  }

  async copyBuffer(dataChunks, length, timeout = 10000) {
    if (length > dataChunks.reduce((acc, chunk) => acc + chunk.length, 0)) {
      throw new Error('Requested number of bytes exceeds total available data');
    }

    let copiedData = Buffer.alloc(length);
    let index = 0;
    let currentTimeout;

    timeLog(`Starting data copy operation`);

    for (const chunk of dataChunks) {
      if (index + chunk.length > length) {
        const sliceLength = length - index;
        chunk.copy(copiedData, index, 0, sliceLength);
        break;
      }

      chunk.copy(copiedData, index, 0, chunk.length);
      index += chunk.length;

      if (currentTimeout) clearTimeout(currentTimeout);
      currentTimeout = setTimeout(() => {
        this.logger.error('Data copy operation timed out');
        throw new Error('Data copy operation timed out');
      }, timeout);
    }

    timeEndLog();

    return copiedData;
  }
}

// Usage example:
const dataCopier = new DataCopier(console);

// Assume we have some dataChunks in the form of Buffer objects
const dataChunks = [Buffer.from('Hello, World!'), Buffer.from(' This is a test')];

dataCopier.copyBuffer(dataChunks, 15)
  .then((copiedData) => {
    // Do something with the copied data
    console.log(`Copied data: ${copiedData.toString()}`);
  })
  .catch((error) => {
    console.error(error.message);
  });
```

