```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <map>
#include <vector>
#include <mutex>
#include <log4cplus/logger.h>
#include <log4cplus/initializer.h>
#include <log4cplus/loggingmacros.h>

typedef struct {
    const char* name;
    void* (*implementation)();
    void* params;
} AlgorithmInfo;

class PluginManager {
private:
    std::map<const char*, AlgorithmInfo*, std::less<>> pluginMap;
    std::mutex pluginsMutex;
    log4cplus::LoggerPtr logger;

public:
    PluginManager() : logger(log4cplus::Logger::getInstance("PluginManager")) {}

    void loadPlugin(const char* pluginName, const char* hashOrCipher) {
        std::unique_lock<std::mutex> lock(pluginsMutex);
        if (pluginMap.count(pluginName)) {
            LOG4CPLUS_ERROR(logger, "Plugin '" << pluginName << "' already loaded.");
            return;
        }
        void* pluginHandle = loadLibrary(pluginName);
        if (!pluginHandle) {
            LOG4CPLUS_ERROR(logger, "Failed to load plugin '" << pluginName << "'. Error: " << std::strerror(errno));
            return;
        }
        AlgorithmInfo* algorithm = reinterpret_cast<AlgorithmInfo*>(dlsym(pluginHandle, hashOrCipher));
        if (!algorithm) {
            LOG4CPLUS_ERROR(logger, "Plugin '" << pluginName << "' does not export required symbol: " << hashOrCipher);
            freeLibrary(pluginHandle);
            return;
        }
        pluginMap[pluginName] = algorithm;
        lock.unlock();
    }

    const std::vector<AlgorithmInfo*>& getAvailableAlgorithms() {
        std::unique_lock<std::mutex> lock(pluginsMutex);
        return pluginMap;
    }

private:
    void* loadLibrary(const char* name) {
        void* handle = dlopen(name, RTLD_LAZY | RTLD_GLOBAL);
        if (!handle) {
            return nullptr;
        }
        return handle;
    }

    void freeLibrary(void* handle) {
        dlclose(handle);
    }
};
```
