1. C# Triple DES Decryption Class (TripleDESDecryptor.cs):

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecryptor
{
    private readonly ConcurrentDictionary<string, (TripleDESCryptoServiceProvider Key, byte[] IV)> _decryptionKeys = new ConcurrentDictionary<string, (TripleDESCryptoServiceProvider Key, byte[] IV)>();

    public void RegisterKey(string userType, string messageType, TripleDESCryptoServiceProvider key, byte[] iv)
    {
        _decryptionKeys[GetKeyHash(userType, messageType)] = (key, iv);
    }

    private string GetKeyHash(string userType, string messageType) => SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes($"{userType}-{messageType}"));

    public byte[] DecryptBase64(string input, string userType, string messageType)
    {
        if (!_decryptionKeys.TryGetValue(GetKeyHash(userType, messageType), out var (key, iv)))
            throw new Exception($"No decryption key found for user type: {userType}, message type: {messageType}");

        using var msDecrypt = new MemoryStream(Convert.FromBase64String(input));
        using var msEncrypt = new MemoryStream();
        using (var tsDecrypt = new CryptoStream(msDecrypt, key.CreateDecryptor(key.Key, iv), CryptoStreamMode.Read))
        {
            tsDecrypt.CopyTo(msEncrypt);
        }
        return msEncrypt.ToArray();
    }
}
