import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandRunner {
    private static final String LOG_FILE = "command_log.txt";
    private static ExecutorService executor = Executors.newCachedThreadPool();
    private static Properties props;
    private static Map<String, String> envVars;

    public static void main(String[] args) {
        try {
            loadConfig();
            validateCommands();
            List<String> commands = getCommandsFromConfig();
            runCommands(commands);
        } catch (IOException | InterruptedException | IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        } finally {
            executor.shutdown();
        }
    }

    private static void loadConfig() throws IOException {
        props = new Properties();
        Path configFile = Paths.get(System.getProperty("user.dir") + "/command_config.properties");
        props.load(new FileReader(configFile.toFile()));
    }

    private static void validateCommands() throws IllegalArgumentException {
        // Implement the validation logic here based on the allowed commands list from the config file
    }

    private static List<String> getCommandsFromConfig() {
        List<String> commands = new ArrayList<>();
        for (String command : props.getProperty("commands").split("\n")) {
            if (!command.isEmpty()) {
                commands.add(command);
            }
        }
        return commands;
    }

    private static void runCommands(List<String> commands) throws IOException, InterruptedException {
        for (String command : commands) {
            executor.submit(() -> executeCommand(command));
        }
    }

    private static void executeCommand(String command) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder(command.split(" "));
        pb.redirectErrorStream(true);

        if (envVars != null && !envVars.isEmpty()) {
            for (Map.Entry<String, String> entry : envVars.entrySet()) {
                pb.environment().put(entry.getKey(), entry.getValue());
            }
        }

        Process process = pb.start();

        BufferedReader stdOutput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        int timeout = Integer.parseInt(props.getProperty("timeout"));
        long startTime = System.currentTimeMillis();
        while (System.currentTimeMillis() - startTime < timeout && !process.exitValue() == 0) {
            // Do nothing, just wait for the command to complete within the specified timeout
        }

        if (process.exitValue() != 0) {
            retryCommand(command);
        } else {
            logOutputAndError(stdOutput, stdError);
            // Implement monitoring system signal here
        }
    }

    private static void retryCommand(String command) throws InterruptedException {
        int retries = Integer.parseInt(props.getProperty("retries"));
        if (retries > 0) {
            Thread.sleep(Long.parseLong(props.getProperty("retry_interval")) * 1000);
            executeCommand(command);
        } else {
            throw new RuntimeException("Maximum retries reached for command: " + command);
        }
    }

    private static void logOutputAndError(BufferedReader stdOutput, BufferedReader stdError) throws IOException {
        String line;
        while ((line = stdOutput.readLine()) != null) {
            System.out.println(line);
            logToFile(line);
        }
        while ((line = stdError.readLine()) != null) {
            System.err.println(line);
            logToFile(line);
        }
    }

    private static void logToFile(String message) throws IOException {
        Files.write(Paths.get(LOG_FILE), (message + "\n").getBytes());
    }
}
```

