use diesel::*;
use dotenv::dotenv;
use reqwest::blocking::{get, Client};
use serde_json::from_str;
use std::env;
use tokio::runtime::Runtime;

// Modules
mod config;
mod database;
mod api;
mod error;

use self::config::Config;
use self::database::{DatabaseConnection, RunQuery};
use self::api::fetch_data;
use self::error::Result;

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize configuration and environment variables
    dotenv().ok();

    let config = Config::from_env().unwrap_or_else(|_| Config::default());

    // Initialize the database connection pool
    let db_connection = DatabaseConnection::establish(&config.database_url).await?;

    // Create a new runtime for managing tasks and resources
    let rt = Runtime::new().unwrap();

    // Execute the main task, spawning sub-tasks as needed
    rt.block_on(async move {
        loop {
            let config = Config::from_env().unwrap_or_else(|_| Config::default());
            match config.api_url.is_some() {
                true => run_task(config, db_connection).await?,
                false => break,
            }
        }
    })
}

async fn run_task(config: Config, db_connection: DatabaseConnection) -> Result<()> {
    // Fetch data from the API and store it in the database
    let response = get(&config.api_url.unwrap())?.text()?.await?;
    let data: ApiResponse = from_str(&response).unwrap();

    // Perform database operations with proper handling of transactions and errors
