// External data source interface
class DataSource {
public:
    virtual std::string getTarget() const = 0;
    virtual std::string getValue() const = 0;
};

class Logger {
private:
    static std::mutex mtx;
    static std::ostream& stream;
    int logLevel;

public:
    Logger(int level, std::ostream& os) : logLevel(level), stream(os) {}

    void logOperationSuccess(const std::string& target, const std::string& value, const std::forward_list<std::string>& list) {
        if (logLevel >= 1) {
            // Log the operation's success details.
        }
    }

    void logOperationFailure(const std::exception& ex) {
        if (logLevel >= 2) {
            stream << "Error: " << ex.what() << "\n";
        }
    }
};

std::mutex Logger::mtx;
std::ostream& Logger::stream = std::cout;

// Your function to insert value after the first occurrence of target in the forward list.
void insertAfterFirstOccurrence(std::forward_list<std::string> &list, const DataSource &dataSource, const Logger &logger, std::function<void(const std::string&)> callback) {
    auto it = list.begin();
    bool foundTarget = false;

    std::unique_lock<std::mutex> lock(Logger::mtx); // Synchronize logging operations.

    while (it != list.end()) {
        if (*it == dataSource.getTarget()) {
            foundTarget = true;
            list.insert After(it, dataSource.getValue());
            break;
        }
        it++;
    }

    if (!foundTarget) {
        lock.unlock(); // Unlock the mutex for appending to the end of the list.
        list.push_back(dataSource.getValue());
    }

    if (callback) callback(dataSource.getTarget());

    if (foundTarget) {
        logger.logOperationSuccess(dataSource.getTarget(), dataSource.getValue(), list);
    } else {
        lock.lock(); // Reacquire the mutex for logging after appending to the end of the list.
        logger.logOperationFailure(std::runtime_error("Target not found"));
    }
}
