const blueslip = require('blueslip');
const { Series } = require('async/series');
const { Parallel } = require('async/parallel');
const _ = require('lodash');

class TestRunner {
  constructor(configService) {
    this.configService = configService || {};
    this.testResults = new Map();
  }

  async runTests({ label, f, parallel = false }) {
    const moduleName = _.get(this.configService, 'module', '');
    if (!moduleName) {
      throw new Error('No module specified.');
    }

    let testResultsForModule;
    if (this.testResults.has(moduleName)) {
      testResultsForModule = this.testResults.get(moduleName);
    } else {
      const module = require(moduleName);
      testResultsForModule = new Map();
      this.testResults.set(moduleName, testResultsForModule);
    }

    let testResult;
    try {
      blueslip.reset();
      const testLabel = `${label} (Module: ${moduleName})`;
      console.log(`Running test: ${testLabel}`);

      let results;
      if (parallel) {
        const tests = Array.from(testResultsForModule.keys());
        const testFunctions = tests.map(test => () => f({ label: test, module }));
        results = await new Parallel(testFunctions).execute();
      } else {
        results = await new Series((next) => {
          const testFunction = () => {
            blueslip.reset();
            return f({ label, module });
          };
          testResultsForModule.set(label, { passed: true });
          testFunction((err, result) => {
            if (err) {
              console.error(`Test ${testLabel} failed with error:\n${err.stack}`);
              testResultsForModule.set(label, { passed: false, error: err });
            } else {
              console.log(`Test ${testLabel} passed`);
            }
            next();
          });
        }).execute();
      }

      const passed = results.every((result) => result);
      testResult = { passed, label };
    } catch (error) {
      console.error(`An error occurred while running tests:\n${error.stack}`);
      testResult = { passed: false, error };
    } finally {
      if (!testResult.error) {
        console.log(`Test ${label} complete`);
      }
    }

    return testResult;
  }

  async runAllTests() {
    let testsRunning = 0;
    const results = [];

    for (const [moduleName, testResults] of this.testResults.entries()) {
      for (const [testLabel, testResult] of testResults.entries()) {
        testsRunning++;
        const runTestResult = await this.runTests({ label: testLabel, f: () => testResult.fn, parallel: true });
        results.push(runTestResult);
        if (testsRunning === 1) {
          console.log(`\nRunning all tests for ${moduleName}`);
        }
      }
    }

    const passedCount = results.filter(({ passed }) => passed).length;
    const failedCount = results.filter(({ passed }) => !passed).length;

    console.log(`\nTest summary:`);
    console.log(`Passed: ${passedCount}`);
    console.log(`Failed: ${failedCount}`);
  }
}
```

