using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Xml.Schema;

public static class XmlHelper
{
    private static readonly XmlReaderSettings _xmlReaderSettings = new XmlReaderSettings
    {
        DtdProcessing = DtdProcessing.Parse,
        ValidationType = ValidationType.Auto,
        XmlResolver = null,
    };

    public static XElement GetFirstMatchingElement(string xpathQuery, string filePath = null, string xmlContent = null)
    {
        if (string.IsNullOrEmpty(xpathQuery))
            throw new ArgumentException("XPath query cannot be empty.");

        var xmlToParse = string.IsNullOrEmpty(filePath) && string.IsNullOrEmpty(xmlContent) ?
            throw new ArgumentException("Either filePath or xmlContent must be provided.") :
            xmlContent;

        using (var reader = XmlReader.Create(new StringReader(xmlToParse), _xmlReaderSettings))
        {
            var xmlDocument = new XmlDocument();
            xmlDocument.Load(reader);
            var namespaceManager = new XmlNamespaceManager(xmlDocument.NameTable);
            namespaceManager.AddNamespace("ns", "your-namespace-prefix"); // Replace with your desired namespace prefix

            var query = new XPathNavigator(xmlDocument.CreateNavigator(), namespaceManager);
            var nodes = query.Select(xpathQuery).Cast<XPathNodeIterator>().Select(n => n.Current).ToList();

            if (nodes.Count == 0)
                throw new Exception("No elements matching the XPath query were found.");
            else if (nodes.Count > 1)
                throw new Exception("Multiple elements matching the XPath query were found.");

            return nodes[0] as XElement;
        }
    }
}
