    if (SSL_CTX_set_cipher_list(ctx, cipher->cipher_list) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return 1; // Error setting the chosen cipher suite
    }

    if (SSL_CTX_set_default_hash(ctx, hash->digest()) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return 1; // Error setting the chosen hashing algorithm
    }

    if (SSL_CTX_ctrl_set_options(ctx, SSL_OP_CIPHER_SERVER_PREFERENCE) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_CTX_free(ctx);
        return 1; // Error setting the cipher preference option
    }

    if (SSL_CTX_ctrl_set_options(ctx, SSL_OP_NO_COMPRESSION) <= 0) {
        ERR_print_errors_fp(stderr);
