        {
            if (_cache.TryGetValue(source.Url, out var cached))
            {
                return cached;
            }

            XElement fetched = await fetcher(source).ConfigureAwait(false);
            _cache[source.Url] = fetched;

            // Update the last updated time and start a timer to evict this entry when needed
            source.LastUpdated = DateTime.UtcNow;

            return fetched;
        }

