            {
                // Log errors, handle retries or fallbacks here
                throw new Exception($"Error fetching XML data: {ex.Message}", ex);
            }
        }
    }

    public class XPathParser
    {
        private readonly XmlSource[] _sources;
        private readonly XPathCache _cache;
        private readonly XPathFetcher _fetcher;

        public XPathParser(TimeSpan cacheDuration, params XmlSource[] sources)
        {
            _cache = new XPathCache(cacheDuration);
            _fetcher = new XPathFetcher(XDocument.Load);
            _sources = sources;
        }

        public async Task<XElement> ParseAsync(string xpathExpression)
        {
            var taskList = from source in _sources
                           select _cache.GetCachedOrFetchAsync(source, _fetcher.FetchAsync);

            var tasks = taskList.ToArray();
            await Task.WhenAll(tasks).ConfigureAwait(false);

            var allDocs = tasks.Select(t => t.Result).ToList();

            // Filter out sources that returned empty documents or had errors fetching data
            var nonEmptyDocuments = allDocs.Where(d => d != null && d.Descendants().Any()).ToList();

            if (nonEmptyDocuments.Count > 1)
            {
                throw new Exception("Multiple elements found with the given name.");
            }

            var result = nonEmptyDocuments.FirstOrDefault();
            if (result == null)
            {
                throw new Exception("No element found.");
            }

            // Use XPath to find the first matching element and return it
            return result.XPathSelectElements(xpathExpression).FirstOrDefault();
        }
    }
}
```

