#include <libgen.h> // for basename() and dirname()
#include <fs_library.h> // assumed to provide validatePath function

size_t generateCompatibleFilename(char* originalFilename, char* newFilename) {
    if (!validatePath(originalFilename)) {
        return 0; // invalid input filename
    }

    const size_t maxLength = 255;

    struct timespec timestamp;
    clock_gettime(CLOCK_REALTIME, &timestamp);

    char timestampStr[19];
    sprintf(timestampStr, "%4d%02d%02d_%02d%02d%02d",
            timestamp.tv_sec / 1000,
            timestamp.tv_sec % 1000 / 60,
            timestamp.tv_sec % 1000 % 60,
            timestamp.tv_nsec / 1000000,
            timestamp.tv_nsec % 1000000 / 1000,
            timestamp.tv_nsec % 1000);

    char* dotIndex = strrchr(originalFilename, '.');
    size_t extensionLength = (dotIndex == nullptr) ? 3 : strlen(dotIndex + 1);

    if (extensionLength < 3) {
        const char* extensions[] = {".txt", ".log", ".csv", ".json"};
        for (size_t i = 0; i < sizeof(extensions) / sizeof(char*); ++i) {
            if (strncmp(dotIndex == nullptr ? originalFilename : dotIndex, extensions[i], extensionLength) == 0) {
                strcat(newFilename, extensions[i]);
                break;
            }
        }
    } else {
        strcat(newFilename, dotIndex);
    }

    char* base = basename(originalFilename);
    char* hash = generateHashOfString(base); // implement this function
    strncat(newFilename, hash, maxLength - strlen(timestampStr) - extensionLength - 1);

    strncpy(newFilename + strlen(newFilename), timestampStr, maxLength - strlen(newFilename));

    return strlen(newFilename);
}
