    if (!libssl) {
        log_error("Unable to open the OpenSSL library");
        return 1;
    }

    // Define and initialize the EVP_CIPHER structure
    EVP_CIPHER* cipher = NULL;

    // Allocate memory for the key expansion table
    unsigned char *key_expansion = mmap(NULL, (64 + 128 + 224), PROT_READ|PROT_WRITE, MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
    if (key_expansion == MAP_FAILED) {
        log_error("Unable to allocate memory for key expansion table");
        dlclose(libssl);
        return 1;
    }

    // Check if the specified cipher mode is valid and configure the EVP_CIPHER accordingly
    const char* cipher_mode = getenv("MODE");
    if (strcmp(cipher_mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_mode, "EDE") == 0 || strcmp(cipher_mode, "EDE3") == 0) {
        // Configure EDE or EDE3 mode
        cipher = EVP_des_ede();
        if (strcmp(cipher_mode, "EDE3") == 0) {
            // Set triple encryption flag for EDE3 mode
            EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
            EVP_CIPHER_CTX_set_flags(ctx, EVP_CIPHER_FLAG_ triple_ede);
        }
    } else if (strcmp(cipher_mode, "CFB") == 0) {
        // Parse IV length and value from command-line arguments or environment variables
        int iv_length = ...; // Get IV length
        const unsigned char* iv = getenv("IV");

        // Configure CFB mode with the specified IV
        cipher = EVP_cfb_init(EVP_des_cbc(), NULL, iv, iv_length);
    } else {
        log_error("Invalid cipher mode specified");
        free_evp_cipher(cipher);
        munmap(key_expansion, (64 + 128 + 224));
        dlclose(libssl);
        return 1;
    }

    // Load the encryption/decryption key from an appropriate source
    const unsigned char* key = getenv("KEY");

    // Generate the key expansion table based on the key size
    generate_key_expansion(key_expansion, key, strlen((const char*)key));

    // Initialize the EVP_CIPHER context with the key expansion table
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_set_key(ctx, key_expansion);

    // Perform encryption/decryption operations using the prepared cipher context
    ...

    // Free memory and unload the OpenSSL library
    free_evp_cipher(cipher);
    munmap(key_expansion, (64 + 128 + 224));
    dlclose(libssl);

    return 0;
}
