        {
            _logger = LogManager.GetCurrentClassLogger();
            _maxConcurrentTasks = configuration.GetValue<int>("MaxConcurrentTasks");
            _apiKey = configuration.GetValue<string>("ApiKey");
        }

        public async Task ComputeHashAsync(string input, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentException("Input cannot be null or empty.");

            var md5 = MD5.Create();
            var hashedBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
            var result = BitConverter.ToString(hashedBytes).Replace("-", "").ToLowerInvariant();

            _logger.Debug($"Computed MD5 hash for input: {input}, Result: {result}");
        }

        public async Task<string> ComputeHashAsync(string filePath, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(filePath))
                throw new ArgumentException("File path cannot be null or empty.");

            if (!File.Exists(filePath))
                throw new FileNotFoundException("The specified file does not exist.", filePath);

            using var fileStream = File.OpenRead(filePath);
            var sha256 = SHA256.Create();
            var hashedBytes = await sha256.ComputeHashAsync(fileStream, cancellationToken).ConfigureAwait(false);
            var result = BitConverter.ToString(hashedBytes).Replace("-", "").ToLowerInvariant();

            _logger.Debug($"Computed SHA-256 hash for file: {filePath}, Result: {result}");
        }

        public async Task<string> ComputeHashAsync(string message, string secretKey, CancellationToken cancellationToken)
        {
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Message cannot be null or empty.");
            if (string.IsNullOrEmpty(secretKey))
                throw new ArgumentException("Secret key cannot be null or empty.");

            var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secretKey));
            var hashedBytes = hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
            var result = BitConverter.ToString(hashedBytes).Replace("-", "").ToLowerInvariant();

            _logger.Debug($"Computed HMAC-SHA256 hash for message: {message}, Result: {result}");
        }

