using Microsoft.Extensions.Logging;

public class DatabaseHelper
{
    private readonly ILogger<DatabaseHelper> _logger;
    private readonly string _connectionString;
    private SqlConnection _connection;

    public DatabaseHelper(ILogger<DatabaseHelper> logger, string connectionString)
    {
        _logger = logger;
        _connectionString = connectionString;
    }

    public IDataReader ExecuteCommand(string commandText, Dictionary<string, object> parameters = null)
    {
        var command = BuildCommand(commandText, parameters);

        try
        {
            if (_connection == null || _connection.State != ConnectionState.Open)
            {
                OpenConnection();
            }

            using (var transaction = _connection.BeginTransaction())
            {
                command.Transaction = transaction;
                var reader = command.ExecuteReader();
                if (!reader.HasRows) return reader;

                while (reader.Read())
                {
                    // Process each row here as needed
                }

                transaction.Commit();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while executing command.");
            throw;
        }
    }

    private SqlCommand BuildCommand(string commandText, Dictionary<string, object> parameters = null)
    {
        var command = new SqlCommand();
        command.Connection = _connection;
        command.CommandText = SanitizeInput(commandText);

        if (parameters != null)
        {
            foreach (var param in parameters)
            {
                var match = Regex.Match(commandText, $"@{param.Key}");
                if (!match.Success)
                {
                    command.Parameters.AddWithValue($"@_{param.Key}", param.Value);
                }
                else
                {
                    var index = int.Parse(match.Groups[0].Value.Substring(1));
                    command.Parameters.AddWithValue($"@{index}", param.Value);
                }
            }
        }

        return command;
    }

    private void OpenConnection()
    {
        if (_connection != null && _connection.State == ConnectionState.Open) return;

        var builder = new SqlConnectionStringBuilder(_connectionString);
        if (builder.Pooling == false)
        {
            builder.Pooling = true;
        }

        _connection = new SqlConnection(builder.ToString());
        _connection.Open();
    }

    private string SanitizeInput(string input)
    {
