```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <functional>
#include <mutex>

class Employee {
public:
    explicit Employee(int id) : id_(id), salary_(0.0), department_("") {}

    void setSalary(double newSalary) { salary_ = newSalary; }
    void setDepartment(const std::string& newDepartment) { department_ = newDepartment; }

    int getId() const { return id_; }
    double getSalary() const { return salary_; }
    const std::string& getDepartment() const { return department_; }

private:
    int id_;
    double salary_;
    std::string department_;
};

// Mutex for thread-safety
std::mutex g_mutex;
std::vector<std::unique_ptr<Employee>> employees_;

void updateEmployeeDetails(std::vector<std::unique_ptr<Employee>>& employees, int employeeId, double newSalary, std::string newDepartment, const std::function<void(const Employee&)>& callback) {
    // Lock the mutex to protect shared resources
    std::unique_lock<std::mutex> lock(g_mutex);

    auto it = employees_.begin();
    auto end = employees_.end();

    // Iterate through the vector using std::find_if to find the employee with the given ID
    auto foundEmployee = std::find_if(it, end, [employeeId](const auto& employee) { return employee->getId() == employeeId; });

    if (foundEmployee != end) {
        // If the employee is found, update its details and invoke the callback if provided
        foundEmployee->reset(new Employee(*foundEmployee));
        foundEmployee->get()->setSalary(newSalary);
        foundEmployee->get()->setDepartment(newDepartment);

        if (callback) {
            lock.unlock(); // Unlock the mutex to allow callback function to run without contention
            callback(*foundEmployee->get());
            lock.lock(); // Lock the mutex again to ensure thread-safety when modifying the vector
        }
    } else {
        std::cerr << "Error: Employee with ID " << employeeId << " not found." << std::endl;
    }
}
```

The above code demonstrates a well-organized, scalable, and modular implementation of the `updateEmployeeDetails()` function. It maintains resource management through smart pointers and RAII principles, provides concurrency support using a mutex, integrates with an external system via a callback, and logs operation results safely in a multi-threaded environment.

