        private readonly XmlReaderSettings _xmlSettings;
        private readonly XmlSchemaSet _schemaSet;
        private readonly DbConnection _databaseConnection;
        private readonly ILogger<ConfigLoader> _logger;
        private readonly int _maxSimultaneousDownloads;
        private readonly TimeSpan _retryInterval;
        private readonly string _loggingLevel;

        public ConfigLoader(HttpClient httpClient, XmlReaderSettings xmlSettings, XmlSchemaSet schemaSet, DbConnection databaseConnection, ILogger<ConfigLoader> logger, int maxSimultaneousDownloads = 5, TimeSpan retryInterval = TimeSpan.FromSeconds(2), string loggingLevel = "Information")
        {
            _httpClient = httpClient;
            _xmlSettings = xmlSettings;
            _schemaSet = schemaSet;
            _databaseConnection = databaseConnection;
            _logger = logger;
            _maxSimultaneousDownloads = maxSimultaneousDownloads;
            _retryInterval = retryInterval;
            _loggingLevel = loggingLevel;
        }

        public async Task<string> LoadConfigurationAsync()
        {
            var configurationUrl = ConfigurationManager.AppSettings["ConfigurationUrl"];

            var semaphoreSlim = new SemaphoreSlim(MaxValue: _maxSimultaneousDownloads);

            try
            {
                await semaphoreSlim.WaitAsync();

                var taskCompletionSource = new TaskCompletionSource<string>();

                var httpRequestMessage = new HttpRequestMessage
                {
                    RequestUri = new Uri(configurationUrl),
                    Method = HttpMethod.Get
                };

                _httpClient.SendAsync(httpRequestMessage, HttpCompletionOption.ResponseHeadersRead).ContinueWith(task =>
                {
                    if (task.IsFaulted)
                    {
                        _logger.LogError($"Failed to load configuration: {task.Exception}", task.Exception);

                        if (CanRetry())
                        {
                            semaphoreSlim.Release();
                            LoadConfigurationAsync().Wait();
                        }
                    }
                    else
                    {
                        var httpResponse = task.Result;

                        if (!httpResponse.IsSuccessStatusCode)
                        {
                            _logger.LogError($"Received non-success status code: {httpResponse.StatusCode}", null);

                            if (CanRetry())
                            {
                                semaphoreSlim.Release();
                                LoadConfigurationAsync().Wait();
                            }
                        }
                        else
                        {
                            var configurationStream = await httpResponse.Content.ReadAsStreamAsync();

                            using (var xmlReader = XmlReader.Create(configurationStream, _xmlSettings))
                            {
                                if (!ValidateConfiguration(xmlReader))
                                {
                                    _logger.LogError("Invalid XML configuration file.", null);

                                    if (CanRetry())
                                    {
                                        semaphoreSlim.Release();
                                        LoadConfigurationAsync().Wait();
                                    }
                                }
                                else
                                {
                                    var configurationElement = GetConfigurationElement(xmlReader);

                                    if (configurationElement == null)
                                    {
                                        _logger.LogError("Configuration element not found.", null);
                                    }
                                    else
                                    {
                                        taskCompletionSource.SetResult(configurationElement.GetValue());
                                    }
                                }
                            }
                        }
                    }
                });

                return await taskCompletionSource.Task;
            }
            finally
            {
                semaphoreSlim.Release();
            }
        }

