public class ApiFunction {
    private final OkHttpClient httpClient = new OkHttpClient();
    private final Cache cache = CacheBuilder.newBuilder()
            .maximumSize(100_000) // configure your cache size limit here
            .expireAfterAccess(Duration.ofMinutes(5)) // configure TTL here
            .build();

    private final Map<String, String> tokens = new ConcurrentHashMap<>();
    private final Semaphore semaphore = new Semaphore(10); // configure concurrent request limit here

    public <T> void fetchAndProcessJsonData(String url, Class<T> clazz, Consumer<T> consumer) throws IOException {
        URI uri = URI.create(url);

        CachedResult<String> cachedResponse = cache.getIfPresent(uri.toString());
        if (cachedResponse != null) { // use cached response if available
            Gson gson = new Gson();
            T jsonData = gson.fromJson(cachedResponse.getValue(), clazz);
            consumer.accept(jsonData);
            return;
        }

        RateLimiter rateLimiter = new TokensoBasedRateLimiter(10, 60); // configure rate limit here
        if (!rateLimiter.tryAcquire()) {
            System.out.println("Rate limiting exceeded, retry after waiting.");
            return;
        }

        try (SemaphorePermit permit = semaphore.tryAcquire()) {
            if (permit == null) { // concurrent request limit reached, wait and retry
                Thread.sleep(100);
                fetchAndProcessJsonData(url, clazz, consumer);
                return;
            }

            Request request = new Request.Builder()
                    .url(uri)
                    .addHeader("Authorization", getAuthToken())
                    .build();

            Call call = httpClient.newCall(request);
            Response response = call.execute();
            if (!response.isSuccessful()) {
                System.out.println("API request failed with status code: " + response.code());
                return;
            }

            String jsonData = response.body().string();
            Gson gson = new Gson();
            T parsedJson = gson.fromJson(jsonData, clazz);

            cache.put(uri.toString(), CachedResult.newCachedResult(jsonData)); // store the processed data in the cache
            consumer.accept(parsedJson);
        } catch (InterruptedException | ExecutionException e) {
            System.out.println("An error occurred while fetching and processing JSON data: " + e.getMessage());
        }
    }

    private String getAuthToken() throws IOException {
        // generate, update, and manage your tokens here based on JWT implementation of your choice
        throw new UnsupportedOperationException();
    }
}
