import os
import time
import hashlib
import requests
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor

API_URL = 'https://api.random.com/string'  # Replace with your API URL
HEADERS = {'User-Agent': 'batch_rename_files'}  # Add appropriate headers for the API
RATE_LIMIT_RESET = datetime(2023, 1, 1)  # Change to your API rate limit reset date
RETRY_DELAY = 5  # Retry delay in seconds

def get_random_string():
    response = requests.get(API_URL, headers=HEADERS)
    if response.status_code == 200:
        return response.json()['random_string']
    else:
        time.sleep(RETRY_DELAY)
        if datetime.now() < RATE_LIMIT_RESET:
            get_random_string()  # Retry if not at rate limit reset
        else:
            print("API rate limit exceeded, using a fixed random string.")
            return str(hashlib.sha256(str(time.time()).encode('utf-8')).hexdigest())

def is_today(file_timestamp):
    file_date = datetime.strptime(file_timestamp, '%Y%m%d_%H%M%S')
    today = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)
    return file_date.date() == today.date()

def batch_rename_files(directory):
    if not os.path.isdir(directory):
        raise FileNotFoundError(f"Directory '{directory}' does not exist.")

    rename_counter = 0
    seen_files = set()
    file_extensions = ('.txt', '.jpg', '.png')

    for root, _, files in os.walk(directory):
        for filename in files:
            ext = os.path.splitext(filename)[1]
            if ext.lower() not in file_extensions:
                continue

            filepath = os.path.join(root, filename)
            timestamp = time.strftime('%Y%m%d_%H%M%S', time.gmtime(os.path.getctime(filepath)))
            basename, ext = os.path.splitext(filename)

            if is_today(timestamp):
                continue

            new_filename = f"{basename}_{timestamp}{get_random_string()}{ext}"
            new_filepath = os.path.join(root, new_filename)

            try:
                os.rename(filepath, new_filepath)
                rename_counter += 1
                seen_files.add(new_filepath)
            except Exception as e:
                print(f"Error while renaming file '{filename}': {e}")

    print(f"Renamed {rename_counter} files in the directory.")

if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        print("Usage: python batch_rename_files.py [directory]")
        sys.exit(1)

    batch_rename_files(sys.argv[1])
```

