typedef std::map<std::string, int> WordCountMap;
struct WordFrequency {
    std::string word;
    int count;
};

static char api_key[256];
static bool case_sensitive = true;
static std::string output_file;

size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

CURLcode lookup_word(const std::string &word) {
    CURL *curl;
    CURLcode res;
    std::string json_response;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "https://api.dictionaryapi.com/api/v1/words/" + word);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &json_response);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "Error looking up word: " << curl_easy_strerror(res) << std::endl;
        }

        curl_easy_cleanup(curl);
    }

    return res;
}

void process_file(std::ifstream &input, WordCountMap &word_counts, bool is_main_thread) {
    std::string line;
    while (std::getline(input, line)) {
        for (char c : line) {
            if (!isal alpha(c)) continue;
            size_t pos = 0;
            std::string word;
            if (case_sensitive) {
                word.append(1, tolower(c));
                while ((pos = line.find(word, pos)) != std::string::npos && ++pos < line.length()) {
                    word.append(line, pos, 1);
                    auto it = word_counts.find(word);
                    if (it != word_counts.end()) {
                        it->second++;
                    } else {
                        word_counts[word] = 1;
                    }
                }
            } else {
                while ((pos = line.find(word, pos)) != std::string::npos && ++pos < line.length()) {
                    word.append(1, towlower((unsigned char)line[pos]));
                    auto it = word_counts.find(word);
                    if (it != word_counts.end()) {
                        it->second++;
                    } else {
                        word_counts[word] = 1;
                    }
                }
            }

            if (!is_main_thread) {
                lookup_word(word);
            }
        }
    }
}

void display_usage() {
    std::cout << "Usage: text_analysis_tool [options] input_file" << std::endl;
    std::cout << "-o, --output-file <output_file>: Specify the output file for word frequency analysis." << std::endl;
    std::cout << "-cs, --case-sensitive: Perform case sensitive analysis. Default is true." << std::endl;
    std::cout << "--manpage: Display this help message and exit." << std::endl;
}

int main(int argc, char *argv[]) {
    int opt = 0;
    bool output_set = false;
    bool case_sensitive_set = false;

    while ((opt = getopt(argc, argv, "o:cs:")) != -1) {
        switch (opt) {
            case 'o':
                output_file = optarg;
                output_set = true;
                break;
            case 'c':
                case_sensitive_set = true;
                break;
            case 's':
                case_sensitive = false;
                break;
            case '?':
                if (optopt == 'o' || optopt == 'c' || optopt == 's') {
                    std::cerr << "Option -" << optopt << " requires an argument." << std::endl;
                } else {
                    std::cerr << "Unknown option: -" << optopt << std::endl;
                }
                display_usage();
                return 1;
            default:
                break;
        }
    }

    if (optind >= argc) {
        display_usage();
        return 1;
    }

    std::ifstream input(argv[optind], std::ios::in);
    if (!input.is_open()) {
        std::cerr << "Error opening input file: " << argv[optind] << std::endl;
        return 1;
    }

    if (!case_sensitive_set) {
        strcpy(api_key, getenv("DICTIONARY_API_KEY"));
    } else {
        snprintf(api_key, sizeof(api_key), "%s_UPPER", getenv("DICTIONARY_API_KEY"));
    }

    if (output_set) {
        std::ofstream output_file_stream(output_file);
        if (!output_file_stream.is_open()) {
            std::cerr << "Error opening output file: " << output_file << std::endl;
            return 1;
        }
    }

    pthread_t threads[256];
    WordCountMap word_counts;

    size_t thread_count = 0;
    process_file(input, word_counts, true); // main thread processes initial lines

    for (char c : input.getline(std::string(), '\n')) {
        if (!isal num(c)) continue;
        if (++thread_count >= 256) break;
        pthread_create(&threads[thread_count - 1], nullptr, process_file, &input, &word_counts, false);
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], nullptr);
    }

    if (output_set) {
        std::ofstream output_file_stream(output_file, std::ios::app);
        for (auto &it : word_counts) {
            output_file_stream << it.first << ": " << it.second << '\n';
        }
        output_file_stream.close();
    } else {
        for (auto &it : word_counts) {
            std::cout << it.first << ": " << it.second << '\n';
        }
    }

    return 0;
}
```

