```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <regex.h>
#include <iconv.h>
#include <string.h>

/* Max number of concurrent threads */
#define THREAD_COUNT 10

typedef struct {
    const char* email;
    size_t index;
} EmailData;

/* Validates an email address using a custom regex pattern and iconv for handling encodings */
int validateEmail(const char* email, FILE* logFd) {
    regex_t re;
    regmatch_t match[1];
    int rc = regcomp(&re, "\\b[\\w.%+-]+@[\\w.-]+\\.[a-zA-Z]{2,}\\b", 0);
    if (rc) {
        perror("Invalid regex pattern");
        return -1;
    }

    rc = regexec(&re, email, 1, match, 0);

    regfree(&re);

    if (rc == 0) {
        return 0;
    }

    /* Handle internationalized domain names by converting the email to UTF-8 and validating it */
    iconv_t cd = iconv_open("UTF-8", NULL);
    size_t input_size = strlen(email), output_size = 0;
    char *input, *output = malloc(input_size + 1);

    if (cd == (iconv_t) -1) {
        perror("Failed to open iconv context");
        return -1;
    }

    input = malloc(input_size * 2 + 1);
    strcpy(input, email);

    size_t bytesRemaining = input_size;
    char* inbuf = input;
    char* outbuf = output;
    iconv(cd, &inbuf, &bytesRemaining, &outbuf, &output_size);

    if (bytesRemaining > 0) {
        fprintf(logFd, "Email %ld exceeds the maximum length limit\n", input_size);
        return -1;
    }

    rc = regexec(&re, output, 1, match, 0);

    free(output);
    free(input);
    iconv_close(cd);

    if (rc == 0) {
        return 0;
    } else {
        fprintf(logFd, "Invalid email address: %s\n", email);
        return -1;
    }
}

void* validateEmailThread(void* data) {
    EmailData* emailData = (EmailData*) data;
    if (validateEmail(emailData->email, stderr) < 0) {
        fprintf(stderr, "Error validating email at index %ld\n", emailData->index);
    }
    return NULL;
}

void validateEmailBatch(const char* const* emailBatch, size_t batchSize, FILE* logFd, size_t maxLen) {
    if (!emailBatch || batchSize <= 0 || maxLen <= 0) {
        fprintf(logFd, "Invalid input parameters\n");
        return;
    }

    pthread_t threads[THREAD_COUNT];
    EmailData emailDatas[THREAD_COUNT];
    size_t emailsProcessed = 0;

    for (size_t i = 0; i < batchSize; ++i) {
        if (strlen(emailBatch[i]) > maxLen) {
            fprintf(logFd, "Email %ld exceeds the maximum length limit\n", i);
            continue;
        }
        emailDatas[emailsProcessed].email = emailBatch[i];
        emailDatas[emailsProcessed].index = i;
        emailsProcessed++;

        if (emailsProcessed >= THREAD_COUNT) {
            for (size_t j = 0; j < emailsProcessed; ++j) {
                pthread_create(&threads[j], NULL, validateEmailThread, &emailDatas[j]);
            }
            for (size_t k = 0; k < emailsProcessed; ++k) {
                pthread_join(threads[k], NULL);
            }
            emailsProcessed = 0;
        }
    }

    if (emailsProcessed > 0) {
        for (size_t j = 0; j < emailsProcessed; ++j) {
            pthread_create(&threads[j], NULL, validateEmailThread, &emailDatas[j]);
        }
        for (size_t k = 0; k < emailsProcessed; ++k) {
            pthread_join(threads[k], NULL);
        }
    }
}
```

