#include <forward_list>
#include <string>
#include <functional>
#include <mutex>
#include <iostream>
#include <sstream>
#include <chrono>
#include <thread>
#include <condition_variable>

class ThreadSafeLogger {
public:
    void log(const std::string& message) {
        std::unique_lock<std::mutex> lock(logMutex);
        logMessages.push_back(message);
        logCondition.notify_one();
    }

    void waitAndLog() {
        std::unique_lock<std::mutex> lock(logMutex);
        logCondition.wait(lock, [this] { return !logMessages.empty(); });
        lastLoggedMessage = logMessages.front();
        logMessages.pop_front();
    }

private:
    std::forward_list<std::string> logMessages;
    std::mutex logMutex;
    std::condition_variable logCondition;
    std::string lastLoggedMessage;
};

void insertAfterFirstOccurrence(std::forward_list<std::string>& data, const std::string& target, const std::string& value, const std::function<void(const std::string&)>& callback, ThreadSafeLogger& logger) {
    auto it = data.begin();
    bool inserted = false;

    std::unique_lock<std::mutex> lock(syncMutex);
    std::thread checkForTarget([this, &it, target]() mutable {
        for (; it != data.end(); ++it) {
            if (*it == target) {
                std::unique_lock<std::mutex> unlockGuard(lock);
                it = data.insertAfter(it, value);
                inserted = true;
                break;
            }
        }
    });

    if (!inserted) {
        it = data.end();
        it = data.insert(it, value);
    }

    checkForTarget.detach();

    if (callback) callback(target);
    logger.log("Inserted '" + value + "' after '" + target + "', position: " + std::to_string((it - data.begin())));
}

int main() {
    ThreadSafeLogger logger;
    std::forward_list<std::string> data = {"apple", "banana", "cherry", "date"};

    insertAfterFirstOccurrence(data, "banana", "blueberry", [](const std::string& target) {
        std::cout << "Target found: " << target << '\n';
    }, logger);

    logger.waitAndLog();
    return 0;
}
