const { Pool } = require('pg');
const path = require('path');
const fs = require('fs');
const jasmine = require('jest');

// Database connection configuration
const pool = new Pool({
  user: 'your_username',
  host: 'database_host',
  database: 'database_name',
  password: 'your_password',
  port: 5432,
});

// API endpoint function
async function getEmployees(req, res) {
  const { supervisorId, department, jobTitle, page = 1, limit = 10 } = req.query;

  try {
    // Prepare SQL query with parameterized queries to prevent SQL injection
    const queryText = `
      SELECT name, city, address, department, job_title
        FROM Employees
       WHERE supervisor_id = $1
         AND (department ILIKE $2 OR $2 IS NULL)
         AND (job_title ILIKE $3 OR $3 IS NULL)
      OFFSET (${page - 1} * ${limit}) LIMIT ${limit}`;
    const values = [supervisorId, `${department}%`, `${jobTitle}%'];

    const results = await pool.query(queryText, values);
    res.status(200).json(results.rows);
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
}

// External data source for roles and departments fetching function
async function getRoleAndDepartmentData() {
  try {
    const response = await axios.get('http://your_external_data_source_url');
    return response.data;
  } catch (err) {
    console.error(err);
    throw new Error('Failed to fetch external data source');
  }
}

// Initialize Express app
const app = express();
app.use(express.json());

// Define the API endpoint route
app.get('/api/employees', async (req, res) => {
  try {
    // Fetch roles and departments data from external source before querying employees table
    const roleAndDepartmentData = await getRoleAndDepartmentData();

    // Call the helper function to get employees based on the input parameters
    const employees = await getEmployees(req, res);

    res.status(200).json({
      employees: employees,
      roles: roleAndDepartmentData.roles,
      departments: roleAndDepartmentData.departments,
    });
  } catch (err) {
    console.error(err);
    res.status(500).send('Internal Server Error');
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server is running on port ${port}`);
});
