/**
 * Structure to hold resource bundle metadata and item pointers.
 */
typedef struct _ResourceBundle {
    size_t count;      /**< Number of items in the bundle. */
    char **items;     /**< Pointer array holding the item pointers. */
} ResourceBundle;

/**
 * Function to load a resource bundle from a file and return the number of items in the bundle.
 *
 * @param path The path to the resource file.
 * @return A pointer to the ResourceBundle or NULL on error. Free with `free_resource_bundle()` when no longer needed.
 */
ResourceBundle* load_resource_bundle(const char *path);

/**
 * Private helper function for load_resource_bundle(). Reads the resource file and populates the ResourceBundle.
 *
 * @param path The path to the resource file.
 * @param bundle Pointer to the ResourceBundle structure to be populated.
 * @return True on success, false otherwise.
 */
static bool _load_resource_bundle(const char *path, ResourceBundle **bundle);

/**
 * Private helper function for load_resource_bundle(). Allocates memory for a single item in the resource bundle.
 *
 * @param item The string representing the resource item.
 * @return A newly allocated copy of the item or NULL on failure.
 */
static char* _allocate_item(const char *item);

/**
 * Private helper function for load_resource_bundle(). Frees a single item in the resource bundle.
 *
 * @param item The string representing the resource item to be freed.
 */
static void _free_item(char *item);

/**
 * Private helper function for load_resource_bundle(). Frees all items and the ResourceBundle structure itself.
 *
 * @param bundle Pointer to the ResourceBundle structure to be deallocated.
 */
static void _free_resource_bundle(ResourceBundle *bundle);

/**
* Private helper function for load_resource_bundle(). Checks if a given path is valid and accessible.
*
* @param path The path to check.
* @return True if the path is valid, false otherwise.
*/
static bool _is_valid_path(const char *path);

/**
* Private helper function for load_resource_bundle(). Initializes a CURL handle and fetches the resource file from the given URL.
*
* @param url The URL to fetch the resource file from.
* @param file The output file where the fetched data will be written.
* @return True on success, false otherwise.
*/
static bool _fetch_resource(const char *url, FILE *file);

/**
* Private helper function for load_resource_bundle(). Reads a line from the given file and returns it as a newly allocated string.
*
* @param file The input file to read from.
* @return A newly allocated copy of the line or NULL on failure.
*/
static char* _read_line(FILE *file);

ResourceBundle* load_resource_bundle(const char *path) {
    ResourceBundle *bundle;

    if (!_is_valid_path(path)) return NULL;

    bool success = _load_resource_bundle(path, &bundle);
    if (!success) return NULL;

    return bundle;
}

static bool _load_resource_bundle(const char *path, ResourceBundle **bundle) {
    FILE *file = fopen(path, "r");
    if (file == NULL) return false;

    // Load resource bundle in a separate thread to avoid blocking the main thread.
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, _load_resource_bundle_worker, file) != 0) {
        fclose(file);
        return false;
    }

    // Wait for the worker thread to finish its job.
    ResourceBundle *temp_bundle;
    pthread_join(thread_id, (void**) &temp_bundle);

    if (temp_bundle == NULL) {
        fclose(file);
        return false;
    }

    // Copy the temporary bundle to the output bundle.
    *bundle = malloc(sizeof(ResourceBundle));
    (*bundle)->count = temp_bundle->count;
    (*bundle)->items = malloc((*bundle)->count * sizeof(char*));
    memcpy((*bundle)->items, temp_bundle->items, (*bundle)->count * sizeof(char*));

    // Clean up the temporary bundle and file.
    _free_resource_bundle(temp_bundle);
    fclose(file);

    return true;
}

static void _load_resource_bundle_worker(void *arg) {
    FILE *file = (FILE*) arg;
    ResourceBundle *bundle = NULL;

    char *line = _read_line(file);
    if (!line) goto cleanup;

    size_t line_len = strlen(line);
    if (line[line_len - 1] == '\n') line[--line_len] = '\0';

    // Check for comments and empty lines.
    if (line[0] == '#' || line_len == 0) goto next;

    // Allocate memory for a new item and store it in the bundle.
    char *item = _allocate_item(line);
    if (!item) goto cleanup;

    ResourceBundle **tmp_bundle_ptr = &bundle;
    while (*tmp_bundle_ptr != NULL) {
        tmp_bundle_ptr = &((*tmp_bundle_ptr)->items[(*tmp_bundle_ptr)->count]);
    }
    *tmp_bundle_ptr = item;
    (*tmp_bundle_ptr)->count++;

next:
    free(line);
    line = _read_line(file);
    if (!line) goto cleanup;
    // ... Repeat the loop until the end of the file is reached.

cleanup:
    _free_resource_bundle(bundle);
}

static char* _allocate_item(const char *item) {
    size_t len = strlen(item) + 1;
    char *new_item = malloc(len);
    if (new_item == NULL) return NULL;
    strcpy(new_item, item);
    return new_item;
}

static void _free_item(char *item) {
    free(item);
}

static void _free_resource_bundle(ResourceBundle *bundle) {
    size_t i;
    for (i = 0; i < bundle->count; ++i) {
        _free_item(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}

static bool _is_valid_path(const char *path) {
    // Check if the path is a valid file or URL.
    struct stat st;
    if (stat(path, &st) == 0 && S_ISREG(st.st_mode)) return true;

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(path, NULL, &hints, &res) == 0) {
        freeaddrinfo(res);
        return true;
    }

    return false;
}

static bool _fetch_resource(const char *url, FILE *file) {
    CURL *curl = curl_easy_init();
    if (curl == NULL) return false;

    struct curl_slist *chunk = NULL;
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL); // Write to file directly.
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, file);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: %s\n", curl_easy_strerror(res));
        goto cleanup;
    }

    // Extract content-type header and validate the resource file format.
    chunk = curl_easy_get_request_data(curl, 0);
    const char *content_type = strtok(chunk->data, ";");
    if (strcasecmp(content_type, "text/plain") != 0) {
        fprintf(stderr, "Error: Invalid content type '%s'\n", content_type);
        goto cleanup;
    }

cleanup:
    curl_easy_cleanup(curl);
    curl_slist_free_all(chunk);
    return res == CURLE_OK;
}

static char* _read_line(FILE *file) {
    char c, *line = NULL, *prev = NULL;
    int line_len = 0;

    while ((c = fgetc(file)) != EOF && c != '\n') {
        if (line == NULL) {
            line_len = 1;
            line = malloc(line_len);
            line[0] = c;
            prev = line;
        } else {
            line_len++;
            char *new_line = realloc(prev, line_len + 1);
            if (new_line == NULL) return NULL;
            prev = new_line;
            prev[line_len] = c;
        }
    }

    if (c == EOF && line != NULL) {
        free(line);
        return NULL;
    }

    *prev = '\0';
    return line;
}
