import com.fasterxml.jackson.databind.ObjectMapper;
import redis.clients.jedis.Jedis;
import org.slf4j.Logger;
import org.slab.cache.Cache;
import org.slab.cache.async.AsyncRedisCacheManager;
import org.slab.cache.eviction.LruEvictionPolicy;
import org.slab.cache.serializer.Jackson2JsonRedisSerializer;
import java.io.IOException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import javax.annotation.PostConstruct;
import javax.inject.Inject;

public class CustomDeserializer {
    private static final Logger LOGGER = LoggerFactory.getLogger(CustomDeserializer.class);

    @Inject
    private ObjectMapper objectMapper;

    private Cache<String, User> userCache;

    @PostConstruct
    public void init() {
        AsyncRedisCacheManager cacheManager = new AsyncRedisCacheManager();
        cacheManager.setSerializer(new Jackson2JsonRedisSerializer<>(User.class));
        cacheManager.setExpireTime(1, TimeUnit.HOURS);
        cacheManager.setEvictionPolicy(new LruEvictionPolicy());
        this.userCache = cacheManager.build();
    }

    public User deserializeFromByteArrayAsync(String userId, byte[] serializedData) {
        try {
            User userFromCache = userCache.get(userId);
            if (userFromCache != null) {
                return userFromCache;
            }

            Jedis jedis = new Jedis(); // Use connection pool for production
            byte[] cachedData = jedis.hgetAll(userId + ":data");
            if (cachedData != null && cachedData.length > 0) {
                User user = objectMapper.treeToValue(objectMapper.readTree(cachedData), User.class);
                userCache.putIfAbsent(userId, user);
                return user;
            }

            // Deserialize the byte array and handle any exceptions
            User user = objectMapper.readValue(serializedData, User.class);
            if (user == null) {
                throw new DeserializationException("Failed to deserialize user data");
            }

            // Save the deserialized user instance to the cache and the database
            userCache.putIfAbsent(userId, user);
            saveToDatabase(userId, serializedData);

            return user;
        } catch (IOException | ExecutionException e) {
            LOGGER.error("Error while deserializing user data", e);
            throw new DeserializationException("Error while deserializing user data", e);
        }
    }

    private void saveToDatabase(String userId, byte[] serializedData) {
        // Implement the logic to save the serialized data into your existing data storage system (e.g., Cassandra)
    }
}
