import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileLoader {
    private static final int DEFAULT_BUFFER_SIZE = 1024 * 64;

    public static MoSTState loadStateObject(String filePath, int bufferSize, Logger logger) {
        try (BufferedInputStream inputStream = new BufferedInputStream(new FileInputStream(filePath))) {
            ObjectInputStream objectInput = new ObjectInputStream(inputStream);

            try {
                Object loadedObject = objectInput.readObject();
                if (loadedObject instanceof MoSTState) {
                    return (MoSTState) loadedObject;
                }
            } catch (ClassNotFoundException e) {
                logger.error("Failed to load state object from file: " + e.getMessage());
            }
        } catch (IOException e) {
            int retryAttempts = 3;
            if (e.getMessage().contains("No such file or directory")) {
                while (--retryAttempts > 0 && !Files.exists(Path.of(filePath))) {
                    logger.warn("Temporary error: state file not found, retrying in " + retryAttempts + " seconds...");
                    try {
                        Thread.sleep(1000 * retryAttempts);
                    } catch (InterruptedException ex) {
                        logger.error("Failed to sleep during file retry: " + ex.getMessage());
                        break;
                    }
                }
            } else {
                logger.error("Error while loading state object from file: " + e.getMessage());
            }
        }

        return null;
    }
}
