using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Xml.XPath;
using System.Xml.Linq;
using System.Text;
using System.Diagnostics;

public class KickstartConfigManager
{
    private readonly HttpClient _httpClient;
    private readonly Dictionary<string, XDocument> _xmlCache = new Dictionary<string, XDocument>();
    private readonly SemaphoreSlim _rateLimiter = new SemaphoreSlim(10, 10); // Set rate limit to 10 requests per second

    public KickstartConfigManager()
    {
        _httpClient = new HttpClient();
    }

    public async Task<XElement> GetXmlElementAsync(string xmlUrl, string xPathExpression)
    {
        if (_xmlCache.TryGetValue(xmlUrl, out XDocument xmlDocument))
        {
            return xmlDocument.XPathSelectElements(xPathExpression).FirstOrDefault();
        }

        await _rateLimiter.WaitAsync();

        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync(xmlUrl);

            if (!response.IsSuccessStatusCode)
                throw new Exception($"Failed to retrieve XML data from {xmlUrl}");

            XDocument xmlDocument = XDocument.Load(await response.Content.ReadAsStreamAsync());

            _xmlCache[xmlUrl] = xmlDocument;
            return xmlDocument.XPathSelectElements(xPathExpression).FirstOrDefault();
        }
        catch (Exception ex)
        {
            if (ex is TaskCanceledException) // Handle cases where the data source might be unreachable or slow
                await Task.Delay(TimeSpan.FromSeconds(5)).ContinueWith(_ => GetXmlElementAsync(xmlUrl, xPathExpression));

            throw new Exception($"Failed to retrieve XML data from {xmlUrl}", ex);
        }
    }

    public void ModifyConfigFile(string configFilePath, Dictionary<string, string> placeholders)
    {
        ProcessStartInfo startInfo = new ProcessStartInfo("python", $"modify_config.py {configFilePath} {string.Join(' ', placeholders.Select(kvp => kvp.Key + "=" + kvp.Value))}");
        startInfo.RedirectStandardOutput = true;
        startInfo.UseShellExecute = false;

        using (Process process = new Process())
        {
            process.StartInfo = startInfo;
            process.Start();

            while (!process.StandardOutput.EndOfStream)
            {
                string line = process.StandardOutput.ReadLine();
                // Handle encrypted password addition here
            }

            process.WaitForExit();
        }
    }
}
