def fetch_certificate(oauth_request):
    cache = TTLCache(maxsize=100, ttl=timedelta(minutes=5))
    certificate = cache.get(oauth_request)

    if not certificate:
        try:
            response = requests.get(f"https://key-management-service/{oauth_request}", verify=True)
            response.raise_for_status()

            private_key = OpenSSL.crypto.load_privatekey(OpenSSL.crypto.FILETYPE_PEM, response.content)
            certificate = OpenSSL.crypto.load_certificate(OpenSSL.crypto.FILETYPE_PEM, response.content)

            if check_certificate_validity(certificate):
                cache[oauth_request] = (private_key, certificate)
                return (private_key, certificate)
            else:
                log_error(f"Invalid or expired certificate for OAuth request {oauth_request}")
        except requests.exceptions.RequestException as error:
            log_error(f"Error fetching certificate for OAuth request {oauth_request}: {error}")

    return cache[oauth_request]

