```java
import java.time.Instant;
import java.util.ConcurrentMap;
import java.util.Deque;
import java.util.LinkedList;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MetadataUpdater {
    private static final Logger LOGGER = LoggerFactory.getLogger(MetadataUpdater.class);
    private static final int MAX_UPDATES_PER_MINUTE = 100;
    private static final long TIME_WINDOW_MINUTES = 5;
    private FileSystem fs;
    private ConcurrentMap<String, MetadataCache> cache;
    private Deque<UpdateLogEntry> logQueue;

    public MetadataUpdater(FileSystem fs) {
        this.fs = fs;
        this.cache = new ConcurrentHashMap<>();
        this.logQueue = new LinkedList<>();
    }

    public void updateMetadata(String[] filePaths, Map<String, String> metadata) throws Exception {
        if (filePaths == null || filePaths.length == 0) {
            throw new IllegalArgumentException("Invalid file paths provided.");
        }

        var timestamp = Instant.now();
        var updateCount = 0;

        for (String path : filePaths) {
            if (!isPathValid(path)) {
                LOGGER.error("Invalid file path: {}", path);
                continue;
            }

            var cacheEntry = cache.computeIfAbsent(path, k -> new MetadataCache());
            cacheEntry.setLastUpdated(timestamp);
            cacheEntry.updateMetadata(metadata);

            if (!cacheEntry.shouldWriteToHDFS()) {
                continue;
            }

            var statusCode = updateFileMetadataOnHDFS(path, metadata);
            logUpdate(timestamp, path, statusCode);
            updateCount++;
        }

        throttleUpdates(updateCount);
    }

    private boolean isPathValid(String path) {
        try {
            new Path(path, fs.getUri());
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private int updateFileMetadataOnHDFS(String path, Map<String, String> metadata) throws Exception {
        var fileStatus = fs.getFileStatus(new Path(path));
        fs.setMetaData(fileStatus.getPath(), metadata);
        return 200; // HTTP 200 OK
    }

    private void logUpdate(Instant timestamp, String path, int statusCode) {
        logQueue.add(new UpdateLogEntry(timestamp, path, statusCode));
        pruneLogQueue();
    }

    private void pruneLogQueue() {
        while (logQueue.size() > TIME_WINDOW_MINUTES * MAX_UPDATES_PER_MINUTE) {
            logQueue.pollFirst();
        }
    }

    private void throttleUpdates(int updateCount) {
        if (updateCount > MAX_UPDATES_PER_MINUTE) {
            var sleepDuration = TimeUnit.SECONDS.convert((MAX_UPDATES_PER_MINUTE - updateCount) * 60, TimeUnit.MILLISECONDS);
            Thread.sleep(sleepDuration);
        }
    }

    private static final class MetadataCache {
        private Instant lastUpdated;
        private Map<String, String> metadata;

        public void setLastUpdated(Instant timestamp) {
            this.lastUpdated = timestamp;
        }

        public boolean shouldWriteToHDFS() {
            long currentTime = System.currentTimeMillis();
            if (currentTime - lastUpdated.toEpochMilli() > TimeUnit.MINUTES.toMillis(1)) {
                return true;
            }
            return false;
        }

        public void updateMetadata(Map<String, String> metadata) {
            this.metadata = metadata;
        }
    }

    private static final class UpdateLogEntry {
        private Instant timestamp;
        private String path;
        private int statusCode;

        public UpdateLogEntry(Instant timestamp, String path, int statusCode) {
            this.timestamp = timestamp;
            this.path = path;
            this.statusCode = statusCode;
        }
    }
}
```

