```java
import org.apache.commons.io.FileUtils;
import org.apache.commons.codec.digest.DigestUtils;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class HashFile {
    public static void main(String[] args) throws Exception {
        String filePath = "/path/to/your/file";
        String md5Hash = computeMD5(filePath);
        // Add the code to store the computed hash in a remote database here.
        System.out.println("The MD5 of file " + filePath + " is: " + md5Hash);
    }

    public static String computeMD5(String filePath) {
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192]; // Optimize for 8KB chunks. Adjust as needed for your specific use case.
            MessageDigest md = MessageDigest.getInstance("MD5");
            int numRead;
            while ((numRead = is.read(buffer)) > 0) {
                md.update(buffer, 0, numRead);
            }
            return DigestUtils.md5Hex(md.digest());
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }
}
```

To store the computed hash in a remote database, you can use any JDBC or ORM library available for Java. To optimize performance when dealing with large files, it's important to read and process data chunks at a time instead of loading the entire file into memory. This code reads the file in 8KB chunks, but you can adjust the buffer size as needed based on your specific use case.

