(function () {
  const loadFiles = async (files) => {
    let loadedScripts = [];

    for (let file of files) {
      try {
        const script = document.createElement("script");
        script.src = file;
        document.head.appendChild(script);
        loadedScripts.push(script);
      } catch (e) {
        console.error(`Failed to load ${file}:`, e);
      }
    }

    return Promise.all(loadedScripts.map((script) => new Promise((resolve, reject) => {
      script.onload = () => resolve(script);
      script.onerror = (e) => reject(e);
    })));
  };

  loadFiles(['local_file.js', 'remote_file.js']).then(() => console.log('All scripts loaded successfully')).catch((e) => console.error('Error loading scripts:', e));
})();
