#include <sstream>
#include <system_error>

// Custom Context class for thread-safe operation metadata storage
class Context {
public:
    explicit Context(const std::string& userID) : userID_(userID), timestamp_(std::chrono::steady_clock::now()) {}

    const std::string& getUserID() const { return userID_; }
    auto getTimestamp() const { return timestamp_; }

private:
    std::string userID_;
    std::chrono::steady_clock::time_point timestamp_;
};

// Thread-safe logging function
void log(const Context& context, const std::string& message) {
    // Replace this with actual logging implementation
    std::cout << "[" << context.getTimestamp().time_since_epoch().count() << "] UserID: " << context.getUserID()
              << ", Operation Type: InsertAfterFirstOccurrence, Message: " << message << '\n';
}

// Thread-safe callback function
using Callback = std::function<void(const Context&)>;
class SafeCallback {
public:
    explicit SafeCallback(Callback cb) : callback_(std::move(cb)) {}

    void operator()(const Context& context) const {
        std::unique_lock<std::mutex> lock(mutex_);
        callback_(context);
    }

private:
    Mutex mutex_;
    Callback callback_;
};

// Utility function to find the position of target in the list
auto findTargetPosition(const std::forward_list<std::string>& list, const std::string& target) {
    auto it = list.begin();
    auto end = list.end();

    for (; it != end && *it != target; ++it) {}

    return it;
}

// Main function: insertAfterFirstOccurrence
void insertAfterFirstOccurrence(std::forward_list<std::string>& list, const std::string& target, const std::string& value,
                                 const Context* context, SafeCallback callback) {
    auto it = findTargetPosition(list, target);

    // Check for empty input strings and potential errors
    if (target.empty() || value.empty()) {
        throw std::invalid_argument("Empty input strings are not allowed.");
    }

    // Perform operation with concurrency support using mutexes
    std::unique_lock<std::mutex> lock(mutex_);
    lock.unlock();

    if (it != list.end()) {
        auto insertIt = it;
        ++insertIt;
        list.insert(insertIt, value);
        log(*context, "Inserted '" + value + "' after '" + target + "'");
    } else {
        log(*context, "Could not find '" + target + "' in the list.");

        // Insert at the end of the list if not found
        list.push_back(value);
        it = list.end();
    }

    // Call the callback function safely
    callback(*context);
}
