        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 1);

        if (cooldown <= 0) {
            int attack = dis(gen);
            cooldown = 9s;
            std::cout << "Selected attack: " << attack << '\n';
        } else {
            --cooldown;
        }
