    void InsertData(const std::string& target, const std::string& newData) {
        if (_list.empty()) {
            _list.emplace_front(_list.begin(), Node{target, _list.next()});
            bl::get("<0>") << "First element inserted: " << target;
            return;
        }

        auto it = _list.begin();
        bool found = false;
        while (it != _list.end()) {
            if (it->data == target) {
                found = true;
                break;
            }
            ++it;
        }

        if (!found) {
            bl::get("<0>") << "Target not found: " << target;
            return;
        }

        if (insertionsCount >= maxInsertions) {
            bl::get("<0>") << "Maximum number of insertions reached.";
            throw std::runtime_error("Maximum number of insertions exceeded.");
        }

        auto newNode = _list.before_begin();
        newNode->data = newData;
        newNode->next = _list.next(_list.find(target));
        ++insertionsCount;
        bl::get("<0>") << "Inserted data: " << newData << ", after target: " << target;
    }

private:
