import os
import json
import requests
from datetime import timedelta, datetime
import time
from retrying import retry

# Configurable API keys and endpoints through environment variables
API_KEY = os.environ['WEATHER_API_KEY']
BASE_URL = os.environ['WEATHER_API_ENDPOINT']
CACHE_FILE = 'weather_cache.json'
EXPIRATION_TIME = 60 * 60  # 1 hour in seconds

def get_current_weather(city):
    try:
        if is_cache_valid():
            data = load_cache()
            if city in data:
                return data[city]

        params = {'q': city, 'appid': API_KEY}
        response = requests.get(BASE_URL, params=params)
        response.raise_for_status()
        data = response.json()

        if city not in data or 'error' in data:
            raise Exception('Failed to fetch weather data')

        save_cache({city: data})
        return data
    except Exception as e:
        print(f"Error fetching weather data for {city}: {str(e)}")
        return None

@retry(stop_max_attempt_number=3, wait_fixed=1000, wait_random_min=0, wait_random_max=2000)
def is_cache_valid():
    if not os.path.exists(CACHE_FILE):
        return False

    cache_data = load_cache()
    current_time = datetime.now()
    expiration_time = current_time - timedelta(seconds=EXPIRATION_TIME)

    for city, timestamp in cache_data.items():
        if timestamp > expiration_time:
            return False

    return True

def load_cache():
    if not os.path.exists(CACHE_FILE):
        return {}

    with open(CACHE_FILE) as f:
        data = json.load(f)

    return data

def save_cache(data):
    with open(CACHE_FILE, 'w') as f:
        json.dump(data, f)

if __name__ == "__main__":
    city = "New York"  # Replace this with the desired city
    weather_data = get_current_weather(city)
    if weather_data is not None:
        print(f"Current weather in {city}: {json.dumps(weather_data, indent=2)}")
```

