import hashlib
import secrets
import string
import time
from typing import Optional

class TokenCache:
    def __init__(self):
        self._cache = {}

    def get_or_set(self, user_id: str, value) -> str:
        if user_id not in self._cache:
            self._cache[user_id] = value
        return self._cache[user_id]

def generate_and_hash(user_id: str, password: str, salt: Optional[str] = None) -> tuple[str, str]:
    if not salt:
        raise ValueError("Salt must be provided.")

    tokens_characters = string.ascii_letters + string.digits + string.punctuation
    token = ''.join(secrets.choice(tokens_characters) for _ in range(32))

    salted_password = f"{password}:{salt}" if salt else password
    hashed_password = hashlib.sha256(salted_password.encode()).hexdigest()

    token_cache = TokenCache()
    unique_token = token_cache.get_or_set(user_id, token)

    return (unique_token, hashed_password)
