```java
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicIntegerArray;
import java.util.stream.IntStream;

public class DisjointSet {
    private final AtomicIntegerArray parent, rank, maxSize;
    private int setCount = 0;

    public DisjointSet(int[] elements) {
        this.parent = new AtomicIntegerArray(elements.length);
        this.rank = new AtomicIntegerArray(elements.length);
        this.maxSize = new AtomicIntegerArray(1);
        for (int i = 0; i < elements.length; ++i) {
            makeSet(i, elements[i]);
        }
    }

    private void makeSet(int i, int element) {
        parent.set(i, i);
        rank.set(i, 1);
        maxSize.set(element, Math.max(maxSize.get(element), 1));
        ++setCount;
    }

    public void addElement(int element) {
        int index = findSet(element);
        if (index >= parent.length()) {
            makeSet(parent.length(), element);
        }
    }

    public void removeElement(int element) {
        int index = findSet(element);
        if (index < 0 || index >= parent.length()) {
            throw new IllegalArgumentException("Invalid element");
        }
        union(index, -1);
    }

    private synchronized int findSet(int element) {
        int root = find(element);
        if (root != element) {
            maxSize.set(find(element), Math.min(maxSize.get(element), maxSize.get(root)));
        }
        return root;
    }

    private synchronized int find(int element) {
        int parentVal = parent.get(element);
        if (parentVal != element) {
            parent.updateAndGet(element, v -> parent.get(v));
        }
        return parentVal;
    }

    public synchronized int mergeSets(int a, int b) {
        int rootA = findSet(a);
        int rootB = findSet(b);

        if (rootA == rootB) {
            return rootA;
        }

        if (rank.get(rootA) > rank.get(rootB)) {
            maxSize.set(rootA, Math.max(maxSize.get(rootA), maxSize.get(rootB)));
            parent.set(rootB, rootA);
            return rootA;
        } else if (rank.get(rootA) < rank.get(rootB)) {
            maxSize.set(rootB, Math.max(maxSize.get(rootB), maxSize.get(rootA)));
            parent.set(rootA, rootB);
            return rootB;
        } else { // rank is equal for both sets
            parent.set(rootB, rootA);
            ++rank.get(rootA);
            return rootA;
        }
    }

    public int countDisjointPairs() {
        return setCount - parent.length();
    }

    public static void main(String[] args) {
        DisjointSet ds = new DisjointSet(new int[]{1, 2, 3, 3, 4, 5, 6, 6, 7});
        long start = System.currentTimeMillis();
        for (int i = 0; i < ds.countDisjointPairs(); ++i) {
            int a = (int)(Math.random() * ds.parent.length());
            int b = (int)(Math.random() * ds.parent.length());
            if (ds.find(a) != ds.find(b)) {
                ds.mergeSets(a, b);
            }
        }
        long end = System.currentTimeMillis();
        System.out.printf("Number of disjoint pairs: %d\n", ds.countDisjointPairs());
        System.out.printf("Time taken to check pairs: %d ms\n", end - start);
    }
}
```

This code snippet provides a simple Union-Find implementation with some optimizations for large arrays and thread safety. The main method demonstrates the usage of the DisjointSet class, generating random pairs of elements to merge and printing the number of disjoint pairs and the time taken to check each pair.

