2. Define a custom semaphore struct that includes the required state and functions:

```c
typedef struct semaphore {
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    memcached_st* mc;
    char key[64]; // Semaphore key in memcached
} semaphore_t;

void init_semaphore(semaphore_t*, const char*, int);
void wait_semaphore(semaphore_t*);
void post_semaphore(semaphore_t*);
void cleanup_semaphore(semaphore_t*);
```

3. Implement the functions:

```c
#define SEMAPHORE_KEY_PREFIX "semaphore:"

void init_seaphore(semaphore_t *sem, const char *name, int value) {
    memset(sem, 0, sizeof(*sem));
    strncpy(sem->key, SEMAPHORE_KEY_PREFIX, sizeof(sem->key));
    strncat(sem->key, name, sizeof(sem->key) - strlen(SEMAPHORE_KEY_PREFIX));

    sem->count = value;
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);
    memcached_return_t rc = memcached_return_success; // Default success return value

    // Initialize memcached connection and set semaphore key-value pair
    memcached_st *mc = memcached_create(NULL);
    if (!mc) {
        fprintf(stderr, "Error creating memcached instance.\n");
        rc = memcached_return_fatal;
    }
    else {
        if (memcached_server_list_append(mc, "localhost", 11211, &rc) != MEMCACHED_SUCCESS) {
            fprintf(stderr, "Error appending server to memcached instance.\n");
            rc = memcached_return_fatal;
        }
    }

    if (rc == memcached_return_success) {
        sem->mc = mc;
        void *value = &sem->count;
        int status = memcached_set(sem->mc, sem->key, strlen(sem->key), 0, 0, &value, sizeof(int));
        if (status != MEMCACHED_SUCCESS) {
            fprintf(stderr, "Error setting initial semaphore value in memcached.\n");
            rc = memcached_return_fatal;
        }
    }
}

void wait_semaphore(semaphore_t *sem) {
    void *value;
    int status = memcached_get(sem->mc, sem->key, strlen(sem->key), 0, &value, NULL);
    if (status == MEMCACHED_SUCCESS) {
        int current_count = *(int*)value;
        pthread_mutex_lock(&sem->lock);
        while (current_count <= 0) {
            pthread_cond_wait(&sem->cond, &sem->lock);
            current_count = *(int*)value;
        }
        --*(int*)value;
        pthread_mutex_unlock(&sem->lock);
    }
    else {
        fprintf(stderr, "Error retrieving semaphore value from memcached.\n");
    }
}

void post_semaphore(semaphore_t *sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->count;
    pthread_mutex_unlock(&sem->lock);

    memcached_return_t rc = memcached_return_success;
    if (rc == memcached_return_success) {
        int status = memcached_set(sem->mc, sem->key, strlen(sem->key), 0, 0, &sem->count, sizeof(int));
        if (status != MEMCACHED_SUCCESS) {
            fprintf(stderr, "Error setting updated semaphore value in memcached.\n");
            rc = memcached_return_fatal;
        }
    }
}

void cleanup_semaphore(semaphore_t *sem) {
    if (sem->mc) {
        memcached_free(sem->mc);
        sem->mc = NULL;
    }
    pthread_mutex_destroy(&sem->lock);
    pthread_cond_destroy(&sem->cond);
}
```

