const fs = require('fs-extra');
const path = require('path');
const zlib = require('zlib');
const chokidar = require('chokidar');
const asyncPool = require('async-pool');
const AWS = require('aws-sdk');
const config = require('config');
const Logger = require('pino');

class DynamicFileProcessor {
  constructor({ cloudStorage, logger }) {
    this.cloudStorage = cloudStorage || new S3(AWS.defaultClient);
    this.logger = logger || Logger({ level: 'debug' });
    this.threadPool = asyncPool(config.get('ThreadPoolSize'), this.processFile.bind(this), { concurrencyLimit: config.get('ConcurrencyLimit') });
  }

  async readDirectory(directory) {
    try {
      const files = await fs.readdir(directory);
      return Promise.all(files.map(file => path.join(directory, file)));
    } catch (error) {
      this.logger.error({ error }, `Failed to read directory: ${directory}`);
      throw error;
    }
  }

  async filterFilesByExtension(directory, extension) {
    const files = await this.readDirectory(directory);
    return files.filter(file => path.extname(file) === `.${extension}`);
  }

  async processFile(filePath) {
    try {
      const data = await fs.readFile(filePath);
      // Process the file here

      // Compress the file if needed
      if (config.get('Compression')) {
        const compressedData = zlib.gzipSync(data);
        await fs.writeFile(`${filePath}.gz`, compressedData);
      }
    } catch (error) {
      this.logger.error({ error }, `Failed to process file: ${filePath}`);
    }
  }

  async uploadToCloudStorage(filePath, cloudKey) {
    try {
      await this.cloudStorage.upload({
        Bucket: config.get('S3Bucket'),
        Key: cloudKey,
        Body: fs.createReadStream(filePath),
      }).promise();
    } catch (error) {
      this.logger.error({ error }, `Failed to upload file to cloud storage: ${filePath}`);
      throw error;
    }
  }

  async downloadFromCloudStorage(cloudKey, destinationDir) {
    try {
      const s3Object = await this.cloudStorage.getObject({
        Bucket: config.get('S3Bucket'),
        Key: cloudKey,
      }).promise();

      // Write the file to the specified directory
      await fs.writeFile(path.join(destinationDir, path.basename(cloudKey)), s3Object.Body);
    } catch (error) {
      this.logger.error({ error }, `Failed to download file from cloud storage: ${cloudKey}`);
      throw error;
    }
  }

  async processDirectory(directory, extension, options = {}) {
    const files = await this.filterFilesByExtension(directory, extension);

    if (!options.cancelToken) {
      // Create a watcher to handle real-time processing of new or updated files
      const watcher = chokidar.watch(directory, { persistent: true });
      watcher.on('add', filePath => this.threadPool.execute(filePath));
      watcher.on('change', filePath => this.threadPool.execute(filePath));
    }

    await Promise.all(files.map(filePath => this.threadPool.execute(filePath, options)));
  }
}
