Here's a simplified version of the requested JavaScript function using Node.js, ES6, and WorkerThreads for concurrent processing. It integrates with cloud storage service (Google Cloud Storage in this example) and uses memory-cache package for caching frequently accessed files.

```javascript
const fs = require('fs');
const path = require('path');
const readline = require('@google-cloud/readline');
const MemoryCache = require('memory-cache');
const { Storage } = require('@google-cloud/storage');

const storage = new Storage();
const cache = new MemoryCache({ max: 1000, checkperiod: 60*60 }); // configure cache settings as needed

function readFiles(dir, version, cb) {
  const files = [];
  const filePromises = [];

  function processFile(filePath) {
    return new Promise((resolve, reject) => {
      const encoding = 'utf8'; // default to utf-8 encoding
      const requestOptions = { version };

      const cachedFile = cache.get(filePath);
      if (cachedFile) {
        console.log(`Using cached file: ${filePath}`);
        return resolve(cachedFile);
      }

      fs.readFile(filePath, encoding, (err, data) => {
        if (err || !data) reject(err || new Error('Empty file'));
        return resolve(data);
      });
    }).catch(err => {
      storage.bucket('your-bucket-name').file(filePath).getSignedUrl(requestOptions, (urlError, url) => {
        if (urlError) return cb(urlError);

        readline.createInterface({
          input: fs.createReadStream(url),
          output: process.stdout,
          error: process.stderr
        }).on('error', err => cb(err)).on('end', () => {
          const data = filePath.includes('https') ? url : Buffer.from(Buffer.concat([...filePromises])).toString(encoding);
          cache.put(filePath, data); // store the processed file in cache
          files.push(data);
        });
      });
    });
  }

  fs.readdir(dir, (err, files) => {
    if (err) return cb(err);

    files.forEach((file) => {
      const filePath = path.join(dir, file);
      filePromises.push(processFile(filePath));
    });

    Promise.all(filePromises).then(() => cb(null, files.join('\n'))).catch(cb);
  });
}

// Example usage:
readFiles('./your-directory', '1', (err, content) => {
  if (err) throw err;
  console.log('Content: ', content);
});
```

