```javascript
class ChunkManager {
  constructor(options) {
    this.buffer = Buffer.concat([...options.chunks]);
  }

  getData(start, end) {
    const chunkStart = Math.floor(start / CHUNK_SIZE) * CHUNK_SIZE;
    const chunkEnd = Math.ceil(end / CHUNK_SIZE) * CHUNK_SIZE;

    let resultBuffer = Buffer.alloc(0);
    for (let i = chunkStart; i < chunkEnd; ++i) {
      resultBuffer = Buffer.concat([resultBuffer, this.buffer.slice(i, i + CHUNK_SIZE)]);
    }

    return resultBuffer;
  }

  // Support for inlining and non-inlining modes would be added here
}
```

