function copyBuffer(srcBuffers, destBuffer, rangeList) {
  let readIndex = 0;
  let writeIndex = 0;

  for (const [start, end] of rangeList) {
    if (start > srcBuffers[readIndex].length || end > srcBuffers[readIndex].length) {
      throw new Error('Invalid range');
    }

    const chunk = srcBuffers[readIndex].slice(start, end);

    if (chunk.length !== end - start) {
      throw new Error('Insufficient data');
    }

    destBuffer.write(chunk, writeIndex);
    writeIndex += chunk.length;

    // Handle non-contiguous chunks here

    if (readIndex < srcBuffers.length - 1) {
      readIndex++;
    }
  }
}

