#include <iostream>
#include <forward_list>
#include <mutex>
#include <chrono>
#include <thread>
#include <vector>

// Logging helper class for thread-safe logging
class Logger {
public:
    void log(const std::string& message) {
        // Add timestamp, user ID, and operation type to the log message
        // ...
        std::cout << message << '\n';
    }

private:
    mutable std::mutex m_mutex;
};

// Context class for carrying additional information about the operation context
class Context {
public:
    virtual ~Context() = default;
};

// Helper function for searching a forward list while maintaining concurrency safety
template<typename T>
T* findAndLock(std::forward_list<T>& list, const T& target) {
    std::shared_ptr<std::mutex> lock = std::make_shared<std::mutex>();
    auto it = std::find_if(list.begin(), list.end(), [&](const T& elem) { return elem == target; });

    if (it != list.end()) {
        std::unique_lock<std::mutex> lck(*lock);
        lck.lock(); // Lock the element to prevent concurrent modifications
        it = list.begin() + std::distance(list.begin(), it); // Relocate the iterator for convenience
    }

    return it;
}

// Function signature as requested
void appendOrInsertAfterTarget(std::forward_list<std::string>& list,
                               const std::string& target,
                               const std::string& value,
                               std::function<void(const std::string&, const std::string&, const Context&)>& callback,
                               const Context& context, Logger& logger) {
    auto found_it = findAndLock<std::string>(list, target);

    if (found_it != list.end()) { // If the target exists
        *found_it = value; // Replace the target with the new value

        std::thread callback_thread([&]() {
            auto start = std::chrono::high_resolution_clock::now();
            callback(target, value, context); // Invoke the callback function
            logger.log("Callback invoked: " + std::to_string(std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - start).count()) + " seconds");
        });

        callback_thread.detach(); // Run the callback on a separate thread
    } else { // If the target doesn't exist
        list.insert_after(*list.begin(), value); // Insert the new element after the first one
    }
}
```

