#include <stdexcept>
#include <mutex>
#include <functional>
#include <atomic>
#include <iostream>
#include <boost/asio.hpp>

class Node {
public:
    std::string name;
    std::string attribute;

    // Constructor, destructor, and other member functions as needed
};

// Helper function to fetch external validation for node names and attributes
bool validateNodeData(const std::string& nodeName, const std::string& attribute);

void updateNodeAttributes(std::forward_list<std::unique_ptr<Node>>& list, const std::string& nodeName, const std::string& newAttribute, const std::string& context) {
    // Preallocate a new Node object for efficient insertion if necessary
    static std::unique_ptr<Node> newNode(std::make_unique<Node>());

    std::mutex listMutex;

    auto it = list.begin();
    auto end = list.end();

    // Use an atomic counter to track the current node iterator position
    std::atomic<decltype(it)>=0> counter{0};

    auto updateNode = [&](auto it) {
        if (!it->get()) return; // Skip empty nodes

        if (it->get()->name == nodeName && it->get()->attribute != newAttribute) {
            it.get()->attribute = newAttribute;
            logOperation(*it, context);
            return;
        }

        counter++;
        std::advance(it, 1); // Move to the next node in the list
    };

    auto task = [&](auto it) {
        if (boost::asio::posted_work::is_posting()) return; // Prevent racing with concurrent postings

        try {
            if (!validateNodeData(nodeName, newAttribute)) throw std::runtime_error("Invalid node data");

            updateNode(it);

            if (counter >= list.size()) {
                // If we didn't find the node and reached the end of the list, create a new node
                newNode->name = nodeName;
                newNode->attribute = newAttribute;
                std::unique_lock<std::mutex> lock(listMutex);
                list.emplace_back(std::move(newNode));
            }
        } catch (const std::exception& e) {
            std::cerr << "Error: " << e.what() << "\n";
        }
    };

    // Use posted work to safely handle concurrent modifications and network delays/failures
    boost::asio::post(boost::asio::io_service(), task, std::move(it));
}

