}

void batchConvertImagesToPdf(const char *input_dir, const char *base_output_dir, int max_compression) {
    if (!is_directory_valid(input_dir)) {
        log_message("Input directory does not exist.");
        return;
    }

    create_output_directory(base_output_dir);

    log_file = fopen("conversion.log", "w+");
    signal(SIGINT, signal_handler);

    int index = 0;
    ImageData *img_data = get_next_image_data(input_dir, &index);
    pthread_t thread_id;

    while (img_data) {
        pthread_create(&thread_id, NULL, convert_image, img_data);
        pthread_join(thread_id, NULL);
        img_data = get_next_image_data(input_dir, &index);
    }

    fclose(log_file);
}
