#include <string.h>
#include <malloc.h> // for portable memory allocation functions

typedef struct AES256GCM_context {
    EVP_CIPHER_CTX* cipher;
    unsigned char key[32];
    unsigned char iv[16];
} AES256GCM_ctx;

static int init_aes256gcm(AES256GCM_ctx* ctx, const char* passphrase, const char* salt, size_t iv_len) {
    if (!passphrase || !salt || iv_len < 12) return -1; // Invalid inputs

    EVP_CIPHER_CTX* cipher = EVP_CIPHER_CTX_new();
    if (!cipher) return -2; // Memory allocation failure

    int ret = EVP_PBE_with_SHA256_and_AES_256_CBC(cipher, NULL, NULL, passphrase, strlen(passphrase), salt, strlen(salt), NULL, 0);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(cipher);
        return -3; // Cryptographic failure
    }

    size_t key_len = sizeof(ctx->key);
    ret = EVP_PBE_with_SHA256_and_AES_256_CBC(cipher, ctx->key, &key_len, passphrase, strlen(passphrase), salt, strlen(salt), ctx->iv, iv_len);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        EVP_CIPHER_CTX_free(cipher);
        return -3; // Cryptographic failure
    }

    ctx->cipher = cipher;
    if (iv_len < 12) memset(ctx->iv + iv_len, 0, 12 - iv_len);
    return 0;
}

static void cleanup_aes256gcm(AES256GCM_ctx* ctx) {
    if (ctx->cipher) {
        EVP_CIPHER_CTX_free(ctx->cipher);
        ctx->cipher = NULL;
    }
}

// ... Implement the key management service interface for salt and passphrase retrieval here ...

int encrypt_data(const AES256GCM_ctx* ctx, const unsigned char* data, size_t len, unsigned char** out) {
    if (!ctx || !data || len <= 0 || !out) return -1; // Invalid inputs

    EVP_CIPHER_CTX* cipher = ctx->cipher;
    if (!cipher) return -2; // Resource not initialized

    unsigned char buffer[16 + 16 + len];
    size_t buffer_len = sizeof(buffer);
    memcpy(buffer, ctx->iv, 12);
    size_t encrypted_len = EVP_CipherInit(cipher);
    if (encrypted_len <= 0) {
        ERR_print_errors_fp(stderr);
        return -3; // Cryptographic failure
    }
    size_t padding_len = EVP_CIPHER_CTX_get_padding(cipher);
    buffer_len -= encrypted_len + padding_len;
    if (buffer_len < len) {
        free(*out);
        return -4; // Insufficient output buffer
    }
    memcpy(buffer + encrypted_len, data, len);

    int ret = EVP_CipherUpdate(cipher, buffer, &encrypted_len);
    if (ret <= 0) {
        ERR_print_errors_fp(stderr);
        return -3; // Cryptographic failure
    }
    memcpy(*out, buffer, encrypted_len + padding_len);
    return encrypted_len + padding_len;
}
```

