    private readonly IAmazonS3 _s3Client;
    private readonly ElasticClient _elasticClient;
    private readonly IConfiguration _configuration;
    private readonly SemaphoreSlim _threadPool;
    private readonly BlockingCollection<ProcessFileTask> _queue;

    public DynamicFileProcessor(ILoggerFactory loggerFactory, IAmazonS3 s3Client, ElasticClient elasticClient, IConfiguration configuration)
    {
        _logger = loggerFactory.CreateLogger<DynamicFileProcessor>();
        _s3Client = s3Client;
        _elasticClient = elasticClient;
        _configuration = configuration;
        _threadPool = new SemaphoreSlim(_configuration["ThreadPoolSize"]);
        _queue = new BlockingCollection<ProcessFileTask>();
    }

    public void StartProcessing()
    {
        var taskCompletionSourceList = Enumerable.Range(0, _configuration["MaxConcurrentTasks"]).Select(_ => new TaskCompletionSource<ProcessFileTask>()).ToList();
        var tasks = taskCompletionSourceList.Select(tcs => Task.Factory.StartNew(() => tcs.TrySetResult(Dequeue()), TaskCreationOptions.LongRunning)).ToList();

        CancellationTokenSource cts = new CancellationTokenSource();
        Task.Run(() => { while (!cts.IsCancellationRequested) { var task = tasks.FirstOrDefault(t => t.Status == TaskStatus.WaitingForActivation); if (task != null) task.Start(); } }, cts);
    }

    public void AddTask(ProcessFileTask task)
    {
        _queue.Add(task);
    }

