#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    long *offsets;
    int *keys;
    Record *records;
    size_t num_records;
    int min_value, max_value;
    bool (*validate)(long *, int *, size_t);
} InitData;

bool validate(long *offsets, int *keys, size_t num_records) {
    // Custom validation logic here. Return true if valid, false otherwise.
    return true;
}

void* init_arrays(void* data) {
    InitData *id = (InitData*)data;

    id->offsets = calloc(id->num_records + 1, sizeof(long));
    if (!id->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return NULL;
    }

    id->keys = malloc(id->num_records * sizeof(int));
    if (!id->keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(id->offsets);
        return NULL;
    }

    id->records = calloc(id->num_records, sizeof(Record));
    if (!id->records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(id->keys);
        free(id->offsets);
        return NULL;
    }

    pthread_mutex_init(&id->mutex, NULL);

    srand(time(NULL));

    size_t i = 0;
    for (; i < id->num_records; ++i) {
        while (!id->validate(id->offsets, id->keys + i, id->num_records)) {
            id->keys[i] = rand() % (id->max_value - id->min_value + 1) + id->min_value;
            id->offsets[i + 1] = id->offsets[i] + id->keys[i];
        }

        id->records[i].value = rand() % (id->max_value - id->min_value + 1) + id->min_value;
    }

    id->offsets[id->num_records] = 0;

    pthread_mutex_destroy(&id->mutex);
    free(id->keys);
    free(id->offsets);
    return id->records;
}

InitData* create_init_data(size_t num_records, int min_value, int max_value, bool (*validate)(long *, int *, size_t)) {
    InitData *id = malloc(sizeof(InitData));
    if (!id) {
        fprintf(stderr, "Failed to allocate memory for InitData\n");
        return NULL;
    }

    id->num_records = num_records;
    id->min_value = min_value;
    id->max_value = max_value;
    id->validate = validate;

    return id;
}
