    while (currentFileIndex < nonEmptyFiles.length) {
      const chunkSize = Math.min(this.maxConcurrentOperations, nonEmptyFiles.length - currentFileIndex);
      const fileChunk = nonEmptyFiles.slice(currentFileIndex, currentFileIndex + chunkSize);

