```javascript
import { Map } from 'immutable'; // For dependency management

const CDN_REGEX = /^https?:\/\/[^\s/.]+/;

class ModuleLoader {
  constructor(dependencyMap) {
    this.dependencyMap = dependencyMap;
    this.loadedModules = new Map();
  }

  loadModule(moduleName) {
    if (this.loadedModules.has(moduleName)) return this.loadedModules.get(moduleName);

    const modulePath = this.dependencyMap.get(moduleName);

    // Fetch script asynchronously
    fetch(modulePath).then(response => {
      if (!response.ok) throw new Error(`Failed to load module: ${moduleName}`);

      return response.text();
    }).then(scriptCode => {
      const module = new Function('return ' + scriptCode)(this);

      this.loadedModules.set(moduleName, module);

      // Handle any external dependencies by recursively loading them
      Array.from(module.dependencies).forEach(dependency => this.loadModule(dependency));
    }).catch(error => console.error(`Error while loading module: ${moduleName}`, error));

    return this.loadedModules.get(moduleName); // Return a promise that resolves to the loaded module (or previously loaded if available)
  }

  // Optionally, you can provide an async function to execute modules in the correct order
  executeModules(callback) {
    const keys = Array.from(this.loadedModules.keys());
    const sortedKeys = keys.sort((a, b) => this.dependencyMap.get(b).version - this.dependencyMap.get(a).version); // Sort by version number for proper execution order (assuming dependency management system provides versioning)

    let executedModulesCount = 0;
    const executeNextModule = () => {
      if (executedModulesCount < sortedKeys.length) {
        const moduleName = sortedKeys[executedModulesCount];
        const module = this.loadedModules.get(moduleName);

        if (!module || module.loadingError) return; // Skip modules with errors

        executedModulesCount++;

        module.call({}, (...args) => {
          // Execute the callback function once all modules have been loaded and executed
          if (executedModulesCount === sortedKeys.length) callback(...args);
          else executeNextModule();
        });
      }
    };

    executeNextModule();
  }
}
```

This code provides a basic module loader for JavaScript that integrates with an external dependency management system (like Webpack or RequireJS). The `loadModule()` method fetches and executes the specified script, handling network errors and managing dependencies recursively. The `executeModules()` function allows you to execute all modules in the correct order when needed.

