import com.jcraft.jsch.*;
import org.apache.commons.net.telnet.TelnetClient;
import org.junit.jupiter.api.*;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class RemoteCommandExecutor {
    private static final String CONFIG_FILE = "config.json"; // Update this with the path to your external configuration file or API endpoint
    private Map<String, ServerConfiguration> servers;

    public RemoteCommandExecutor() throws IOException {
        servers = loadServersFromConfig();
    }

    public void executeCommands(String targetFile, String updateCommand) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(servers.size());
        List<Future<?>> futures = new ArrayList<>();

        for (Map.Entry<String, ServerConfiguration> server : servers.entrySet()) {
            final String key = server.getKey();
            Callable callable = () -> executeCommandOnServer(server.getValue(), targetFile, updateCommand);
            futures.add(executor.submit(callable));
        }

        executor.shutdown();
        try {
            Future<Void> future = executor.invokeAny(futures);
            future.get();
        } catch (ExecutionException | InterruptedException e) {
            e.printStackTrace();
        } finally {
            if (!executor.isTerminated()) {
                executor.shutdownNow();
            }
        }
    }

    private Map<String, ServerConfiguration> loadServersFromConfig() throws IOException {
        // Load servers configuration here
    }

    private void executeCommandOnServer(ServerConfiguration serverConfig, String targetFile, String updateCommand) throws Exception {
        TelnetClient telnetClient = new TelnetClient();
        JSch jsch = new JSch();

        try (InputStream in = null; OutputStream out = null; BufferedReader reader = null; PrintWriter writer = null) {
            if (!telnetClient.connect(serverConfig.getHost(), serverConfig.getPort())) {
                System.out.println("Failed to connect: " + telnetClient.getReply());
                return;
            }

            reader = new BufferedReader(new InputStreamReader(telnetClient.getInputStream()));
            writer = new PrintWriter(telnetClient.getOutputStream());

            Session session = null;
            try {
                session = jsch.getSession(serverConfig.getUser(), serverConfig.getHost(), serverConfig.getPort());
                JSchException jschException = null;

                if (serverConfig.getKeyFile() != null) {
                    session.setConfig("StrictHostKeyChecking", "no");
                    session.loadHostKeyRepository(new File(serverConfig.getKeyFile()));
                } else {
                    session.setPassword(serverConfig.getPassword());
                }

                session.connect();
                Channel channel = session.openChannel("shell");
                channel.connect();

                out = new PrintStream(channel.getOutputStream());
                InputStream input = channel.getInputStream();

                // Execute command to check if file exists and delete it
                out.println("ls " + targetFile);
                out.flush();
                String line;
                while ((line = reader.readLine()) != null) {
                    if (line.contains(targetFile)) {
                        out.println("rm " + targetFile);
                        out.flush();
                    }
                }

                // Execute the update command
                out.println(updateCommand);
                out.flush();

                // Read and process the output from the server
                while (true) {
                    int i = input.read();
                    if (i < 0) {
                        break;
                    }
                    System.out.print((char) i);
                }
            } catch (JSchException e) {
                jschException = e;
            } finally {
                if (session != null) {
                    session.disconnect();
                }
                if (telnetClient.isConnected()) {
                    telnetClient.disconnect();
                }
                if (reader != null) reader.close();
                if (writer != null) writer.close();

                if (jschException != null) {
                    jschException.printStackTrace();
                }
            }
        }
    }
}
