            return self._decrypt(cached_value)
        try:
            response = requests.get(self.api_url + f"?setting={setting_name}")
            if response.status_code == 200:
                setting_data = response.json()
                self.cache.set(f"config:{setting_name}", self._encrypt(setting_data), ex=self.cache_expiration)
                return setting_data
            else:
                logging.error(f"Error fetching configuration for {setting_name}: {response.status_code}")
        except requests.exceptions.RequestException as e:
            logging.error(f"Error fetching configuration for {setting_name}: {e}")
        return default

    def update_cache(self):
        settings = self.get_config("allSettings", {})
        if not settings:
            return
        for setting in settings:
            self.cache.set(f"config:{setting}", self._encrypt(settings[setting]), ex=self.cache_expiration)

    def run(self):
        while True:
            self.update_cache()
            timedelta(seconds=self.update_interval).sleep()
