using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using UnityEngine;

namespace AsyncFileReaderManager
{
    public class AsyncFileReaderManager
    {
        private int minValue, maxValue;
        private readonly object _lock = new object();

        public int MinValue { get => minValue; set => lock (_lock) { minValue = value; } }
        public int MaxValue { get => maxValue; set => lock (_lock) { maxValue = value; } }

        public override string ToString() => $"Range: [{MinValue}, {MaxValue}]";

        private async Task<Dictionary<string, long>> GetDirectoryContentAsync(string directoryPath, int sizeLimit, bool includeDirectories, List<string> extensionsToProcess)
        {
            var fileLengths = new Dictionary<string, long>();

            try
            {
                var directoryInfo = new DirectoryInfo(directoryPath);

                if (!directoryInfo.Exists)
                {
                    throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");
                }

                ParallelOptions options = new ParallelOptions() { MaxDegreeOfParallelism = Environment.ProcessorCount / 2 }; // Adjust degree of parallelism according to system resources

                if (!includeDirectories)
                {
                    await Parallel.ForEachAsync(directoryInfo.EnumerateFiles(), options, async (FileInfo file) =>
                    {
                        try
                        {
                            if (file.Extension.InArray(extensionsToProcess))
                            {
                                fileLengths[file.FullName] = file.Length;

                                if (fileLengths.Sum() > sizeLimit)
                                {
                                    return Task.FromResult<bool>(true); // Return true to break the loop early when the limit is reached
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"An error occurred while processing file '{file.FullName}': {ex}");
                        }
                    });
                }
                else
                {
                    await Parallel.ForEachAsync(directoryInfo.EnumerateFiles("*", SearchOption.AllDirectories), options, async (FileInfo file) =>
                    {
                        try
                        {
                            if (file.Extension.InArray(extensionsToProcess))
                            {
                                fileLengths[file.FullName] = file.Length;

                                if (fileLengths.Sum() > sizeLimit)
                                {
                                    return Task.FromResult<bool>(true); // Return true to break the loop early when the limit is reached
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            Debug.LogError($"An error occurred while processing file '{file.FullName}': {ex}");
                        }
                    });
                }
            }
            catch (Exception ex)
            {
                Debug.LogError($"An error occurred while getting directory content: {ex}");
                return null;
            }

            return fileLengths;
        }

        private int RandomInclusive(int min, int max) => UnityEngine.Random.Range(min, max + 1);
        private int RandomExclusive(int min, int max) => UnityEngine.Random.Range(min, max);
    }
}
```

This code defines an `AsyncFileReaderManager` class that implements the specified requirements. The `GetDirectoryContentAsync` method uses parallel processing to read file lengths asynchronously and handles exceptions for missing files or unsupported encoding. The degree of parallelism is controlled by adjusting the maximum degree of parallelism based on the number of available processors.

1. Semaphore System (semaphore_system.h and semaphore_system.c)

```c
#ifndef SEMAPHORE_SYSTEM_H
#define SEMAPHORE_SYSTEM_H

typedef struct SemaphoreSem {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int count;
} SemaphoreSem;

void semaphore_init(SemaphoreSem *sem, int initial_count);
int semaphore_wait(SemaphoreSem *sem);
void semaphore_post(SemaphoreSem *sem);
void semaphore_destroy(SemaphoreSem *sem);

#endif // SEMAPHORE_SYSTEM_H

#ifndef SEMAPHORE_SYSTEM_C
#define SEMAPHORE_SYSTEM_C

#include "semaphore_system.h"
#include <pthread.h>

void semaphore_init(SemaphoreSem *sem, int initial_count) {
    pthread_mutex_init(&sem->lock, NULL);
    pthread_cond_init(&sem->cond, NULL);
    sem->count = initial_count;
}

int semaphore_wait(SemaphoreSem *sem) {
    int result;
    pthread_mutex_lock(&sem->lock);

    while (sem->count <= 0) {
        result = pthread_cond_wait(&sem->cond, &sem->lock);
        if (result != 0 && errno != EINTR) {
            pthread_mutex_unlock(&sem->lock);
            return -1;
        }
    }

    --sem->count;
    pthread_mutex_unlock(&sem->lock);
    return 0;
}

void semaphore_post(SemaphoreSem *sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->count;
    pthread_mutex_unlock(&sem->lock);
    pthread_cond_signal(&sem->cond);
}

void semaphore_destroy(SemaphoreSem *sem) {
    pthread_mutex_destroy(&sem->lock);
    pthread_cond_destroy(&sem->cond);
}

#endif // SEMAPHORE_SYSTEM_C
```

2. TIFF Image Metadata Extraction (tiff_metadata.h and tiff_metadata.c)

```c
#ifndef TIFF_METADATA_H
#define TIFF_METADATA_H

typedef struct TiffMetadata {
    uint16_t bits_per_sample;
    uint16_t sample_per_pixel;
    int compression;
    double resolution[2];
    char color_space[4];
    uint16_t num_extra_samples;
} TiffMetadata;

TiffMetadata tiff_metadata_extract(const char *filename);
void tiff_metadata_store(const TiffMetadata *metadata, const char *filename);

#endif // TIFF_METADATA_H

#ifndef TIFF_METADATA_C
#define TIFF_METADATA_C

#include "tiff.h"
#include <string.h>
#include <stdio.h>
#include <math.h>

TiffMetadata tiff_metadata_extract(const char *filename) {
    Tiff *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        return (TiffMetadata){ .bits_per_sample = 0 };
    }

    TiffMetadata metadata;
    uint16_t samples_per_pixel;
    int bits_per_sample;
    int compression;
    double xres, yres;
    char color_space[4];
    uint16_t num_extra_samples = 0;

    TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samples_per_pixel);
    switch (samples_per_pixel) {
        case 1:
            bits_per_sample = TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, 8);
            break;
        case 2:
            bits_per_sample = TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, 16);
            if (bits_per_sample != 8 && bits_per_sample != 16) {
                TIFFClose(tiff);
                return (TiffMetadata){ .bits_per_sample = 0 };
            }
            break;
        case 4:
            bits_per_sample = TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, 8);
            if (bits_per_sample != 8) {
                TIFFClose(tiff);
                return (TiffMetadata){ .bits_per_sample = 0 };
            }
            break;
        case 8:
            bits_per_sample = TIFFGetFieldDefaulted(tiff, TIFFTAG_BITSPERSAMPLE, 8);
            break;
        default:
            TIFFClose(tiff);
            return (TiffMetadata){ .bits_per_sample = 0 };
    }

    compression = TIFFGetFieldDefaulted(tiff, TIFFTAG_COMPRESSION, COMPRESSION_NONE);

    if (TIFFGetField(tiff, TIFFTAG_RESOLUTION, &xres, &yres) != 1 || xres <= 0.0 || yres <= 0.0) {
        xres = yres = 72; // Default value
    }

    if (TIFFGetField(tiff, TIFFTAG_COLORMAP, color_space, sizeof(color_space)) != 1) {
        memcpy(color_space, "RGB ", sizeof(color_space));
    }

    uint16_t extra_samples;
    if (TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extra_samples) != 1) {
        num_extra_samples = 0;
    } else {
        num_extra_samples = extra_samples - 3;
    }

    TIFFClose(tiff);
    metadata = (TiffMetadata){ .bits_per_sample, .sample_per_pixel = samples_per_pixel,
                               .compression, .resolution = { xres, yres },
                               .color_space, .num_extra_samples };
    return metadata;
}

void tiff_metadata_store(const TiffMetadata *metadata, const char *filename) {
    // Implement a function to store the extracted metadata into an external database
}

#endif // TIFF_METADATA_C
