// Thread-safe wrapper for the callback
class ThreadSafeCallback : public Callback {
private:
    std::mutex mtx_;
    Callback* cb_;
public:
    explicit ThreadSafeCallback(Callback* cb) : cb_(cb) {}
    void operator()(const std::string& placeholder) override {
        std::unique_lock<std::mutex> lock(mtx_);
        cb_->operator()(placeholder);
    }
};

class ModifyKickstartConfig {
