        : configFilePath_(filePath), callback_(cb), placeholderRegex_(std::regex("{{(.*?)}}")) {}

    void modify() {
        std::ifstream ifs(configFilePath_);
        if (!ifs.is_open()) {
            throw std::system_error(errno, std::generic_category(), "Error opening config file");
        }

