            if (!oss.str().empty()) { // Add a new line with the encrypted password only when there's something to print
                fmt::print_thread_safe(fmt::format("{}: {} - modifying config: {}", chrono::system_clock::now().time_since_epoch().count(), getuid(), oss.str()));
                lines_.push_back(oss.str() + "\n" + encryptedPassword);
            }
        }

        ifs.close();
    }

private:
