using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.Schema;
using System.Xml.XPath;
using System.Threading.Tasks;
using System.Security.Cryptography.Xml;

namespace XmlParser
{
    public class Config
    {
        // Properties for configuring the parser, such as default namespaces, logging options, etc.
    }

    public class XmlValidator
    {
        // Class for validating XML content against an XML schema if provided.
    }

    public class XPathQueryEngine
    {
        // Class for executing XPath queries efficiently on large XML documents.
    }

    public class XmlParser
    {
        private readonly Config _config;
        private readonly XmlValidator _validator;
        private readonly XPathQueryEngine _xpath;

        public XmlParser(Config config)
        {
            // Initialize properties with passed configuration.
            _config = config;
            _validator = new XmlValidator(config);
            _xpath = new XPathQueryEngine();
        }

        public async Task<XmlNode> ParseAsync(string pathOrXmlString, string xPathQuery)
        {
            // Validate the XML content before parsing.
            if (!_validator.IsValid(pathOrXmlString))
                throw new Exception("Invalid XML content.");

            // Load XML from file or string and create an XmlDocument object.
            var xmlDoc = CreateXmlDocumentFromSource(pathOrXmlString);

            // Perform lazy loading of nodes to minimize memory consumption.
            xmlDoc.LoadXPath(xPathQuery);

            // Extract the first matching node, or throw an exception if no match is found or multiple matches exist.
            var node = xmlDoc.SelectSingleNode(xPathQuery) ?? throw new Exception("No node was found with the given XPath query.");

            return node;
        }

        public async Task<XmlNode> ParseAsync(Stream stream, string xPathQuery)
        {
            // Validate the XML content before parsing.
            if (!_validator.IsValid(stream))
                throw new Exception("Invalid XML content.");

            // Create an XmlDocument object and load the XML data from the stream asynchronously.
            var xmlDoc = new XmlDocument();
            await xmlDoc.LoadAsync(stream);

            // Perform lazy loading of nodes to minimize memory consumption.
            xmlDoc.LoadXPath(xPathQuery);

            // Extract the first matching node, or throw an exception if no match is found or multiple matches exist.
            var node = xmlDoc.SelectSingleNode(xPathQuery) ?? throw new Exception("No node was found with the given XPath query.");

            return node;
        }

        private XmlDocument CreateXmlDocumentFromSource(string pathOrXmlString)
        {
            if (Uri.IsWellFormedUriString(pathOrXmlString, UriKind.Absolute))
                // Load XML from file using a Uri object.
                return new XmlDocument();

            // Load XML directly from a string.
            var xml = XElement.Parse(pathOrXmlString);
            return xml.CreateNavigator().ReadOuterXmlAsDoc();
        }
    }
}
