use std::env;
use std::fs::{self, create_dir_all, remove_dir_all};
use std::sync::Mutex;
use tempfile::Builder as TempDirBuilder;
use rayon::prelude::*;
use dotenv::dotenv;
use reqwest::blocking::get;
use serde::Deserialize;

#[derive(Deserialize)]
struct Config {
    base_dir: String,
}

static CONFIG: Lazy<Mutex<Option<Config>>> = Lazy::new(|| Mutex::new(None));

pub fn setup_temp_dir() -> Result<String, Box<dyn std::error::Error>> {
    let mut config = match *CONFIG.lock().unwrap() {
        Some(ref c) => c.clone(),
        None => {
            dotenv().ok(); // load .env file if it exists
            let resp = get("https://your-config-service.com/config")?;
            let config: Config = serde_json::from_str(&resp.text()?).unwrap();
            config
        }
    };

    let subdir = TempDirBuilder::new().prefix("myapp_").tempdir()?.path();
    env::set_var("TMPDIR", &subdir.to_str().unwrap());
    Ok(String::from(subdir.to_str().unwrap()))
}

pub fn cleanup() {
    let mut config = match *CONFIG.lock().unwrap() {
        Some(ref c) => c.clone(),
        None => return, // continue if no configuration was loaded
    };

    let subdir = format!("{}/{}", &config.base_dir, env::var_os("TMPDIR").as_deref().unwrap());
    if fs::metadata(&subdir).is_ok() {
        create_dir_all(subdir).unwrap();
        remove_dir_all(&subdir).unwrap();
    }
}

// Use Rayon's `par_iter` for multi-threaded operations on the temporary directories
fn do_something_with_temporary_dirs(directory: &str) {
