import concurrent.futures
import json
import os
import random
import string
import time
from unittest.mock import patch

import requests_mock  # third-party library for testing HTTP requests and responses

# Define a function to encrypt password using mock subprocess command
def encrypt_password(password):
    return f"ENCRYPTED_{''.join(random.choices(string.ascii_uppercase + string.digits, k=16))}"

# Define a function to replace placeholders in the Kickstart configuration file
def modify_config(config, replacements):
    for key, value in replacements.items():
        config = config.replace(key, value)
    # Add new line with encrypted password
    config += f"\n{encrypt_password('my-secret-password')}"
    return config

# Define a function to handle GET request to the service and process responses
def get_user_data(api_url, params):
    response = requests.get(api_url, params=params)
    if response.status_code == 200:
        return json.loads(response.content)
    elif response.status_code == 408:
        raise TimeoutError("Request timed out")
    elif response.status_code >= 500:
        raise Exception(f"Server error: {response.status_code}")

# Define a function to retry failed requests with exponential backoff
def retry_get_user_data(api_url, params, max_retries=3):
    for attempt in range(max_retries):
        try:
            return get_user_data(api_url, params)
        except (TimeoutError, Exception) as e:
            if attempt < max_retries - 1:
                delay = 2 ** attempt
                time.sleep(delay)
            else:
                raise e

# Define a function to aggregate data from multiple responses into a single structured format
def aggregate_data(responses):
    result = {}
    for response in responses:
        for key, value in response.items():
            if key not in result:
                result[key] = []
            result[key].extend(value)
    return result

# Test double for the subprocess module using requests_mock
@patch("subprocess.run")
def test_modify_config(mock_subprocess):
    config = "placeholder-1\nplaceholder-2"
    replacements = {"placeholder-1": "value-1", "placeholder-2": "value-2"}
    modify_config(config, replacements)
    mock_subprocess.assert_called()

# Main function to perform batch processing of user data
def process_users(api_base_url, config_file, user_data_params, max_concurrent=100):
    with open(config_file, "r") as f:
        config = f.read()

    # Replace placeholders in the Kickstart configuration file
    modified_config = modify_config(config, user_data_params)

    # Write the modified config to a temp file
    with open("temp_config.txt", "w") as f:
        f.write(modified_config)

    responses = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = [executor.submit(retry_get_user_data, api_base_url + user["id"], user_data_params[user["key"]]) for user in user_data_params]

        for future in concurrent.futures.as_completed(futures):
            response = future.result()
            responses.append({"id": user["id"], "response": response})

    aggregated_data = aggregate_data(responses)

    # Clean up temp file and clear mock subprocess calls
    os.remove("temp_config.txt")
    mock_subprocess.reset_mock()

    return aggregated_data

# Example usage with test data and mocked responses
api_base_url = "https://my-service.com/users"
user_data_params = {
    "user-1": {"key": "params-1", "id": "1"},
    "user-2": {"key": "params-2", "id": "2"}
}

# Test with mocked network latency and different response statuses
with requests_mock.Mocker() as m:
    m.get(api_base_url + "1", text="user-1 data", delay=0.1)  # success
    m.get(api_base_url + "2", timeout=5)  # timeout
    m.get(api_base_url + "3", status_code=500, delay=0.2)  # server error

process_users(api_base_url, "kickstart.cfg", user_data_params)
