using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;

public class RandomValueGenerator
{
    private const string ApiEndpoint = "https://your-api-endpoint.com/range";
    private readonly HttpClient _httpClient;
    private double _min, _max;
    private CancellationTokenSource _cancellationTokenSource;

    public event Action<double, double> RangeUpdated;

    public RandomValueGenerator()
    {
        _httpClient = new HttpClient();
        FetchRangeAsync().Wait(); // Fetch initial range on construction
    }

    private async Task FetchRangeAsync()
    {
        try
        {
            var response = await _httpClient.GetAsync(ApiEndpoint);
            if (!response.IsSuccessStatusCode) throw new Exception($"Failed to fetch range from API: {response.StatusCode}");

            var content = await response.Content.ReadAsStringAsync();
            var rangeParams = JsonConvert.DeserializeObject<Dictionary<string, string>>(content);

            if (!double.TryParse(rangeParams["min"], out _min) || !double.TryParse(rangeParams["max"], out _max))
                throw new Exception("Invalid or incomplete range parameters from API");

            _cancellationTokenSource = new CancellationTokenSource();
            RangeUpdated?.Invoke(_min, _max);
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully and retry fetching the range periodically
            Debug.LogError($"Error fetching range from API: {ex}");
            _cancellationTokenSource = new CancellationTokenSource();
        }
    }

    public double GetRandomFloat() => UnityEngine.Random.Range(_min, _max);

    public int GetRandomInt() => (int)UnityEngine.Mathf.Round(GetRandomFloat());

    public override string ToString() => $"Current range: ({_min}, {_max}){Environment.NewLine}Status: {_cancellationTokenSource?.IsCancellationRequested ? "Connection failed, retrying..." : "Connected" }";

    public void RequestRangeUpdate()
    {
        FetchRangeAsync().Wait(); // Refresh the range from API
    }

    public async Task<Unit> UpdateRangeAsync(CancellationToken cancellationToken)
    {
        try
        {
            await FetchRangeAsync();
        }
        catch (TaskCanceledException) { } // Ignore cancellation exceptions when the task is manually canceled

        return Unit.Default;
    }
}
