use std::collections::HashMap;
use std::env;
use std::fmt::{self, Debug, Formatter};
use std::io::{self, Write};
use std::mem;
use std::os::unix::process::ExitStatusExt;
use std::path::PathBuf;
use std::sync::{Arc, Mutex, RwLock};
use std::thread;
use std::time::{Duration, Instant};
use rustc_driver::CargoToml;
use rustc_driver::catch_with_exit_code;
use rustc_driver::Config;
use rustc_driver::DiagnosticConsumer;
use rustc_driver::LogHook;

mod util {
    use super::*;

    pub trait Timed {
        fn time(&self) -> Duration;
    }

    pub struct ResourceTracker {
        initial_rss: Option<u64>,
    }

    impl ResourceTracker {
        pub fn new() -> Self {
            ResourceTracker { initial_rss: None }
        }

        pub fn get(&self) -> u64 {
            match self.initial_rss {
                Some(initial) => mem::size_of::<u64>() as u64 + initial,
                None => unsafe { libc::getrusage(libc::RUSAGE_SELF).resid[libc::RUSRES_RSS] as u64 },
            }
        }
    }

    impl Debug for ResourceTracker {
        fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
            write!(f, "ResourceTracker({})", self.get())
        }
    }
}

pub struct CompileJob {
    path: PathBuf,
    log_hook: Arc<RwLock<LogHook>>,
    diagnostics: Vec<String>,
    start_time: Instant,
    resource_tracker: util::ResourceTracker,
}

impl Debug for CompileJob {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        write!(f, "CompileJob({}, {}, {}, {})", self.path.display(), self.start_time, self.resource_tracker, self.diagnostics.len())
    }
}

pub fn compile_multiple(file_paths: Vec<PathBuf>, max_concurrent: usize) -> Result<(f64, f64), io::Error> {
    let mut jobs = Vec::with_capacity(file_paths.len());
    let log_hook = Arc::new(RwLock::new(LogHook::new()));
    for file_path in file_paths {
        let log_hook_clone = Arc::clone(&log_hook);
        jobs.push(CompileJob {
            path: file_path,
            log_hook,
            diagnostics: Vec::new(),
            start_time: Instant::now(),
            resource_tracker: util::ResourceTracker::new(),
        });
    }

    let mut processed = 0;
    let jobs_iter = jobs.into_iter();
    let max_concurrent = min(max_concurrent, jobs_iter.count());
    let mut pool = threadpool::ThreadPool::new(max_concurrent);

    for job in jobs_iter {
        pool.execute(move || {
            let job = Arc::clone(&job);
            compile_single(job)
        });
    }

    let mut total_exit_codes = 0;
    let mut total_duration = Duration::ZERO;
    let mut total_memory = 0u64;

    pool.join();

    for job in jobs {
        total_exit_codes += job.exit_code()?;
        total_duration += job.time();
        total_memory += job.resource_tracker.get();
        writeln!(env::var("RUST_LOG").unwrap().as_mut_os_str().expect("expected a valid environment variable"), "{:?}", job.diagnostics)?;
    }

    let average_exit_code = total_exit_codes as f64 / jobs.len() as f64;
    let average_duration = total_duration / Duration::from_secs(jobs.len() as u64);
    let average_memory = total_memory / jobs.len() as u64;

    Ok((average_exit_code, average_duration.as_secs_f64() + average_memory as f64))
}

fn compile_single(job: CompileJob) -> Result<(), io::Error> {
    let mut config = Config::new();
    config.filenames.push(job.path.to_str().unwrap());
    config.driver = Some(CargoToml::new());

    let mut diagnostics = Vec::new();
    let exit_code = catch_with_exit_code(|_| {
        let log_hook_read = log_hook.write().unwrap();
        log_hook_read.set(&job.path);

        let config_clone = Arc::clone(&config);
        let diagnostics_vec = &mut diagnostics;
        let resource_tracker = job.resource_tracker.clone();

        move || {
            rustc_driver::exec(config_clone, DiagnosticConsumer::new(|diag| diagnostics_vec.push(format!("{}", diag))), None)
                .expect("failed to execute rustc")
                .unwrap()
        }
    })?;

    job.diagnostics.extend(diagnostics);
    Ok(exit_code)
}

fn min<T: Ord>(x: T, y: T) -> T {
    if x < y {
        x
    } else {
        y
    }
}
