static LOGGER: SyncLazy<log4rs::Logger> = SyncLazy::new(|| {
    let root_logger = log4rs::init_file("logging.yml", Default::default()).unwrap();
    root_logger.set_level_filter(log4rs::filters::LevelFilter::Info);
    root_logger
});

fn execute_python_program() -> i32 {
    let python = match which::which("python3") {
        Ok(path) => path,
        Err(_) => {
            error!("Python executable not found. Make sure 'python3' is installed.");
            return 1;
        }
    };

    let json_program = env::current_exe().unwrap();
    let python_args = vec![python, json_program];

    let mut process = Command::new(python)
                             .arg(json_program)
                             .stdout(Stdio::inherit())
                             .stderr(Stdio::inherit())
                             .spawn()
                             .expect("Failed to spawn process");

    let start_time = Instant::now();
    let rss = unsafe { libc::getrusage().resident_setsize as u64 };

    match process.wait() {
        Ok(status) => {
            let elapsed = start_time.elapsed().as_secs_f32();
            let memory_usage = rss / 1024.0; // Convert to KB
            LOGGER.info!("Execution time: {} seconds, Memory usage: {}", elapsed, memory_usage);
            status.code()
        }
        Err(e) => {
            error!("Python program failed with error: {}", e);
            let suggestion = "Check your JSON parsing and creation code for errors.\n\nTips:\n- Make sure your class has the necessary methods for converting data to a JSON string and creating a new instance from a JSON string.\n- Ensure that your JSON objects are properly formatted according to the JSON specification.";
            LOGGER.error!(target: "execution", "{}", suggestion);
            1
        }
    }
}

fn main() {
    catch_with_exit_code(|| {
        let exit_code = execute_python_program();
        if exit_code != 0 {
            return exit_code;
        }
        // Your custom logic here...
        0
    }, |err, diag| {
        error!("{}", err);
        let message = format!(
            "An error occurred while executing the Python program: {} \n\nError details:\n{}",
            err, diag.iter().map(|d| d.message()).collect::<Vec<_>>().join("\n")
        );
        LOGGER.error!(target: "execution", "{}", message);
        1
    })
}
