    pthread_t *threads;
    int thread_count;
    int queue_count;
    pthread_mutex_t queue_mutex;
    pthread_cond_t condition;
};

// Function for validating a single email address
void validate_email(char *email) {
    // Your email validation logic here, using ICU library functions.
    // Ensure the domain part exists and '@' symbol appears only once.
    // Handle IDNs and different character encodings gracefully.
    // Log errors or issues to log_fd as necessary.
}

// Function for processing a single email address in a separate thread
void* process_email(void *arg) {
    char *email = arg;
    validate_email(email);
    free(email);
    return NULL;
}

// Multi-threaded validation function
void validateEmailBatchAdvanced(char **emailBatch, int batchSize, FILE *log_fd) {
    log_fd = log_fd; // Silence unused variable warning

    // Initialize thread pool
    struct thread_pool *tp = malloc(sizeof(struct thread_pool));
    tp->thread_count = 10; // Set the number of worker threads
    tp->queue_count = batchSize;
    tp->threads = calloc(tp->thread_count, sizeof(pthread_t));
    pthread_mutex_init(&tp->queue_mutex, NULL);
    pthread_cond_init(&tp->condition, NULL);

    // Create and start worker threads
    for (int i = 0; i < tp->thread_count; ++i) {
        int rc = pthread_create(&tp->threads[i], NULL, process_email, NULL);
        if (rc) {
            fprintf(log_fd, "Error creating thread: %s\n", strerror(rc));
            exit(EXIT_FAILURE);
        }
    }

    // Process the email batch concurrently using the thread pool
    char **currentBatch = emailBatch;
    char **endBatch = currentBatch + batchSize;
    while (currentBatch < endBatch) {
        pthread_mutex_lock(&tp->queue_mutex);

        if (tp->queue_count == 0) {
            pthread_cond_wait(&tp->condition, &tp->queue_mutex);
        }

        // Add the current email to the thread pool's queue
        tp->queue_count++;
        void *email = (*currentBatch++);
        pthread_mutex_unlock(&tp->queue_mutex);

        // Signal a worker thread to process the email
        pthread_mutex_lock(&tp->queue_mutex);
        if (tp->queue_count <= tp->thread_count) {
            void *arg = email;
            pthread_t *worker = tp->threads + (tp->queue_count - 1);
            pthread_cond_signal(worker);
        }
        pthread_mutex_unlock(&tp->queue_mutex);
    }

    // Wait for all remaining emails in the thread pool to be processed
    while (tp->queue_count > 0) {
        sleep(1);
    }

    // Clean up the thread pool
    pthread_mutex_destroy(&tp->queue_mutex);
    pthread_cond_destroy(&tp->condition);
    free(tp->threads);
}
