typedef struct {
    const char *name;
    void* (*init)(void);
    void (*fini)(void*);
} Plugin;

// Cache structure for plugins
struct PluginCache {
    Plugin **plugins;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    time_t cache_time;
};

// Thread-safe plugin cache functions
PluginCache *plugin_cache_new(void) {
    PluginCache *cache = mmap(NULL, sizeof(PluginCache), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (cache == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    cache->plugins = NULL;
    cache->count = 0;
    cache->capacity = 0;
    pthread_mutex_init(&cache->mutex, NULL);
    cache->cache_time = time(NULL);
    return cache;
}

void plugin_cache_delete(PluginCache *cache) {
    if (cache == NULL) return;

    munmap(cache, sizeof(PluginCache));
}

Plugin* plugin_cache_get(PluginCache *cache, const char *name) {
    // Implement cache invalidation policy based on time or usage metrics here

    pthread_mutex_lock(&cache->mutex);

    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->plugins[i]->name, name) == 0) {
            pthread_mutex_unlock(&cache->mutex);
            return cache->plugins[i];
        }
    }

    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

Plugin* plugin_cache_load(PluginCache *cache, const char *name) {
    Plugin *plugin = plugin_cache_get(cache, name);
    if (plugin != NULL) return plugin;

    // Load the shared library containing the plugin implementation
    void *handle = dlopen("path/to/plugin.so", RTLD_LAZY | RTLD_NOLOAD);
    if (!handle) {
        perror("dlopen");
        return NULL;
    }

    // Get the plugin initialization function from the shared library symbol table
    typedef Plugin* (*get_plugin_func)(void);
    get_plugin_func get_plugin = (get_plugin_func) dlsym(handle, "get_plugin");
    if (get_plugin == NULL) {
        perror("dlsym");
        dlclose(handle);
        return NULL;
    }

    Plugin *new_plugin = get_plugin();
    if (new_plugin->init == NULL) {
        printf("Plugin '%s' has no initialization function.\n", new_plugin->name);
        goto error;
    }

    // Add the loaded plugin to the cache and update the cache time
    pthread_mutex_lock(&cache->mutex);

    if (cache->capacity <= cache->count) {
        Plugin **new_plugins = realloc(cache->plugins, sizeof(Plugin *) * (2 * cache->capacity));
        if (new_plugins == NULL) {
            pthread_mutex_unlock(&cache->mutex);
            perror("realloc");
            goto error;
        }
        cache->plugins = new_plugins;
        cache->capacity *= 2;
    }

    cache->plugins[cache->count] = new_plugin;
    ++cache->count;
    cache->cache_time = time(NULL);

    pthread_mutex_unlock(&cache->mutex);

    return new_plugin;
error:
    if (handle) dlclose(handle);
    return NULL;
}

