            dataSource = DriverManager.getDataSource("jdbc:mysql://db-server:3306/mydb", "user", "password");
            pdfCache = CacheBuilder.newBuilder().maximumSize(MAX_CACHE_SIZE).build();
        } catch (SQLException e) {
            throw new ExceptionInInitializerError("Unable to initialize data source", e);
        }
