    public ResponseEntity<InputStream> processRequest(HttpEntityEnclosingRequest request) {
        long startTime = System.currentTimeMillis();
        try {
            String templateId = extractTemplateId(request);
            PdfDocument pdf = fetchAndApplyTemplate(templateId);

            InputStream inputStream = new ByteArrayInputStream(pdf.getPdfBytes());
            return ResponseEntity.ok()
                    .contentType(APPLICATION_PDF)
                    .body(inputStream);
        } catch (Exception e) {
            logError(e, "Error processing request");
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).build();
        } finally {
            logOperation(startTime, System.currentTimeMillis(), request.getContentLength());
        }
    }

    private String extractTemplateId(HttpEntityEnclosingRequest request) throws IOException {
        String templateId = request.getFirstHeader("X-Template-ID").getValue();
        if (templateId == null) {
            throw new MalformedRequestException("Missing X-Template-ID header");
        }
        return templateId;
    }

    private PdfDocument fetchAndApplyTemplate(String templateId) throws SQLException, IOException {
        PdfDocument pdf = pdfCache.getIfPresent(templateId);
        if (pdf != null) {
            return pdf;
        }

        Connection connection = dataSource.getConnection();
        try {
            PreparedStatement statement = connection.prepareStatement("SELECT template_data FROM templates WHERE id = ?");
            statement.setString(1, templateId);
            ResultSet resultSet = statement.executeQuery();
            if (!resultSet.next()) {
                throw new DataAccessException("Template not found", resultSet.getWarningCount() > 0);
            }

            byte[] templateData = resultSet.getBytes("template_data");
            pdf = applyTemplate(templateData);
            pdfCache.put(templateId, pdf);
        } catch (SQLException e) {
            throw new DataAccessException("Error fetching template", e);
        } finally {
            connection.close();
        }

        return pdf;
    }

    private PdfDocument applyTemplate(byte[] templateData) throws IOException, DocumentException {
        // Use iText library to apply the template data to a pre-defined data buffer template
        // ...
    }

    private void logOperation(long startTime, long endTime, long bytesProcessed) {
        logger.info("Operation completed in {} ms, processed {} bytes", endTime - startTime, bytesProcessed);
    }

    private void logError(Throwable e, String message) {
        logger.error(message, e);
    }
}
