class GameCharacterDatabaseOperations {
private:
    std::mutex mtx;
    std::chrono::steady_clock::time_point lastAttackTime;
    int attackCooldownMs = 9 * 1000; // 9 seconds
    std::vector<std::string> attacks = {"Attack 1", "Attack 2"};
    std::default_random_engine generator;
    std::uniform_int_distribution<> distribution(0, 1);

public:
    void RandomAttackSelector() {
        std::unique_lock<std::mutex> lock(mtx);
        if (std::chrono::steady_clock::now() - lastAttackTime >= std::chrono::milliseconds(attackCooldownMs)) {
            lock.unlock();
            int attackNum = distribution(generator);
            std::cout << "Selected Attack: " << attacks[attackNum] << "\n";
            std::this_thread::sleep_for(std::chrono::milliseconds(attackCooldownMs));
            lock.lock();
            lastAttackTime = std::chrono::steady_clock::now();
        }
    }
};

