        std::lock_guard<std::mutex> lk(mtx);
        list.emplace_front(node);
    }
    // Implement other member functions as needed (pop_front, erase_after etc.)
};

// Utility function for finding a node by name
Node* findNodeByName(ConcurrentList& list, const std::string& name) {
    for (auto it = list.begin(); it != list.end(); ++it) {
        if ((*it)->name == name) return *it;
    }
    return nullptr;
}

void updateNodeAttributes(ConcurrentList& list, const std::string& nodeName, const std::string& newValue, const std::string& newAttribute, const std::string& context) {
    // Check for invalid inputs
