    // Update or add the node in a thread-safe manner
    std::lock_guard<std::mutex> lk(findNodeTask.get()->mtx);
    if (fetchedContext != findNodeTask->context) {
        findNodeTask->context = fetchedContext;
    }
    findNodeTask->value = newValue[0] - '0'; // Assuming the new value is always an integer and is given as a string
    findNodeTask->attribute = newAttribute;

    // Log the operation for monitoring and troubleshooting purposes
    std::cout << "Updated node '" << findNodeTask->name << "' with context '" << findNodeTask->context << "' and attribute '" << findNodeTask->attribute << "'." << std::endl;
