1. Create a new module named `uploader.js`:

```javascript
const express = require('express');
const multer = require('multer');
const axios = require('axios');
const { promisify } = require('util');
const fs = require('fs');
const bl = require('bl');
const cte = require('chunked-transfer-encoding');

const storage = multer.memoryStorage();
const upload = multer({ storage });

// Singleton instance of the FileStorage service
let fileStorage;

class FileStorage {
  constructor(options) {
    // Initialize your external file storage service here, e.g., AWS S3 or Google Cloud Storage
  }

  async upload(file, rangeStart, rangeEnd, progressCallback) {
    const chunkSize = 10 * 1024 * 1024; // Set your chunk size (10MB in this example)
    let currentPosition = rangeStart;
    let remainingBytes = rangeEnd - rangeStart + 1;

    while (remainingBytes > 0) {
      const chunkEnd = Math.min(currentPosition + chunkSize, rangeEnd);
      const chunkFile = file.buffer.slice(currentPosition, chunkEnd + 1);

      await this._uploadChunk(chunkFile, progressCallback);

      currentPosition = chunkEnd + 1;
      remainingBytes -= (chunkEnd - currentPosition + 1) + 1;
    }

    return { fileUrl: this.getUploadedFilePath(), buffer: file.buffer };
  }

  async _uploadChunk(chunk, progressCallback) {
    // Handle upload retries here if needed
    const response = await axios.post('YOUR_MULTIPART_UPLOAD_ENDPOINT', chunk, {
      headers: {
        'Content-Range': `bytes ${currentPosition}-${chunkEnd} / ${fileSize}`,
        'Content-Type': fileType, // Get the file type from the file object
        ...this._getCustomHeaders() // Include any custom headers required by your file storage service
      },
      maxRedirects: 0,
      onUploadProgress: (progressEvent) => {
        progressCallback(Math.round((currentPosition + progressEvent.loaded) / fileSize * 100));
      }
    });

    if (!response.ok) {
      throw new Error(`Chunk upload failed with status ${response.status}`);
    }
  }

  getUploadedFilePath() {
    // Return the URL of the uploaded file
  }

  _getCustomHeaders() {
    // Return any custom headers required by your file storage service, if needed
  }
}

module.exports = { FileStorage };
```

