    // Calculate the cooldown period based on the character's current state
    auto cooldownDuration = calculateCooldown(characterState);

    if (cooldownDuration > 9_seconds) {
        cooldowDuration = 9_seconds;
    }

    // Start the cooldown timer
    std::thread cooldown([cooldownPromise = std::move(cooldownPromise)]() mutable {
        std::this_thread::sleep_for(cooldownDuration);
        cooldownPromise.set_value();
    });
    cooldown.detach();

    // Wait for the cooldown to finish before selecting a new attack
    if (!cooldownFuture.wait_until(std::chrono::steady_clock::now() + 1s)) {
        std::cerr << "Error: Cooldown timed out. Cannot select a new attack." << std::endl;
        return lastUsedAttack;
    }

    // Select the attack based on the character's current state and random chance
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distribution(0, 1);
    int randomNumber = distribution(gen);

    AttackType selectedAttack;
    if (randomNumber == 0) {
        selectedAttack = ATTACK1;
    } else {
        selectedAttack = ATTACK2;
    }

    // Update the last used attack in the database for this character
    updateLastUsedAttack(characterId, selectedAttack);

    return selectedAttack;
}

