```java
package com.example.authentication;

import java.time.Instant;
import java.util.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class TokenManager {
    private static final Logger LOGGER = LoggerFactory.getLogger(TokenManager.class);
    private static final int CACHE_SIZE = 1000;
    private ConcurrentHashMap<String, Token> tokenCache;
    private OkHttpClient httpClient;
    private String tokenValidationServiceUrl;

    public TokenManager(OkHttpClient httpClient, String tokenValidationServiceUrl) {
        this.httpClient = httpClient;
        this.tokenValidationServiceUrl = tokenValidationServiceUrl;
        this.tokenCache = new ConcurrentHashMap<>(CACHE_SIZE);
    }

    public void storeToken(String tokenType, String userId, String token) {
        Token storedToken = new Token(tokenType, userId, Instant.now().plusSeconds(TOKEN_LIFETIME), null);
        tokenCache.putIfAbsent(token, storedToken);
    }

    public Token getToken(String token) throws TokenInvalidFormatException, TokenExpiredException, TokenRevokedException, TokenValidationFailureException, CommunicationErrorException {
        Token cachedToken = tokenCache.get(token);
        if (cachedToken == null || !isTokenValid(cachedToken)) {
            throw new TokenNotFoundException("Token not found or invalid in cache");
        }
        return cachedToken;
    }

    private boolean isTokenValid(Token token) {
        if (Instant.now().isAfter(token.getExpirationTime())) {
            LOGGER.debug("Token expired: {}", token);
            throw new TokenExpiredException("Token has expired");
        }
        if (!validateWithExternalService(token)) {
            LOGGER.debug("Token invalidated by external service: {}", token);
            throw new TokenRevokedException("Token revoked");
        }
        return true;
    }

    private boolean validateWithExternalService(Token token) {
        try {
            Request request = new Request.Builder()
                    .url(tokenValidationServiceUrl + "/validate?token=" + token.getToken())
                    .build();
            Response response = httpClient.newCall(request).execute();
            if (!response.isSuccessful()) {
                throw new CommunicationErrorException("Error communicating with the external service");
            }
            if (!"valid".equalsIgnoreCase(response.body().string())) {
                throw new TokenValidationFailureException("Token validation failed");
            }
        } catch (ExecutionException | InterruptedException | IOException e) {
            LOGGER.error("Error validating token: {}", e.getMessage());
            throw new CommunicationErrorException("Error communicating with the external service");
        }
        return true;
    }

    // Add other utility methods, error exceptions and logging mechanisms as needed
}

record Token(String tokenType, String userId, Instant expirationTime, String validationResponse) {}
```

