using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using log4net;

public static class DatabaseQueryHelper
{
    private static readonly ILog _logger = LogManager.GetLogger(typeof(DatabaseQueryHelper));

    public static async Task<IDataReader> ExecuteParameterizedQuery(string sqlTemplate, List<object> parameters, SqlConnection connection, SqlTransaction transaction = null)
    {
        if (sqlTemplate == null || !sqlTemplate.Contains(@"@") || parameters?.Count != sqlTemplate.Split(@"\@").Length - 1)
            throw new ArgumentException("Invalid SQL template or parameter count.");

        using var command = new SqlCommand(sqlTemplate, connection) { Transaction = transaction };

        int paramIndex = 0;
        foreach (var parameter in parameters)
        {
            if (parameter is string sParam)
                command.Parameters.AddWithValue($"@p{paramIndex++}", sParam);
            else if (parameter is DateTime dateParam)
                command.Parameters.Add(new SqlParameter($"@p{paramIndex++}", dateParam));
            // Add other data types as needed
        }

        try
        {
            return await command.ExecuteReaderAsync();
        }
        catch (Exception ex)
        {
            _logger.Error("Failed to execute SQL query", ex);
            throw;
        }
    }
}
```

