    public class ConfigLoader
    {
        private readonly HttpClient _httpClient;
        private readonly string _schemaSource;
        private readonly ValidationContext _validationContext;

        public ConfigLoader(HttpClient httpClient, string schemaSource)
        {
            _httpClient = httpClient;
            _schemaSource = schemaSource;
            _validationContext = new ValidationContext(this);
        }

        [Required]
        public XDocument Configuration { get; private set; }

        public async Task LoadAsync()
        {
            if (Configuration != null) return;

            var configurationXml = await FetchConfigFromServerAsync();

            try
            {
                ValidateXml(configurationXml);
            }
            catch (ValidationException ex)
            {
                throw new InvalidDataException($"Invalid configuration file: {ex.Message}");
            }

            Configuration = configurationXml;
        }

        private async Task<XDocument> FetchConfigFromServerAsync()
        {
            var configUrl = ConfigurationManager.AppSettings["ConfigUrl"];
            using (var response = await _httpClient.GetAsync(configUrl))
            {
                response.EnsureSuccessStatusCode();
                return XDocument.Load(await response.Content.ReadAsStreamAsync());
            }
        }

        private void ValidateXml(XDocument config)
        {
            var validationResults = new List<ValidationResult>();
            Validator.TryValidateXml(config, _validationContext, validationResults, true);

            if (!validationResults.IsValid)
            {
                throw new ValidationException("XML file is not valid against the schema");
            }
        }
    }

    public class ValidationException : Exception
    {
        public ValidationException(string message) : base(message) {}
    }
}
