using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.IdentityModel.Tokens;

namespace CryptoService
{
    public class AesGcmDecryptionService
    {
        private readonly IKeyManagementService _keyManager;
        private readonly ICachingService _cache;

        public AesGcmDecryptionService(IKeyManagementService keyManager, ICachingService cache)
        {
            _keyManager = keyManager;
            _cache = cache;
        }

        public async Task<byte[]> DecryptAsync(HttpRequest request)
        {
            var ciphertext = request.Body.ToMemoryStream().ToArray();

            try
            {
                // Retrieve key and IV from cache or key management system
                var (key, iv) = await GetEncryptionKeyAndIVAsync(request);

                using var aes = AES.Create();

                switch (GetPaddingScheme(ciphertext))
                {
                    case PaddingScheme.PKCS7:
                        aes.PadMode = PaddingMode.PKCS7;
                        break;
                    case PaddingScheme.PKCS5:
                        aes.PadMode = PaddingMode.PKCS5;
                        break;
                    case PaddingScheme.NoPadding:
                        aes.PadMode = PaddingMode.None;
                        break;
                }

                using var gcm = new GcmBlockEncryptor(aes, iv);

                // Decrypt and handle errors
                var plaintext = await Task.Run(() => gcm.Decrypt(ciphertext));

                if (plaintext.Length == 0)
                    throw new Exception("Invalid ciphertext.");

                return plaintext;
            }
            catch (Exception ex)
            {
                // Handle errors and log exception details
                Console.WriteLine(ex);
                throw;
            }
        }

        private async Task<(byte[], byte[])> GetEncryptionKeyAndIVAsync(HttpRequest request)
        {
            var keyId = GetKeyIdFromRequest(request);

            // Retrieve encryption key and IV from key management system or cache
            var (key, iv) = await _keyManager.RetrieveKeyAndIVAsync(keyId);

            if (iv == null)
                iv = GenerateRandomIV();

            // Cache key and IV for future use
            await _cache.SetEncryptionCredentialsAsync(keyId, key, iv);

            return (key, iv);
        }

        private PaddingScheme GetPaddingScheme(byte[] ciphertext) =>
            ciphertext[ciphertext.Length - 1] switch
            {
                0x04 => PaddingScheme.PKCS7,
                _   => ciphertext[ciphertext.Length - 2] == 0x02 ? PaddingScheme.PKCS5 : PaddingScheme.NoPadding
            };

        private byte[] GenerateRandomIV() => new byte[12];

        private string GetKeyIdFromRequest(HttpRequest request)
        {
            // Extract key ID from authentication token or other means of user identification
        }
    }

    public enum PaddingScheme
    {
        PKCS7,
        PKCS5,
        NoPadding
    }
}
