#include <pthread.h>

// Metadata service API callback for obtaining metadata
typedef struct {
    int num_digits;
    char file_type[10];
} Metadata;

// Callback function to extract metadata from the filename
void get_metadata(const char* filename, void* userdata) {
    // Implement the call to your external metadata service here.
    // This is just a placeholder example for an async call.
    Metadata* metadata = static_cast<Metadata*>(userdata);
    // Assuming we have some way of extracting metadata from filenames...
    sprintf(metadata->file_type, "%s", ".example");
    metadata->num_digits = 3;
}

void renameFileWithMetadata(const char* dirpath, const char* oldfilename, const char* new_extension) {
    // Create a DIR object to represent the directory.
    DIR *d;
    struct dirent *dir;
    d = opendir(dirpath);

    if (!d) {
        perror("Error opening directory");
        return;
    }

    Metadata metadata;
    memset(&metadata, 0, sizeof(Metadata));

    while ((dir = readdir(d)) != NULL) {
        if (strcmp(dir->d_name, oldfilename) == 0) {
            get_metadata(oldfilename, &metadata);
            break;
        }
    }

    closedir(d);

    if (!metadata.num_digits || !metadata.file_type[0]) {
        printf("Error: Invalid metadata obtained\n");
        return;
    }

    char newname[128]; // Assuming that's enough for a typical path + extension.
    sprintf(newname, "%s/%0*d%s", dirpath, metadata.num_digits, strtoul(oldfilename + (strlen(oldfilename) - metadata.num_digits), NULL, 10), metadata.file_type);

    if (rename(oldfilename, newname) != 0) {
        perror("Error renaming file");
    } else {
        printf("Successfully renamed %s to %s\n", oldfilename, newname);
    }
}

// Concurrent version of the renameFileWithMetadata function using pthreads.
void* renameFileWithMetadata_concurrent(void* arg) {
    const char* dirpath = static_cast<char*>(arg);
    renameFileWithMetadata(dirpath, *(static_cast<const char**>(arg + 1)), *(static_cast<const char**>(arg + 2)));
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 4) {
        printf("Usage: %s <directory> <oldfilename> <new_extension>\n", argv[0]);
        return -1;
    }

    pthread_t threads[1];
    pthread_create(&threads[0], NULL, renameFileWithMetadata_concurrent, static_cast<void*>(const_cast<char* const>(argv + 1)));
    pthread_join(threads[0], NULL);

    return 0;
}
