import time
from datetime import datetime
from distributed_db import DistributedDatabase
from logging import getLogger, StreamHandler, Formatter
from collections import defaultdict

class TemperatureSensorReading:
    def __init__(self, sensor_id, temperature=None, timestamp=None, status='active'):
        self.sensor_id = sensor_id
        self.temperature = temperature if temperature is not None else 0.0
        self.timestamp = timestamp if timestamp is not None else datetime.now()
        self.status = status

class TemperatureSensorManager:
    def __init__(self, db_config):
        self.db = DistributedDatabase(**db_config)
        self.sensors = defaultdict(TemperatureSensorReading)
        self.logger = getLogger(__name__)
        self.handler = StreamHandler()
        self.handler.setFormatter(Formatter('%(asctime)s - %(levelname)s - %(message)s'))
        self.logger.addHandler(self.handler)

    def update_sensor_readings(self, readings):
        try:
            for sensor_id, reading in readings.items():
                if not sensor_id or not isinstance(sensor_id, int):
                    self.logger.warning(f"Invalid sensor ID: {sensor_id}")
                    continue

                if sensor_id not in self.sensors:
                    self.sensors[sensor_id] = TemperatureSensorReading(sensor_id)

                self.sensors[sensor_id].temperature = reading['temperature']
                self.sensors[sensor_id].status = reading['status'] or 'active'
                self.sensors[sensor_id].timestamp = datetime.fromisoformat(reading['timestamp'])

                # Store the updated sensor data in the distributed database
                self.db.store_sensor_data(self.sensors[sensor_id])

        except Exception as e:
            self.logger.error(f"Error updating sensor readings: {e}")

    def get_sensor_reading(self, sensor_id):
        try:
            if not sensor_id or not isinstance(sensor_id, int):
                raise ValueError("Invalid sensor ID")

            # Retrieve the sensor data from the distributed database
            sensor_data = self.db.get_sensor_data(sensor_id)

            if sensor_data:
                return TemperatureSensorReading(*sensor_data)
            else:
                self.logger.warning(f"No data found for sensor ID: {sensor_id}")
                return None
        except Exception as e:
            self.logger.error(f"Error retrieving sensor reading: {e}")
            raise
