// Function to append slash if within limit and space available
char* appendSlashIfWithinLimit(const char* inputStr, size_t sizeLimit, int fd, char* outputBuffer, size_t bufferSize) {
    // Check for valid inputs
    if (!inputStr || sizeLimit < 0 || !outputBuffer || bufferSize <= 0) {
        fprintf(fd, "Error: Invalid input\n");
        return NULL;
    }

    // Initialize the output length and pointer
    size_t outputLen = 0;
    char* outputPtr = outputBuffer;

    // Check if string is within limit and there's space in buffer
    if (strlen(inputStr) <= sizeLimit && outputLen + strlen(inputStr) + 1 <= bufferSize) {
        // Copy the input string to the output buffer
        strncpy(outputPtr, inputStr, outputLen + strlen(inputStr));

        // Increment output pointer and length
        outputPtr += strlen(inputStr);
        outputLen += strlen(inputStr);

        // Append slash if not already present at the end of the string
        if (outputStr[outputLen - 1] != '/') {
            *outputPtr++ = '/';
            outputLen++;
        }
    } else {
        // Log an error message and return NULL if limit is exceeded or buffer is not large enough
        fprintf(fd, "Error: Size limit exceeded or buffer too small\n");
        return NULL;
    }

    // Return the processed output buffer
    return outputBuffer;
}

// Mutex for thread-safe access to the log file
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
