using System.Threading;
using System.Threading.Tasks;
using System.Net.Sockets;

public class GameCharacterDatabaseOperations {
    public async Task<DataTableReader> SendByteArrayToDatabase(byte[] data) {
        var retryAttempts = 3;
        TcpClient client = null;
        try {
            while (true) {
                try {
                    client = new TcpClient("DatabaseServer", 12345);
                    using (var networkStream = client.GetStream()) {
                        await networkStream.WriteAsync(data, 0, data.Length);
                    }

                    using (var sqlConnection = new SqlConnection("Data Source=DatabaseServer;Initial Catalog=GameDB;Integrated Security=True")) {
                        var command = new SqlCommand("ExecuteQuery", sqlConnection);
                        command.CommandType = CommandType.StoredProcedure;

                        sqlConnection.Open();
                        using (var reader = command.ExecuteReader()) {
                            return reader;
                        }
                    }
                } catch (Exception ex) {
                    if (--retryAttempts > 0) {
                        Console.WriteLine("Network failure. Retrying in 5 seconds...");
                        await Task.Delay(5000);
                    } else {
                        throw;
                    }
                } finally {
                    if (client != null && client.Connected) client.Close();
                }
            }
        } catch (Exception ex) {
            Console.WriteLine($"Fatal error: {ex.Message}");
            throw;
        }
    }
}
