class OperationQueue extends EventEmitter {
  private concurrentOperations = 0;

  enqueue(operation: () => Promise<void>) {
    this.concurrentOperations++;
    operation()
      .then(() => {
        this.concurrentOperations--;
        if (this.concurrentOperations === 0) {
          this.emit('idle');
        }
      })
