```csharp
using System;
using System.Collections.Generic;
using UnityEngine;

public class DynamicStringProcessor
{
    private readonly string _apiEndpoint;
    private readonly Dictionary<string, Tuple<int, int>> _ranges;

    public DynamicStringProcessor(string apiEndpoint)
    {
        _apiEndpoint = apiEndpoint;
        _ranges = new Dictionary<string, Tuple<int, int>>();
    }

    public void AddRange(string key, int minLength, int maxLength)
    {
        _ranges[key] = new Tuple<int, int>(minLength, maxLength);
    }

    public string GenerateRandomStringInclusive(string key)
    {
        if (!_ranges.ContainsKey(key)) throw new KeyNotFoundException($"No range found for key: {key}");

        var range = _ranges[key];
        return GenerateString(range.Item1, range.Item2);
    }

    public string GenerateRandomStringExclusive(string key)
    {
        if (!_ranges.ContainsKey(key)) throw new KeyNotFoundException($"No range found for key: {key}");

        var range = _ranges[key];
        return GenerateString(range.Item1 + 1, range.Item2);
    }

    private string GenerateString(int minLength, int maxLength)
    {
        return new string(Enumerable.Repeat(UnityEngine.Random.Range('a', 'z'), UnityEngine.Random.Range(minLength, maxLength)).Distinct().ToArray());
    }

    public string ProcessString(string input, int sizeLimit)
    {
        if (input == null || input.Length >= sizeLimit) return input;

        var suffix = new string(Enumerable.Repeat('a', sizeLimit - input.Length).Distinct().ToArray());
        return input + suffix;
    }

    public override string ToString()
    {
        var builder = new System.Text.StringBuilder();
        builder.AppendLine("Dynamic String Processor:");
        foreach (var range in _ranges)
        {
            builder.AppendFormat("- Key: {0}, Range: ({1} - {2})", range.Key, range.Value.Item1, range.Value.Item2);
        }
        return builder.ToString();
    }
}
```

