const fs = require('fs');
const path = require('path');
const readline = require('readline');
const { promisify } = require('util');
const AWS = require('aws-sdk'); // For S3 and Azure Storage support

// Configuration for external systems (e.g., access keys, regions)
const azureConfig = {
  // ...
};
const s3Config = {
  // ...
};

function readDirRecursive(dirPath, callback) {
  const results = [];
  const extensions = ['txt', 'json', 'log']; // Filter files based on given extensions

  fs.readdir(dirPath, (err, files) => {
    if (err) return callback(err);

    // Loop through the current directory's files and subdirectories recursively
    (function processFilesAndDirs(filesToProcess) {
      let currentFile;

      if (!filesToProcess.length) {
        return callback(null, results);
      }

      currentFile = filesToProcess.pop();
      const fullPath = path.join(dirPath, currentFile);

      fs.stat(fullPath, (errStat, stats) => {
        if (stats && stats.isDirectory()) {
          processFilesAndDirs([...filesToProcess, fullPath]);
        } else if (!errStat) {
          const ext = path.extname(currentFile).toLowerCase();

          if (extensions.includes(ext)) {
            results.push(fullPath);
          }

          processFilesAndDirs([...filesToProcess, fullPath]); // Process the next file/directory
        } else {
          return callback(errStat);
        }
      });
    })([...files]);
  });
}

async function readRemoteDirRecursive(remoteDirPath, remoteStorageConfig, callback) {
  const s3 = new AWS.S3(remoteStorageConfig); // Instantiate the necessary external system client

  try {
    const params = { Bucket: remoteDirPath };

    if (remoteStorageConfig.region) params.Region = remoteStorageConfig.region;

    const listObjectsV2Output = await promisify(s3.listObjectsV2).call(s3, params);

    const results = [];
    let filesToProcess = [].concat(listObjectsV2Output.Contents, listObjectsV2Output.CommonPrefixes || []);

    (function processFilesAndDirs(filesToProcess) {
      let currentFile;

      if (!filesToProcess.length) {
        return callback(null, results);
      }

      currentFile = filesToProcess.pop();
      const fullPath = currentFile.Key;

      if (currentFile.IsDir) {
        params.Prefix = fullPath + '/';
        processFilesAndDirs([].concat(await promisify(s3.listObjectsV2).call(s3, params).then(res => res.Contents || res.CommonPrefixes || [])));
      } else if (!currentFile.IsDir) {
        const ext = path.extname(fullPath).toLowerCase();

        if (extensions.includes(ext)) {
          results.push(fullPath);
        }

        processFilesAndDirs([...filesToProcess, fullPath]); // Process the next file/directory
      }
    })(filesToProcess);
  } catch (err) {
    callback(err);
  }
}

module.exports = {
  readDirRecursive,
  readRemoteDirRecursive,
};
```

