static off_t logFilePosition = 0;
static int logFileDescriptor;

// Function to handle logging
void my_log(int priority, const char* message) {
    syslog(priority, "%s", message);
}

// Third-party tool command for converting JPEG to PDF (replace with the actual command)
#define CONVERT_CMD "convert -density 300 input.jpeg output.pdf"

// Function to convert JPEG to PDF and embed metadata
int jpeg_to_pdf(const char* inputFile, const char* outputDir, const char* title, const char* author, const char* creationDate) {
    // Create output file path
    char outputFilePath[1024];
    snprintf(outputFilePath, sizeof(outputFilePath), "%s/pdf_%s.pdf", outputDir, basename(inputFile));

    // Check if the output directory exists and create it if not
    struct stat dirStat;
    if (stat(outputDir, &dirStat) != 0 || !S_ISDIR(dirStat.st_mode)) {
        my_log(LOG_ERR, "Output directory doesn't exist or is not a directory.");
        return 1;
    }

    // Create temporary metadata file for the PDF converter
    char tempMetadataFile[1024];
    snprintf(tempMetadataFile, sizeof(tempMetadataFile), "/tmp/my_app_metadata.txt");

    // Write metadata to temporary file
    FILE* tempMetadata = fopen(tempMetadataFile, "w");
    if (!tempMetadata) {
        my_log(LOG_ERR, "Failed to create the temporary metadata file.");
        return 1;
    }
    fprintf(tempMetadata, "%s\n%s\n%s\n", title, author, creationDate);
    fclose(tempMetadata);

    // Replace the input and metadata files in the CONVERT_CMD command
    char* cmd = malloc((strlen(CONVERT_CMD) + strlen(inputFile) + strlen(outputFilePath) + strlen(tempMetadataFile) + 4) * sizeof(char));
    snprintf(cmd, strlen(CONVERT_CMD) + strlen(inputFile) + strlen(outputFilePath) + strlen(tempMetadataFile) + 4, CONVERT_CMD, inputFile, outputFilePath, tempMetadataFile);

    // Execute the command using system() and handle errors gracefully
    int cmdStatus = system(cmd);
    free(cmd);

    if (cmdStatus != 0) {
        my_log(LOG_ERR, "Failed to convert JPEG to PDF.");
        unlink(tempMetadataFile); // Delete temporary metadata file on error
        return 1;
    }

    // Clean up and return success
    unlink(tempMetadataFile);
    return 0;
}

// Thread-safe version of jpeg_to_pdf using pthread_mutex_t
pthread_mutex_t jpeg_to_pdf_mutex = PTHREAD_MUTEX_INITIALIZER;
void threaded_jpeg_to_pdf(const char* inputFile, const char* outputDir, const char* title, const char* author, const char* creationDate) {
    pthread_mutex_lock(&jpeg_to_pdf_mutex);

    int result = jpeg_to_pdf(inputFile, outputDir, title, author, creationDate);

    pthread_mutex_unlock(&jpeg_to_pdf_mutex);
}
```

