    {
        // Connect to streaming platform
        var consumer = await _realtimeStreamingService.CreateConsumer();

        try
        {
            // Start consuming messages from the stream
            while (true)
            {
                var message = await consumer.ReceiveAsync();

                if (message == null) continue;

                await ProcessMessage(message);
            }
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Error while consuming messages");
        }
    }

    private async Task ProcessMessage(Consumable<string> message)
    {
