class LogManager {
private:
    forward_list<string> logs_;
    unsigned int num_insertions_ = 0;
    unsigned int max_insertions_ = 10000; // Adjust this value according to your requirements.
    ExternalLoggingService logging_service_;
    spsc_queue<string> log_queue_;
    mutex logs_mutex_;
    steady_timer timer_;
    deadline_timer log_failure_timeout_;

public:
    void insert(const forward_list<string>& source_logs, const string& target, const string& insertion, unsigned int max_insertions = 0) {
        // Your implementation goes here.
        // For this example, we'll use a simple loop to simulate concurrent insertions and log failures after a delay.

        for (const auto& log : source_logs) {
            unique_lock<mutex> lock(logs_mutex_);
            if (num_insertions_ < max_insertions && logs_.contains(target)) {
                logs_.insert_after(find(logs_.begin(), logs_.end(), target), insertion);
                ++num_insertions_;
                log_queue_.push(log);
            } else if (max_insertions > 0 && num_insertions_ >= max_insertions) {
                logging_service_.log("Insertion limit exceeded.");
            } else {
                logging_service_.log("Target string not found.");
            }
        }

        if (num_insertions < source_logs.size() && log_queue_.size() > 0) {
            async_spawn(io_context_, [this](){ this->flushLogs(); });
        }
    }

    void flushLogs() {
        unique_lock<mutex> lock(logs_mutex_);
        while (log_queue_.pop(logs_)) {
            logging_service_.log(logs_.c_str());
        }
    }
};
```

This design includes a `LogManager` class that manages the log entries, an external logging service for recording insertions and failures, and asynchronous flushing of logs to minimize latency. It also implements a simple concurrent insertion mechanism using a lock-free queue and manages resource usage by tracking the number of insertions performed.

