```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

#define BUFFER_GROWTH 16

typedef struct {
    char* data;
    size_t length;
    size_t capacity;
    pthread_mutex_t mutex;
} SafeStringBuffer;

SafeStringBuffer* safeStringInit(size_t initialCapacity) {
    SafeStringBuffer* buffer = malloc(sizeof(SafeStringBuffer));
    if (!buffer) return NULL;

    buffer->data = malloc(initialCapacity);
    if (!buffer->data) {
        free(buffer);
        return NULL;
    }

    buffer->length = 0;
    buffer->capacity = initialCapacity;
    pthread_mutex_init(&buffer->mutex, NULL);

    return buffer;
}

void safeStringFree(SafeStringBuffer* buffer) {
    free(buffer->data);
    pthread_mutex_destroy(&buffer->mutex);
    free(buffer);
}

int safeStringAppend(const char* source, SafeStringBuffer* destination) {
    assert(destination != NULL && source != NULL);

    pthread_mutex_lock(&destination->mutex);
    if (destination->length + strlen(source) <= destination->capacity) {
        memcpy(destination->data + destination->length, source, strlen(source) + 1);
        destination->length += strlen(source);
    } else {
        size_t newCapacity = destination->capacity + BUFFER_GROWTH;
        char* newData = realloc(destination->data, newCapacity);
        if (!newData) {
            pthread_mutex_unlock(&destination->mutex);
            return 0;
        }
        destination->data = newData;
        destination->capacity = newCapacity;
        safeStringAppend(source, destination);
    }
    pthread_mutex_unlock(&destination->mutex);

    return 1;
}

char* safeStringAppendNoLock(const char* source, SafeStringBuffer* destination) {
    assert(destination != NULL && source != NULL);

    if (destination->length + strlen(source) <= destination->capacity) {
        memcpy(destination->data + destination->length, source, strlen(source) + 1);
        destination->length += strlen(source);
    } else {
        size_t newCapacity = destination->capacity + BUFFER_GROWTH;
        char* newData = realloc(destination->data, newCapacity);
        if (!newData) return NULL;
        destination->data = newData;
        destination->capacity = newCapacity;
        safeStringAppendNoLock(source, destination);
    }

    return destination->data;
}
```

This code provides two functions: one using a lock for thread safety (`safeStringAppend`) and another without a lock for performance optimization when there's no concurrent access (`safeStringAppendNoLock`). Both functions initialize, free, and resize the buffer if needed. They also protect against overflow attacks by checking the current length plus the source string length before appending.

