```javascript
const express = require('express');
const multer = require('multer');
const sharp = require('sharp');
const AWS = require('aws-sdk');
const axios = require('axios');
const cache = require('memory-cache');
const RateLimiter = require('limiter').RateLimiter;
const logger = require('./logger');

// Initialize Express app and Multer for file handling
const app = express();
const upload = multer({ dest: 'uploads/' });

// AWS S3 configuration
AWS.config.update({
  accessKeyId: process.env.S3_ACCESS_KEY,
  secretAccessKey: process.env.S3_SECRET_KEY,
  region: process.env.S3_REGION,
});
const s3 = new AWS.S3();

// Initialize rate limiter and cache
const limiter = new RateLimiter({ max: 5, time: 60 * 1000 });
cache.MaxAge = 60 * 60; // Cache expiration in seconds

app.post('/resize', async (req, res) => {
  const imageKey = req.body.imageKey;
  const width = parseInt(req.body.width);
  const height = parseInt(req.body.height);
  const quality = parseInt(req.body.quality);

  // Rate limit and cache check
  await limiter.removeTokens(1);
  const cachedImage = cache.get(imageKey);

  if (cachedImage) {
    res.send({ image: cachedImage });
  } else {
    try {
      // Fetch the original image from the specified source (local file, cloud storage, or URL)
      let imageBuffer;
      if (imageKey.startsWith('http')) {
        const response = await axios.get(imageKey);
        imageBuffer = response.data;
      } else if (imageKey.includes('/uploads/')) {
        imageBuffer = require(`./${imageKey}`);
      } else {
        const params = { Bucket: process.env.S3_BUCKET, Key: imageKey };
        const s3Response = await s3.getObject(params).promise();
        imageBuffer = s3Response.Body;
      }

      // Resize the image asynchronously using Sharp
      const resizedImageBuffer = await sharp(imageBuffer)
        .resize(width, height, { fit: 'inside', withoutEnlargement: true })
        .jpeg({ quality });

      // Save the resized image to cache and S3
      const cacheOptions = { expires: new Date().getTime() + cache.MaxAge };
      cache.put(imageKey, resizedImageBuffer, cacheOptions);
      await s3.putObject({
        Bucket: process.env.S3_BUCKET,
        Key: `resized-${imageKey}`,
        Body: resizedImageBuffer,
        ContentType: 'image/jpeg',
      }).promise();

      res.send({ image: resizedImageBuffer });
    } catch (error) {
      logger.error(`Error resizing image: ${error}`);
      res.status(500).send({ error: 'An error occurred while resizing the image.' });
    }
  }
});

// ... Rest of the application code, including logging system, metadata service integration, and other functionalities
```

