public class RestClient {
 private static final Logger LOGGER = LoggerFactory.getLogger(RestClient.class);

 private static Properties properties;
 private OkHttpClient httpClient;
 private Gson gson;

 static {
 try {
 properties = new Properties();
 properties.load(new FileInputStream("api-settings.properties"));
 } catch (IOException e) {
 LOGGER.error("Error loading API settings", e);
 System.exit(1);
 }
 }

 public RestClient() {
 httpClient = new OkHttpClient().newBuilder()
 .connectTimeout(10, TimeUnit.SECONDS)
 .readTimeout(30, TimeUnit.SECONDS)
 .writeTimeout(30, TimeUnit.SECONDS)
 .callTimeout(60, TimeUnit.SECONDS)
 .followRedirects(false)
 .retryOnConnectionFailure(true)
 .build();
 gson = new GsonBuilder().create();
 }

 private OkHttpClient getAuthenticatedClient() {
 // Implement OAuth2 authentication and refresh token logic here
 // Return the authenticated OkHttpClient instance
 throw new UnsupportedOperationException("OAuth2 authentication not implemented.");
 }

 private void handleRequest(String method, String url, RequestBody requestBody) throws IOException, ExecutionException {
 OkHttpClient client = httpClient;
 if (method.equalsIgnoreCase("POST")) {
 client = getAuthenticatedClient();
 }

 Request request = new Request.Builder()
 .url(url)
 .method(method, requestBody)
 .build();

 Future<Response> future = client.newCall(request).enqueue();
 Response response = future.get();
 if (!response.isSuccessful()) {
 // Implement backoff strategy here
 // Log error and return an appropriate response or throw an exception
 LOGGER.error("Request failed with code: {}", response.code());
 throw new RuntimeException("Request failed");
 }
 }

 public void get(String url) throws IOException, ExecutionException {
 handleRequest("GET", url, null);
 }

 public <T> T post(String url, String json) throws IOException, ExecutionException, JsonSyntaxException {
 RequestBody requestBody = RequestBody.create(jsonContentType(), json);
 return gson.fromJson(handleRequest("POST", url, requestBody).body().string(), (Class<T>) TypeToken.getParameterized(getClass(), T.class).getType());
 }
}
```

