```cpp
#include <atomic>
#include <forward_list>
#include <mutex>
#include <memory>
#include <string>
#include <utility>
#include <iostream>
#include <sstream>
#include <chrono>
#include <thread>

class Context {
public:
    Context(const std::string& user_id, const std::string& task_type)
        : timestamp_(std::chrono::high_resolution_clock::now()),
          user_id_(user_id),
          task_type_(task_type) {}

    void addField(const std::string& field_name, const std::string& field_value) {
        fields_[field_name] = field_value;
    }

private:
    std::chrono::high_resolution_clock::time_point timestamp_;
    std::string user_id_, task_type_;
    std::unordered_map<std::string, std::string> fields_;
};

struct TaskQueue {
    struct Task {
        std::shared_ptr<Context> context;
        std::string target;
        std::forward_list<std::string> tasks;
    };

    std::mutex mtx_;
    std::atomic<bool> shutdown_{false};
    std::forward_list<Task> queue_;
    std::function<void(const Task&)> callback;

    void enqueueTask(std::string taskTarget, std::shared_ptr<Context> context, const std::string& taskValue) {
        std::unique_lock<std::mutex> lock(mtx_);
        if (shutdown_) throw std::runtime_error("The task queue is shutting down.");

        Task targetTask = std::find_if(queue_.begin(), queue_.end(),
            [&](const auto& t) { return t.target == taskTarget; });

        if (targetTask != queue_.end()) {
            targetTask->tasks.insert_after(std::find_if(targetTask->tasks.begin(), targetTask->tasks.end(),
                [&](const auto& v) { return v == taskValue; }), taskValue);

            if (callback) {
                callback(*targetTask);
            }
        } else {
            Task newTask = { context, taskTarget, { taskValue } };
            queue_.insert_after(queue.end(), std::move(newTask));
        }

        // Logging and status updates (to be implemented)
    }
};
```

This code creates a `Context` class that holds metadata like timestamp, user ID, task type, and can dynamically add additional fields. The `TaskQueue` struct contains a forward_list for efficient enqueuing/dequeuing operations and supports the enqueue operation described in the prompt.

The `enqueueTask` function uses a mutex to ensure thread safety when modifying the shared resources (i.e., task queue). An external system callback can be set using the `callback` member, which is thread-safe due to the use of a mutex.

This code provides a good starting point for addressing the other requirements mentioned in the prompt, such as error handling, logging, resource management, and concurrency handling.

