import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

public class CustomSerializer {
    private static final ThreadLocal<ObjectOutput> serializationBuffer = new ThreadLocal<>() {
        @Override
        protected ObjectOutput initialValue() {
            return new ObjectOutputStream(new ByteArrayOutputStream());
        }
    };

    public static <T> T deserialize(byte[] data) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data)) {
            GZIPInputStream gis = new GZIPInputStream(bis);
            ObjectInputStream ois = new ObjectInputStream(gis);
            return (T) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error during deserialization: " + e.getMessage(), e);
        }
    }

    public static byte[] serialize(Serializable object) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutput out = getSerializationBuffer().put(new ObjectOutputStream(bos))) {
            out.writeObject(object);
            out.flush();
            byte[] data = bos.toByteArray();
            return compressData(data);
        } catch (IOException e) {
            throw new RuntimeException("Error during serialization: " + e.getMessage(), e);
        }
    }

    private static byte[] compressData(byte[] data) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             GZIPOutputStream gos = new GZIPOutputStream(bos)) {
            gos.write(data);
            gos.flush();
            return bos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Error during compression: " + e.getMessage(), e);
        }
    }

    private static ThreadLocal<ObjectOutput> getSerializationBuffer() {
        ObjectOutput serializationBuffer = this.serializationBuffer.get();
        if (serializationBuffer == null || !serializationBuffer.checkOpen()) {
            this.serializationBuffer.remove();
            serializationBuffer = newObjectOutputStream();
        }
        return serializationBuffer;
    }

    private static ObjectOutputStream newObjectOutputStream() {
        return new ObjectOutputStream(new ByteArrayOutputStream());
    }
}

@SuppressWarnings("unchecked")
public class CustomDataStructure implements Serializable {
    // Add your custom data structure implementation here.
}
```

