bool validate_access_token(const std::string &json_str, const std::string &client_id, const std::string &client_secret) {
    json_t *root = json_loads(json_str.c_str(), 0, NULL);

    if (!root) {
        std::cerr << "Error: Invalid JSON string." << std::endl;
        return false;
    }

    bool valid = true;

    json_t *access_token = json_object_get(root, "access_token");
    if (!json_is_string(access_token)) {
        std::cerr << "Error: Missing or invalid 'access_token' field." << std::endl;
        valid = false;
    }

    json_t *expires_in = json_object_get(root, "expires_in");
    if (!json_is_integer(expires_in)) {
        std::cerr << "Error: Missing or invalid 'expires_in' field." << std::endl;
        valid = false;
    } else if (json_integer_value(expires_in) <= 0) {
        std::cerr << "Error: Invalid value for 'expires_in' field." << std::endl;
        valid = false;
    }

    json_t *token_type = json_object_get(root, "token_type");
    if (!json_is_string(token_type) || std::string("Bearer") != json_string_value(token_type)) {
        std::cerr << "Error: Missing or invalid 'token_type' field." << std::endl;
        valid = false;
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if (json_exists(refresh_token)) {
        // Handle the 'refresh_token' field as needed for your specific use case.
    }

    MYSQL *conn = mysql_init(NULL);

    if (!conn) {
        std::cerr << "Error: Failed to initialize MySQL connection." << std::endl;
        valid = false;
    } else {
        if (mysql_real_connect(conn, "[your_host]", "[your_user]", "[your_password]", "[your_database]", 0, NULL, 0)) {
            // Perform the SQL query to check the client credentials.
            // ...

            if (mysql_errno(conn)) {
                std::cerr << "Error: Failed to execute the SQL query." << mysql_error(conn) << std::endl;
                valid = false;
            } else {
                // Handle the result of the SQL query and close the connection.
                // ...
                mysql_close(conn);
            }
        } else {
            std::cerr << "Error: Failed to connect to MySQL." << mysql_error(conn) << std::endl;
            valid = false;
        }
    }

    json_decref(root);

    return valid;
}
