        private readonly IVaultClient _vaultClient;
        private readonly INotificationService _notificationService;
        private readonly IMetadataService _metadataService;
        private readonly IConfiguration _configuration;
        private readonly SemaphoreSlim _semaphore;
        private readonly Queue<string> _queue;

        public DynamicFileProcessor(ILogger<DynamicFileProcessor> logger, IAmazonS3 s3Client, IElasticClient elasticSearch, IVaultClient vaultClient, INotificationService notificationService, IMetadataService metadataService, IConfiguration configuration)
        {
            _logger = logger;
            _s3Client = s3Client;
            _elasticSearch = elasticSearch;
            _vaultClient = vaultClient;
            _notificationService = notificationService;
            _metadataService = metadataService;
            _configuration = configuration;
            _semaphore = new SemaphoreSlim(_configuration["ThreadCount"]);
            _queue = new Queue<string>();
        }

        public async Task AddFileToQueue(string filePath)
        {
            await _semaphore.WaitAsync();
            try
            {
                _queue.Enqueue(filePath);
                ProcessNextFile();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error adding file to queue");
            }
            finally
            {
                _semaphore.Release();
            }
        }

        private async void ProcessNextFile()
        {
            if (_queue.TryDequeue(out var filePath))
            {
                try
                {
                    using (var fileStream = File.OpenRead(filePath))
                    {
                        await ProcessFileAsync(fileStream);
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, $"Error processing file: {filePath}");
                }
            }
        }

