using StackExchange.Redis;
using Npgsql;

namespace DynamicFileProcessor
{
    public class DynamicFileProcessor
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<DynamicFileProcessor> _logger;
        private readonly IDatabase _redisDatabase;
        private readonly BlobContainerClient _blobContainerClient;
        private readonly NpgsqlConnection _databaseConnection;

        public DynamicFileProcessor(IConfiguration configuration, ILogger<DynamicFileProcessor> logger, IDatabase redisDatabase, BlobContainerClient blobContainerClient, NpgsqlConnection databaseConnection)
        {
            _configuration = configuration;
            _logger = logger;
            _redisDatabase = redisDatabase;
            _blobContainerClient = blobContainerClient;
            _databaseConnection = databaseConnection;
        }

        public void ProcessFile(string filePath, FileProcessingPriority priority)
        {
            // Handle file processing asynchronously and store the task in Redis for monitoring
            var redisTaskKey = $"file-task:{Guid.NewGuid()}";
            _redisDatabase.Enqueue(redisTaskKey, ProcessFileInternalAsync);

            _redisDatabase.ListLeftPush(redisTaskKey, filePath);
            _redisDatabase.HashTags(redisTaskKey, new[] { "priority", priority.ToString() });
        }

        private async Task ProcessFileInternalAsync(object obj)
        {
            // Load the file and metadata from Redis
            var redisTaskKey = (string)obj;
            var filePath = _redisDatabase.ListDequeue(redisTaskKey);
            var priority = Enum.Parse<FileProcessingPriority>(_redisDatabase.HashTags(redisTaskKey).FirstOrDefault()?.Value);

            using (var fileStream = File.OpenRead(filePath))
            {
                // Compress the file if necessary and upload to Azure Blob Storage
                var compressedFileStream = new MemoryStream();
                await UsingCompressionAsync(compressedFileStream, fileStream);
                await UploadToAzureBlobStorageAsync(compressedFileStream, GetFileNameFromPath(filePath));

                // Store the metadata in the relational database and integrate with external logging service
                var creationTime = DateTime.UtcNow;
                await UsingDatabaseTransactionAsync(_databaseConnection, async tx =>
                {
                    await InsertMetadataAsync(tx, filePath, compressedFileStream.Length, priority, creationTime);
                    await LogProcessingAsync(_logger, $"Start processing file: {filePath}");
                });
            }
        }

        private async Task UsingCompressionAsync(Stream output, Stream input)
        {
            // Implement compression logic here
        }

        private async Task UploadToAzureBlobStorageAsync(Stream stream, string fileName)
        {
            // Implement Azure Blob Storage uploading logic here
        }

        private async Task LogProcessingAsync(ILogger logger, string message)
        {
            // Implement logging service integration here
        }

        private async Task UsingDatabaseTransactionAsync(NpgsqlConnection connection, Func<NpgsqlTransaction, Task> transactionAction)
        {
            using var transaction = await connection.BeginTransactionAsync();
            try
            {
                await transactionAction(transaction);
                await transaction.CommitAsync();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to commit database transaction");
                await transaction.RollbackAsync();
                throw;
            }
        }

