#!/usr/bin/env node

const fs = require('fs-extra');
const path = require('path');
const glob = require('glob');
const { promisify } = require('util');
const chokidar = require('chokidar');
const zlib = require('zlib');
const axios = require('axios');
const yargs = require('yargs/yargs');
const { hideBin } = require('yargs/helpers');
const mongoose = require('mongoose');
const Bluebird = require('bluebird');

// Load configuration
const config = require('./config');
const { DB_URI, CONCURRENT_REQUESTS, DIRECTORY_TO_WATCH, ENCODING } = config;

// Initialize Mongoose connection to the database
mongoose.connect(DB_URI).catch((err) => console.error(`MongoDB connection error: ${err}`));

// Define metadata schema and model for processed files
const MetadataSchema = new mongoose.Schema({
  filePath: String,
  contentEncoding: String,
  lastProcessed: Date,
});
const Metadata = mongoose.model('Metadata', MetadataSchema);

// Utilities
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);
const globAsync = promisify(glob);
const mkdirp = require('mkdirp');

// Define functions for processing each file and accessing external data sources
async function processFile(filePath) {
  try {
    const content = await readFileAsync(filePath, ENCODING);

    // Access external data source using axios
    const response = await axiox.get(`https://api.example.com/process`, {
      params: { fileContent: content },
    });

    // Save metadata about the processed file in the database
    await Metadata.create({ filePath, lastProcessed: new Date() });

    console.log(`Processed file "${filePath}" successfully!`);
  } catch (err) {
    console.error(`Error processing file "${filePath}": ${err}`);
  }
}

// Initialize Chokidar to watch the specified directory and handle new files added to it
const watcher = chokidar.watch(DIRECTORY_TO_WATCH, { persistent: true });

// Define a Bluebird pool for concurrent requests, based on the configured concurrency level
const concurrentRequestsPool = Bluebird.pool(CONCURRENT_REQUESTS);

// Handle file events in the watched directory
watcher
  .on('add', async (filePath) => {
    try {
      await mkdirp(path.dirname(filePath));
      console.log(`New file detected: "${filePath}"`);

      // Limit concurrent requests by adding the task to a Bluebird pool
      const task = concurrentRequestsPool.acquire(() => processFile(filePath));
      await task();
    } catch (err) {
      console.error(`Error handling new file "${filePath}": ${err}`);
    }
  })
  .on('error', (err) => console.error(`Watcher error: ${err}`));

// Command-line interface for executing shell commands through the application
const argv = yargs(hideBin(process.argv[0]))
  .option('command', {
    alias: 'c',
    describe: 'Execute a shell command',
    type: 'string',
  })
  .help()
  .alias('help', 'h').argv;

if (argv.command) {
  exec(argv.command, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command: ${error}`);
      return;
    }

    console.log('Command output:');
    console.log(stdout);
  });
}
