public class DynamicFileProcessor : IActionResult
{
    private readonly IExternalService _externalService;
    private readonly ILogger<DynamicFileProcessor> _logger;
    private readonly IDatabase _redisDatabase;
    private readonly ConcurrentQueue<string> _fileProcessingQueue;
    private readonly SemaphoreSlim _semaphore;
    private readonly DynamicFileProcessorOptions _options;

    public DynamicFileProcessor(IExternalService externalService, ILogger<DynamicFileProcessor> logger, IOptions<DynamicFileProcessorOptions> options)
    {
        _externalService = externalService;
        _logger = logger;
        _redisDatabase = ConnectionMultiplexer.Connect(options.Value.RedisConnectionString).GetDatabase();
        _fileProcessingQueue = new ConcurrentQueue<string>();
        _semaphore = new SemaphoreSlim(options.Value.MaxConcurrentTasks);
        _options = options.Value;
    }

    public async Task<IActionResult> ExecuteAsync(CancellationToken cancellationToken)
    {
        await ProcessNextFileAsync(cancellationToken);
        return new EmptyResult();
    }

    private async Task ProcessNextFileAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            if (_fileProcessingQueue.TryDequeue(out string filePath))
            {
                _semaphore.Wait();
                try
                {
                    await ProcessFileAsync(filePath, cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to process file: {FilePath}", filePath);
                }
                finally
                {
                    _semaphore.Release();
                }
            }
            else
            {
                await Task.Delay(100, cancellationToken);
            }
        }
    }

