import java.util.Properties;
import java.util.concurrent.ConcurrentSkipListSet;
import java.util.stream.Collectors;

public class LegacyDataFeed {
    private static final Properties PROPERTIES = new Properties();
    private OkHttpClient client;

    public LegacyDataFeed(String apiEndpoint, String username, String password) {
        PROPERTIES.put("apiEndpoint", apiEndpoint);
        PROPERTIES.put("username", username);
        PROPERTIES.put("password", password);

        OkHttpClient.Builder builder = new OkHttpClient.Builder();
        // Add additional client configurations if needed
        client = builder.build();
    }

    public int[] fetchIntegers() throws IOException {
        Request request = new Request.Builder()
                .url(URI.create(PROPERTIES.getProperty("apiEndpoint") + "/integers"))
                .addHeader("Authorization", authenticate())
                .build();

        Response response = client.newCall(request).execute();
        if (!response.isSuccessful()) throw new IOException("Unexpected code " + response);

        String responseBody = response.body().string();
        List<Integer> list = Arrays.stream(responseBody.split(","))
                .mapToInt(Integer::parseInt)
                .boxed()
                .collect(Collectors.toCollection(ConcurrentSkipListSet::new));

        return list.toArray(int[]::new);
    }

