            System.out.println("[command]: fetch (default) | help | update");
        } else {
            String apiEndpoint = args[0];
            String username = args[1];
            String password = args[2];
            LegacyDataFeed legacyDataFeed = new LegacyDataFeed(apiEndpoint, username, password);

            try {
                int[] integers = legacyDataFeed.fetchIntegers();
                Arrays.sort(integers);
                System.out.println("Largest integer: " + integers[integers.length - 1]);
