    public class DynamicFileProcessor
    {
        private readonly ILogger<DynamicFileProcessor> _logger;
        private readonly IConfiguration _configuration;
        private readonly IProducerBuilder<Null, string> _producerBuilder;
        private readonly IMqttClient _mqttClient;
        private BlobContainerClient _azureBlobStorage;
        private AwsS3Client _awsS3Client;
        private BlobStorageClient _googleCloudStorage;
        private IReaderWriterQueue<FileProcessingTask> _queue;
        private readonly IEncryptionService _encryptionService;
        private readonly IValidator _validator;
        private readonly ITransformer _transformer;
        private readonly IThrottler _throttler;

        public DynamicFileProcessor(ILogger<DynamicFileProcessor> logger, IConfiguration configuration, IProducerBuilder<Null, string> producerBuilder, IMqttClient mqttClient, IReaderWriterQueue<FileProcessingTask> queue, IEncryptionService encryptionService, IValidator validator, ITransformer transformer, IThrottler throttler)
        {
            _logger = logger;
            _configuration = configuration;
            _producerBuilder = producerBuilder;
            _mqttClient = mqttClient;
            _queue = queue;
            _encryptionService = encryptionService;
            _validator = validator;
            _transformer = transformer;
            _throttler = throttler;
        }

        public void Start()
        {
            _mqttClient.ConnectAsync().Wait();
            _mqttClient.SubscribeAsync("fileProcessingTopic").Wait();

            var cloudStorageProvider = _configuration["CloudStorage:Provider"];
            if (cloudStorageProvider == "Azure")
                _azureBlobStorage = new BlobContainerClient(_configuration["Azure:ConnectionString"], _configuration["Azure:ContainerName"]);
            else if (cloudStorageProvider == "AWS")
                _awsS3Client = new AwsS3Client(_configuration["AWS:AccessKeyId"], _configuration["AWS:SecretAccessKey"], RegionEndpoint.GetBySystemName(_configuration["AWS:Region"]));
            else if (cloudStorageProvider == "Google")
                _googleCloudStorage = GoogleCloudStorageHelper.Create(_configuration);

            Task.Factory.StartNew(async () =>
            {
                while (true)
                {
                    var task = await _queue.DequeueAsync();

                    _throttler.ThrottleTask(ProcessFile, task);
                }
            });
        }

        private async Task ProcessFile(FileProcessingTask task)
        {
            using (var fileStream = File.OpenRead(task.LocalFilePath))
            {
                var encryptedContent = await _encryptionService.DecryptAsync(fileStream);
                var processedContent = _validator.Validate(JsonConvert.DeserializeObject<dynamic>(await encryptedContent.ReadToEndAsync()));

                if (!_validator.IsValid)
                {
                    var transformedContent = await _transformer.TransformAsync(processedContent);
                    processedContent = JsonConvert.SerializeObject(transformedContent);
                }

                await ProcessAndUpload(processedContent, task);
            }
        }

        private async Task ProcessAndUpload(string content, FileProcessingTask task)
        {
            // Real-time data processing using a streaming platform (e.g., Kafka, MQTT)

            await UploadToCloudStorageAsync(content, task);
        }

        private async Task UploadToCloudStorageAsync(string content, FileProcessingTask task)
        {
            switch (_configuration["CloudStorage:Provider"])
            {
                case "Azure":
                    await _azureBlobStorage.GetBlockBlobReference(task.FileName).UploadTextAsync(content);
                    break;
                case "AWS":
                    var putRequest = new PutObjectRequest
                    {
                        BucketName = _configuration["AWS:BucketName"],
                        Key = task.FileName,
                        ContentStream = new MemoryStream(Encoding.UTF8.GetBytes(content))
                    };
                    await _awsS3Client.PutObjectAsync(putRequest);
                    break;
                case "Google":
                    var blob = _googleCloudStorage.Bucket(_configuration["Google:BucketName"]).Object($"{task.FileName}");
                    await blob.UploadAsync(new MemoryStream(Encoding.UTF8.GetBytes(content)));
                    break;
            }
        }
    }
}
