import java.io.File;
import java.lang.management.ManagementFactory;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Queue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.stream.Collectors;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DataProcessor {

    private static final Logger LOGGER = LoggerFactory.getLogger(DataProcessor.class);
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final ConcurrentHashMap<String, AtomicInteger> fileProcessingStatus = new ConcurrentHashMap<>();

    public void processAndTransformData(Queue<String> filePaths, Map<String, Object> transformationParameters) {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.start();

        MemoryMXBean mxBean = ManagementFactory.getMemoryMXBean();
        long initialMemoryUsage = mxBean.getHeapMemoryUsage().getUsed();

        filePaths.stream()
                .filter(this::isValidFileType)
                .parallel()
                .map(this::processFile)
                .peek(this::notifyProgressCallbackIfPresent)
                .onCompletion((result) -> {
                    stopwatch.stop();
                    long totalProcessingTime = stopwatch.elapsed(TimeUnit.MILLISECONDS);
                    long finalMemoryUsage = mxBean.getHeapMemoryUsage().getUsed();
                    LOGGER.info("Total processing time: {}", totalProcessingTime, " ms");
                    LOGGER.info("Peak memory usage: {} MB", (finalMemoryUsage - initialMemoryUsage) / (1024 * 1024));
                })
                .collect(Collectors.toList());
    }

    private boolean isValidFileType(String filePath) {
        String fileExtension = getFileExtension(filePath);
        return transformationParameters.containsKey(fileExtension);
    }

    private Callable<Void> processFile(String filePath) {
        AtomicInteger status = fileProcessingStatus.getOrDefault(filePath, new AtomicInteger());

        return () -> {
            try {
                if (status.incrementAndGet() != 1) {
                    throw new IllegalStateException("Multiple threads attempting to process the same file.");
                }

                File file = new File(filePath);
                if (!file.exists() || !file.isFile()) {
                    LOGGER.error("Skipping invalid file: {}", filePath);
                    throw new FileNotFoundException();
                }

                // Use an instance of the ExternalDataProcessingAPI class to process the file.
                // Implement this class to handle interactions with your specific API.

            } catch (Exception e) {
                LOGGER.error("Error processing file: {}, Error code: {}", filePath, e.getMessage(), e);
                throw e;
            } finally {
                status.decrementAndGet();
            }
        };
    }

    private void notifyProgressCallbackIfPresent(Callable<Void> task) {
        Consumer<Integer> callback = (progress) -> {
            synchronized (fileProcessingStatus) {
                // Notify the parent system of the progress or completion status of the transformation tasks.
                // Implement this mechanism using your desired communication method (e.g., event bus, callbacks).
            }
        };

        Runnable runnable = () -> {
            try {
                callback.accept(fileProcessingStatus.getOrDefault(task.call().toString(), -1));
            } catch (Exception e) {
                LOGGER.error("Error notifying progress: {}", e.getMessage(), e);
            }
        };

        executor.submit(runnable);
    }

    private String getFileExtension(String filePath) {
        int dotIndex = filePath.lastIndexOf('.');
        return (dotIndex >= 0) ? filePath.substring(dotIndex + 1).toLowerCase() : "";
    }
}
