#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/syscall.h>
#include <unistd.h>

// Define log levels and their priorities
typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sigatomic_t current_log_level = ERROR;
static gid_t thread_gid; // Use GID to identify threads for logging purposes

void set_log_level(LogLevel level) {
    current_log_level = level;
}

#define LOG_FORMAT "[%lu] %s: "

void logConditionalMessage(LogLevel level, const char *format, ...) {
    if (current_log_level <= level) {
        va_list args;
        va_start(args, format);
        int bufferSize = 1024; // Initial buffer size
        char buffer[bufferSize];

        while (1) {
            size_t bytesWritten = snprintf(buffer, bufferSize, LOG_FORMAT format, getgid(), __func__, args...);

            if (bytesWritten >= bufferSize - 1) { // Leave one character for the null terminator
                bufferSize *= 2;
            } else {
                break;
            }
        }

        pthread_mutex_lock(&log_mutex);
        fputs(buffer, stderr);
        pthread_mutex_unlock(&log_mutex);

        va_end(args);
    }
}
```
This code defines a function `logConditionalMessage` that writes a formatted message to an error log if the specified log level is met or lower. The function utilizes `snprintf`, variable argument lists via `va_start` and `va_end`. It also handles dynamic log level settings and ensures thread safety for concurrent access from multiple processes using a mutex lock. Additionally, it optimizes the performance for high-throughput environments by dynamically growing the buffer size while writing the message. However, please note that this code is a starting point and may need further optimization depending on specific use cases and requirements.

