#include <stddef.h>
#include <stdlib.h>
#include <string.h>

char* appendSlashIfValid(const char *inputStr, size_t limit) {
    if (!inputStr) return "";

    size_t inputLen = strlen(inputStr);
    if (inputLen <= limit - 1) {
        char result[limit + 1];
        strcpy(result, inputStr);
        result[inputLen] = '/';
        result[inputLen + 1] = '\0';
        return strdup(result);
    } else {
        return "";
    }
}
