class Logger {
private:
    std::mutex mtx;

public:
    void log(const std::string& msg) {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << "[Logger] " << msg << std::endl;
    }
};

// Function to dynamically insert data and call callbacks
void dynamicDataInsertion(std::forward_list<std::string>& list, const std::string& target, const std::string& value, const std::shared_ptr<Context>& context,
                          const std::function<void(const std::string&, const std::string&)>& callback) {
    auto it = list.begin();
    auto prevIt = list.before_begin();

    // Validation and error handling
    if (context == nullptr || target.empty() || value.empty()) {
        Logger lg;
        lg.log("Error: Invalid input parameters.");
        throw std::invalid_argument("Invalid input parameters");
    }

    // Search for the target element
    while (it != list.end() && *it != target) {
        prevIt = it++;
    }

    // Insert or update data based on whether the target was found
    if (it == list.end()) {
        list.insert(prevIt, value);

        if (!callback) {
            Logger lg;
            lg.log("Insertion success: " + value + " inserted at position " + std::to_string(std::distance(list.begin(), prevIt)) + ".");
        } else {
            callback(target, value);
        }
    } else {
        auto prevValue = *it;
        list.erase(it);
        list.insert(prevIt, value);

        if (!callback) {
            Logger lg;
            lg.log("Update success: Replaced " + prevValue + " with " + value + " at position " + std::to_string(std::distance(list.begin(), prevIt)) + ".");
        } else {
            callback(target, value);
        }
    }
}
