    if (!key) {
        // Handle errors here
        cleanup();
        return;
    }

    // Initialize OpenSSL cipher context with provided algorithm
    if (initCipherContext(algorithm, key) <= 0) {
        // Handle errors here
        cleanup();
        return;
    }

    // Encrypt payload and store encrypted data in encrypted_data
    int plaintext_len = strlen(payload);
    encrypted_data = (unsigned char *)malloc(plaintext_len + AES_BLOCK_SIZE);
