const crypto = require('crypto');
const zlib = require('zlib');
const lodash = require('lodash');

class ByteRangeCopier {
  constructor(compressionAlgorithm, metadataStorage) {
    this.compressionAlgorithm = compressionAlgorithm;
    this.metadataStorage = metadataStorage;
    this.cache = new Map();
    this.rateLimiter = new RateLimiter({
      max: 10, // Adjust as needed
      time: 100 // Milliseconds between requests
    });
  }

  async copyBytesRange(range, source) {
    if (!lodash.isNumber(range[0]) || !lodash.isNumber(range[1])) {
      throw new Error('Invalid byte range');
    }

    const start = Math.min(range[0], range[1]);
    const end = Math.max(range[0], range[1]);

    let buffer = this.cache.get(source);
    if (!buffer) {
      buffer = await loadBufferedDataOrFile(source);
      this.cache.set(source, buffer);
    }

    const cachedSegment = buffer.slice(start, end + 1);
    if (cachedSegment.byteLength > 0) {
      return cachedSegment;
    }

    await this.rateLimiter.wait(); // Wait before next request

    let segment;
    if (this.compressionAlgorithm) {
      const compressedBuffer = await compressData(buffer, start, end, this.compressionAlgorithm);
      segment = compressedBuffer.slice(start, end + 1);
    } else {
      segment = buffer.slice(start, end + 1);
    }

    if (segment.byteLength > 0) {
      this.cache.set(source, buffer); // Update cache
      await storeMetadata(source, start, end); // Store metadata
    }

    return segment;
  }
}
