                Duration delay = new Random().nextInt((int) TimeUnit.MINUTES.toMillis(5)) + TimeUnit.MILLISECONDS.toMillis(1);
                Thread.sleep(delay.toMillis());

                service.stop();
                LOGGER.info("Stopped service: {}", service.getName());

                ProducerRecord<String, String> record = new ProducerRecord<>(SERVICE_STOPPED_TOPIC, service.getName());
                kafkaProducer.send(record);
            } catch (Exception e) {
                LOGGER.error("Error managing service: {}", service.getName(), e);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        ServiceManager manager = new ServiceManager(/* ... */);
        // Start statusUpdater and serviceExecutor threads and manage services
    }
}

