<?php
function updateUserPassword($userId, $newPassword, $confirmPassword, $authServiceConfig) {
    $dbHost = $authServiceConfig['db']['host'];
    $dbName = $authServiceConfig['db']['name'];
    $dbUser = $authServiceConfig['db']['user'];
    $dbPass = $authServiceConfig['db']['password'];

    // Establish connection to the database
    $conn = new mysqli($dbHost, $dbUser, $dbPass, $dbName);

    if ($conn->connect_error) {
        logError("Connection error: " . $conn->connect_error);
        die("Connection failed: " . $conn->connect_error);
    }

    // Set timeouts for the connection and query execution
    $conn->set_charset('utf8mb4');
    $conn->query("SET SESSION wait_timeout = 60"); // 1 minute timeout for the query

    // Fetch the current password from the database
    $currentPasswordQuery = $conn->prepare("SELECT password FROM users WHERE id = ? LIMIT 1");
    $currentPasswordQuery->bind_param("i", $userId);
    $currentPasswordQuery->execute();
    $currentPasswordResult = $currentPasswordQuery->get_result();
    $currentPassword = $currentPasswordResult->fetch_assoc()['password'];

    // Check if the new password matches the confirmation and meets complexity criteria
    if (strlen($newPassword) < 12 || !preg_match('/(?=(.*[a-z]){2})(?=(.*[A-Z]){2})(?=(.*\d){2})(?=(.*[@#$%]).{12}/', $newPassword)) {
        logError("Invalid password format.");
        die("Password must be at least 12 characters long, containing two uppercase letters, two lowercase letters, two digits, and two special characters.");
    }

    if ($newPassword === $currentPassword) {
        logError("Current password cannot be the same as the new password.");
        die("New password must be different from the current password.");
    }

    if ($newPassword !== $confirmPassword) {
        logError("The provided passwords do not match.");
        die("The new password and confirmation password must match.");
    }

    // Verify password strength with external authentication service
    try {
        $passwordStrengthResult = callExternalService($newPassword, $authServiceConfig);
        if (!$passwordStrengthResult->isValid) {
            logError("Invalid password strength according to the external service.");
            die("The new password does not meet the required complexity.");
        }
    } catch (Exception $e) {
        logError($e->getMessage());
        // Implement fallback mechanisms when the external service is not available
    }

    // Rate limiting: Check if the user has exceeded the allowed number of attempts within the last 30 minutes
    $attemptTime = strtotime("now - 30 minutes");
    $attemptQuery = $conn->prepare("SELECT COUNT(*) AS attempts FROM password_attempts WHERE user_id = ? AND attempt_time > ?");
    $attemptQuery->bind_param("ii", $userId, $attemptTime);
    $attemptQuery->execute();
    $attemptResult = $attemptQuery->get_result();
    $attemptRow = $attemptResult->fetch_assoc();
    $currentAttempts = (int) $attemptRow['attempts'];

    if ($currentAttempts >= $authServiceConfig['rateLimit']['maxAttempts']) {
        logError("The user has exceeded the allowed number of password update attempts.");
        die("Please try again later.");
    }

    // Begin transaction
    $conn->begin_transaction();

    try {
        // Check if the new password is already used by the user or stored in the history table
        $existingPasswordQuery = $conn->prepare("SELECT id FROM users WHERE password = ?");
        $existingPasswordQuery->bind_param("s", $newPassword);
        $existingPasswordQuery->execute();
        $existingPasswordResult = $existingPasswordQuery->get_result();
        if ($existingPasswordResult->num_rows > 0) {
            throw new Exception("The new password is already in use by another user or was previously used by this user.");
        }

        // Update the user's password and increment the attempt counter in the password_attempts table
        $passwordUpdateQuery = $conn->prepare("UPDATE users SET password = ? WHERE id = ?");
        $passwordUpdateQuery->bind_param("ss", $newPassword, $userId);
        $passwordUpdateQuery->execute();

        $attemptUpdateQuery = $conn->prepare("INSERT INTO password_attempts (user_id, attempt_time) VALUES (?, ?)");
        $attemptUpdateQuery->bind_param("ii", $userId, time());
        $attemptUpdateQuery->execute();

        // Commit the transaction
        $conn->commit();
    } catch (Exception $e) {
        // Rollback the transaction and log the error
        $conn->rollback();
        logError($e->getMessage());
    }

    // Release the connection
    $conn->close();
}
