#define NFAPI_CRFC_INDICATION_PDU_T \
struct NFAPI_CRFC_INDICATION_PDU_T {\
    RX_UE_INFORMATION_TAG rx_ue_information_tag;\
    RNTI rnti;\
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;\
};

typedef struct data_source {
