unsigned int calculate_checksum(const void* data, size_t size) {
    // Implement the checksum calculation algorithm here
    // This is place holder, you need to replace with your specific algorithm
    unsigned int result = 0;
    const unsigned char* data_ptr = (const unsigned char*)data;
    for(size_t i = 0; i < size; ++i) {
        result += data_ptr[i];
    }
    return result;
}

unsigned int get_crcflag(const NFAPI_CRFC_INDICATION_PDU_T* pdu) {
    // Calculate the checksum of RX_UE_INFORMATION_TAG and RNTI values
    unsigned int checksum = calculate_checksum(&pdu->rx_ue_information_tag, sizeof(RX_UE_INFORMATION_TAG));
    checksum += calculate_checksum(&pdu->rnti, sizeof(RNTI));

    return checksum % 2;
}

NFAPI_CRFC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRFC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRFC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Failed to allocate memory for PDU.");
        return NULL;
    }
    return pdu;
}

void destroy_pdu(NFAPI_CRFC_INDICATION_PDU_T** ppdu) {
    if (*ppdu) {
        free(*ppdu);
        *ppdu = NULL;
    }
}

NFAPI_CRFC_INDICATION_PDU_T** populate_pdus(size_t n, DataSource* sources[]) {
    NFAPI_CRFC_INDICATION_PDU_T** pdus = malloc(n * sizeof(NFAPI_CRFC_INDICATION_PDU_T*));
    if (!pdus) {
        log_error("Failed to allocate memory for PDUs.");
        return NULL;
    }

    pthread_t threads[n];
    for(size_t i = 0; i < n; ++i) {
        pdus[i] = create_pdu();
        if (!pdus[i]) {
            // If creation fails for any PDUs, free all previously allocated PDUs and return early
            for(size_t j = 0; j < i; ++j) {
                destroy_pdu(&pdus[j]);
            }
            log_error("Failed to allocate memory for some PDUs.");
            free(pdus);
            return NULL;
        }

        int rc = pthread_create(&threads[i], NULL, populate_pdu_worker, (void*)&sources[i][0], (void*)i);
        if (rc) {
            log_error("Failed to create thread.");
            // If creation fails for any threads, free all previously allocated PDUs and return early
            for(size_t j = 0; j < i; ++j) {
                destroy_pdu(&pdus[j]);
            }
            free(pdus);
            return NULL;
        }
    }

    for(size_t i = 0; i < n; ++i) {
        rc = pthread_join(threads[i], NULL);
        if (rc) {
            log_error("Failed to join thread.");
            // If joining any threads fails, free all previously allocated PDUs and return early
            for(size_t j = 0; j < n; ++j) {
                destroy_pdu(&pdus[j]);
            }
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}

void* populate_pdu_worker(void* arg) {
    size_t index = *(size_t*)arg;
    DataSource* source = (DataSource*)&((char*)arg)[sizeof(size_t)];

    // Access the data source, check for completeness and correctness of incoming data, populate the PDU structure

    if (!source->is_active || !source->handle) {
        log_error("Invalid or inactive data source.");
        destroy_pdu(&pdus[index]); // Free the PDUs created by this thread
        return NULL;
    }

    // Populate the PDU structure with data from the active data source
    // ...

    NFAPI_CRFC_INDICATION_PDU_T* pdu = pdus[index];
    pdu->crc_indication_rel8_tag.crcflag = get_crcflag(pdu);

    return pdu;
}

