@Service
public class DataProcessor {
    private final RedisCache redis;
    @Autowired
    public DataProcessor(RedisCache redis) { this.redis = redis; }

    public Map<String, String> processRequest(String endpointName) throws IOException {
        ApiEndpoint apiEndpoint = getApiEndpoints().stream()
            .filter(apiEndpoint -> apiEndpoint.getName().equals(endpointName))
            .findFirst()
            .orElseThrow(() -> new RuntimeException("Endpoint not found: " + endpointName));

        Map<String, String> result;
        while (true) {
            try {
                ApiResponse response = apiEndpoint.fetchData();
                result = apiEndpoint.extractKeyValue(response);
                if (!redis.contains(endpointName + ":result")) {
                    redis.set(endpointName + ":result", result, ConfigurableEvictionPolicyBuilder
                        .JsonRedisCache() // Custom eviction policy based on RedisJsonPolicy
                        .maxEntries(100)
                        .timeToLive(300)
                        .build());
                }
                break;
            } catch (RateLimitExceededException e) {
                apiEndpoint.handleRateLimitError();
            } catch (TokenExpiredException e) {
                apiEndpoint.handleTokenExpiredError();
            } catch (IOException e) { // Add more specific exception types and custom retry logic if needed
                Thread.sleep(Math.exp(Math.log(2) * Math.random())); // Random backoff strategy
            }
        }
        return result;
    }
}

