class Context {
public:
    std::string userID;
    std::string taskType;
    std::chrono::steady_clock::time_point timestamp;

    // Constructor, destructor, and other methods for flexibility and extensibility
};

std::mutex mtx;
std::condition_variable cv;
std::queue<std::pair<std::string, std::shared_ptr<Context>>> taskQueue;
unsigned int concurrentTaskLimit = 0; // Set system capacity constraint here

void executeTask(const std::pair<std::string, std::shared_ptr<Context>>& task) {
    // Execute the task using a callback function and handle logging
}

void enqueueTask(std::forward_list<std::string> commands, const std::string& taskTarget, const std::string& taskValue, const std::shared_ptr<Context>& context) {
    if (!context) {
        std::cerr << "Error: Invalid context pointer" << std::endl;
        return;
    }

    auto it = commands.begin();
    auto end = commands.end();

    while (it != end) {
        if (*it == taskTarget) {
            taskQueue.emplace(std::pair<std::string, std::shared_ptr<Context>>(taskValue, context));
            break;
        }
        ++it;
    }

    if (it == end) {
        taskQueue.emplace_back(std::pair<std::string, std::shared_ptr<Context>>(taskValue, context));
    }

    std::unique_lock<std::mutex> lock(mtx);
    cv.notify_one(); // Notify one thread to process the new task

    if (taskQueue.size() > concurrentTaskLimit) {
        while (taskQueue.size() > concurrentTaskLimit) {
            cv.wait(lock); // Wait for a slot to become available
        }
    }

    std::thread worker([&]() { executeTask(taskQueue.front()); taskQueue.pop_front(); }).detach();
}
