    @wraps(f)
    def wrapper(*args, **kwargs):
        conn = None
        try:
            conn = pool.getconn()
            with conn.cursor() as cur:
                cur.execute("BEGIN;")
                logger.info(f"Starting test '{label}'...")
                res = f(*args, **kwargs, conn=conn, cur=cur)
                cur.execute("COMMIT;")
            pool.putconn(conn)
            return res
        except Exception as e:
            cur = None
            if conn:
                conn.rollback()
                conn.close()
            logger.error(f"Error during test '{label}': {str(e)}")
            raise e
    return wrapper

# Sample usage with a simple test function
@db_test("SampleTest", lambda conn, cur: conn.cursor().execute("SELECT 1;").fetchone(), pool_size=5)
def test():
    pass
