```javascript
const { Stream, pipeline } = require('stream');
const _ = require('lodash');
const winston = require('winston');
const Promise = require('bluebird');

class MergeStream extends Stream {
  constructor(options) {
    super({ objectMode: true });

    this.bufferSizeLimit = options.bufferSizeLimit || 1048576; // default buffer size limit: 1MB
    this.maxBuffer = [];
    this.paused = false;

    this.on('data', (chunk) => {
      if (!this.paused) {
        this.maxBuffer.push(chunk);
        this.flushIfNeeded();
      }
    });
  }

  async _write(chunk, encoding, callback) {
    try {
      // Handle writing data to the destination stream here
      await this.destStream.write(chunk);
      callback();
    } catch (error) {
      winston.error(`Error while writing data: ${error}`);
      callback(error);
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    this.flushIfNeeded();
  }

  flushIfNeeded() {
    if (this.maxBuffer.length > this.bufferSizeLimit) {
      winston.info(`Flushing buffer due to size limit exceeded`);
      this.flush();
    } else {
      requestIdleCallback(_.throttle(() => this.flushIfNeeded(), 100)); // flush the buffer every 100ms
    }
  }

  async _flush(callback) {
    try {
      const dataChunk = Buffer.concat(this.maxBuffer);
      await Promise.all([this.write(dataChunk), this.destStream.flush()]);
      this.maxBuffer = [];
      callback();
    } catch (error) {
      winston.error(`Error while flushing data: ${error}`);
      callback(error);
    }
  }
}

// Usage example
const destStream = new Stream.Writable({ objectMode: true });
const mergeStream = new MergeStream({ bufferSizeLimit: 500000 }); // set the desired buffer size limit (e.g., 500KB)
mergeStream.pipe(destStream);

// Add more streams to merge here, for example:
const stream1 = createDataStream();
const stream2 = createAnotherDataStream();

Promise.all([stream1.pipe(mergeStream), stream2.pipe(mergeStream)])
  .then(() => {
    mergeStream.pause(); // pause the merging operation when you want to stop it
  })
  .catch((error) => {
    winston.error(`Error occurred during data merging: ${error}`);
  });
```

