class Logger {
public:
    enum class Severity { Debug, Info, Warning, Error, Critical };
    using Channel = std::function<void(const char*, Severity)>;

    void addChannel(Channel channel) { _channels.emplace_back(channel); }
    void removeChannel(Channel channel) {
        _channels.remove_if([channel](const auto& c) { return c == channel; });
    }

    template<typename... Args>
    void log(Severity severity, const char* format, Args&&... args) {
        std::stringstream ss;
        ss << std::forward<Args>(args)...;
        auto message = ss.str();
        vsnprintf(message.data(), message.size(), format, &args...);

        std::unique_lock<std::mutex> lock(_mutex);
        for (auto& channel : _channels) {
            channel(message.c_str(), severity);
        }
    }

private:
    std::vector<Channel> _channels;
    std::mutex _mutex;
};
