```cpp
#include <iostream>
#include <list>
#include <mutex>
#include <string>
#include <algorithm>

class Node {
public:
    std::string name;
    std::string value;
    std::string attribute;
    std::mutex mtx;

    explicit Node(const std::string& name) : name(name) {}
};

void updateNodeAttributes(std::forward_list<Node*>& list, const std::string& nodeName, const std::string& newValue, const std::string& newAttribute, const std::string& context) {
    auto it = list.begin();
    bool foundMatchingContext = false;

    while (it != list.end()) {
        std::unique_lock<std::mutex> lock((*it)->mtx);

        if ((*it)->name == nodeName && (!context.empty() ? (*it)->context == context : true)) {
            foundMatchingContext = true;
            (*it)->value = newValue;
            (*it)->attribute = newAttribute;
            std::cout << "Updated attribute for node: " << nodeName << "\n";
            break;
        }
        it++;
    }

    if (!foundMatchingContext && !nodeName.empty()) {
        Node* newNode = new Node(nodeName);
        newNode->value = newValue;
        newNode->attribute = newAttribute;
        list.push_back(newNode);
        std::cout << "Created new node with name: " << nodeName << "\n";
    }
}
