namespace TextDataProcessor
{
    public class TextDataProcessor
    {
        private readonly Dictionary<string, ApiIntegration> _apis = new Dictionary<string, ApiIntegration>();
        private readonly Random _random = new Random();
        private int _processingRangeMin;
        private int _processingRangeMax;
        private Timer _statusUpdateTimer;

        public TextDataProcessor(params (string apiKey, string apiUrl)[] apis)
        {
            foreach (var api in apis)
                RegisterApiIntegration(api.apiKey, api.apiUrl);
        }

        public void RegisterApiIntegration(string apiKey, string apiUrl)
        {
            _apis[apiKey] = new ApiIntegration(apiKey, apiUrl);
        }

        public int ProcessingRangeMin { get => _processingRangeMin; set => _processingRangeMin = Math.Max(value, 1); }
        public int ProcessingRangeMax { get => _processingRangeMax; set => _processingRangeMax = value > int.MaxValue ? int.MaxValue : value; }

        public async Task<string> GenerateRandomStringAsync(int minLength, int maxLength)
        {
            if (minLength < 1 || maxLength <= 0 || maxLength < minLength)
                throw new ArgumentOutOfRangeException(nameof((int, int) minLength, maxLength), "Invalid length parameters.");

            var apiIntegrations = _apis.Values.Where(x => x.IsHealthy).ToList();
            if (apiIntegrations.Count == 0)
                return null;

            var targetLength = _random.Next(minLength, maxLength);
            var results = await Task.WhenAll(apiIntegrations.Select(GenerateStringFromApiAsync));
            var generatedString = string.Join("", results.Where(x => x != null).ToArray());

            if (generatedString.Length < targetLength)
                return generatedString + GetSuffixForShortStrings();

            return generatedString;
        }

        private string GenerateStringFromApiAsync(ApiIntegration api)
        {
            try
            {
                return api.GetRandomStringAsync().Result;
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"API '{api.Key}' failed with error: {ex.Message}");
                api.MarkAsUnhealthy();
                return null;
            }
        }

        private string GetSuffixForShortStrings()
        {
            const int suffixLength = 5;
            return new string(Enumerable.Repeat("a", suffixLength).Select(c => (char)(_random.Next(97, 123))).ToArray());
        }

        public override string ToString()
        {
            var statusBuilder = new StringBuilder();

            foreach (var api in _apis.Values)
                statusBuilder.AppendLine($"API '{api.Key}': {api.Status}");

            statusBuilder.AppendLine($"\nProcessing Range: {_processingRangeMin}-{_processingRangeMax}");
            return statusBuilder.ToString();
        }

        private void UpdateApiHealthStatus()
        {
            foreach (var api in _apis.Values)
                api.CheckHealthStatus();
        }

        public void StartStatusUpdates(int intervalMs = 60_000)
        {
            _statusUpdateTimer = new Timer(intervalMs);
            _statusUpdateTimer.Elapsed += UpdateApiHealthStatus;
            _statusUpdateTimer.Start();
        }
    }

    public class ApiIntegration
    {
        public string Key { get; private set; }
        public string Url { get; private set; }
        public bool IsHealthy { get; private set; }

        public ApiIntegration(string key, string url)
        {
            Key = key;
            Url = url;
            IsHealthy = true;
        }

        public void MarkAsUnhealthy() => IsHealthy = false;

        public virtual async Task<string> GetRandomStringAsync()
        {
            // Implement API-specific functionality here.
            throw new NotImplementedException();
        }

        public void CheckHealthStatus()
        {
            if (IsHealthy)
                IsHealthy = HttpRequestHelper.IsApiHealthy(Url);
        }
    }

    public static class HttpRequestHelper
    {
        public static bool IsApiHealthy(string url)
        {
            try
            {
                using var httpClient = new HttpClient();
                var response = await httpClient.GetAsync(url);
                return response.IsSuccessStatusCode;
            }
            catch (HttpRequestException ex)
            {
                Console.WriteLine($"API '{url}' failed with error: {ex.Message}");
                return false;
            }
        }
    }
}
