using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;
using RestSharp;

namespace LoggingService
{
    public interface ILoggerService
    {
        Task<bool> ArchiveLogAsync(LogEvent logEvent);
        void NotifyOnError(string errorMessage, string email);
    }

    public class LoggerService : ILoggerService
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<LoggerService> _logger;
        private readonly RestClient _restClient;
        private readonly List<ILogFilter> _logFilters;

        public LoggerService(IConfiguration configuration, ILogger<LoggerService> logger)
        {
            _configuration = configuration;
            _logger = logger;
            _restClient = new RestClient(_configuration["LoggingServiceApiUrl"]);
            _logFilters = new List<ILogFilter>();
        }

        public async Task<bool> ArchiveLogAsync(LogEvent logEvent)
        {
            try
            {
                foreach (var filter in _logFilters)
                {
                    if (!filter.ShouldProcess(logEvent)) return false;
                }

                var request = new RestRequest("logs", Method.POST);
                request.AddJsonBody(logEvent);
                var response = await _restClient.ExecuteAsync(request);

                if (response.IsSuccessful) return true;
            }
