    }

    public class LogLevelFilter : ILogFilter
    {
        private readonly string _logLevel;

        public LogLevelFilter(string logLevel) => _logLevel = logLevel.ToUpper();

        public bool ShouldProcess(LogEvent logEvent) => logEvent.LogLevel == _logLevel;
    }

    public class KeywordFilter : ILogFilter
    {
        private readonly string[] _keywords;

        public KeywordFilter(string[] keywords) => _keywords = keywords;

        public bool ShouldProcess(LogEvent logEvent) => _keywords.Any(keyword => logEvent.Message.Contains(keyword, StringComparison.OrdinalIgnoreCase));
    }

    public class LogEvent
    {
        public string Source { get; set; }
        public string Message { get; set; }
        public LogLevel LogLevel { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public enum LogLevel
    {
        Debug,
        Info,
        Warning,
        Error,
        Fatal
    }
}
