import time
import json
import threading
from typing import Dict, Any
from datetime import timedelta
from functools import wraps
from urllib.request import urlopen
from redisson import RedisClient

class CacheManager:
    def __init__(self):
        self.redis = RedisClient()
        self._config_url = "YOUR_CONFIG_SERVER_URL"
        self._version = 1
        self._lock = threading.Lock()
        self.cache_hits = 0
        self.cache_misses = 0
        self.updates = 0

    def _get_prefs_from_server(self) -> Dict[str, Any]:
        with urlopen(self._config_url) as response:
            data = json.load(response)
            data['version'] = self._version
            return data

    def _log(self, action: str):
        if action == 'hit':
            self.cache_hits += 1
        elif action == 'miss':
            self.cache_misses += 1
        else:
            self.updates += 1

    def wrap_func(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = f"user:{args[0]}"
            cached_prefs = self.redis.get(key)
            if cached_prefs:
                self._log('hit')
                return json.loads(cached_prefs)
            else:
                self._log('miss')
                with self._lock:
                    cached_prefs = self.redis.get(key)
                    if not cached_prefs:
                        pref_data = func(*args, **kwargs)
                        updated_prefs = self._update_cache(key, pref_data)
                        return updated_prefs
                    else:
                        return json.loads(cached_prefs)

        return wrapper

    def _update_cache(self, key: str, data: Dict[str, Any]) -> Dict[str, Any]:
        if self._version != data['version']:
            new_data = self._get_prefs_from_server()
            self.redis.set(key, json.dumps(new_data), ex=60)  # Set expiry to 1 minute (adjust as needed)
        else:
            self.redis.set(key, json.dumps(data), ex=60)
        return data

    def get_user_preferences(self, user_id: int):
        return self.wrap_func(self._get_user_preferences)(user_id)

def _get_user_preferences(user_id: int):
