        }
        res = curl_easy_perform(curl_handle, word);
    }
    data->count += res == CURLE_OK;
    return NULL;
}

void logConditionalMessage(int level, const char *format, ...) {
    if (level <= logLevel) {
        va_list args;
        va_start(args, format);
        vsyslog(level, format, args);
        va_end(args);
    }
}

