    int opt;
    while ((opt = getopt(argc, argv, "o:cs:hv")) != -1) {
        switch (opt) {
            case 'c':
                caseSensitive = true;
                break;
            case 's':
                caseSensitive = false;
                break;
            case 'o':
                outputFile = optarg;
                break;
            case 'h':
            case 'v':
                // Display manpage or version information
                return 0;
        }
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_handle = curl_easy_init();
    // Initialize logging system and other required resources

    struct stat st;
    FILE *inputFile;
    size_t numFiles = argc - optind;
    files = malloc(numFiles * sizeof(FILE*));
    threads = malloc(numThreads * sizeof(pthread_t));
    semaphores = malloc(numFiles * sizeof(sem_t));

    for (size_t i = optind; i < argc; ++i) {
        inputFile = fopen(argv[i], "r");
        if (!inputFile) {
            logConditionalMessage(LOG_ERR, "Error opening file: %s", argv[i]);
            continue;
        }
        files[i - optind] = inputFile;

        sem_init(&semaphores[i - optind], 0, numThreads);
        FileHandler *handler = malloc(sizeof(FileHandler));
        handler->filename = argv[i];
        handler->fp = inputFile;
        handler->sem = semaphores[i - optind];
        pthread_create(&threads[numThreads++], NULL, &wordFrequencyAnalysis, handler);
    }

    // Parallel processing of the files using concurrent threads

    for (size_t i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(files);
    free(threads);
    free(semaphores);

    // Release resources and write results to outputFile

    curl_global_cleanup();
    return 0;
}
