 *
 * @param {Array<Function>} tests - Array of test functions. Each function should accept no arguments and return a Promise.
 * @param {Array<String>} labels - Corresponding labels for each test function.
 */
async function executeTests(tests, labels) {
  const mockedModules = {}; // Store mocked modules to be reset after each test

  // Mock necessary components using blueslip
  tests.forEach((testFunc) => {
    const deps = getDependencies(testFunc);
    deps.forEach((dep) => {
      if (!mockedModules[dep]) {
        mockedModules[dep] = blueslip.mock(dep);
      }
    });
  });

  try {
    const results = await parallel(tests, async (testFunc, _, done) => {
      try {
        // Execute test function and handle any errors or timeouts
        const result = await testFunc();

        // Report test results based on the result value or error thrown
        if (result instanceof Error) {
          console.error(`${chalk.red('TEST FAILURE')}: ${labels[tests.indexOf(testFunc)]} (${testFunc.name})`, result.message);
        } else {
          console.log(`${chalk.green('TEST PASSED')}: ${labels[tests.indexOf(testFunc)]} (${testFunc.name})`);
        }

        // Reset mocks for the next test
        Object.entries(mockedModules).forEach(([dep, mock]) => mock.reset());

        done();
      } catch (error) {
        console.error(`${chalk.red('TEST FAILURE')}: ${labels[tests.indexOf(testFunc)]} (${testFunc.name})`, error);
        done(error);
      }
    });

    // Summarize test results
    const successCount = results.filter((result) => result === undefined).length;
    const failureCount = results.filter((result) => result instanceof Error).length;
    console.log(`${chalk.yellow('TEST SUMMARY')}`);
    console.log(`  ${successCount} tests passed`);
    console.log(`  ${failureCount} tests failed`);
  } catch (error) {
    console.error(chalk.red('TEST FRAMEWORK ERROR'), error);
  }
}

