#include <boost/asio.hpp>
#include <process.h>
#include <sys/types.h>
#include <unistd.h>

void executeCommand(const std::string& command, int maxRetries = 3) {
    pid_t pid = fork();
    if (pid == -1) {
        throw std::runtime_error("Error while forking process");
    }

    if (!pid) { // child process
        std::string logFilePath = "command_" + command + ".log";
        freopen(logFilePath.c_str(), "w", stdout);
        system((command + " >& " + logFilePath).c_str());
        exit(0);
    } else { // parent process
        if (waitpid(pid, nullptr, WUNTRACED) == -1) {
            throw std::runtime_error("Error waiting for child process");
        }
    }
}
