// External configuration service trait
trait ConfigService {
    async fn get_base_dir(&self) -> Result<String, Box<dyn std::error::Error>>;
}

// Quota service trait
trait QuotaService {
    async fn quota(&self) -> Result<u64, Box<dyn std::error::Error>>;
}

struct TempDirManager {
    config: Box<dyn ConfigService + Send + Sync>,
    quota: Box<dyn QuotaService + Send + Sync>,
    log: Logger,
}

impl TempDirManager {
    async fn new(config: Box<dyn ConfigService + Send + Sync>, quota: Box<dyn QuotaService + Send + Sync>) -> Self {
        let log = init_logger();
        Self { config, quota, log }
    }

    async fn create(&self) -> Result<PathBuf, Box<dyn std::error::Error>> {
        let base_dir = self.config.get_base_dir().await?;
        let mut dir_path = Path::new(&base_dir);
        dir_path.push(format!("{}_temp_{}", env::var("APP_NAME").unwrap(), env::var("APP_VERSION").unwrap()));
        fs::create_dir_all(&dir_path)?;
        let lockfile = self.lock_file(&dir_path).await?;
        drop(lockfile); // Release the file lock
        Ok(dir_path)
    }

    async fn lock_file(&self, dir: &Path) -> Result<NamedTempFile, Box<dyn std::error::Error>> {
        // Implement using tempfile or another suitable library
    }

    async fn use_temp_dir<F>(&'static self, f: F) -> Result<(), Box<dyn std::error::Error>>
        where F: FnOnce(PathBuf) + Send + Sync + 'static {
        let temp_dir = self.create().await?;
        let mut lockfile = self.lock_file(&temp_dir).await?;
        let mut guard = Mutex::new(lockfile);
        let lockfile = tokio::task::spawn(async move {
            loop {
                tokio::select! {
                    _ = guard.locked().recv() => break,
                    _ = tokio::time::sleep(std::time::Duration::from_secs(5)).fuse() => {},
                }
            }
        });

        f(temp_dir).await?;
        drop(lockfile); // Release the file lock on return
        Ok(())
    }

    async fn cleanup(&self) -> Result<(), Box<dyn std::error::Error>> {
        let mut log_path = self.log.log_path().unwrap();
        if fs::metadata(&log_path).is_ok() {
            fs::remove_file(&log_path)?;
        }

        let base_dir = self.config.get_base_dir().await?;
        for entry in fs::read_dir(Path::new(&base_dir))? {
            let entry = entry?;
            let path = entry.path();
            if path.is_dir() && path.file_name().and_then(|n| n.to_str()).map_or(false, |s| s.starts_with("_temp")) {
                fs::remove_dir_all(&path)?;
            }
        }

        Ok(())
    }
}

fn init_logger() -> Logger {
    env_logger::Builder::from_env(env::current_exe().unwrap().file_name().unwrap().to_str().unwrap())
        .format(|buf, record| {
            writeln!(buf, "{:<5} [{}] {}", chrono::Local::now(), record.level(), record.args())
        })
        .try_init()
        .unwrap()
}
