            throw new InvalidOperationException("Failed to update game state.");

        var attack = SelectRandomAttack();
        var canExecuteAttack = CheckCooldown() && CanExecuteAttack(attack);

        if (canExecuteAttack)
            ExecuteAttack(attack);
    }

    public void ExecuteAttack(GameCharacterStatus status)
    {
        // Simulate uploading character's state and downloading a new state
        _characterStatesCache[status.Id] = status;
        var attack = SelectRandomAttack();
        if (CanExecuteAttack(attack))
            ExecuteAttack(attack);
    }

