    {
        // Handle concurrent requests with cancellationToken
        // ...
    }

    private bool TryUpdateGameState()
    {
        if (_lastQueryTime.AddMilliseconds(_queryIntervalMilliseconds) >= DateTimeOffset.UtcNow) return true;

        try
        {
            _characterStatesCache = _gameStateManager.GetCharacterStatuses();
            _lastQueryTime = DateTimeOffset.UtcNow;
        }
        catch (Exception ex)
        {
            _logger.Error(ex, "Failed to query game state.");
            return false;
        }

        return true;
    }

    private GameAttack SelectRandomAttack() => _characterStatesCache.Values
        .SelectMany(s => s.AvailableAttacks)
        .Where(a => a != null)
        .OrderBy(_ => Guid.NewGuid())
        .First();

    private bool CanExecuteAttack(GameAttack attack) => !attack.IsOnCooldown && _characterStatesCache[attack.CharacterId].Health > 0;

    private bool CheckCooldown() => DateTimeOffset.UtcNow - _lastQueryTime >= TimeSpan.FromMilliseconds(_attackCooldownMilliseconds);

    // Implement logging, error handling and performance optimization as needed
}
