const renderCDNScripts = (scripts, userPreferences, deviceCapabilities) => {
  const scriptContainer = document.querySelector('script[data-cdn]');
  if (!scriptContainer) return; // Bail out early if no script container exists

  const scriptElement = document.createElement('script');
  scriptElement.dataset.cdn = true;

  scripts.forEach((scriptObj, index) => {
    if (!scriptObj || !scriptObj.key || typeof scriptObj.code !== 'string') return; // Skip invalid script objects

    scriptElement.src = `https://cdn.example.com/scripts/${scriptObj.key}.js`;
    scriptElement.innerHTML = `// ${scriptObj.key} (CDN fallback)
${scriptObj.code}`;
    scriptElement.id = `cdn-script-${index}`;

    if (userPreferences.conditionalRendering && !deviceCapabilities.supportsScript) {
      scriptElement.style.display = 'none';
    }
  });

  scriptContainer.parentNode.insertBefore(scriptElement, scriptContainer.nextSibling);
};
