        Stopwatch stopwatch = new Stopwatch();
        stopwatch.start();

        long memoryUsageBefore = ManagementFactory.getMemoryMXBean().getHeapMemUsage().getUsed();

        try {
            Stream.iterate(filePaths, this::getNextFileOrReturnEmptyIfEmpty)
                    .parallel()
                    .map(this::processAndTransformFile)
                    .sequential()
                    .forEach(result -> handleResult(result));
        } catch (ConcurrentModificationException e) {
            LOGGER.error("Concurrent modification exception occurred during data processing", e);
        } finally {
            stopwatch.stop();
            long memoryUsageAfter = ManagementFactory.getMemoryMXBean().getHeapMemUsage().getUsed();
            LOGGER.info("Total processing time: {}", stopwatch.elapsed(TimeUnit.MILLISECONDS) + " ms");
            LOGGER.info("Memory usage before processing: {} MB", (memoryUsageBefore / 1024d / 1024d));
            LOGGER.info("Memory usage after processing: {} MB", (memoryUsageAfter / 1024d / 1024d));
        }
    }

