    private void processAndTransformFile(String filePath) {
        try {
            Request request = buildRequest(filePath, getApiFunctionForFileType(getFileTypeFromParameter(filePath)));
            Response response = httpClient.newCall(request).execute();

            getApiFunctionForFileType(getFileTypeFromParameter(filePath)).apply(response);
        } catch (Exception e) {
            LOGGER.error("Error processing file {}: {}", filePath, e.getMessage());
        } finally {
            processingCounter.incrementAndGet();
