#include <vector>

class Context {
public:
    std::string userID;
    std::string operationType;
    std::string timestamp;

    Context(const std::string& user, const std::string& type, const std::string& time)
        : userID(user), operationType(type), timestamp(time) {}
};

class ThreadSafeLog {
public:
    void logOperation(const std::string& message) {
        std::unique_lock<std::mutex> lock(logMutex);
        logMessages.emplace_back(message);
    }

    void printLog() const {
        std::unique_lock<std::mutex> lock(logMutex);
        for (const auto& message : logMessages) {
            std::cout << message << '\n';
        }
        logMessages.clear();
    }

private:
    std::vector<std::string> logMessages;
    std::mutex logMutex;
};

void dynamicDataInsertion(std::forward_list<std::string>& dataList, const std::string& target, const std::string& value, const std::shared_ptr<Context>& context, std::function<void()> callback) {
    auto it = dataList.begin();
    if (it == dataList.end()) {
        throw std::invalid_argument("Data list is empty");
    }

    bool foundTarget = false;
    auto targetPos = dataList.before_begin();
    for (auto itr = dataList.begin(); itr != dataList.end(); ++itr) {
        if (*itr == target) {
            foundTarget = true;
            break;
        }
        targetPos = std::prev(dataList.begin(), itr);
    }

    if (!foundTarget) {
        // Use emplace_after to minimize copying overhead
        dataList.emplace_after(targetPos, value);
    } else {
        // Use swap_if_equal to avoid unnecessary moves or copies
        dataList.swap_if(_Eq(), targetPos, target);
        *targetPos = value;
    }

    if (callback) {
        std::unique_lock<std::mutex> lock(syncMutex);
        callback();
    }

    // Log the operation details in a thread-safe manner
    static ThreadSafeLog log;
    log.logOperation("Inserted " + value + " at position " + std::to_string(std::distance(dataList.begin(), targetPos)));
}

int main() {
    // Initialize the data list and context objects
    std::forward_list<std::string> myDataList = { "apple", "banana", "cat" };
    auto myContext = std::make_shared<Context>("user1", "insertion", "2022-03-01");

    // Perform the dynamic data insertion operation
    dynamicDataInsertion(myDataList, "apple", "orange", myContext);

    // Call a callback function to update external data structures or perform logging in a multi-threaded environment
    auto callback = []() { std::cout << "Performed operation: " + myContext->operationType << '\n'; };
    dynamicDataInsertion(myDataList, "banana", "kiwi", myContext, std::move(callback));

    // Print the updated data list
    for (const auto& item : myDataList) {
        std::cout << item << ' ';
    }

    // Print the log messages
    dynamicDataInsertion::log.printLog();

    return 0;
}
