#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>

// Global variables for thread safety
static pthread_mutex_t aes_context_mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned char global_iv[16] = { 0 }; // IV length of 16 bytes (128 bits)
static unsigned char global_key[32] = { 0 }; // Key length of 32 bytes (256 bits)
static uint8_t global_nonce[12] = { 0 }; // Nonce length of 96 bits, with the first 12 bytes being time-based

AES_KEY aes_context;
EVP_CIPHER_CTX* cipher_ctx;

// Initialize AES-256-GCM context using given password and random IV.
void init_aes_context(const char* passwd) {
    // Derive key from SHA-256 hash of the provided password.
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, passwd, strlen(passwd));
    SHA256_Final(hash, &sha256);

    // Copy the derived key to global_key.
    memcpy(global_key, hash, sizeof(hash));

    // Initialize AES-GCM context with a random IV and nonce based on current time.
    RAND_bytes(global_iv, 16);
    time(&global_nonce[0]);
    global_nonce[1] = (uint8_t)(global_nonce[0] >> 32);
    global_nonce[2] = (uint8_t)(global_nonce[0] >> 24);
    global_nonce[3] = (uint8_t)(global_nonce[0] >> 16);
    global_nonce[4] = (uint8_t)(global_nonce[0] >>  8);
    global_nonce[5] = (uint8_t)(global_nonce[0]);
    global_nonce[6] = (uint8_t)(global_nonce[1] >> 32);
    global_nonce[7] = (uint8_t)(global_nonce[1] >> 24);
    global_nonce[8] = (uint8_t)(global_nonce[1] >> 16);
    global_nonce[9] = (uint8_t)(global_nonce[1] >>  8);
    global_nonce[10] = (uint8_t)(global_nonce[1]);

    AES_set_encrypt_key(global_key, 256, &aes_context);
    EVP_GCM_init(&cipher_ctx, &aes_context, global_iv, global_nonce);
}

// Clean up and disable the AES-256-GCM cipher context.
void cleanup_aes_context() {
    if (cipher_ctx != NULL) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        cipher_ctx = NULL;
        memset(&aes_context, 0, sizeof(AES_KEY));
    }
}
```

This code provides two functions: `init_aes_context()`, which initializes the AES-256-GCM context using a given password and random IV, and `cleanup_aes_context()`, which cleans up and disables the cipher context. The global variables are managed with a mutex to ensure thread safety in a multi-threaded environment.

