using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using StackExchange.Redis;

public class TripleDESDecryptor
{
    private readonly ConnectionMultiplexer _redis;
    private readonly IDatabase _db;

    public TripleDESDecryptor(string redisConnectionString)
    {
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        _db = _redis.GetDatabase();
    }

    public async Task<string> DecryptAsync(string userType, string messageType, string base64EncodedMessage)
    {
        // Implement caching based on cache size, eviction policies, etc.
        var cacheKey = GenerateCacheKey(userType, messageType);
        var cachedMessage = _db.StringGet(cacheKey);

        if (cachedMessage != null)
            return cachedMessage;

        // Implement key and IV selection based on userType and messageType
        var key = GetKey(userType);
        var iv = GetIV(messageType);

        // Use TripleDES to decrypt the message
        using (var tripleDES = TripleDESCryptoServiceProvider.Create())
        {
            tripleDES.Key = key;
            tripleDES.IV = iv;
            var decryptedMessageBytes = Convert.FromBase64String(base64EncodedMessage);
            var decryptor = new ICryptoTransform(tripleDES.CreateDecryptor());
            var decryptedMessage = Encoding.UTF8.GetString(decryptor.TransformFinalBlock(decryptedMessageBytes, 0, decryptedMessageBytes.Length));

            // Implement caching of the decrypted message
            _db.StringSet(cacheKey, decryptedMessage, TimeSpan.FromSeconds(GetCachingDuration(userType, messageType)));

            return decryptedMessage;
        }
    }

    // Implement methods for key and IV selection, caching duration calculation, etc.
}
