typedef struct {
    unsigned int sequence;
    char extension[9];
} LogFormat;

LogFormat logFormats[] = {
    {"log", ".log"},
    {"text", ".txt"},
    {"json", ".json"}
};

const int NUM_LOG_FORMATS = sizeof(logFormats) / sizeof(LogFormat);

char *generateUniqueLogFilename(const char *inputFileName, bool isThreadSafe) {
    static thread_local unsigned long long lastHash = 0; // For concurrent processing
    static thread_local int lastSequence = 0; // For log rotation and thread safety
    const size_t bufferSize = 256;
    char buffer[bufferSize];
    time_t rawtime;
    struct tm *timeinfo;
    unsigned long long currentHash = hash_filename(inputFileName);
    int inputFileNameLength = strlen(inputFileName);

    if (currentHash == lastHash && lastSequence >= 1000) { // Log rotation check
        lastSequence = 0;
    }

    if (!lastHash || currentHash != lastHash || inputFileNameLength != lastHashLength) {
        lastHash = currentHash;
        lastHashLength = inputFileNameLength;
    }

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);

    strftime(buffer, bufferSize - 17, "%Y%m%d_%H%M%S", timeinfo); // Timestamp
    strncat(buffer, "_", bufferSize - strlen(buffer) - 16);

    int baseNameLength = inputFileNameLength;
    if (!strchr(inputFileName, '.')) { // Add default extension based on logFormats[]
        for (int i = 0; i < NUM_LOG_FORMATS; ++i) {
            strncat(buffer + strlen(buffer), logFormats[i].extension, bufferSize - strlen(buffer) - 1);
            if (validatePath(buffer)) break; // Validate the filename and return it if valid
        }
    } else {
        baseNameLength = inputFileNameLength + 1; // Account for extension when calculating unique identifier hash
    }

    char *baseName = malloc(baseNameLength);
    strncpy(baseName, inputFileName, baseNameLength);

    unsigned long long uniqueIdentifierHash = hash_filename(baseName);
    sprintf(buffer + strlen(buffer), "%llu_%05d", uniqueIdentifierHash, lastSequence++);

    free(baseName);

    if (isThreadSafe) {
        pthread_mutex_lock(&mutex); // Add thread safety for this example. Remove in production code.
        strcat(buffer, ""); // Include thread-specific lock information here to support multithreading, if required.
        pthread_mutex_unlock(&mutex);
    }

    return buffer;
}
