                return EXIT_SUCCESS;
            case 'i':
                opt.input_file = optarg;
                break;
            case 'o':
                opt.output_file = optarg;
                break;
            case 'r':
                regcomp(&opt.filter_regex, optarg, REG_EXTENDED | REG_NEWLINE);
                if (regerror(REG_SYNTAXERR, &opt.filter_regex, NULL) == 0) {
