                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                else
                    fprintf(stderr, "Unknown option character `\\x%x'.\n", optopt);
                return EXIT_FAILURE;
            default:
                break; // getopt_long will print an error message
        }
    }

    if (!opt.input_file) {
        fprintf(stderr, "Error: no input file provided.\n");
        return EXIT_FAILURE;
    }

