#include <chrono>
#include <condition_variable>
#include <mutex>
#include <queue>
#include <unordered_map>
#include <thread>
#include "PhysicsEngine.h" // External physics engine API

// Global mutex and condition variable to handle resource contention
std::mutex mtx;
std::condition_variable cv;
std::queue<std::string> positionQueue;

std::chrono::microseconds cooldown = std::chrono::milliseconds(300);

void updatePlayerPosition(const std::string& playerId) {
    // Store the player in a map using the playerId as key
    std::unordered_map<std::string, std::chrono::microseconds> cooldownMap;

    // Lock the mutex to avoid concurrency issues
    std::unique_lock<std::mutex> lock(mtx);

    // Check if the player has waited long enough before updating their position
    auto now = PhysicsEngine::getCurrentTime();
    if (cooldownMap.find(playerId) != cooldownMap.end() && (now - cooldownMap[playerId]) >= cooldown) {
        // Apply user input and environmental factors to the player's position
        // Use the physics engine's API to apply forces, etc.
        PhysicsEngine::applyForces(playerId);

        // Update the cooldown time for this player
        cooldownMap[playerId] = now;
    } else {
        // If the cooldown period hasn't elapsed yet, add the player to a queue to process later
        positionQueue.push(playerId);
    }

    // Notify other threads that there are updates in the queue
    cv.notify_one();
}

// Thread function to process updates from the position queue when needed
void processUpdates() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [] { return !positionQueue.empty(); });

        if (!positionQueue.empty()) {
            auto playerId = positionQueue.front();
            positionQueue.pop();

            // Process the update for this player here
            updatePlayerPosition(playerId);
        }
    }
}
