void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    pthread_mutex_lock(&log_mutex);
    vfprintf(log_file, format, args);
    fputc('\n', log_file);
    pthread_mutex_unlock(&log_mutex);
}

char *expandStringWithSlash(const char *input, size_t limit) {
    if (!input) {
        log_message("Error: input is NULL");
        return NULL;
    }

    // Trim trailing whitespace and calculate the string length
    size_t len = strspn(input, " \t\r\n\f\v");
    if (len >= limit) {
        log_message("Error: String exceeds limit");
        free((char *)input); // Free input buffer if it was allocated dynamically
        return NULL;
    }

    char *output = malloc(len + 2); // Allocate memory for the string and separator
    if (!output) {
        log_message("Error: Memory allocation failure");
        free((char *)input); // Free input buffer if it was allocated dynamically
        return NULL;
    }

    strncpy(output, input, len + 1); // Copy the input string to the output buffer
    output[len] = '/'; // Append the separator to the end of the string
    output[len + 1] = '\0'; // Null-terminate the string

    return output;
}

// Customize the separator using a configuration system here...
