    size_t limit = 5; // Set the size limit at runtime using a configuration system here...

    for (int i = 0; i < sizeof(test_strings) / sizeof(char *); ++i) {
        char *str = expandStringWithSlash(test_strings[i], limit);
        if (!str) {
            log_message("Error: Failed to allocate memory for test string %d", i);
            continue;
        }
        log_message("Successfully expanded string %d: %s", i, str);
        free_and_log(str);
    }

