// Configuration options
const config = {
  directory: '', // Directory to read files from
  encoding: 'utf8', // File content encoding (default: utf-8)
  concurrentLimit: 100, // Maximum number of concurrent file reads (default: 100)
  extensions: ['.txt'], // File extensions to process (default: .txt)
  ignorePatterns: [] // Patterns to ignore when finding files (e.g., 'node_modules/**')
};

// Helper functions
async function readFile(filePath, encoding) {
  try {
    return await fs.readFile(filePath, encoding);
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error);
  }
}

function isSupportedEncoding(encoding) {
  // Add your encoding validation logic here
  return true;
}

// Main function
async function concatenateFiles(options) {
  Object.assign(config, options);

  if (!isSupportedDirectory(config.directory)) {
    console.error(`Invalid directory path: ${config.directory}`);
    process.exit(1);
  }

  const filesToProcess = findFiles(config.directory, config.extensions, config.ignorePatterns);

  if (filesToProcess.length === 0) {
    console.log('No files found to process.');
    process.exit(0);
  }

  let combinedText = '';
  const concurrentLimiter = new Limiter(config.concurrentLimit);

  function handleFile(filePath) {
    concurrentLimiter.acquire(() => {
      readFile(filePath, config.encoding).then((content) => {
        combinedText += content;
        concurrentLimiter.release();
      });
    });
  }

  const watcher = chokidar.watch(config.directory, { persistent: true });

  // Process files immediately and monitor for new ones while watching the directory
  processFiles(filesToProcess);

  watcher.on('add', (filePath) => {
    if (isSupportedFile(filePath, config.extensions)) {
      combinedText += readFile(filePath, config.encoding).then((content) => content);
    }
  });

  function processFiles(filesArray) {
    if (filesArray.length === 0) return;

    concurrently([...filesArray].map((filePath) => handleFile(filePath))).catch((error) => {
      console.error('Error while processing files:', error);
      process.exit(1);
    });
  }

  async function findFiles(directory, extensions, ignorePatterns) {
    return glob.sync(`${directory}/**/*{${extensions.join(',')}}`, { ignore: ignorePatterns });
  }

  function isSupportedDirectory(directory) {
    // Add your directory validation logic here
    return fs.existsSync(directory);
  }

  function isSupportedFile(filePath, extensions) {
    const fileExtension = path.extname(filePath).toLowerCase();
    return extensions.includes(fileExtension);
  }
}

// Custom concurrent task runner with rate limiting (Limiter class)
class Limiter {
  constructor(limit) {
    this.queue = [];
    this.waiting = limit;
  }

  acquire(callback) {
    if (this.waiting > 0) {
      --this.waiting;
      callback();
      return;
    }

    this.queue.push(callback);
    setTimeout(() => {
      this.queue[0]();
      this.queue.shift();

      if (this.queue.length > 0) {
        this.waiting++;
      } else {
        this.waiting = Math.min(this.limit, this.queue.length);
      }
    }, 10);
  }

  release() {
    ++this.waiting;
  }
}
```

