package com.mycompany.userdata;

import redis.clients.jedis.Jedis;
import org.codehaus.jackson.map.ObjectMapper;
import java.io.IOException;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import com.datastax.driver.core.Cluster;
import com.datastax.driver.core.ResultSet;
import com.datastax.driver.core.Row;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class UserDataService {
    private static final Logger LOGGER = LoggerFactory.getLogger(UserDataService.class);
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final int MAX_CONCURRENT_REQUESTS = 1000;
    private static final long CACHE_EXPIRATION_TIME_MS = 60 * 60 * 24; // 1 day

    private final Cluster cassandraCluster;
    private final Jedis redisClient;

    public UserDataService() {
        // Initialize Cassandra and Redis connections here
    }

    public Future<UserData> getUserData(String userId, long timestamp) throws InterruptedException, ExecutionException, IOException {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
        Callable<UserData> callable = () -> fetchAndDeserializeDataFromCassandraAndCache(userId, timestamp);
        Future<UserData> future = executor.submit(callable);
        return future;
    }

    private UserData fetchAndDeserializeDataFromCassandraAndCache(String userId, long timestamp) throws IOException {
        // Fetch serialized byte array from Cassandra
        Row row = cassandraCluster.execute("SELECT data FROM user_data WHERE user_id = ? AND timestamp = ?", userId, timestamp).one();
        if (row == null || row.getUUID("data") == null) {
            throw new DeserializationException(ErrorCodes.DATA_RETRIEVAL_FAILURE);
        }

        // Deserialize byte array to UserData instance
        try {
            return mapper.treeToValue(mapper.readTree(row.getUUID("data")), UserData.class);
        } catch (Exception e) {
            throw new DeserializationException(ErrorCodes.DESERIALIZATION_FAILURE, e);
        }
    }

    private void cacheUserDataInRedis(String userId, UserData userData) {
        // Cache deserialized instance in Redis with a TTL of 1 day
        redisClient.setex(userId, CACHE_EXPIRATION_TIME_MS, mapper.writeValueAsBytes(userData));
    }

    private void logErrorAndUpdateCacheIfNeeded(String userId, DeserializationException exception) {
        // Log error message
        LOGGER.error("Error deserializing user data for {}", userId, exception);

        // If the cache contains a valid instance for this user ID and timestamp, update it with an empty or invalid object to trigger re-deserialization on next request
        redisClient.set(userId, "");
    }
}
