    try:
        response = requests.get(api_url)
        if response.status_code == 200:
            language_list = [lang['name'] for lang in response.json()]
        else:
            logging.error(f"Error fetching programming languages from API: {response.reason}")
            return {}
    except Exception as e:
        logging.error(f"Error fetching programming languages from API: {e}")
        return {}

    # Combine the predefined regex patterns and the new list of programming languages
    regex = re.compile('|'.join([regex_programming_languages[lang] for lang in language_list]), re.IGNORECASE)

    matches = []
    for match in regex.findall(text):
        if match.lower() not in stopwords:  # Filter out common words
            if match in text.split():  # Check if the word is a whole word (not part of another word)
                matches.append(match)

    freq_dict = defaultdict(int)
    for word in matches:
        freq_dict[word] += 1
    return dict(freq_dict)

