public:
    void log(const std::string& message) {
        std::unique_lock<std::mutex> lock(log_mutex_);
        if (!logging_) {
            return; // Skip logging if logging is disabled
        }
        log_buffer_ << message << std::endl;
        lock.unlock();
        cv_.notify_one();
