async function resizeImage(req, res, next) {
  try {
    // Extract image details and resize parameters from request

    const originalUrl = req.file.originalname;
    const { width, height } = req.body;

    let cachedResizedImage = cacheManager.get(`${width}x${height}_${originalUrl}`);

    if (cachedResizedImage) { // Serve from cache if available
      res.send(cachedResizedImage);
    } else {
      const resizedBuffer = await sharp(req.file.path)
        .resize(width, height)
        .toBuffer();

      cacheManager.set(`${width}x${height}_${originalUrl}`, resizedBuffer); // Cache the resized image

      res.send(resizedBuffer);
    }
  } catch (error) {
    console.error(error);
    next(error);
  }
}
