        self.api_client = api_client
        self.metadata_key = metadata_key
        self.metadata_value = metadata_value
        self.today = datetime.now().date()
        self.last_updated = {os.path.join(self.directory_path, file): self.today for file in os.listdir(self.directory_path)}

    def update_file_metadata_threaded(self):
        with ThreadPoolExecutor(max_workers=5) as executor:
            for file in os.listdir(self.directory_path):
                if not file.endswith('.meta'):
                    file_path = os.path.join(self.directory_path, file)
                    if file not in self.last_updated or self.today != self.last_updated[file]:
                        self.last_updated[file] = self.today
                        executor.submit(self.api_client.update_file_metadata, file_path, self.metadata_key, self.metadata_value)

    def run(self):
        try:
            self.update_file_metadata_threaded()
        except Exception as e:
            print(f'Error: {e}')

if __name__ == "__main__":
