#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <string.h>
#include <ctype.h>
#include <stdarg.h>
#include <signal.h>

// Configuration file parsing and command validation functions (not included)

typedef struct {
    char *command;
    int timeout, retries;
} Command;

struct log_data {
    FILE *file;
    char buffer[4096];
};

void log(const char *fmt, ...) {
    va_list args;
    struct log_data data = {stderr, {0}};
    va_start(args, fmt);
    vsnprintf(data.buffer, sizeof(data.buffer), fmt, args);
    va_end(args);
    fputs(data.buffer, data.file);
}

void exec_command(Command cmd) {
    pid_t pid = fork();
    if (pid == 0) { // child process
        execv(cmd.command, (char*[]){cmd.command, NULL});
        log("Error: Failed to execute command %s\n", cmd.command);
        exit(1);
    } else if (pid > 0) { // parent process
        struct timespec wait_time = {cmd.timeout * 1e9, 0};
        clock_gettime(CLOCK_MONOTONIC, &wait_time);
        while (!WIFEXITED(waitpid(pid, NULL, WNOHANG)) && (clock_gettime(CLOCK_MONOTONIC, &wait_time) - wait_time).tv_sec < cmd.timeout) {}
        if (WIFSIGNALED(waitpid(pid, NULL, 0))) {
            log("Error: Command %s exited with signal %d\n", cmd.command, WTERMSIG(waitpid(pid, NULL, 0)));
        } else if (WEXITSTATUS(waitpid(pid, NULL, 0)) != 0) {
            int retries_left = cmd.retries;
            while (retries_left > 0) {
                log("Retrying command %s due to failure\n", cmd.command);
                execv(cmd.command, (char*[]){cmd.command, NULL});
                sleep(1); // Add a delay between retries
                --retries_left;
            }
            log("Error: Command %s failed after all retries\n", cmd.command);
        } else {
            log("Command %s executed successfully\n", cmd.command);
        }
    } else { // fork() failure
        perror("Error: Failed to fork");
    }
}

int main(int argc, char **argv) {
    Command *commands;
    int commands_count = parse_config(argc > 1 ? argv[1] : "config.txt", &commands_count, &commands);
    if (commands_count <= 0 || !commands) return 1;

    signal(SIGINT, SIG_IGN); // Ignore interrupt signals (e.g., Ctrl+C)

    for (int i = 0; i < commands_count; ++i) {
        exec_command(commands[i]);
    }

    free(commands);
    return 0;
}
