async function readDirectory(directoryPath, extensions, credentials, callback) {
  let files = [];
  const walker = fs.createReadStream(directoryPath, { encoding: 'utf8' });

  walker.on('data', async (fileData) => {
    if (path.extname(fileData) === `.${extensions.join('.')}`) {
      try {
        const stats = await fs.stat(fileData);
        files.push({
          path: fileData,
          size: stats.size,
          lastModified: stats.mtimeMs,
          // Add more metadata as needed
        });
      } catch (err) {
        console.error(`Error reading file ${fileData}:`, err);
      }
    }
  });

  walker.on('end', async () => {
    try {
      await db.logReadOperation(files);
      callback(null, files);
    } catch (err) {
      console.error(`Error logging operation:`, err);
      callback(err);
    }
  });

  walker.on('error', (err) => {
    console.error(`Error reading directory ${directoryPath}:`, err);
    callback(err);
  });
}

