    [ApiController]
    public class DecryptionController : ControllerBase
    {
        private readonly ILogger<DecryptionController> _logger;
        private readonly IDictionary<string, (byte[] Key, byte[] Iv)> _userKeysAndIvs;

        public DecryptionController(ILogger<DecryptionController> logger, UserKeyAndIVManager userKeyAndIVManager)
        {
            _logger = logger;
            _userKeysAndIvs = userKeyAndIVManager.UserKeysAndIvs;
        }

        [HttpPost]
        public async Task<IActionResult> Decrypt(DecryptRequest request)
        {
            if (!_userKeysAndIvs.TryGetValue(request.UserId, out var (key, iv)))
            {
                _logger.LogError("User not found: {UserId}", request.UserId);
                return BadRequest("User not found");
            }

            try
            {
                using (var aes = AES.Create())
                {
                    aes.Key = key;
                    aes.IV = iv;

                    var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
                    var cryptoServiceProvider = new ICryptoTransformWrapper(decryptor);

                    using (var ms = new MemoryStream(request.Ciphertext))
                    {
                        using (var cs = new CryptoStream(ms, cryptoServiceProvider, CryptoStreamMode.Read))
                        {
                            var decryptedPlaintext = new byte[cs.ReadAllBytes().LongLength];
                            cs.Read(decryptedPlaintext, 0, decryptedPlaintext.Length);

                            return Ok(decryptedPlaintext);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to decrypt data for user: {UserId}", request.UserId);
                return StatusCode(StatusCodes.Status500InternalServerError);
            }
        }
    }

    public class DecryptRequest
    {
        [JsonProperty("userId")]
        public string UserId { get; set; }

        [JsonProperty("ciphertext")]
        public byte[] Ciphertext { get; set; }
    }
}
