            var encryptedPlaintext = Encoding.UTF8.GetBytes("Test data");
            var ciphertextWithPadding = PadToBlockSize(encryptedPlaintext, AES.Create().BlockSize);

            // Modify the key in userKeysAndIvs for the TestUser
            userKeysAndIvs["TestUser"] = (new byte[] {1,2,3}, new byte[] {4,5,6,7});

            var request = new DecryptRequest { UserId = "TestUser", Ciphertext = ciphertextWithPadding };

            // Act
            var result = decryptionController.Decrypt(request).Result;

            // Assert
            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int) StatusCodes.Status500InternalServerError, ((StatusCodeResult)result).StatusCode);
        }

        private byte[] PadToBlockSize(byte[] plaintext, int blockSize)
        {
            var padding = blockSize - (plaintext.Length % blockSize);
            return plaintext.Concat(new byte[padding]).ToArray();
        }
