use std::io::{Read, Write};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Instant;

struct Logger {
    log_mutex: Arc<Mutex<()>>,
    log_func: Box<dyn Fn(&String)>,
}

impl Logger {
    fn new(log_func: Box<dyn Fn(&String)> ) -> Self {
        Self {
            log_mutex: Arc::new(Mutex::new(())),
            log_func,
        }
    }

    fn log(&self, msg: &str) {
        let mut guard = self.log_mutex.lock().unwrap();
        (self.log_func)(msg);
    }
}

fn copy_buffers(
    input_chunks: Vec<&[u8]>,
    output_buf: &mut Vec<u8>,
    logger: &Logger,
) -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();

    // Create a pool of worker threads that perform the copying task concurrently.
    let num_workers = std::thread::available_parallelism() * 2;
    let worker_count = Arc::new(AtomicUsize::new(0));

    let mut workers = Vec::with_capacity(num_workers);
    for _ in 0..num_workers {
        let output_buf_clone = output_buf.clone();
        let input_chunks_clone = input_chunks.clone();
        let logger_clone = logger.clone();
        workers.push(thread::spawn(move || {
            worker(output_buf_clone, &input_chunks_clone, logger_clone)
        }));
    }

    for worker in workers {
        worker.join().unwrap();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let memory_usage = rss(); // Replace this with your preferred method to measure memory usage
    logger.log(&format!("Copying completed in {}s, Memory Usage: {}", elapsed, memory_usage));

    Ok(())
}

fn worker(output_buf: Vec<u8>, input_chunks: &[&[u8]], logger: Logger) {
    let mut output_buf_mutex = output_buf.lock().unwrap();
    for chunk in input_chunks {
        // Ensure the buffer has enough space to copy the data.
        if output_buf_mutex.len() + chunk.len() > output_buf.capacity() {
            logger.log("Buffer overflow error: increase buffer capacity.");
            return;
        }

        // Copy the data and check for errors
        output_buf_mutex.extend_from_slice(chunk);
    }
}

fn rss() -> usize {
    // Replace this function with your preferred method to measure memory usage.
    0
}
