    if (fileContent.length > 0) {
      // Apply user-defined merge criteria here
      const processedContent = applyMergeCriteria(fileContent, config.mergeCriteria);
      return { content: processedContent, metadata };
    }
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error);
    // Store error information in the metadata system if needed
