```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.Pkcs5;

public byte[] DecryptAES_CBC(string ciphertext, string keyBase64, string ivBase64)
{
    var key = Convert.FromBase64String(keyBase64);
    var iv = Convert.FromBase64String(ivBase64);

    var aesAlg = AES.Create();
    aesAlg.Key = key;
    aesAlg.IV = iv;

    var paddedCiphertext = ciphertext switch
    {
        _ when IsPKCS7Padding(ciphertext) => RemovePKCS7Padding(ciphertext),
        _ when IsPKCS5Padding(ciphertext) => RemovePKCS5Padding(ciphertext),
        _ => ciphertext
    };

    byte[] decryptedData;
    MemoryStream memoryStream = new MemoryStream(paddedCiphertext);
    CryptoStream cryptoStream = new CryptoStream(memoryStream, aesAlg.CreateDecryptor(), CryptoStreamMode.Read);
    decryptedData = new byte[cryptoStream.ReadAllBytes().Length];
    cryptoStream.Read(decryptedData, 0, decryptedData.Length);

    return decryptedData;

    bool IsPKCS7Padding(string ciphertext) => ciphertext.Length % aesAlg.BlockSize > 0;
    byte[] RemovePKCS7Padding(string ciphertext) => ciphertext.Remove(ciphertext.Length - (ciphertext[^1] - (byte)'0'));
    byte[] RemovePKCS5Padding(string ciphertext) => Pkcs5Padding.Unpad(Convert.FromBase64String(ciphertext), aesAlg.BlockSize);
}

