#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <json/json.h>
#include <spdlog/spdlog>
#include <boost/filesystem.hpp>
#include <boost/program_options.hpp>

namespace po = boost::program_options;
namespace fs = boost::filesystem;

struct LogConfig {
    std::string level;
    std::string format;
    int rotation_size;
    int rotation_age;
    std::string output_directory;
};

LogConfig read_config(const std::string& path) {
    Json::CharReaderBuilder builder;
    Json::CharReader* reader = builder.newCharReader();
    Json::Value root;
    std::string errs;
    bool parsing_successful = reader->parse(path.c_str(), &root, &errs);
    delete reader;
    if (!parsing_successful) {
        std::cerr << "Error reading config file: " << errs << std::endl;
        throw std::runtime_error("Failed to parse configuration");
    }

    LogConfig config;
    config.level = root["logLevel"].asString();
    config.format = root["format"].asString();
    config.rotation_size = root["rotationSize"].asInt();
    config.rotation_age = root["rotationAge"].asInt();
    config.output_directory = root["outputDirectory"].asString();
    return config;
}

void log_init(const LogConfig& config) {
    spdlog::set_pattern("%^[%T] [%n] %v%$");

    auto flags = spdlog::color_mode::always;
    if (config.level == "DEBUG") {
        flags |= spdlog::color_mode::debug;
    } else if (config.level == "INFO") {
        flags |= spdlog::color_mode::info;
    } else if (config.level == "WARNING") {
        flags |= spdlog::color_mode::warn;
    } else if (config.level == "ERROR") {
        flags |= spdlog::color_mode::err;
    }

    spdlog::set_level(flags);

    auto logger = spdlog::rotating_logger_mt("logger", config.format,
                                            config.rotation_size, config.rotation_age,
                                            config.output_directory);
}

void print_usage() {
    std::cout << "Usage: myapp [options]\n"
              << "Options:\n"
              << "  --help         Display this help message\n"
              << "  -c path        Path to the JSON configuration file\n"
              << "  -l level       Log level (DEBUG, INFO, WARNING, ERROR)\n"
              << "  -f filename    Log file name\n"
              << "  -o directory   Output directory for log files\n";
}

int main(int argc, char* argv[]) {
    po::options_description desc("Options");
    desc.add_options()
        ("help", "Display this help message")
        ("c,config", po::value<std::string>(), "Path to the JSON configuration file")
        ("l,level", po::value<std::string>(), "Log level (DEBUG, INFO, WARNING, ERROR)")
        ("f,filename", po::value<std::string>(), "Log file name")
        ("o,output-directory", po::value<std::string>(), "Output directory for log files");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        print_usage();
        return 0;
    }

    std::string config_path;
    std::string log_level;
    std::string log_filename;
    std::string output_directory;

    try {
        if (vm.count("config")) {
            config_path = vm["config"].as<std::string>();
        } else {
            throw std::runtime_error("Missing JSON configuration file");
        }

        if (vm.count("level")) {
            log_level = vm["level"].as<std::string>();
        } else {
            throw std::runtime_error("Missing log level");
        }

        if (!fs::exists(config_path)) {
            std::cerr << "Error: Configuration file not found" << std::endl;
            print_usage();
            return 1;
        }

        // Add more checks for optional options here
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        print_usage();
        return 1;
    }

    LogConfig config = read_config(config_path);
    log_init(config);

    // Main program logic here

    return 0;
}
