                    comments.append(&mut extracted_comments);
                }
            } else {
                return Err("Failed to read file".to_string());
            }
        }

        // Generate documentation.
        let generated_doc = self.config.documentation_generator.generate(comments)?;

        // Write the generated documentation to the output directory.
        for (i, doc) in generated_doc {
            if let Err(e) = std::fs::write(self.config.output_format.template_file.join(&i), &doc) {
                return Err(format!("Failed to write documentation: {}", e));
            }
        }

        Ok(())
    }
