#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <iconv.h>
#include <time.h>

typedef struct {
    char *email;
    int id;
} EmailThreadData;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static iconv_t encoding;

void validateEmail(const char *email, FILE *fd) {
    size_t domain_start = strcspn(email, "@");
    if (domain_start >= 1 + strlen(email)) {
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "%lu: Error: Invalid email format - no '@' symbol found\n", time(NULL));
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    size_t maxLen = 256; // Adjust this value as needed for your specific requirements
    if (strlen(email) > maxLen) {
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "%lu: Error: Email exceeds maximum length limit\n", time(NULL));
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    size_t at_count = 1 + strcspn(email, "@"); // Count the number of '@' symbols in the email address
    if (at_count != 1) {
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "%lu: Error: More than one '@' symbol found\n", time(NULL));
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    // Add code to handle internationalized domain names and different character encodings here.
}

void* validateEmailThread(void *data) {
    EmailThreadData *thread_data = data;
    validateEmail(thread_data->email, stderr);
    free(thread_data->email);
    free(thread_data);
    return NULL;
}

void validateEmailBatch(const char *emailBatch[], int batchSize, FILE *fd, size_t maxLen) {
    if (!emailBatch || batchSize < 0) {
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Invalid arguments passed to validateEmailBatch\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    iconv_t conv = encoding;
    size_t needed = 0;
    char *inputBuffer = malloc(2 * maxLen); // Adjust this value as needed for your specific requirements
    if (!inputBuffer) {
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Out of memory\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    iconv_t tmp_encoding = iconv_open("UTF-8", NULL);
    if (tmp_encoding == (iconv_t) -1) {
        free(inputBuffer);
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Unable to open UTF-8 encoding\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }
    conv = tmp_encoding;

    pthread_t *threads = malloc(batchSize * sizeof(pthread_t));
    if (!threads) {
        iconv_close(conv);
        free(inputBuffer);
        pthread_mutex_lock(&log_mutex);
        fprintf(fd, "Error: Out of memory\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    for (int i = 0; i < batchSize; ++i) {
        char *email = strtok(emailBatch[i], "\n");
        if (!email) continue;

        EmailThreadData *thread_data = malloc(sizeof(EmailThreadData));
        if (!thread_data) {
            iconv_close(conv);
            free(inputBuffer);
            free(threads);
            pthread_mutex_lock(&log_mutex);
            fprintf(fd, "Error: Out of memory\n");
            pthread_mutex_unlock(&log_mutex);
            return;
        }

        size_t readSize = iconv(conv, &const_cast<char**>(&email), &needed, &inputBuffer, &needed);
        if (readSize == (size_t)-1) {
            free(thread_data->email);
            free(thread_data);
            continue;
        }

        thread_data->email = inputBuffer;
        thread_data->id = i;
        pthread_create(&threads[i], NULL, validateEmailThread, thread_data);
    }

    for (int i = 0; i < batchSize; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
    iconv_close(conv);
    free(inputBuffer);
}
