```cpp
#include <iostream>
#include <vector>
#include <string>
#include <map>
#include <list>
#include <chrono>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <mutex>

class NetworkResolver {
public:
    using IPAddressList = std::vector<std::string>;

    NetworkResolver() : timeout_(10) {}

    void setTimeout(int seconds) {
        timeout_ = seconds;
    }

    IPAddressList resolve(const std::string& hostname) {
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;     // AF_INET6 to force IPv6 resolution if available
        hints.ai_socktype = SOCK_STREAM;

        int status;
        if ((status = getaddrinfo(hostname.c_str(), nullptr, &hints, &res)) != 0) {
            std::cerr << "getaddrinfo: " << gai_strerror(status) << '\n';
            return {};
        }

        IPAddressList addresses;
        for (struct addrinfo *p = res; p != nullptr; p = p->ai_next) {
            char ipstr[INET6_ADDRSTRLEN];
            void* address;
            socklen_t size;

            if (p->ai_family == AF_INET) {
                address = &((struct sockaddr_in*)p->ai_addr)->sin_addr;
                size = sizeof(sockaddr_in);
            } else { // AF_INET6
                address = &((struct sockaddr_in6*)p->ai_addr)->sin6_addr;
                size = sizeof(sockaddr_in6);
            }

            inet_ntop(p->ai_family, address, ipstr, sizeof(ipstr));
            addresses.push_back(ipstr);
        }
        freeaddrinfo(res);

        std::mutex mtx;
        auto it = cachedResolutions_.find(hostname);
        if (it != cachedResolutions_.end() && std::chrono::steady_clock::now() - it->second.timestamp < std::chrono::seconds(timeout_)) {
            return it->second.addresses;
        }

        mtx.lock();
        if (cachedResolutions_.find(hostname) == cachedResolutions_.end()) {
            cachedResolutions_[hostname] = {std::chrono::steady_clock::now(), addresses};
        }
        mtx.unlock();

        return addresses;
    }

private:
    struct ResolutionCacheEntry {
        std::chrono::steady_clock::time_point timestamp;
        IPAddressList addresses;
    };

    int timeout_;
    std::map<std::string, ResolutionCacheEntry> cachedResolutions_;
};
```

