let refreshOperations = {};

function refreshDialogFields(resourceId, url, fields) {
    if (!_.isArray(fields)) {
        throw new Error('Fields must be an array');
    }

    const operationKey = resourceId + '-' + url;

    if (refreshOperations[operationKey]) {
        // If an operation is already in progress, return early to prevent multiple requests
        return refreshOperations[operationKey].promise;
    }

    let operation = {
        promise: null,
        timeoutId: null,
        retryCount: 0
    };

    operation.promise = axios.all(fields.map(field => {
        return axios.get(`${url}/${resourceId}/${field}`)
            .then((response) => {
                // Update the dialog field with the new value
                updateField(field, response.data);

                // Reset retry count and clear timeout on success
                operation.retryCount = 0;
                clearTimeout(operation.timeoutId);
            })
            .catch((error) => {
                handleError(error, field, url, resourceId);
            });
    }))
    .then(() => {
        // Clear the operation once all requests are complete or an error occurs
        delete refreshOperations[operationKey];
    })
    .catch((allErrors) => {
        handleError(allErrors[0], null, url, resourceId);
    });

    // Set a timeout to retry the request if it fails due to network issues
    operation.timeoutId = setTimeout(() => {
        if (operation.retryCount < 3) {
            operation.retryCount++;
            refreshDialogFields(resourceId, url, fields);
        } else {
            handleError({message: 'Max retries reached'}, null, url, resourceId);
        }
    }, 5000); // Retry after 5 seconds

    // Store the operation in a map for concurrent refresh handling
    refreshOperations[operationKey] = operation;

    return operation.promise;
}

function updateField(field, value) {
    // Update the dialog field with the new value. This function should be provided by your application's UI library
}

function handleError(error, field, url, resourceId) {
    const errorMessage = getErrorMessage(error);

    logger.error(`Refresh failed for resource ID ${resourceId}, URL ${url}, Field ${field}: ${errorMessage}`);

    // Show a user-friendly message and suggest potential solutions based on the error message
    showErrorMessage(errorMessage);
}

function getErrorMessage(error) {
    if (error.response && error.response.status === 429) {
        return 'The server is temporarily unable to handle the request due to a high load. Try again later.';
    } else {
        return error.message || JSON.stringify(error);
    }
}

function showErrorMessage(message) {
    // Display an error message to the user based on the provided message. This function should be provided by your application's UI library
}
