```c
#include <tiffio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    char compression;
    int image_width;
    int image_height;
    const char* color_profile;
} TiffMetadata;

TiffMetadata ParseTIFFImage(const char *filename)
{
    TIFF *tif = TIFFOpen(filename, "r");
    if (!tif) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    TiffMetadata metadata;

    // Extract image metadata
    metadata.bits_per_sample = TIFFGetField(tif, TIFTAG_SAMPLESPERPIXEL);
    if (metadata.bits_per_sample != 1 && metadata.bits_per_sample != 2 &&
        metadata.bits_per_sample != 4 && metadata.bits_per_sample != 8 &&
        metadata.bits_per_sample != 16) {
        fprintf(stderr, "Unsupported bits per sample\n");
        exit(EXIT_FAILURE);
    }

    metadata.sample_per_pixel = TIFFGetField(tif, TIFTAG_SAMPLESPERPIXEL);

    // Handle compression method support and dimensions here
    metadata.compression = TIFFGetField(tif, TIFTAG_COMPRESSION);
    metadata.image_width = TIFFGetField(tif, TIFTAG_IMAGEWIDTH);
    metadata.image_height = TIFFGetField(tif, TIFTAG_IMAGELENGTH);

    // Extract color profile from the image and store it as a string
    const char *cp = TIFFGetFieldDescription(TIFFGetField(tif, TIFTAG_COLORSPACE));
    metadata.color_profile = strdup(cp);

    TIFClose(tif);
    return metadata;
}
```

