```python
import sys
import time
import heapq
from unionfind import UnionFind
import requests

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size))
        self.rank = [1] * size

    def find(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)

        if root_x == root_y:
            return

        if self.rank[root_x] < self.rank[root_y]:
            self.parent[root_x] = root_y
            self.rank[root_y] += self.rank[root_x]
        else:
            self.parent[root_y] = root_x
            self.rank[root_x] += self.rank[root_y]

def disjoint_pairs(lst):
    if not isinstance(lst, list) or any(not isinstance(i, int) for i in lst):
        return None

    uf = UnionFind(len(lst))
    pairs = 0

    for i in range(len(lst)):
        for j in range(i+1, len(lst)):
            start_time = time.time()
            uf.union(lst[i], lst[j])
            elapsed_time = (time.time() - start_time) * 1000
            # Assuming you have an API for validation, replace 'url' with the actual API URL
            response = requests.post('http://your-api-url', json={'pair': (i, j), 'elapsed_time': elapsed_time})
            if response.status_code == 200:
                pairs += 1

    return pairs

def save_log(data, filename='log.txt'):
    with open(filename, 'w') as f:
        for key, value in data.items():
            f.write(f'{key}: {value}\n')
```

