using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using NLog;

namespace GameEngine.Services
{
    public class DynamicGameCharacterService
    {
        private readonly IGameStateManager _gameStateManager;
        private readonly Logger _logger;
        private readonly ConcurrentDictionary<string, TimeSpan> _cooldowns;
        private readonly AttackStrategyProvider _attackStrategyProvider;

        public DynamicGameCharacterService(IGameStateManager gameStateManager, IConfiguration configuration)
        {
            _gameStateManager = gameStateManager;
            _logger = LogManager.GetLogger("DynamicGameCharacterService");
            _cooldowns = new ConcurrentDictionary<string, TimeSpan>();
            _attackStrategyProvider = new AttackStrategyProvider(configuration);
        }

        public async Task ExecuteAttackAsync(string characterId)
        {
            if (!_gameStateManager.IsValidGameState())
            {
                throw new InvalidOperationException("Invalid game state.");
            }

            var currentTime = _gameStateManager.GetCurrentTime();
            var attackStrategy = GetAttackStrategy(characterId);

            var canExecuteAttack = attackStrategy.Cooldown.IsExpired(currentTime) || !_cooldowns.ContainsKey(characterId);

            if (canExecuteAttack)
            {
                _logger.Info($"Character {characterId} executing attack.");

                var result = await attackStrategy.ExecuteAsync(_gameStateManager);

                if (!result.Success)
                {
                    _logger.Error($"Failed to execute attack for character {characterId}: {result.Message}");
                }

                _cooldowns[characterId] = attackStrategy.Cooldown;
            }
            else
            {
                _logger.Info($"Character {characterId} cannot execute attack due to cooldown.");
            }
        }

        private AttackStrategy GetAttackStrategy(string characterId)
        {
            var configuration = new ConfigurationBuilder()
                .SetBasePath(AppContext.BaseDirectory)
                .AddJsonFile("appsettings.json")
                .Build();

            var attackStrategyName = configuration[$"Characters:{characterId}:AttackStrategy"] ?? "Default";
            return _attackStrategyProvider[attackStrategyName];
        }
    }
}
