public class RestClient {
    private static final Logger LOGGER = LogManager.getLogger(RestClient.class);
    private static final String CONFIG_FILE_PATH = "config.properties";

    private final HttpClientBuilder clientBuilder;
    private final LoadingCache<String, String> accessTokenCache;
    private final CacheLoader<String, String> tokenLoader;
    private final ExecutorService executor;
    private final RateLimiter rateLimiter;

    public RestClient() {
        Properties props = new Properties();
        try (FileInputStream fis = new FileInputStream(CONFIG_FILE_PATH)) {
            props.load(fis);
        } catch (IOException e) {
            LOGGER.error("Error loading configuration file", e);
        }

        SSLContext sslContext = createSSLContext(props);
        PoolingHttpClientConnectionManager cm = new PoolingHttpClientConnectionManager(sslContext);
        cm.setTcpNoDelay(true);

        HttpHost baseUrl = HttpHost.create(props.getProperty("baseUrl"));
        RequestConfig requestConfig = RequestConfig.custom()
                .setConnectTimeout(5000)
                .setConnectionRequestTimeout(5000)
                .setSocketTimeout(5000)
                .build();

        clientBuilder = HttpClients.custom()
                .setSSLSocketFactory(cm.getSSLConnectionSocketFactory())
                .setDefaultRequestConfig(requestConfig)
                .setRetryHandler(new DefaultHttpRequestRetryHandler(3, false))
                .setProxy(null);

        accessTokenCache = CacheBuilder.newBuilder()
                .maximumSize(100)
                .expireAfterAccess(5, TimeUnit.MINUTES)
                .build(tokenLoader);

        executor = Executors.newFixedThreadPool(10);
        rateLimiter = RateLimiter.create(1.0 / Double.parseDouble(props.getProperty("rateLimit")));
    }

    private SSLContext createSSLContext(Properties props) {
        // Load trust store and key store properties
        String trustStorePath = props.getProperty("trustStorePath");
        String trustStorePassword = props.getProperty("trustStorePassword");
        String keyStorePath = props.getProperty("keyStorePath");
        String keyStorePassword = props.getProperty("keyStorePassword");

        // Initialize SSLContext and TrustManagerFactory/KeyManagerFactory
        try {
            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(new FileInputStream(keyStorePath), keyStorePassword.toCharArray());

            TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
            tmf.init(new FileInputStream(trustStorePath));

            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);

            return sslContext;
        } catch (Exception e) {
            LOGGER.error("Error initializing SSL context", e);
        }

        return null;
    }

    private CacheLoader<String, String> tokenLoader() {
        return new CacheLoader<>() {
            @Override
            public String load(String key) throws Exception {
                // Implement logic for OAuth2 access token retrieval using the base URL and client credentials
            }
        };
    }

    public void sendRequest(HttpUriRequest request) throws IOException, URISyntaxException {
        rateLimiter.acquire();
        Callable<CloseableHttpResponse> callable = () -> clientBuilder.build().execute(request);
        Future<CloseableHttpResponse> future = executor.submit(callable);
        try {
            CloseableHttpResponse response = future.get();
            if (response.getStatusLine().getStatusCode() != 200) {
                LOGGER.error("Request failed with status code {}", response.getStatusLine().getStatusCode());
            }

            HttpEntity entity = response.getEntity();
            if (entity != null) {
                try (InputStream content = entity.getContent()) {
                    // Implement logic for handling API responses (e.g., JSON, XML) and verify data integrity during transmission
                }
            }
        } catch (ExecutionException | InterruptedException e) {
            LOGGER.error("Error executing request", e);
        } finally {
            if (!future.isDone()) {
                future.cancel(true);
            }
        }
    }
}
```

