import java.util.concurrent.*;

public final class ConcurrentExecutors {
    private static volatile ExecutorService executor;

    public static ExecutorService getInstance() {
        if (executor == null) {
            synchronized (ConcurrentExecutors.class) {
                if (executor == null) {
                    int maxThreadCount = Math.min(Runtime.getRuntime().availableProcessors(), 10);
                    executor = Executors.newFixedThreadPool(maxThreadCount);
                }
            }
        }
        return executor;
    }
}
