```kotlin
import okhttp3.*
import java.io.File
import java.io.FileOutputStream
import java.lang.Exception
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit

class ThemeBitmapCache {
    private val cache = ConcurrentHashMap<String, Bitmap>()
    private val maxCacheSize: Int = 100
    private val executorService = Executors.newFixedThreadPool(5)
    private val client = OkHttpClient()
    private val baseUrl = "https://your-theme-management-api.com"

    fun getThemeBitmap(themeId: String): Bitmap? {
        if (cache.containsKey(themeId)) return cache[themeId]
        val callback = object : Callback() {
            override fun onFailure(call: Call, e: IOException) {
                Log.e("ThemeBitmapCache", "Failed to load theme bitmap for $themeId", e)
            }

            override fun onResponse(call: Call, response: Response) {
                if (!response.isSuccessful) {
                    Log.w("ThemeBitmapCache", "Received non-success status for $themeId")
                    return
                }
                val bitmap = BitmapFactory.decodeStream(response.body().byteStream())
                synchronized(cache) {
                    if (cacheSize > maxCacheSize) evictLeastRecentlyUsed()
                    cache[themeId] = bitmap
                }
            }
        }
        val request = Request.Builder().url("$baseUrl/themes/$themeId").build()
        executorService.submit { client.newCall(request).enqueue(callback) }
        return null
    }

    private fun evictLeastRecentlyUsed() {
        var oldest: Map.Entry<String, Long>? = null
        synchronized(cache) {
            for ((key, value) in cache.entries) {
                if (oldest == null || System.currentTimeMillis() - value.lastAccessTime > oldest?.value!!) {
                    oldest = Map.Entry.of(key, System.currentTimeMillis())
                }
            }
        }
        oldest?.let { cache.remove(it.key) }
    }

    fun clearCache() {
        synchronized(cache) {
            cache.clear()
        }
    }
}
