```csharp
using System;
using System.Text;
using System.IO;
using System.Security.Cryptography;
using System.Collections.Generic;

public class TripleDESDecryptor
{
    private Dictionary<string, (byte[] Key, byte[] IV)> _keysAndIVs;
    private MemoryCache _cache;
    private int _cacheSize = 1000;

    public TripleDESDecryptor(Dictionary<string, (byte[] Key, byte[] IV)> keysAndIVs)
    {
        _keysAndIVs = keysAndIVs;
        _cache = MemoryCache.Default;
    }

    public string DecryptBase64(string userType, string messageType, string base64EncodedMessage)
    {
        var keyIVPair = _keysAndIVs[userType + "_" + messageType];
        byte[] encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

        using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = keyIVPair.Item1;
            tripleDes.IV = keyIVPair.Item2;

            var decryptedBytes = tripleDes.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    public T GetOrAddToCache<T>(string cacheKey, Func<string, T> factory)
    {
        var cachedObject = _cache.Get(cacheKey);
        if (cachedObject != null) return (T)cachedObject;

        var result = factory(cacheKey);
        _cache.Set(cacheKey, result, new CacheItemPolicy() { AbsoluteExpiration = DateTime.UtcNow.AddMinutes(_cacheSize) });
        return result;
    }
}
