const axios = require('axios');
const dotenv = require('dotenv');
const async = require('async');
const _ = require('lodash');

dotenv.config();

class MarketDataCollector {
    constructor(markets, interval) {
        this.markets = markets;
        this.interval = interval;
        this.streams = {};
    }

    start() {
        _.forEach(this.markets, (market) => {
            const streamKey = `market_${market}`;
            if (!this.streams[streamKey]) {
                this.streams[streamKey] = axios.CancelToken.source();
                this._getDataStream(market);
            }
        });
    }

    pause() {
        _.forEach(this.streams, (source) => source.cancel());
    }

    resume() {
        _.forEach(this.streams, (source) => source.token.cancelAndResolve());
        _.delayed(() => this.start(), this.interval);
    }

    _getDataStream(market) {
        const streamKey = `market_${market}`;
        const url = `https://api.example.com/market/${market}/stream`;

        axios.get(url, { cancelToken: this.streams[streamKey].token })
            .then((response) => {
                // process data and cache it
            })
            .catch((error) => {
                if (axios.isCancel(error)) return;
                console.error(`Error in market ${market}:`, error);
            });
    }
}
