            var keyBytes = new byte[32];
            _rng.GetBytes(keyBytes);
            _aes = Aes.Create();
            _aes.Key = keyBytes;
            _aes.Generator.InitVector = new byte[16];
            _rng.GetBytes(_aes.Generator.InitVector);
        }

        public async Task<string> ReadConfigAsync(string directory, string fileName)
        {
            if (_configCache.ContainsKey($"{directory}/{fileName}"))
                return JsonConvert.SerializeObject(_configCache[$"{directory}/{fileName}"]);

            var fileExtensions = new[] { ".json", ".yaml", ".ini" };
            var extensionIndex = Array.FindIndex(fileExtensions, x => fileName.EndsWith(x));
            if (extensionIndex == -1)
                throw new ArgumentException($"Unsupported file extension: {fileName}");

            var config = await Task.WhenAll(
                from extension in Enumerable.Range(0, fileExtensions.Length)
                let filePath = Path.Combine(directory, fileName.Replace(fileExtensions[extensionIndex], fileExtensions[extensionIndex + (extension >= fileExtensions.Length - 1 ? 0 : extension)]))
                where File.Exists(filePath)
                select ReadConfigFromFileAsync(filePath)).ConfigureAwait(false);

            if (config.Count() != 1)
                throw new InvalidOperationException("Multiple configurations found for the same file.");

            _configCache[$"{directory}/{fileName}"] = config.First();
            return JsonConvert.SerializeObject(_configCache[$"{directory}/{fileName}"]);
        }

        private async Task<object> ReadConfigFromFileAsync(string filePath)
        {
            var memoryUsage = 0;
            using (var streamReader = new StreamReader(filePath))
            {
                var content = await streamReader.ReadToEndAsync().ConfigureAwait(false);
                memoryUsage += content.Length;

                if (memoryUsage > MaxMemoryUsage)
                    throw new OutOfMemoryException("Exceeded maximum allowed memory usage.");

                object parsedConfig;
                switch (Path.GetExtension(filePath).ToLower())
                {
                    case ".json":
                        parsedConfig = JsonConvert.DeserializeObject(content);
                        break;
                    case ".yaml":
                        var deserializer = new DeserializerBuilder().Build();
                        parsedConfig = deserializer.Load(new StringReader(content));
                        break;
                    case ".ini":
                        // Implement INI file parsing here...
                        throw new NotImplementedException("INI file parsing not implemented.");
                    default:
                        throw new ArgumentException($"Unsupported file extension: {Path.GetExtension(filePath)}");
                }

                return parsedConfig;
            }
        }

        public byte[] Encrypt(byte[] data)
        {
            if (data == null || data.Length == 0)
                throw new ArgumentException("Data cannot be empty or null.");

            using var encryptor = _aes.CreateEncryptor();
            return encryptor.TransformFinalBlock(data, 0, data.Length);
