```javascript
const axios = require('axios');
const fs = require('fs');
const path = require('path');
const Bluebird = require('bluebird');
const { Buffer } = require('buffer');

function uploadAndCopyChunks(url, filePath, chunkSize, concurrency, bufferData) {
  const copiedBuffer = Buffer.allocUnsafe(bufferData.length);

  let offset = 0;
  let remainingBytes = bufferData.length;

  function copyAndPush(srcBuffer, start, end) {
    srcBuffer.copy(copiedBuffer, offset, start, end);
    offset += end - start;
    remainingBytes -= end - start;
  }

  const totalChunks = Math.ceil(bufferData.length / chunkSize);
  const chunks = Array.from({ length: totalChunks }, (_, i) => i * chunkSize);

  const promises = [];

  for (let i = 0; i < chunks.length; ) {
    const end = Math.min(chunks[i] + chunkSize, bufferData.length);
    promises.push(
      Bluebird.try(() => {
        const chunkData = bufferData.slice(chunks[i], end);
        copyAndPush(copiedBuffer, offset, end - chunks[i]);

        return new Promise((resolve) => {
          const fileChunk = fs.readFileSync(filePath, { start: chunks[i], end });
          const uploadUrl = uploadChunk(url, fileChunk);
          promises.push(uploadUrl);
          resolve();
        });
      })
    );

    if (++i === chunks.length || i === chunks.length - 1 && promises.length < concurrency) {
      Bluebird.map(promises, axios.all, { concurrency }).then(() => {
        // Return the final object containing URLs and copied data buffer
        return { urls: promises, copiedData: copiedBuffer };
      });
    }
  }
}

function uploadChunk(url, fileChunk) {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('PUT', url);
    xhr.onload = () => resolve(xhr.responseURL);
    xhr.onerror = (err) => reject(err);
    xhr.send(fileChunk);
  });
}
```

