    {
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        _db = _redis.GetDatabase();
    }

    public byte[] DecryptBase64(string userType, string messageType, string base64EncodedMessage)
    {
        var keyBytes = GetKey(userType);
        var ivBytes = GetIV(messageType);
        var encryptedBytes = Convert.FromBase64String(base64EncodedMessage);

        using (var tripleDES = TripleDESCryptoServiceProvider.Create())
        {
            tripleDES.Key = keyBytes;
            tripleDES.IV = ivBytes;
            var decryptor = tripleDES.CreateDecryptor();
            return decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
