    }

    start() {
        if (isMainThread) {
            this.workers = new Map();

            this.markets.forEach((symbol) => {
                const worker = new Worker(__filename, { workerData: symbol });
                this.workers.set(worker.threadId, worker);
            });

            setInterval(() => this.tick(), this.interval);
        } else {
            this.tick();
        }
