Here is a minimal example of ThirdPartyApiClient implementation:

```java
import java.util.concurrent.*;
import org.springframework.stereotype.Component;
import okhttp3.*;

@Component
public class ThirdPartyApiClient implements Runnable {
    private final OkHttpClient httpClient = new OkHttpClient();
    private final RateLimiter rateLimiter;
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public ThirdPartyApiClient(RateLimiter rateLimiter) {
        this.rateLimiter = rateLimiter;
    }

    @Override
    public void run() {
        // Perform request and process response here...
    }

    public void sendRequest(String url) throws InterruptedException, ExecutionException {
        if (!rateLimiter.tryAcquire()) {
            logRateLimited();
            return;
        }
        Call call = httpClient.newCall(new Request.Builder().url(url).build());
        Future<Response> future = executorService.submit(this);
        Runnable task = () -> {
            try {
                Response response = future.get();
                if (response.isSuccessful()) {
                    // Process response here...
                } else {
                    logError("Failed request: " + url, response);
                }
            } catch (IOException e) {
                logNetworkIssue(e);
            } finally {
                rateLimiter.release();
            }
        };
        executorService.execute(task);
    }
}
