        return;
    }

    // Prepare SQL statement and bind file identifier
    const char* sql = "SELECT * FROM tiff_metadata WHERE id = ?";
    sqlite3_stmt* stmt;
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "SQL error: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return;
    }

    // Bind file identifier and execute query
    sqlite3_bind_int(stmt, 1, file_id);
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        memcpy(metadata, sqlite3_column_text(stmt, 0), sizeof(*metadata));
    } else {
        fprintf(stderr, "No metadata found for file with id %d\n", file_id);
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
}

