    iconv_t iconv;
    log_func_t log;
};

static void* validate_email(void* data) {
    struct email_validators* validator = (struct email_validators*)data;
    const char* email = *(const char**)data + strspn(*(const char**)data, "\r\n");
    size_t len = strlen(email);

    char local[256], domain[256];
    sscanf(email, "%255[^@]@%255[^ \n]", local, domain);

    if (strlen(local) == 0 || strlen(domain) == 0) {
        validator->log("Validation Error", email);
        return NULL;
    }

    // Implement external validation service query here
    // ...

    return email;
}

void processEmailBatch(const char* const *emailBatch, int batchSize, log_func_t log) {
    struct email_validators validator = {0};
    iconv_init(&validator.iconv, ICONV_CONST, "UTF-8", ICONV_CONST, "ISO-8859-1");

    pthread_t threads[10000];
    for (int i = 0; i < batchSize; ++i) {
        const char* email = iconv(validator.iconv, &emailBatch[i], NULL, NULL, 0);
        if (!email) continue; // Handle iconv errors gracefully

        pthread_create(&threads[i % 10000], NULL, validate_email, &email);
    }

    for (int i = 0; i < batchSize; ++i) {
        pthread_join(threads[i % 10000], NULL);
    }
}
