class RustCompile {
public:
    explicit RustCompile(int numThreads) : threadPool_(numThreads) {}

    int compile(const std::vector<char>& byteArray) {
        // Deserialize the byte array
        RustCompileData data;
        boost::restore_visitor(data, byteArray.data(), byteArray.size());

        // Parse TIFF image and extract details
        int bitsPerSample = data.image_.bitsPerSample_;
        std::vector<int> samplePerPixel = data.image_.samplePerPixel_;
        std::vector<float> extraSamples = data.image_.extraSamples_;

        // Check if the bits per sample is supported
        if (!(bitsPerSample == 1 || bitsPerSample == 2 || bitsPerSample == 4 || bitsPerSample == 8 || bitsPerSample == 16)) {
            throw std::runtime_error("Unsupported number of bits per sample.");
        }

        // Handle images with extra samples
        int numExtraSamples = extraSamples.size();

        // Start the compilation process using a thread pool
        std::vector<boost::process::child> children;
        for (auto& path : data.sourceFiles_) {
            auto command = "rustc --crate-name my_project " + path + " -o output";
            children.push_back(boost::process::search_path("rustc", {"rustc", "/usr/local/bin/rustc"})[0]
                                .async_launch(command));
        }

        // Wait for all subprocesses to finish and gather exit codes
        std::vector<int> exitCodes;
        for (auto& child : children) {
            exitCodes.push_back(child.wait().exit_code());
        }

        // Report errors and warnings to the logging service
        for (const auto& exitCode : exitCodes) {
            if (exitCode != 0) {
                SPDLOG_WARN("Compilation failed with exit code: {}", exitCode);
            }
        }

        // Measure compilation time and memory usage
        std::chrono::steady_clock::time_point start = std::chrono::steady_clock::now();
        int maxRss;
        if (getrusage(RUSAGE_SELF, &ru_) < 0) {
            throw std::runtime_error("Error retrieving maximum RSS.");
        }
        maxRss = ru_.ru_maxrss;
        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        auto compilationDuration = std::chrono::duration<double>(end - start).count();

        // Log compilation information
        SPDLOG_INFO("Compilation completed in {} seconds.", compilationDuration);
        SPDLOG_INFO("Peak RSS usage: {}", maxRss);

        return static_cast<int>(std::accumulate(exitCodes.begin(), exitCodes.end(), 0));
    }

private:
    boost::thread_group threadPool_;
    rusage ru_;
};
