void* initialize_data(void* arg) {
    long *offsets = malloc(10000000 * sizeof(long));
    int *keys = malloc(10000000 * sizeof(int));
    struct Record *records = malloc(10000000 * sizeof(struct Record));

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (long i = 0; i < 10000000; ++i) {
        long offset = i;
        int key = validate(offset, i);
        if (key != -1) {
            records[i].value = key;
        }
    }

    return NULL;
}

void init_data() {
    pthread_t threads[10];
    for (long i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, initialize_data, NULL);
    }

    // Wait for all threads to finish
    for (long i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }
}
