public class FileDeleter {
    private static final HttpClient httpClient = HttpClient.newBuilder().build();

    public static void deleteFile(String path) throws IOException, InterruptedException, ExecutionException {
        // Send a DELETE request to the external file management service API using the provided file path.
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create("https://api.example.com/files/" + path))
                .DELETE()
                .build();
        CompletionStage<HttpResponse<Void>> deletion = httpClient.sendAsync(request, HttpResponse.BodyHandlers.discarding());
        deletion.toCompletableFuture().get();
    }
}
