Here is a simple C++ example using `nlohmann::json` library, `boost::asio`, `Boost.PropertyTree` for configuration and `curlpp` for HTTP requests. Note that this is a basic implementation and does not cover all possible edge cases or optimizations.

```cpp
#include <iostream>
#include <nlohmann/json.hpp>
#include <boost/property_tree/ptree.hpp>
#include <boost/property_tree/xml_parser.hpp>
#include <curlpp/Simple.hpp>
#include <boost/asio/io_service.hpp>
#include <boost/asio/strand.hpp>
#include <boost/chrono/system_clock.hpp>
#include <boost/optional.hpp>
#include <map>
#include <thread>
#include <mutex>

using json = nlohmann::json;
using namespace curlpp;
using boost::asio::io_service;
using boost::asio::strand;
using boost::system_clock::now;
using boost::optional;

struct Endpoint {
    std::string url;
    int timeout;
};

class TokenValidator {
public:
    void configure(const boost::property_tree::ptree& config) {
        for (auto& e : config.get_child("endpoints")) {
            endpoints.emplace_back(e.second.get<std::string>("url"),
                                   e.second.get<int>("timeout"));
        }
        retry_limit = config.get<int>("retry-limit");
        delay_ms = config.get<int>("delay-ms");
    }

    bool validate(const std::string& token) {
        for (auto it = endpoints.begin(); it != endpoints.end(); ++it) {
            if (validateToken(*it, token)) return true;
        }
        return false;
    }

private:
    bool validateToken(const Endpoint& endpoint, const std::string& token) {
        Simple curl;
        curl.setOpt(new Post(endpoint.url));
        curl.setOpt(new Header("Content-Type", "application/json"));
        curl.setOpt(new Timeout(endpoint.timeout));

        strand scope(io_service);
        curl.perform();
        auto responseCode = curl.getInfoCode();
        if (responseCode != CURLcode::OK) {
            if (++numRetries[endpoint] < retry_limit) {
                std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms));
                continue;
            }
        } else {
            numRetries[endpoint].reset();
        }

        curl.setOpt(new Header("Accept", "application/json"));
        auto rawResponse = scope.submit([&curl]() {
            std::stringstream ss;
            curl.getOutputCb().setStream(&ss);
            curl.perform();
            return ss.str();
        }).get();

        json j = json::parse(rawResponse);
        if (!j.count("access_token")) return false;
        if (j["token_type"] != "Bearer") return false;
        if (!j.count("expires_in") || !json::is_number<int>(j["expires_in"]) || j["expires_in"] < 0) return false;

        return true;
    }

    struct RetryCounter {
        int numRetries = 0;
        std::mutex mtx;
    };

    std::vector<Endpoint> endpoints;
    int retry_limit;
    int delay_ms;
    std::map<Endpoint, RetryCounter> numRetries;
};

int main() {
    boost::property_tree::ptree config;
    boost::property_tree::read_xml("config.xml", config);

    TokenValidator validator;
    validator.configure(config);

    // Process input tokens here...
}
```

This code defines a `TokenValidator` class that reads its configuration from an XML file, and can validate OAuth2 access tokens using multiple endpoints. It supports retrying failed validations based on configurable limits and delays, and concurrently processes token validation requests using Boost.Asio's io_service.

