using Microsoft.Extensions.Logging;

namespace GameWorld
{
    public class ConfigurationManager
    {
        private readonly ILogger<ConfigurationManager> _logger;
        private Dictionary<string, XElement> _configurations;

        public ConfigurationManager(ILogger<ConfigurationManager> logger)
        {
            _logger = logger;
            _configurations = new Dictionary<string, XElement>();
        }

        public async Task LoadConfigurationsAsync()
        {
            var configurationFiles = Directory.GetFiles("Config", "*.xml");

            var tasks = configurationFiles.Select(LoadConfigurationFile);
            await Task.WhenAll(tasks);
        }

        private async Task LoadConfigurationFile(string filePath)
        {
            try
            {
                using (var reader = XElement.Load(filePath))
                {
                    _configurations[Path.GetFileNameWithoutExtension(filePath)] = reader;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Failed to load configuration file: {filePath}");
            }
        }

        public XElement GetConfiguration(string name)
        {
            if (_configurations.TryGetValue(name, out var configuration))
            {
                return configuration;
            }

            throw new KeyNotFoundException($"Configuration '{name}' not found.");
        }

        public void InitializeGameWorld()
        {
            var tileSize = GetInteger("TileSize", "Dimensions");
            var worldWidth = GetInteger("WorldWidth", "Dimensions");
            var worldHeight = GetInteger("WorldHeight", "Dimensions");
            var cameraSpeed = GetFloat("CameraSpeed", "");

            // Initialize game world with the loaded settings.
        }

        private int GetInteger(string key, string section)
        {
            if (int.TryParse(_GetValue(key, section), out int value))
            {
                return value;
            }

            throw new Exception($"Invalid integer configuration value for key '{key}' in section '{section}'.");
