        {
            if (float.TryParse(_GetValue(key, section), out float value))
            {
                return value;
            }

            throw new Exception($"Invalid floating-point configuration value for key '{key}' in section '{section}'.");
        }

        private string _GetValue(string key, string section)
        {
            var config = GetConfiguration(section);
            var element = config.Element(key);
            if (element != null)
                return element.Value;

            throw new KeyNotFoundException($"Key '{key}' not found in section '{section}'.");
        }
    }
}
