        /// <summary>
        /// Computes the MD5 hash of a given string asynchronously.
        /// </summary>
        /// <param name="input">The input string.</param>
        /// <returns>The MD5 hash of the input as a hexadecimal string.</returns>
        public async Task<string> ComputeMD5Hash(string input)
        {
            if (string.IsNullOrEmpty(input))
                throw new ArgumentNullException(nameof(input), "Input cannot be null or empty.");

            var md5 = MD5.Create();
            var inputBytes = Encoding.UTF8.GetBytes(input);

            await Task.Run(() => ProcessHashTask(md5, inputBytes));

            return md5.Hash;
        }

        /// <summary>
        /// Computes the MD5 hash of a given byte array asynchronously.
        /// </summary>
        /// <param name="input">The input byte array.</param>
        /// <returns>The MD5 hash of the input as a hexadecimal string.</returns>
        public async Task<string> ComputeMD5Hash(byte[] input)
        {
            if (input == null || input.Length == 0)
                throw new ArgumentNullException(nameof(input), "Input cannot be null or empty.");

            var md5 = MD5.Create();

            await Task.Run(() => ProcessHashTask(md5, input));

            return md5.Hash;
        }

        private void ProcessHashTask(HashAlgorithm algorithm, byte[] input)
        {
            algorithm.TransformBlock(input, 0, input.Length, null, 0);
            algorithm.TransformFinalBlock(null, 0, 0);
        }

