                await Task.Delay(RetryDelayMilliseconds);
            }

            var result = apiResultTask.Result;

            if (!result.Success || string.IsNullOrEmpty(result.Hash))
                throw new Exception("Failed to get the hash from the external API.");

            return result.Hash;
        }

