    private static final Map<String, MessageProcessorImpl> processors = new HashMap<>();
    private static final KafkaProducer<String, String> producer;
    private static final Set<String> subscribedTopics = ConcurrentSkipListSet.newInstance();
    private static final Jedis redisClient;

