    public void addMessageProcessor(MessageProcessorImpl processor) {
        processors.put(processor.getMessageTypeId(), processor);
    }

    public String processMessage(String messageJson) {
        try {
            MessageMessage message = objectMapper.readValue(messageJson, Message.class);
            MessageProcessorImpl processor = processors.get(message.getTypeId());
            if (processor != null) {
                return objectMapper.writeValueAsString(processor.process(message));
            }
        } catch (IOException e) {
            // Handle JSON parsing errors here
        }
        return "";
    }

    public void publishMessage(String topic, String messageJson) {
        producer.send(new KeyedProducerRecord<String, String>(topic, messageJson));
    }

    public void subscribeToTopics() {
        var consumer = new KafkaConsumer<>(createConsumerConfigs());
        consumer.subscribe(subscribedTopics);
        new Thread(() -> {
            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
                for (ConsumerRecord<String, String> record : records) {
                    try {
                        MessageMessage message = objectMapper.readValue(record.value(), Message.class);
                        processMessage(objectMapper.writeValueAsString(message));
                    } catch (IOException e) {
                        // Handle JSON parsing errors here
                    }
                }
            }
        }).start();
    }

    public void storeMessageInRedis(String key, MessageMessage message) {
        redisClient.set(key, objectMapper.writeValueAsString(message));
    }

    private static Properties createConsumerConfigs() {
        // Return Kafka consumer configuration properties here
    }
}

