import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.bouncycastle.util.Strings;

public class FileHasher {

  public static String calculateMd5Hash(String filePath) throws Exception {
    Mac mac = Mac.getInstance("HmacMD5");
    SecretKeySpec secretKey = new SecretKeySpec(Strings.toByteArray("SECRET_KEY"), "HmacMD5");
    mac.init(secretKey);

    try (InputStream fileInputStream = new FileInputStream(filePath)) {
      byte[] md5Hash = mac.doFinal(fileInputStream.readAllBytes());
      return String.valueOf(new BigInteger(1, md5Hash));
    } catch (IOException e) {
      throw new Exception("Error reading file.", e);
    }
  }
}
```

