public class ElementService
{
    private readonly IUserAuthenticationService _userAuthenticationService;
    private readonly IElementUpdateService _elementUpdateService;
    private readonly ILoggingService _loggingService;

    public ElementService(IUserAuthenticationService userAuthenticationService, IElementUpdateService elementUpdateService, ILoggingService loggingService)
    {
        _userAuthenticationService = userAuthenticationService;
        _elementUpdateService = elementUpdateService;
        _loggingService = loggingService;
    }

    public async Task<HttpResponseMessage> UpdateElementAsync(int userId, int pageSectionId, int elementId, string htmlContent)
    {
        if (!await _userAuthenticationService.IsAuthorizedForModification(userId))
        {
            return new HttpResponseMessage(HttpStatusCode.Forbidden);
        }

        var updateResult = await _elementUpdateService.UpdateElementHtmlAsync(pageSectionId, elementId, htmlContent);

        if (updateResult)
        {
            _loggingService.LogModificationAttempt(userId, pageSectionId, elementId);
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = JsonContent.Create(new { Success = true, RefreshRequired = true }) };
        }
        else
        {
            return new HttpResponseMessage(HttpStatusCode.InternalServerError);
        }
    }
}

public interface IUserAuthenticationService
{
    Task<bool> IsAuthorizedForModification(int userId);
}

public interface IElementUpdateService
{
    Task<bool> UpdateElementHtmlAsync(int pageSectionId, int elementId, string htmlContent);
}

public interface ILoggingService
{
    void LogModificationAttempt(int userId, int pageSectionId, int elementId);
}
