import csv
from datetime import datetime
from statistics import mean
from itertools importislice, isearchkey

def validate_date(date):
    try:
        datetime.strptime(date, "%Y-%m-%d")
        return True
    except ValueError:
        return False

def read_csv_chunked(file, chunk_size=100000):
    with file as csvfile:
        reader = csv.DictReader(csvfile)
        for chunk in (islice(reader, chunk_size) for _ in range(chunk_size, len(reader)+1, chunk_size)):
            yield from chunk

def process_data(data):
    for row in data:
        if not validate_date(row['date']):
            raise ValueError("Invalid date format")
        close_price = float(row['close price'])
        volume = int(row['volume'])
        yield close_price, volume

def write_averages_and_volumes(processed_data, output_file):
    averages = {}
    max_volume = 0
    for close_price, volume in processed_data:
        if not (date := row['date']) in averages:
            averages[date] = mean([close_price])
        else:
            averages[date].append(close_price)
        max_volume = max(max_volume, volume)

    with output_file as csvfile:
        fieldnames = ['date', 'average_close_price', 'max_volume']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for date, avg in averages.items():
            writer.writerow({'date': date, 'average_close_price': round(avg, 2), 'max_volume': max_volume})

def main():
    input_file = "stock_quotes.csv"
    output_file = "processed_stock_quotes.csv"

    with open(input_file, mode='r') as f:
        for data in read_csv_chunked(f):
            try:
                process_data(data)
            except Exception as e:
                print(f"Error processing chunk: {e}")

    with open(output_file, mode='w') as f:
        write_averages_and_volumes(process_data(read_csv_chunked(f)), output_file)

if __name__ == "__main__":
    main()
```
