// A helper function for efficient search and insertion in a forward_list.
template<typename T>
void dynamicInsertionHelper(std::forward_list<T>& list, const T& target, const T& value, std::mutex& mutex, Logger& logger) {
    auto predicate = [target](const T& item) { return item == target; };
    auto position = list | std::ranges::find_if(predicate);
    if (position != list.end()) {
        std::lock_guard<std::mutex> lock(mutex);
        list.insert_after(*position, value);
        logger.Log("Inserted after target: " + std::to_string(*position) + ", new list length: " + std::to_string(list.size()));
    }
}

// The dynamicInsertionHandler function.
void dynamicInsertionHandler(std::forward_list<std::string>& data, const std::string& target, const std::string& value, const std::function<void(const std::string&)>& callback, std::mutex& mutex, Logger& logger) {
    if (target.empty() || value.empty()) {
        throw std::invalid_argument("Empty target or value strings are not allowed.");
    }

    // Query the external data source asynchronously.
    auto start = std::chrono::steady_clock::now();
    DataSourceResult result = queryDataSource(target, value);
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
    logger.Log("Querying external data source: " + std::to_string(elapsed) + " ms");

    // Perform the insertion and call the callback if successful.
    std::lock_guard<std::mutex> lock(mutex);
    try {
        dynamicInsertionHelper(data, target, value, mutex, logger);
        if (callback) {
            callback("Successfully inserted: " + value);
        }
    } catch (const std::exception& e) {
        logger.Log("Error during insertion: " + std::string(e.what()));
    }
}
