#include <iostream>
#include <vector>
#include <mutex>
#include <cmath>
#include <utility>

template<typename K, typename V>
class ConcurrentHashTable {
private:
    static constexpr double LOAD_FACTOR = 0.75;
    size_t bucketSize;
    size_t capacity;
    std::vector<std::pair<K, V>> buckets;
    std::mutex mtx;

public:
    ConcurrentHashTable(size_t bucketSize, size_t initialCapacity) : bucketSize(bucketSize), capacity(initialCapacity), buckets(capacity, std::make_pair(K(), V())) {}

    void insert(const K& key, const V& value) {
        size_t hash = hashFunction(key);
        size_t i = hash % capacity;

        std::unique_lock<std::mutex> lock(mtx);

        while (buckets[i].first != key && i < capacity) {
            i = (i + 1) % capacity;
            if (i == hash % capacity) break;
        }

        if (i == capacity) resize();

        buckets[i] = std::make_pair(key, value);
    }

    bool search(const K& key) const {
        size_t hash = hashFunction(key);
        size_t i = hash % capacity;

        std::unique_lock<std::mutex> lock(mtx);

        while (buckets[i].first != key && i < capacity) {
            i = (i + 1) % capacity;
            if (i == hash % capacity) break;
        }

        return i != capacity && buckets[i].first == key;
    }

    void remove(const K& key) {
        size_t hash = hashFunction(key);
        size_t i = hash % capacity;

        std::unique_lock<std::mutex> lock(mtx);

        while (buckets[i].first != key && i < capacity) {
            i = (i + 1) % capacity;
            if (i == hash % capacity) break;
        }

        if (i != capacity) buckets[i] = std::make_pair(K(), V());
    }

private:
    size_t hashFunction(const K& key) const {
        return std::hash<K>{}(key) % capacity;
    }

    void resize() {
        size_t newCapacity = 2 * capacity;
        std::vector<std::pair<K, V>> tempBuckets(newCapacity, std::make_pair(K(), V()));

        std::unique_lock<std::mutex> lock(mtx);

        for (const auto& pair : buckets) {
            size_t hash = hashFunction(pair.first);
            size_t i = hash % newCapacity;

            while (tempBuckets[i].first != pair.first && i < newCapacity) {
                i = (i + 1) % newCapacity;
                if (i == hash % newCapacity) break;
            }

            tempBuckets[i] = pair;
        }

        buckets = std::move(tempBuckets);
        capacity = newCapacity;
    }
};
```

