// Custom logging structure and functions (use a library such as log4c or journald for production)
typedef enum {
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

void log(LogLevel level, const char *format, ...) {
    time_t current_time;
    struct tm time_info;
    char timestamp[32];

    time(&current_time);
    localtime_r(&current_time, &time_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &time_info);

    va_list args;
    vprintf(format, args);
    printf("%s [%s]: ", timestamp, (level == LOG_INFO) ? "INFO" : (level == LOG_WARNING) ? "WARNING" : "ERROR");
    fflush(stdout);
}

// Third-party tool command for image to PDF conversion with compression level
#define TOOL_CMD "convert -compress %s input.jpg output.pdf"

typedef struct BatchConvertContext {
    const char *input_dir;
    const char *output_dir;
    int (*compression_levels)[100]; // 2D array to hold the compression levels for each image
    int num_images;
    bool enable_parallel;
    pthread_mutex_t log_mutex;
    int max_threads;
    unsigned long long total_time, total_memory, max_memory;
    FILE *checkpoint_file;
} BatchConvertContext;

// Function to perform a single image conversion and log the progress
void convert_image(BatchConvertContext *ctx, int img_idx) {
    char input_path[1024], output_path[1024];
    snprintf(input_path, sizeof(input_path), "%s/%d.jpg", ctx->input_dir, img_idx);
    snprintf(output_path, sizeof(output_path), "%s/%d.pdf", ctx->output_dir, img_idx);

    pid_t process = fork();
    if (process == 0) { // Child process
        char cmd[256];
        snprintf(cmd, sizeof(cmd), TOOL_CMD, ctx->compression_levels[img_idx][0]);
        system(cmd);
        exit(EXIT_SUCCESS);
    } else if (process > 0) { // Parent process
        int status;
        waitpid(process, &status, 0);
        if (!WIFSIGNALED(status) && WEXITSTATUS(status) == 0) {
            log(LOG_INFO, "Converted image %d: %s -> %s", img_idx, input_path, output_path);
        } else {
            log(LOG_WARNING, "Failed to convert image %d: %s -> %s", img_idx, input_path, output_path);
        }
    } else { // Error fork()
        perror("Error forking");
        exit(EXIT_FAILURE);
    }
}

void *batch_convert_images(void *arg) {
    BatchConvertContext *ctx = arg;

    struct stat st;
    if (stat(ctx->input_dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
        log(LOG_ERROR, "Input directory does not exist or is not a directory: %s", ctx->input_dir);
        return NULL;
    }

    if (mkdir(ctx->output_dir, 0755) != 0 && errno != EEXIST) {
        log(LOG_ERROR, "Failed to create output directory: %s", ctx->output_dir);
        return NULL;
    }

    DIR *dir = opendir(ctx->input_dir);
    if (!dir) {
        perror("Error opening input directory");
        return NULL;
    }

    struct dirent *entry;
    int num_images = 0, processed_images = 0;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        char filename[128];
        snprintf(filename, sizeof(filename), "%s/%s", ctx->input_dir, entry->d_name);
        if (strchr(filename, '.') && strcmp(entry->d_name + strlen(entry->d_name) - 4, ".jpg") == 0) {
            num_images++;
        }
    }
    closedir(dir);

    if (num_images < 1) {
        log(LOG_ERROR, "Input directory is empty or contains no valid images");
        return NULL;
    }

    ctx->num_images = num_images;

    pthread_t threads[ctx->max_threads];
    int img_idx;
    for (int i = 0; i < ctx->max_threads && processed_images < num_images; ++i) {
        if ((img_idx = pthread_mutex_lock(&ctx->log_mutex)) == EBUSY) continue;
        log(LOG_INFO, "Starting conversion: %d/%d images", processed_images + 1, num_images);
        pthread_create(&threads[i], NULL, (void*(*)(void*))convert_image, ctx);
        pthread_mutex_unlock(&ctx->log_mutex);
        processed_images++;
    }

    for (int i = 0; i < ctx->max_threads && processed_images < num_images; ++i) {
        pthread_join(threads[i], NULL);
    }

    log(LOG_INFO, "All conversions completed");
    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 7) {
        fprintf(stderr, "Usage: %s input_dir output_dir compression_level[0] enable_parallel checkpoint_file max_threads\n", argv[0]);
        return EXIT_FAILURE;
    }

    BatchConvertContext ctx = {
        .input_dir = argv[1],
        .output_dir = argv[2],
        .compression_levels = (int (*)[100])malloc(sizeof(int) * argc - 6),
        .num_images = 0,
        .enable_parallel = atoi(argv[5]),
        .log_mutex = PTHREAD_MUTEX_INITIALIZER,
    };

    for (int i = 6; i < argc; ++i) {
        if (!strcmp(argv[i], "true")) ctx.enable_parallel = 1;
        else if (sscanf(argv[i], "%d", &ctx.compression_levels[ctx.num_images][0]) != 1 || ctx.compression_levels[ctx.num_images][0] < 0 || ctx.compression_levels[ctx.num_images][0] > 99) {
            fprintf(stderr, "Invalid compression level: %s\n", argv[i]);
            return EXIT_FAILURE;
        }
        ++ctx.num_images;
    }

    if (ctx.enable_parallel > ctx.num_images) ctx.max_threads = ctx.num_images;
    else ctx.max_threads = ctx.enable_parallel;

    if (ctx.num_images == 0 || ctx.max_threads <= 0) {
        log(LOG_ERROR, "Invalid input or configuration");
        return EXIT_FAILURE;
    }

    FILE *checkpoint_file = fopen(argv[6], "wb");
    if (!checkpoint_file) {
        perror("Error opening checkpoint file");
        return EXIT_FAILURE;
    }
    ctx.checkpoint_file = checkpoint_file;

    pthread_t main_thread;
    pthread_create(&main_thread, NULL, (void*(*)(void*))batch_convert_images, &ctx);
    pthread_join(main_thread, NULL);

    fclose(ctx.checkpoint_file);
    return EXIT_SUCCESS;
}
