using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;
using System.Xml;
using StackExchange.Redis;
using Newtonsoft.Json.Linq;

namespace ConfigManager
{
    public class ConfigLoader
    {
        private readonly string _connectionString;
        private readonly IDatabase _redisDb;
        private readonly HttpClient _httpClient;
        private const string SchemaTableName = "ConfigSchema";
        private XmlDocument _configXml;
        private XmlSchemaSet _schemaSet;

        public ConfigLoader(string connectionString, IConnectionMultiplexer redis, IHttpClientFactory httpClientFactory)
        {
            _connectionString = connectionString;
            _redisDb = redis.GetDatabase();
            _httpClient = httpClientFactory.CreateClient();
        }

        public async Task LoadConfigurationAsync()
        {
            if (_configXml != null && !_schemaSet.HasChanged()) return; // Avoid unnecessary requests and processing

            var url = await GetLatestConfigUrlAsync();

            using (var response = await _httpClient.GetAsync(url))
            {
                if (!response.IsSuccessStatusCode)
                    throw new Exception($"Failed to fetch configuration: {response.ReasonPhrase}");

                var configXmlText = await response.Content.ReadAsStringAsync();
                _configXml = new XmlDocument();
                _configXml.LoadXml(configXmlText);
            }

            var versionNumber = _configXml.SelectSingleNode("//Config/Version")?.InnerText;
            var schemaJson = await GetSchemaDefinitionAsync(versionNumber);
            _schemaSet = new XmlSchemaSet();
            _schemaSet.Add(JToken.Parse(schemaJson).ToXml());
            _configXml.Validate(_schemaSet);

            await CacheConfigurationAsync();
        }

        private async Task<string> GetLatestConfigUrlAsync()
        {
            // Implement retry policy based on environment and configuration settings
            var url = await _redisDb.StringGetAsync("latest_config_url");
            if (url == null)
                throw new Exception("No cached latest configuration URL found.");

            return url;
        }

        private async Task<string> GetSchemaDefinitionAsync(string versionNumber)
        {
            var schemaSql = "SELECT SchemaJson FROM ConfigSchema WHERE Version = @version";
            var parameters = new SqlParameter("@version", versionNumber);
            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                var command = new SqlCommand(schemaSql, connection);
                command.Parameters.Add(parameters);
                var schemaJson = await command.ExecuteScalarAsync() as string;
                if (string.IsNullOrEmpty(schemaJson))
                    throw new Exception("Schema definition not found for the given version.");

                return schemaJson;
            }
        }

        private async Task CacheConfigurationAsync()
        {
            await _redisDb.StringSetAsync("latest_config_url", _configXml.SelectSingleNode("//Config/Url")?.InnerText, new TimeSpan(0, 5, 0)); // Cache for 5 minutes
            var schemaVersion = _schemaSet.Schemas()[0].TargetNamespace;
            await _redisDb.StringSetAsync($"config_schema_{schemaVersion}", _schemaSet.GetXml(), new TimeSpan(0, 30, 0)); // Cache for 30 minutes
        }
    }
}
