        # Format the context object for passing to the callback function
        pass

@contextlib.asyncctxmanager
def transaction_logger():
    logger = logging.getLogger(__name__)
    yield logger
    logger.flush()

class PaymentProcessor:
    @abc.abstractmethod
    async def process(self, context: PaymentContext) -> bool:
        pass

class ProcessPaymentTransactions:
    def __init__(self, processors: List[PaymentProcessor], callback: Optional[Callable] = None):
        self.processors = processors
        self.callback = callback
        self.lock = threading.Lock()

    async def _process_transaction(self, context: PaymentContext) -> bool:
        with transaction_logger():
            if not context.valid:
                logging.error(f"Transaction {context.transaction_id} is invalid")
                return False
            for processor in self.processors:
                if await processor.process(context):
                    break
        if self.callback:
            self.callback(context.format_for_callback())
        return True

    async def process_payment_transactions(self, transactions: List[PaymentTransaction]):
        tasks = []
        with self.lock:
            for transaction in transactions:
                context = PaymentContext(transaction, "user123", "card")
                if context.valid:
                    tasks.append(asyncio.create_task(self._process_transaction(context)))

        await asyncio.gather(*tasks)
