```python
import json
import threading
from typing import Dict, Any, Callable, Type

class JSONEncoder(json.JSONEncoder):
    pass

class JSONDecoder(json.JSONDecoder):
    pass

class Registry:
    def __init__(self):
        self._registry = threading.Lock()
        self._reg = {}

    def register(self, id_: str, factory: Callable) -> None:
        with self._registry:
            if id_ not in self._reg:
                self._reg[id_] = factory

    def create(self, id_: str, **kwargs) -> Any:
        with self._registry:
            if id_ in self._reg:
                return self._reg[id_](**kwargs)
            raise KeyError(f"No factory registered for ID '{id_}'.")

class JSONParser:
    def __init__(self, registry: Registry = Registry()):
        self._registry = registry

    def dumps(self, obj: Any, *, cls=JSONEncoder, **kwargs) -> str:
        return json.dumps(obj, cls=cls, **kwargs)

    def loads(self, json_str: str, *, cls=JSONDecoder, object_hook: Callable = None) -> Any:
        try:
            data = json.loads(json_str, cls=cls, object_hook=object_hook)
        except json.JSONDecodeError as e:
            raise ValueError("Invalid JSON string.") from e
        return data

    def register_factory(self, id_: str, factory: Callable) -> None:
        self._registry.register(id_, factory)

    def create_from_json(self, json_str: str, id_: str) -> Any:
        return self._registry.create(id_, **self.loads(json_str))

# Usage example
class MySubClass(object):
    pass

def factory_my_subclass(**kwargs) -> MySubClass:
    return MySubClass(**kwargs)

parser = JSONParser()
parser.register_factory("my_subclass", factory_my_subclass)
data = parser.create_from_json('{"id": 1, "name": "My Object", "sub_obj": {"key": "value"}}', "my_subclass")
```

This code defines a `JSONParser` class that supports serialization and deserialization of JSON objects, as well as registration of factory functions for creating subclasses of the base class. It also handles nested JSON structures, includes error handling, and allows for custom encoder and decoder classes. The registry is thread-safe due to using a `threading.Lock`.

