using System;
using System.Buffers;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Caching.Distributed;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json.Linq;

public class DecryptionService
{
    private readonly IKeyManagementService _keyManagementService;
    private readonly IDistributedCache _cache;
    private readonly ILogger<DecryptionService> _logger;

    public DecryptionService(IKeyManagementService keyManagementService, IDistributedCache cache, ILogger<DecryptionService> logger)
    {
        _keyManagementService = keyManagementService;
        _cache = cache;
        _logger = logger;
    }

    public async Task<byte[]> DecryptAsync(string ciphertext, string iv)
    {
        var key = await RetrieveKeyFromKMS(ciphertext);

        using var aes = Aes.Create();
        using var decryptor = aes.CreateDecryptor(key, iv);

        var gcm = new GCMBlockEncryption(aes, new AesKeySettings { Mode = CryptoLib.CipherMode.GCM });

        var data = gcm.Decrypt(ciphertext, iv);

        if (data.Length > int.MaxValue)
        {
            _logger.LogError("Large ciphertext received: {Ciphertext}", ciphertext);
            throw new InvalidDataException("Large ciphertext exceeded maximum size limit.");
        }

        var plaintext = new byte[data.Length];
        Buffer.BlockCopy(data, 0, plaintext, 0, data.Length);

        return plaintext;
    }

    private async Task<byte[]> RetrieveKeyFromKMS(string ciphertext)
    {
        var key = await _cache.GetAsync($"key:{ciphertext}");

        if (key == null)
        {
            try
            {
                key = await _keyManagementService.RetrieveEncryptionKey(ciphertext);
                await _cache.SetAsync($"key:{ciphertext}", key, new DistributedCacheEntryOptions().SetAbsoluteExpiration(TimeSpan.FromMinutes(60)));
            }
            catch (Exception ex)
            {
                // Implement failover mechanism here
                throw;
            }
        }

        return key;
    }
}
