public class DataProcessor {
    private final ExecutorService executor = Executors.newFixedThreadPool(100);
    private final HttpClient client;
    private final Database database;
    private final int maxConcurrentRequests;

    public DataProcessor(HttpClient client, Database database, int maxConcurrentRequests) {
        this.client = client;
        this.database = database;
        this.maxConcurrentRequests = maxConcurrentRequests;
    }

    public void processUserData(List<String> userIds) {
        executor.submit(() -> fetchAndProcessUserData(userIds));
    }

    private void fetchAndProcessUserData(List<String> userIds) {
        Map<String, UserDataResponse> responses = new HashMap<>();

        for (String userId : userIds) {
            Response response = client.sendRequest(userId);

            if (responses.size() >= maxConcurrentRequests) {
                try {
                    Thread.sleep(500);
                } catch (InterruptedException e) {
                    // Handle interruptions here
                }
            } else {
                responses.put(userId, response.getUserData());
            }
        }

        // Process and aggregate the data here

        database.saveAggregatedData(responses);
    }

    public static class HttpClient {
        private final OkHttpClient okHttpClient;
        private final RetryPolicy retryPolicy;

        public HttpClient(OkHttpClient okHttpClient, RetryPolicy retryPolicy) {
            this.okHttpRequestBuilder = okHttpClient.newBuilder();
            this.retryPolicy = retryPolicy;
        }

        public Response sendRequest(String userId) throws URISyntaxException, IOException {
            Request request = new Request.Builder()
                    .url(new URI("https://api.example.com/user/" + userId))
                    .build();

            Response response = okHttpClient.newCall(request).execute();

            if (response.isSuccessful()) {
                return new Response(response.body().string(), response.code());
            } else {
                throw new IOException("Unexpected response code: " + response.code());
            }
        }
    }

    // Implement retry policy, connection pooling, and other optimizations here
}
