class TestLogger {
public:
    enum class LogLevel { Info, Debug, Warning, Error };
    void log(LogLevel level, const std::string& message) {
        // Customize logging mechanism based on the destination and log level
    }
};

class ExternalConfigurationService {
public:
    virtual ~ExternalConfigurationService() {}
    virtual std::unordered_map<std::string, std::string> getConfigurations() const = 0;
};

struct TestInfo {
    std::string label;
    bool dependent;
    int retryCount;
    int priority;
    std::shared_ptr<ExternalConfigurationService> config;
};

class TestCaseGenerator {
public:
    virtual ~TestCaseGenerator() {}
    virtual std::vector<TestInfo> generateTests(const TestLogger& logger, const ExternalConfigurationService& config) const = 0;
};

class TestRunner {
private:
    std::mutex logMutex;
    std::unordered_map<std::string, std::future<void>> testFutures;
    std::forward_list<TestInfo> tests;
    std::shared_ptr<TestCaseGenerator> generator;
    std::shared_ptr<ExternalConfigurationService> configService;
    std::function<void()> setup;
    std::function<void()> teardown;
    TestLogger& logger;

public:
    explicit TestRunner(TestLogger& logger, std::shared_ptr<TestCaseGenerator> generator = nullptr,
                          std::shared_ptr<ExternalConfigurationService> configService = nullptr,
                          std::function<void()> setup = nullptr, std::function<void()> teardown = nullptr)
        : logger(logger), generator(generator), configService(configService), setup(setup), teardown(teardown) {}

    void executeTestSuite(std::forward_list<std::string> testLabels, const std::function<void(const std::string&)>& runTest,
                          const std::function<void(const std::string&, const std::string&, bool)>& logInfo = nullptr,
                          bool parallel = false) {
        // Insert test labels into the forward list and generate test information
        for (auto label : testLabels) {
            TestInfo info{label, false, 3, 0, configService};
            auto it = tests.emplace_after(std::prev(tests.end()), std::move(info));
            logger.log(TestLogger::LogLevel::Info, "Inserted test label: " + label + ", at position: " + std::to_string(it - tests.begin()));
        }

        auto generetedTests = generateTests();
        tests.splice(tests.end(), generetedTests);

        // Sort tests by priority and dependency
        std::sort(tests.begin(), tests.end(), [](const TestInfo& a, const TestInfo& b) { return a.priority < b.priority; });

        // Create threads for running tests in parallel
        if (parallel) {
            std::vector<std::thread> threads;
            int chunkSize = 10;
            int startIndex = 0;

            while (startIndex < tests.size()) {
                int endIndex = startIndex + chunkSize;
                if (endIndex > tests.size()) endIndex = tests.size();

                auto testChunk = tests.begin() + startIndex;
                std::vector<std::future<void>> testFuturesChunk;

                for (auto it = testChunk; it != tests.begin() + endIndex; ++it) {
                    testFuturesChunk.emplace_back(std::async(std::launch::async, [this, it]() mutable {
                        runTest(it->label);
                        this->logInfo(it->label, "Passed", true);
                    }));
                }

                std::for_each(testFuturesChunk.begin(), testFuturesChunk.end(), [this](auto& future) { testFutures[future.get_future().get_label()] = std::move(future); });

                threads.emplace_back(std::thread([this, testChunk]() mutable {
                    for (auto it = testChunk; it != tests.begin() + endIndex; ++it) {
                        auto future = testFutures[it->label];
                        if (!future.wait_for(std::chrono::seconds(5))) {
                            this->logInfo(it->label, "Timed out", false);
                        }
                    }
                }));

                startIndex = endIndex;
            }

            for (auto& thread : threads) thread.join();
        } else {
            for (auto it = tests.begin(); it != tests.end(); ++it) {
                runTest(it->label);
                logInfo(it->label, "Passed", true);
            }
        }

        // Track test performance and provide a report at the end
        auto duration = std::chrono::high_resolution_clock::now() - startTime;
        logger.log(TestLogger::LogLevel::Info, "Total execution time: " + std::to_string(duration.count()) + " nanoseconds");

        // Execute setup and teardown functions
        if (setup) setup();
        if (teardown) teardown();
    }

private:
    auto generateTests() {
        if (!generator) return std::forward_list<TestInfo>();
        return generator->generateTests(logger, *configService);
    }

    std::chrono::high_resolution_clock::time_point startTime;
};
```

