```javascript
// loader.js - Manages loading and executing scripts
import { TokenGenerator } from './token-generator.js';

class ScriptLoader {
  constructor(url, callback) {
    this.url = url;
    this.callback = callback;
    this.script = document.createElement('script');
    this.loaded = false;
    this.errorCount = 0;
  }

  load() {
    if (this.loaded || this.errorCount >= 3) return;

    this.script.src = this.url;
    this.script.onload = () => {
      this.loaded = true;
      this.callback();
    };
    this.script.onerror = () => {
      this.errorCount++;
      console.error(`Failed to load script: ${this.url}`);
      if (this.errorCount < 3) this.load();
    };

    document.head.appendChild(this.script);
  }
}

async function loadScripts(scriptsUrls) {
  const promises = scriptsUrls.map((url) => new Promise((resolve) => {
    const scriptLoader = new ScriptLoader(url, resolve);
    scriptLoader.load();
  }));

  await Promise.all(promises);
}

// token-generator.js - Generates a secure token
import { crypto } from 'crypto';

class TokenGenerator {
  generateToken(userId, password, salt) {
    const hashedPassword = crypto.createHash('sha256')
      .update(`${password}:${salt}`)
      .digest('hex');

    const token = crypto.randomBytes(16).toString('hex') + Date.now().toString(36);
    return { hashedPassword, token };
  }
}
```

