#include <openssl/aes.h>
#include <openssl/sha.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    char password[32];
    pthread_mutex_t mutex;
} AESContext;

AESContext* aes_init(const char* password) {
    AESContext *ctx = malloc(sizeof(AESContext));
    SHA256_CTX sha256;
    unsigned char key[32];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(key, &sha256);

    AES_KEY aes_key;
    AES_set_encrypt_key(key, 256, &aes_key);

    ctx->password[strlen(password)] = '\0';
    strcpy(ctx->password, password);
    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

void aes_encrypt(AESContext* ctx, const uint8_t* iv, const uint8_t* plaintext, size_t length, uint8_t* ciphertext) {
    AES_KEY *key = &ctx->aes_key;
    unsigned char tag[16];
    CCM_CTX ctx_;

    pthread_mutex_lock(&ctx->mutex);

    CCM_set_encrypt_key(key, iv, tag);
    CCM_crypt(CCM_ENCRYPT, length, plaintext, ciphertext);

    pthread_mutex_unlock(&ctx->mutex);
}

