class ConfigCache {
public:
    virtual void put(const std::string& key, const std::string& value) = 0;
    virtual std::string get(const std::string& key) const = 0;
};

class FileCache : public ConfigCache {
public:
    explicit FileCache(const std::string& filePath) : m_file(filePath, std::ios::out | std::ios::trunc) {}

    void put(const std::string& key, const std::string& value) override {
        m_file << key << ':' << value << '\n';
    }

    std::string get(const std::string& key) const override {
        std::string result;
        std::string line;
        std::getline(m_file, line);
        if (line.empty()) return {};
        size_t pos = line.find(':');
        if (pos == std::string::npos) return {};
        result = line.substr(pos + 1);
        return key == result ? result : "";
    }

private:
    std::ofstream m_file;
};

class NoCache : public ConfigCache {
public:
    void put(const std::string&, const std::string&) {}
    std::string get(const std::string&) const { return ""; }
};

struct RateLimiterSettings {
    int max_requests_per_second = 10;
    boost::posix_time::millisec timeout_ms = 500;
};

class HttpClient {
public:
    HttpClient(ip::tcp::resolver& resolver, RateLimiterSettings settings)
        : m_strand(io_service()), m_rate_limiter(settings.max_requests_per_second, settings.timeout_ms),
          m_resolve(m_strand), m_http(m_strand, m_rate_limiter) {
        doResolve();
    }

    void post(const std::string& target, const std::function<void(bpt::ptree&)>& callback, const RateLimiterSettings& settings = {}) {
        auto request = http::request<http::string_body>(http::verb::post, target, 11);
        request.set(http::field::host, m_resolved_address.target().to_string());
        request.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        if (settings.timeout_ms) {
            request.set(http::field::expect_continue, "100-continue");
            m_http.async_send_request(m_resolved_address, request, [this](beast::error_code ec, auto&&) {
                if (!ec) doResolve();
            });
        } else {
            m_http.async_send_request(m_resolved_address, request, [this, ec = std::move(ec), callback](beast::error_code ec2, auto&& response) {
                if (!ec && !ec2) {
                    auto body = beast::get_to_string(response.body());
                    bpt::read_xml(bpt::xml_parser::make_str(body), make_assoc_visitor(), callback);
                } else if (!ec) {
                    BOOST_LOG_TRIVIAL(error) << "Failed to download configuration file: " << ec2.message();
                } else {
                    BOOST_LOG_TRIVIAL(error) << "Failed to resolve address: " << ec.message();
                }
            });
        }
    }

private:
    void doResolve() {
        m_resolve([this](beast::error_code ec, ip::tcp::resolver::results_type results) {
            if (!ec) {
                for (auto it = results.begin(); ec == beast::no_error && it != results.end(); ++it) {
                    m_resolved_address = *it;
                }
                if (m_resolved_address) {
                    m_http.async_handshake(m_resolved_address, [this](beast::error_code ec) {
                        if (!ec) {
                            m_http.async_read(beast::flat_buffer(), [this](beast::error_code ec, auto&&) {
                                if (!ec) {
                                    m_strand.post([this]() { post("", make_callback(), {}); });
                                } else {
                                    BOOST_LOG_TRIVIAL(error) << "Failed to read configuration file: " << ec.message();
                                }
                            });
                        } else {
                            BOOST_LOG_TRIVIAL(error) << "Failed to connect: " << ec.message();
                        }
                    });
                } else {
                    BOOST_LOG_TRIVIAL(error) << "No addresses found";
                }
            } else {
                BOOST_LOG_TRIVIAL(error) << "Failed to resolve address: " << ec.message();
            }
        });
    }

    io_service m_strand;
    rate_limiter<ip::tcp> m_rate_limiter;
    ip::tcp::resolver m_resolve;
    http::async_client<http::string_body> m_http;
    boost::asio::ip::tcp::endpoint_ptr m_resolved_address;
};

struct Context {
    int operation_id = 0;
    // ... add more context members as needed
};

using Callback = std::function<void(Context&, const bpt::ptree&)>;
auto make_callback(Callback callback, const RateLimiterSettings& settings = {}) {
    return [callback, settings](Context& context, const bpt::ptree& config) {
