void retrieveAndValidateConfig(std::forward_list<std::string>& targets,
                                const std::string& elementName,
                                const std::string& schemaUrl,
                                Callback callback,
                                const RateLimiterSettings& rateLimiterSettings = {},
                                ConfigCache* cache = nullptr) {
    auto it = std::find(targets.begin(), targets.end(), elementName);
    if (it == targets.end()) {
        targets.push_front(elementName);
    }

    Context context;
    HttpClient client(*boost::asio::ip::make_strand(m_io_service), rateLimiterSettings);

    auto callbackBound = make_callback(callback, rateLimiterSettings);

    for (auto& target : targets) {
        client.post(target, [this, &context, callbackBound](Context& context_, const bpt::ptree& config) {
            if (validateSchema(config, schemaUrl)) {
                auto value = config.get<std::string>(elementName);
                if (!value.empty()) {
                    BOOST_LOG_TRIVIAL(info) << "Retrieved configuration for target '" << target << "' with element value: " << value;
                    callbackBound(context, config);
                } else {
                    BOOST_LOG_TRIVIAL(error) << "Configuration does not contain the expected element '" << elementName << "' for target '" << target << "'";
                }
            } else {
                BOOST_LOG_TRIVIAL(warning) << "Failed to validate schema for configuration of target '" << target << "'";
            }
        });
    }
}
