const Kafka = require('kafkajs').Kafka;
const { v4: uuidv4 } = require('uuid');
const chokidar = require('chokidar');

class Deserializer {
  constructor(options) {
    this.expectedClass = options.expectedClass;
    this.maxBufferSize = options.maxBufferSize || 1048576; // 1MB
    this.streamType = options.streamType || 'utf8';
    this.kafka = new Kafka({ ...options.kafka });
    this.topic = options.topic;
    this.loggingFunction = options.loggingFunction;
    this.storageSystem = options.storageSystem;
    this.watcher = chokidar.watch(options.watchDirectory, { persistent: true });
  }

  async deserialize(byteArray) {
    try {
      const inputStream = new Buffer.from(byteArray).createReadStream({ encoding: this.streamType });
      let dataChunk;

      if (inputStream.length > this.maxBufferSize) {
        await this.storeAndForward(inputStream);
      } else {
        dataChunk = await new Promise((resolve, reject) => {
          const chunks = [];
          inputStream.on('data', chunk => chunks.push(chunk));
          inputStream.once('end', () => resolve(Buffer.concat(chunks)));
          inputStream.once('error', error => reject(error));
        });
      }

      const deserializedObject = Java.createJavaObject(this.expectedClass, dataChunk);
      return deserializedObject;
    } catch (error) {
      throw new RuntimeException(`Deserialization failed: ${error.message}`);
    }
  }

  async storeAndForward(inputStream) {
    const chunkId = uuidv4();
    let writtenData = await this.storageSystem.writeChunk(chunkId, inputStream);

    if (writtenData.length < inputStream.length) {
      this.loggingFunction(`Written ${writtenData.length} of ${inputStream.length}, chunk id: ${chunkId}`);
      const consumer = this.kafka.consumer({ groupId: `deserializer-group-${uuidv4()}` });
      await consumer.connect();
      consumer.subscribe([this.topic]);

      consumer.on('message', async message => {
        if (message.value.toString() === chunkId) {
          const deserializedObject = Java.createJavaObject(this.expectedClass, Buffer.from(message.value, this.streamType));
          await this.mergeAndProcess(deserializedObject);
          consumer.unsubscribe();
          await consumer.disconnect();
        }
      });
    } else {
      await this.mergeAndProcess(Java.createJavaObject(this.expectedClass, inputStream));
    }
  }

  async mergeAndProcess(deserializedObjects) {
    // Implement a mechanism for merging and processing deserialized objects asynchronously
  }

  start() {
    this.watcher
      .on('add', filePath => this.deserializeFile(filePath))
      .on('change', filePath => this.deserializeFile(filePath));
  }

  deserializeFile(filePath) {
    fs.readFile(filePath, this.streamType, (error, data) => {
      if (!error) this.deserialize(data);
    });
  }
}

module.exports = Deserializer;
