void asyncConcatenateFiles(
    const std::forward_list<std::string>& filePaths,
    const std::string& target,
    const std::string& value,
    const std::function<void(const std::string&, bool)>& callback,
    const ConfigManager& configManager) {
    // Initialize logger
    log::trivial::AppenderFactory factory;
    log::trivial::logger_mt dc("dc");
    factory.add_stream(dc).filter("debug") >> log::trivial::sink_to_ostream();

    FileIntegrityChecker checker;
    VersionController versionController{callback};
    CacheManager cacheManager;

    auto readFileChunk = [&](FileHandle file, ChunkedFileData& data) {
        // Implement reading a file in chunks here.
    };

    std::vector<FileHandle> files;
    std::mutex mtx;
    ThreadPool threadPool(configManager.getThreadCount());

    for (const auto& filePath : filePaths) {
        if (!fs::exists(filePath)) {
            dc("Error: File not found: " + filePath);
            continue;
        }

        try {
            checker.check(filePath, getChecksum(filePath));
            files.emplace_back(new std::ifstream(filePath));
            threadPool.push([this, &filePath, &data]() mutable { readFileChunk(*files.back(), data); });
        } catch (const std::exception& e) {
            dc("Error: Failed to check file integrity or open file: " + filePath + ": " + e.what());
        }
    }

    std::vector<char> content;

    asio::io_context ioc;
    asio::deadline_timer timer{ioc, boost::chrono::seconds(5)};

    while (files.size() > 0 && !timer.expires_at()) {
        ioc.reset();
        timer.async_wait([this, &content, &mtx](const boost::system::error_code& ec) {
            if (!ec) {
                // Cancel all remaining file reads after timeout.
                mtx.lock();
                for (auto it = files.begin(); it != files.end(); ++it) {
                    (*it)->close();
                }
                files.clear();
                mtx.unlock();
            }
        });

        ioc.run_one();

        ChunkedFileData data;
        if (content.empty() && files.size() > 0) {
            mtx.lock();
            auto file = files.front();
            files.erase(files.begin());
            mtx.unlock();
            content = cacheManager.getFromCache(file->get()->name());
        }

        if (!content.empty()) {
            size_t targetPos = content.find(target);
            if (targetPos != std::string::npos) {
                content.insert(targetPos + target.length(), value);
            } else {
                content.append(value);
            }
        }
    }

    // Handle remaining file reads and process the final content.
    mtx.lock();
    for (auto it = files.begin(); it != files.end(); ++it) {
        (*it)->close();
    }
    mtx.unlock();

    auto insertPos = std::find_if(filePaths.cbegin(), filePaths.cend(), [&](const std::string& path) {
        return path < content.cbegin() + target.length();
    });

    dc("Inserting at position: " + std::to_string(std::distance(filePaths.cbegin(), insertPos)));
    dc("Contents before insertion:\n" + std::string(content.begin(), content.end()));
    auto it = filePaths.insert(insertPos, {content.begin(), content.end()});
    dc("Contents after insertion:\n" + std::string(it->cbegin(), it->cend()));

    versionController.control((*it)->get()->name(), true);
}
