const unittest = require('unittest');
const { promisify } = require('util');

// Promisify unittest.Test.run for easier asynchronous execution
const run = promisify(unittest.Test.run);

class TestRunner {
  constructor() {
    this.testResults = new Map();
    this.currentTestName = null;
    this.testExecutionStartTime = null;
    this.parallel = false;
    this.configService = null;
  }

  async runTests(moduleName, testCases, parallel = false, configService) {
    this.parallel = parallel;
    this.configService = configService || {};

    try {
      // Load the module
      const module = require(moduleName);

      // Reset unittest.mock after each test
      this.resetMock();

      // Execute tests in parallel if specified
      if (this.parallel) await this.executeTestsInParallel(testCases, module);
      else await this.executeTestsSequentially(testCases, module);
    } catch (error) {
      console.error(`Error while executing tests for ${moduleName}:`, error);
    } finally {
      // Clean up resources
      this.cleanup();
    }
  }

  resetMock() {
    unittest.mock.resetAll();
  }

  executeTestsInParallel(testCases, module) {
    return Promise.all(
      testCases.map(async (testCase) => {
        try {
          // Store the start time of each test execution
          this.testExecutionStartTime = Date.now();
          console.log(`Executing test: ${testCase.label}`);

          // Cache test results to avoid redundant computations
          if (this.testResults.has(testCase.label)) return this.testResults.get(testCase.label);

          const testFunction = testCase.testFunction;
          const testResult = await run(module, testFunction);
          this.testResults.set(testCase.label, { outcome: testResult.passed ? 'pass' : 'fail', duration: Date.now() - this.testExecutionStartTime });

          // Log the outcome of each test execution
          console.log(`Test ${testCase.label} result: ${testResult.passed ? 'pass' : 'fail'}`);

          return testResult;
        } catch (error) {
          console.error(`Error while executing test ${testCase.label}:`, error);
          throw error;
        } finally {
          // Clean up resources after each test execution in parallel mode
          this.cleanup();
        }
      })
    );
  }

  executeTestsSequentially(testCases, module) {
    return Promise.resolve()
      .then(() => {
        for (const testCase of testCases) {
          this.executeSingleTest(testCase, module);
        }
      })
      .then(() => this.testResults.size === testCases.length); // Return a promise that resolves when all tests are executed
  }

  executeSingleTest(testCase, module) {
    return new Promise(async (resolve, reject) => {
      try {
        // Store the start time of each test execution
        this.testExecutionStartTime = Date.now();
        console.log(`Executing test: ${testCase.label}`);

        // Cache test results to avoid redundant computations
        if (this.testResults.has(testCase.label)) return resolve(this.testResults.get(testCase.label));

        const testFunction = testCase.testFunction;
        const testResult = await run(module, testFunction);
        this.testResults.set(testCase.label, { outcome: testResult.passed ? 'pass' : 'fail', duration: Date.now() - this.testExecutionStartTime });

        // Log the outcome of each test execution
        console.log(`Test ${testCase.label} result: ${testResult.passed ? 'pass' : 'fail'}`);

        resolve(testResult);
      } catch (error) {
        console.error(`Error while executing test ${testCase.label}:`, error);
        reject(error);
      } finally {
        // Clean up resources after each test execution in sequential mode
        this.cleanup();
      }
    });
  }

  async cleanup() {
    console.log('Cleaning up resources...');
    // Add your custom cleanup logic here
  }
}

