        if tenant_id not in self.ratelimit:
            self.ratelimit[tenant_id] = {'tokens': 60, 'refresh_rate': 60}  # Initial rate limit settings
        tokens = self.ratelimit[tenant_id]['tokens']
        if tokens > 0:
