from typing import Dict, Union
from datetime import timedelta
from functools import wraps

# Database connection setup and query helper functions go here
# ...

def process_payment_transaction(orderId: int, paymentMethod: str, amount: float, cardDetails: dict, gatewayConfig: Dict):
    # Rate limiting decorator goes here
    @rate_limited(gatewayConfig)
    def wrap(*args, **kwargs):
        try:
            # Database transaction handling functions go here
            with database_transaction():
                # Validate parameters and card details
                if not validate_params(orderId, amount, paymentMethod):
                    raise ValueError("Invalid orderId or amount.")
                if not validate_card_details(cardDetails):
                    raise ValueError("Invalid card details.")
                if paymentMethod not in gatewayConfig['supported_payment_methods']:
                    raise ValueError("Unsupported payment method.")

                # Gateway call function goes here
                result = call_gateway(gatewayConfig, amount, cardDetails)

                # Store transaction details in the database
                store_transaction_details(orderId, result)

            return "Payment processed successfully."
        except Exception as e:
            logging.error(f"Error processing payment transaction: {e}")
            raise e
    return wrap(*args, **kwargs)

# Decorators go here
def rate_limited(config: Dict):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if not is_rate_limit_allowed(config):
                raise RuntimeError("Rate limit exceeded.")
            return func(*args, **kwargs)
        return wrapper
    return decorator

def database_transaction():
    conn = connect_to_database()
    try:
        conn.autocommit = False
        yield conn
    finally:
        conn.commit() or conn.rollback()
        conn.close()

def is_rate_limit_allowed(config):
    current_time = int(time.time())
    next_allowed_time = config['rate_limits']['max_attempts'] / config['rate_limits']['interval'] * current_time
    if current_time < next_allowed_time:
        return True
    else:
        logging.info("Rate limit exceeded, resetting in {} seconds.".format(config['rate_limits']['interval']))
        time.sleep(config['rate_limits']['interval'])
        return False
