class Attack {
public:
    std::string name;
    int damage;
    std::string type;
    std::chrono::steady_clock::time_point lastUsed;
    int cooldown;

    // Constructor
    Attack(const std::string& name, const std::string& type, int damage, int cooldown)
        : name(name), type(type), damage(damage), lastUsed(std::chrono::steady_clock::now()), cooldown(cooldown) {}

    bool isOnCooldown() const {
        return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::steady_clock::now() - lastUsed).count() >= cooldown;
    }
};

class Character {
public:
    std::string name;
    std::vector<Attack> attacks;

    // Constructor
    Character(const std::string& name) : name(name) {}

    // Function to select an attack if not on cooldown, retrieve details from external data source, and log selection
    void selectAttack(const std::string& attackName) {
        auto it = std::find_if(attacks.begin(), attacks.end(), [&](const Attack& a) { return a.name == attackName; });
        if (it != attacks.end() && !it->isOnCooldown()) {
            CURL* curl;
            CURLcode res;
            std::string readBuffer;

            curl_global_init(CURL_GLOBAL_DEFAULT);
            curl = curl_easy_init();
            if (curl) {
                std::string url = "http://your-data-source.com/attack/" + attackName;
                curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, nullptr);
                curl_easy_perform(curl);
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
                if (res == CURLE_OK) {
                    curl_easy_read(curl, const_cast<char*>(readBuffer.data()), readBuffer.size(), nullptr);
                    nlohmann::json j = nlohmann::json::parse(readBuffer);
                    it->damage = j["damage"].get<int>();
                    it->type = j["type"].get<std::string>();
                }
            }
            curl_easy_cleanup(curl);
            curl_global_clean();

            std::ofstream logFile("logs.txt", std::ios_base::app);
            if (logFile.is_open()) {
                logFile << "Character: " << name << ", Attack: " << attackName << ", Type: " << it->type << ", Damage: " << it->damage << "\n";
                logFile.close();
            }

            it->lastUsed = std::chrono::steady_clock::now();
        }
    }
};

