class OAuthCertManager:
    def __init__(self, redis_url, cert_path, key_path):
        self.redis = redis.Redis(url=redis_url)
        self.cert_path = cert_path
        self.key_path = key_path

    async def _get_certificate(self, request):
        cache_key = f'oauth_{request["client_id"]}'
        cached_cert = self.redis.get(cache_key)
        if cached_cert:
            return cached_cert.decode('utf-8')

        with open(self.cert_path, 'rb') as cert_file:
            with open(self.key_path, 'rb') as key_file:
                combined = cert_file.read() + key_file.read()

        self.redis.setex(cache_key, 3600*24*90, combined)  # Cache for 90 days
        return combined

    def run(self):
