First, let's start with the AES-256-GCM cipher initialization function using OpenSSL library:

```c
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

typedef struct {
    AES_KEY aes_key;
    unsigned char iv[AES_BLOCK_SIZE];
    unsigned char nonce[16];
} session_t;

void generate_random(unsigned char *data, size_t len) {
    RAND_bytes(data, len);
}

session_t *init_cipher(const char* password, size_t key_len, size_t iv_len) {
    if (key_len != 32 || iv_len > AES_BLOCK_SIZE) {
        fprintf(stderr, "Invalid key or IV length.\n");
        exit(EXIT_FAILURE);
    }

    unsigned char key[AES_BLOCK_SIZE], derived_key[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, password, strlen(password));
    SHA256_Final(derived_key, &ctx);

    if (memcmp(derived_key, key, AES_BLOCK_SIZE) != 0) {
        memcpy(key, derived_key, key_len);
        SHA256_Final(derived_key, &ctx);
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, derived_key + key_len, AES_BLOCK_SIZE - key_len);
        SHA256_Final(key + key_len, &sha256);
    }

    session_t *session = malloc(sizeof(session_t));
    generate_random(session->iv, iv_len);
    generate_random(session->nonce, 16);
    AES_set_encrypt_key(key, AES_KEYSIZE_256, &session->aes_key);

    return session;
}
```

To integrate this into a larger system, create a thread-safe wrapper around the above function:

```c
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

static size_t num_sessions = 0;
static sem_t sessions_sem;

session_t *init_cipher_wrapper(const char* password, size_t key_len, size_t iv_len) {
    if (num_sessions >= MAX_SESSIONS) {
        fprintf(stderr, "Maximum number of concurrent sessions reached.\n");
        exit(EXIT_FAILURE);
    }

    sem_wait(&sessions_sem);
    num_sessions++;
    session_t *session = init_cipher(password, key_len, iv_len);
    if (num_sessions == 1) {
        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);
        pthread_t thread;
        pthread_create(&thread, &attr, cleanup_cipher, NULL);
    }

    return session;
}
```

Cleanup function:

```c
void cleanup_cipher(void *arg) {
    while (num_sessions > 0) {
        pthread_t thread;
        pthread_join(thread, NULL);
        num_sessions--;
    }

    AES_free_key(&aes_ctx);
    sem_destroy(&sessions_sem);
}
```

