2. Min-Heap based Algorithm (MergingSortedLists.h):

```cpp
#ifndef MERGINGSORTEDLISTS_H
#define MERGINGSORTEDLISTS_H

#include <vector>
#include <queue>

class MinHeap {
public:
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
};

void mergeSortedLists(MinHeap& heaps) {
    if (heaps.empty()) return;

    MinHeap resultHeaps;
    while (!heaps.empty()) {
        int minElement = heaps.top().heap.top();
        heaps.top().heap.pop();
        resultHeaps.heap.push(minElement);

        if (!heaps.top().heap.empty()) {
            int nextElement = heaps.top().heap.top();
            heaps.top().heap.pop();
            resultHeaps.heap.push(nextElement);
            heaps.top().heap.push(minElement);
        }

        if (!heaps.top().heap.empty()) {
            heaps.erase(std::begin(heaps));
            resultHeaps.swap(heaps);
        }
    }

    std::swap(resultHeaps, heaps);
}
```

