using log4net;

public class AesDecryptor
{
    private static readonly ILog Log = LogManager.GetLogger(typeof(AesDecryptor));

    public byte[] Decrypt(string cipherText, string key, string iv)
    {
        try
        {
            var cryptoServiceProvider = Aes.Create();
            var parameters = new ParametersWithIV(Hex.Decode(key), Hex.Decode(iv));
            cryptoServiceProvider.Key = parameters.Parameters.GetParameterSpec(typeof(AesKeyParameter)).Key;
            cryptoServiceProvider.IV = parameters.Parameters.GetParameterSpec(typeof(IAes IvParameter)).IV;

            var cipher = cryptoServiceProvider.CreateDecryptor();

            byte[] decryptedData;

            switch (paddingScheme)
            {
                case PaddingMode.PKCS7:
                    decryptedData = PKCS5Padding.Decrypt(Convert.FromBase64String(cipherText), cryptoServiceProvider);
                    break;
                case PaddingMode.PKCS5:
                    // Implement PKCS5 padding logic here
                    break;
                case PaddingMode.NoPadding:
                    decryptedData = Convert.FromBase64String(cipherText);
                    break;
                default:
                    throw new Exception($"Invalid padding scheme '{paddingScheme}'");
            }

            return decryptedData;
        }
        catch (Exception ex)
        {
            Log.Error(ex.Message, ex);
            throw;
        }
    }
}
