import sys
import os
import importlib
from compiler.ast import parse
from pyjit import PyJIT

def compile_files(directory_path):
    for filename in os.listdir(directory_path):
        if filename.endswith(".py"):
            filepath = os.path.join(directory_path, filename)
            with open(filepath, "r") as f:
                source_code = f.read()

            try:
                module = importlib.compile(source_code, filename, "exec")
            except SyntaxError as e:
                logging.error(f"Compilation error in {filename}: {e}")
                continue

            thread = threading.Thread(target=execute_module, args=(module,))
            thread.start()

def execute_module(module):
    try:
        module.run_module()
    except Exception as e:
        logging.error(f"Execution error in module: {e}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python compiler.py DIRECTORY_PATH")
        sys.exit(1)

    directory_path = sys.argv[1]
    compile_files(directory_path)

if __name__ == "__main__":
    main()
