#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <errno.h>
#include <fcntl.h>

#define MAX_RESOURCES 1024
#define BUFFER_SIZE 65536

typedef struct Resource {
    char name[256];
    char *data;
} Resource;

typedef struct ResourceBundle {
    int numResources;
    Resource *resources;
} ResourceBundle;

ResourceBundle *loadResourceBundle(const char *server, const char *path) {
    int sockfd, portno, n;
    struct sockaddr_in serv_addr;
    FILE *fp;
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    bundle->numResources = 0;
    bundle->resources = calloc(MAX_RESOURCES, sizeof(Resource));

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("ERROR opening socket");
        return NULL;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(54321); // Set your custom port number here

    if (inet_pton(AF_INET, server, &serv_addr.sin_addr) <= 0) {
        perror("Invalid or bad address/ Address not supported");
        return NULL;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("ERROR connecting");
        return NULL;
    }

    char request[256] = {0};
    snprintf(request, sizeof(request), "GET %s\r\n", path);

    if (write(sockfd, request, strlen(request)) < 0) {
        perror("ERROR writing to socket");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    Resource currentResource;
    pthread_t threadIds[MAX_RESOURCES]; // Create threads for each resource request

    while ((n = read(sockfd, buffer, BUFFER_SIZE)) > 0) {
        int i = 0;
        char *token = strtok(buffer, "\r\n\r\n");

        if (token && strlen(token) >= 2) {
            strncpy(currentResource.name, token, sizeof(currentResource.name));
            token = strtok(NULL, "\r\n");
            if (token) {
                currentResource.data = malloc(strlen(token)+1);
                strcpy(currentResource.data, token);

                pthread_create(&threadIds[bundle->numResources], NULL, storeResource, &currentResource);
                bundle->numResources++;
            }
        }
    }

    if (n < 0) {
        perror("ERROR reading from socket");
        return NULL;
    }

    close(sockfd);
    return bundle;
}

void *storeResource(void *resourcePtr) {
    Resource *resource = (Resource *)resourcePtr;
    int index = -1;

    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (!bundle->resources[i].name[0]) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        fprintf(stderr, "ResourceBundle exceeded maximum resources\n");
        return NULL;
    }

    Resource *resourceArray = bundle->resources;
    memmove(&resourceArray[index+1], &resourceArray[index], sizeof(Resource)*(MAX_RESOURCES-index));
    resourceArray[index] = *resource;
    return NULL;
}
