struct TIFFImageMetadata
{
    int BitsPerSample;
    int SamplesPerPixel;
    std::string CompressionMethod;
    std::pair<int, int> ImageDimensions;
    std::string ColorProfile;
};

TIFF* OpenTIFF(const std::string& filePath);
void CloseTIFF(TIFF* tiff);
std::string ExtractColorProfile(TIFF* tiff);
Json::Value ExtractMetadataFromTIFF(TIFF* tiff);

bool IsSupportedBitsPerSample(int bits) { /* Implement validation logic */ }
bool IsSupportedCompressionMethod(const std::string& compression) { /* Implement validation logic */ }

TIFFImageMetadata GetTIFFImageMetadata(const std::string& filePath)
{
    TIFF* tiff = OpenTIFF(filePath);
    if (!tiff) throw std::runtime_error("Unable to open the TIFF image.");

    TIFFImageMetadata metadata;
    metadata.BitsPerSample = tifgetfield(tiff, "bits-per-sample");
    metadata.SamplesPerPixel = tifgetfield(tiff, "samples-per-pixel");
    metadata.CompressionMethod = ExtractColorProfile(tiff);
    metadata.ImageDimensions = std::make_pair(tiffgetfield(tiff, "rows"), tiffgetfield(tiff, "columns"));
    metadata.ColorProfile = ExtractColorProfile(tiff);

    CloseTIFF(tiff);

    if (!IsSupportedBitsPerSample(metadata.BitsPerSample) || !IsSupportedCompressionMethod(metadata.CompressionMethod))
        throw std::runtime_error("The bits per sample or compression method is not supported.");

    return metadata;
}
