        _cacheSize = cacheSize;
        _logLevel = logLevel;
        ValidateRange(_minValue, _maxValue);
    }

    private void ValidateRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value should be less than or equal to maximum value.");
    }

    public int RandomInclusive(int minValue, int maxValue) => UnityEngine.Random.Range(Mathf.Clamp(minValue, 0, Int32.MaxValue), Mathf.Clamp(maxValue, 0, Int32.MaxValue));

    public int[] RandomListInclusive(int count, int minValue, int maxValue)
    {
        List<int> randomList = new List<int>();

        for (int i = 0; i < count; i++)
            randomList.Add(RandomInclusive(minValue, maxValue));

        return randomList.ToArray();
    }

    private void Log(string message)
    {
        if (_logLevel > 0)
            Debug.Log($"[{DateTime.Now:HH:mm:ss}][StringRangeManager] {message}");
    }

    private string StringWithTrailingSlashIfValid(string input, int sizeLimit) => (input?.Length ?? 0) <= sizeLimit ? input + "/" : null;

    public override string ToString() => $"Min: {_minValue}, Max: {_maxValue}";

    private void Cache(int key, List<int> values)
    {
        if (_cache == null || _cache.Count >= _cacheSize)
            EvictCache();

        _cache[key] = values;
    }

    private List<int> FetchFromCache(int key) => _cache?.ContainsKey(key) ? _cache[key] : new List<int>();

    public int RandomExclusive(int minValue, int maxValue) => UnityEngine.Random.Range(Mathf.Clamp(minValue + 1, 0, Int32.MaxValue), Mathf.Clamp(maxValue, 0, Int32.MaxValue));

    private void EvictCache()
    {
        var keysToRemove = _cache.Keys.OrderByDescending(k => k).Take(_cache.Count / 2);
        foreach (var key in keysToRemove)
            _cache.Remove(key);
    }

    private void IntegrateDatabase() // Implement database connection, querying, and error handling

    private void CachingMechanism() // Implement caching for frequently generated random values

    public string GetStringWithTrailingSlashIfValid(string input, int sizeLimit) => StringWithTrailingSlashIfValid(input, sizeLimit);
}
