const fs = require('fs');
const zlib = require('zlib');
const { pipeline } = require('stream');

function copyByteRange(srcPaths, destPath, range, compress) {
    const gzip = compress ? zlib.createGzip() : null;
    let totalBytesCopied = 0;

    srcPaths.forEach((srcPath, index) => {
        const srcStream = fs.createReadStream(srcPath);
        const destStream = fs.createWriteStream(destPath, { flags: 'a' });

        if (index !== range[0]) return;
        if (range[1] <= srcPaths.length && index === range[1] - 1) {
            srcStream.pipe(destStream);
            totalBytesCopied += srcStream.bytesRead;
        } else {
            srcStream.pipe(gzip).pipe(destStream, { end: false });
            destStream.on('finish', () => {
                gzip.resume();
                totalBytesCopied += gzip.readSync();
            });
        }
    });

    // Log each operation and the total number of bytes copied
    ...
}
