#if defined(_WIN32) || defined(_WINDOWS)
    #define PATH_SEPARATOR '\\'
#else
    #define PATH_SEPARATOR '/'
#endif

typedef struct {
    char* buffer;
    size_t size;
} OutputBuffer;

OutputBuffer* allocate_output_buffer(size_t size) {
    void* ptr = mmap(NULL, size + 1, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for output buffer.\n");
        return NULL;
    }

    OutputBuffer* outputBuffer = malloc(sizeof(OutputBuffer));
    outputBuffer->buffer = ptr;
    outputBuffer->size = size + 1;
    memset(outputBuffer->buffer, 0, outputBuffer->size);

    return outputBuffer;
}

void free_output_buffer(OutputBuffer* buffer) {
    if (buffer == NULL || buffer->buffer == NULL) {
        return;
    }

    munmap(buffer->buffer, buffer->size);
    free(buffer);
}

char* appendPathSeparator(const char* inputPath, size_t pathLimit, OutputBuffer* outputBuffer, int fd) {
    if (inputPath == NULL || outputBuffer == NULL) {
        fprintf(fd, "Invalid input or output buffer.\n");
        return NULL;
    }

    const size_t inputLength = strlen(inputPath);

    // Check if the new string will exceed the path limit.
    if (pathLimit <= inputLength + 2) {
        fprintf(fd, "The new string will exceed the specified path limit.\n");
        return NULL;
    }

    const size_t outputBufferSize = outputBuffer->size - 1;

    // Check if the buffer is large enough to store the modified string.
    if (outputBufferSize <= inputLength + 2) {
        fprintf(fd, "The provided buffer size is insufficient.\n");
        return NULL;
    }

    strcpy(outputBuffer->buffer, inputPath);
    outputBuffer->buffer[inputLength] = PATH_SEPARATOR;
    outputBuffer->buffer[inputLength + 1] = '\0';

    return outputBuffer->buffer;
}
```

