// API class for abstracting data retrieval and handling throttling/rate limits/API key expiration
class Api {
public:
    virtual std::vector<std::pair<std::string, int>> getData() = 0;
    virtual void setApiKey(const std::string& apiKey) = 0;
    virtual void resetThrottleTimer() = 0;
};

// Transformation function for the vector's string part
using StringTransformFunction = std::function<int(const std::string&)>;

// Callback function for specific actions on the integer part of each pair
using CallbackFunction = std::function<void(const std::string&, int)>;

// Helper class to perform processing and transformation in a thread-safe manner
class Processor {
public:
    explicit Processor(Api* api, StringTransformFunction transform, CallbackFunction callback, logging::basic_logger_factory<> loggerFactory);

    void processAndTransformData(const std::vector<std::pair<std::string, int>>& data);

private:
    Api* _api;
    StringTransformFunction _transform;
    CallbackFunction _callback;
    logging::basic_logger<> _logger;
    std::mutex _mutex;
};

// Constructor for Processor class
inline Processor::Processor(Api* api, StringTransformFunction transform, CallbackFunction callback, logging::basic_logger_factory<> loggerFactory)
    : _api(api), _transform(std::move(transform)), _callback(std::move(callback)), _logger(loggerFactory) {}

// ProcessAndTransformData method implementation
void Processor::processAndTransformData(const std::vector<std::pair<std::string, int>>& data) {
    // Handle concurrent modifications and access to shared resources safely using mutexes
    std::unique_lock<std::mutex> lock(_mutex);

    // Retrieve data from the API, considering throttling, rate limits, and API key expiration
    auto apiData = _api->getData();

    // Merge the new data with the existing one (if any)
    data.insert(data.end(), apiData.begin(), apiData.end());

    // Process each element in the vector
    for (const auto& pair : data) {
        std::unique_lock<std::mutex> pairLock(_mutex); // Acquire lock for the current pair

        try {
            int transformedInt = _transform(pair.first); // Apply transformation to the string part

            if (_callback) { // If a callback function is provided, perform specific action on the integer part
                _callback(pair.first, transformedInt);
            }
        } catch (const std::exception& e) {
            _logger(logging::error) << "Failed to process pair: " << pair.first << ": " << e.what();
        }

        pairLock.unlock(); // Release lock for the current pair
    }
}
