async function runTests(moduleName, testCases, parallel = false, configService) {
  const startTime = new Date();
  console.log(`Running tests for module: ${moduleName}`);

  // Load the module and set up environment
  const { [moduleName]: mod } = await import(moduleName);
  let testEnvironmentSetup;

  try {
    testEnvironmentSetup = () => promisify(mod.setup)();
  } catch (e) {
    console.error(`Failed to set up environment for module: ${moduleName}`, e);
    return;
  }

  // Create a cache object for storing test results
  const testCache = {};

  // Mocking library reset function
  const mockReset = () => unittest.mock.restore();

  // Execute the tests in parallel or sequentially based on the flag
  if (parallel) {
    // Implement parallel execution using Promise.all and handle errors gracefully
  } else {
    for (const testCase of testCases) {
      await executeTest(testCase, mod, testEnvironmentSetup, mockReset, testCache);
    }
  }

  // Clean up after the test run
  try {
    await promisify(mod.teardown)();
  } catch (e) {
    console.error(`Failed to tear down environment for module: ${moduleName}`, e);
  }

  const endTime = new Date();
  console.log(`Test run completed for module: ${moduleName}, duration: ${endTime - startTime}ms`);

  // Fetch test configurations dynamically (if provided) and invalidate the cache if needed
  if (configService) {
    const config = await configService.getConfig(moduleName);
    if (JSON.stringify(testCache) !== JSON.stringify(config.testResults)) {
      console.log(`Clearing test cache for module: ${moduleName}`);
      testCache; // Empty the cache here
    }
  }

  function executeTest(testCase, mod, setupFn, mockResetFn, testCache) {
    return new Promise((resolve, reject) => {
      const startSubTestTime = new Date();
      console.log(`Executing test: ${testCase.label}`);

      // Set up the environment for this specific test
      setupFn()
        .then(() => {
          unittest.mock.reset(mod);
          mockResetFn();

          const testFunction = testCase.testFunc;
          try {
            testFunction(unittest.createTest(testCase.label))
              .then(() => {
                console.log(`Test passed: ${testCase.label}`);
                testCache[testCase.label] = true; // Store the result in cache
                resolve();
              })
              .catch((error) => {
                console.error(`Test failed: ${testCase.label}`, error);
                testCache[testCase.label] = false; // Store the result in cache
                reject(error);
              });
          } catch (e) {
            console.error(`An error occurred while executing test: ${testCase.label}`, e);
            reject(e);
          }
        })
        .finally(() => {
          const endSubTestTime = new Date();
          console.log(`Test execution completed for: ${testCase.label}, duration: ${endSubTestTime - startSubTestTime}ms`);
        });
    });
  }
}
