class Logging {
public:
    template<typename T>
    static void log(const T& message) {
        spdlog::get("logger")->info("[Log] {}", message);
    }
};

class SafeSharedPtr final : public std::shared_ptr<int> {
public:
    SafeSharedPtr() = default;
    explicit SafeSharedPtr(std::weak_ptr<int> wptr) noexcept : std::shared_ptr<int>(wptr) {}

    ~SafeSharedPtr() {
        if (use_count() == 1) {
            Logging::log("Deleting value: " + std::to_string(*get()));
        }
        std::shared_ptr<>::reset();
    }
};

class ConcurrentForwardList final : public std::forward_list<SafeSharedPtr<int>> {
private:
    mutable std::mutex mtx;
    std::atomic<bool> is_empty{true};

public:
    ConcurrentForwardList() = default;

    // ... (other member functions omitted for brevity)

    std::shared_ptr<int> try_emplace_after(const SafeSharedPtr& pos, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (is_empty || pos->use_count() == 0) {
            Logging::log("Error: Invalid position or empty list");
            return nullptr;
        }
        is_empty.store(false, std::memory_order_release);

        auto it = begin();
        for (; it != pos && it != end(); ++it) {}
        if (it == end()) {
            Logging::log("Error: Position not found");
            return nullptr;
        }

        // ... (insertion logic omitted for brevity)
    }
};

bool insertAfter(ConcurrentForwardList& list, const SafeSharedPtr<int>& pos, int value) {
    try {
        auto result = list.try_emplace_after(pos, value);
        if (!result) {
            return false;
        }
        return true;
    } catch (const std::exception& e) {
        Logging::log("Error: " + std::string(e.what()));
        return false;
    }
}

int main() {
    // ... (test setup logic omitted for brevity)

    ConcurrentForwardList list;
    list.push_back(std::make_shared<int>(42));
    SafeSharedPtr<int> pos = list.begin();
    assert(insertAfter(list, pos, 10));

    // ... (more test cases and stress testing logic omitted for brevity)
}
