#include <openssl/sha.h>
#include <openssl/pkcs5_pbkdf2.h>
#include <pthread.h>
#include "config.h" // External configuration settings header file

// Global variables
static AES_KEY aes_context;
static char iv[AES_BLOCK_SIZE];
static unsigned char password[PASSWORD_MAX_LENGTH];
static pthread_mutex_t config_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;

// Error codes
enum ErrorCodes {
    EC_SUCCESS,
    EC_CONFIG_FILE_FAILURE,
    EC_KEY_DERIVATION_FAILURE,
    EC_INVALID_CONFIGURATION,
    EC_EMPTY_PASSWORD,
    EC_MEMORY_ALLOCATION_FAILURE
};

// Initialize AES-256-CBC cipher
int aes_init() {
    if (password[0] == '\0') return EC_EMPTY_PASSWORD;

    pthread_mutex_lock(&config_mutex);
    memcpy(iv, config.iv, AES_BLOCK_SIZE);
    pthread_mutex_unlock(&config_mutex);

    const unsigned char salt[SALT_LENGTH] = {0x01}; // Example salt value for PBKDF2
    unsigned char key[AES_KEYSIZE/8];
    PKCS5_PBKDF2_HMAC_SHA256((const char*)password, strlen(password), salt, SALT_LENGTH, config.iterations, SHA256_DIGEST_LENGTH * 8, key, AES_KEYSIZE/8);
    AES_set_encrypt_key(key, AES_KEYSIZE/8, &aes_context);

    return EC_SUCCESS;
}

// Encrypt data using AES-256-CBC cipher
int aes_encrypt(const unsigned char* data, size_t length, unsigned char* encrypted_data) {
    if (aes_init() != EC_SUCCESS) return EC_KEY_DERIVATION_FAILURE;

    AES_cbc_encrypt(data, encrypted_data, length, &aes_context, iv, AES_ENCRYPT);

    return EC_SUCCESS;
}

// Decrypt data using AES-256-CBC cipher
int aes_decrypt(const unsigned char* encrypted_data, size_t length, unsigned char* decrypted_data) {
    if (aes_init() != EC_SUCCESS) return EC_KEY_DERIVATION_FAILURE;

    AES_cbc_encrypt(encrypted_data, decrypted_data, length, &aes_context, iv, AES_DECRYPT);

    return EC_SUCCESS;
}

// Cleanup function for the module (deinitializes and frees resources)
void aes_finalize() {
    // Free any allocated memory here if necessary
}
