        self.config = config_manager.config['logging']
        self.formatters = {
            'simple': logging.Formatter(self.config['formats']['simple']),
            # Add more formats as needed
        }
        self.handlers = []
        for handler_conf in self.config['handlers']:
            if handler_conf['type'] == 'file':
                hdlr = RotatingFileHandler(handler_conf['filename'], maxBytes=handler_conf['maxbytes'], backupCount=handler_conf['backupCount'])
                hdlr.setFormatter(self.formatters[handler_conf['formatter']])
                self.handlers.append(hdlr)
            elif handler_conf['type'] == 'smtp':
                hdlr = SMTPHandler(**handler_conf)
                hdlr.setFormatter(self.formatters[handler_conf['formatter']])
                self.handlers.append(hdlr)
            # Add more handler types as needed

        self.logger = logging.getLogger()
        for hdlr in self.handlers:
            self.logger.addHandler(hdlr)
