Due to the complexity of the task, I will provide you with an outline of a solution using C++17 and Zlib library. Here's a simplified version of how you can structure your code:

```cpp
#include <iostream>
#include <string>
#include <fstream>
#include <vector>
#include <map>
#include <utility>
#include <filesystem>
#include <zlib.h>
#include <unordered_set>
#include <mutex>
#include <system_error>

namespace fs = std::filesystem;

constexpr size_t MAX_FILE_SIZE = 1024 * 1024 * 16; // 16MB max file size
constexpr auto SUPPORTED_EXTENSIONS = {".txt", ".jpg", ".png"};

std::mutex mtx;
std::map<fs::path, std::vector<unsigned char>> cache;
std::unordered_set<fs::path> processing;

std::vector<unsigned char> compressFileData(const std::string& filePath) {
    if (!fs::exists(filePath)) {
        throw std::system_error(errno, std::generic_category(), "Invalid path");
    }

    auto ext = fs::path(filePath).extension().string();
    if (ext.empty() || !std::includes(SUPPORTED_EXTENSIONS.begin(), ext.begin(), ext.end())) {
        throw std::system_error(errno, std::generic_category(), "Unsupported file type");
    }

    // Check if the file is already in cache
    auto it = cache.find(fs::path(filePath));
    if (it != cache.end()) {
        return it->second;
    }

    // Acquire lock to avoid concurrent processing
    std::unique_lock<std::mutex> lock(mtx);
    if (processing.count(fs::path(filePath)) > 0) {
        lock.unlock();
        throw std::system_error(EBUSY, std::generic_category(), "File is currently being processed");
    }
    processing.insert(fs::path(filePath));

    // ... Read the file content into memory efficiently and compress it using Zlib or other chosen library ...

    lock.unlock();
    processing.erase(fs::path(filePath));

    return compressedData;
}
```

This solution uses a cache to store previously compressed files, ensures thread safety with a mutex, and checks for supported file types. You will need to implement the actual compression process using Zlib or another chosen library. Additionally, you should add error handling for null pointers, out-of-memory conditions, and other potential issues. Lastly, don't forget to write unit tests for your implementation!

