namespace DynamicFileProcessor
{
    public class DynamicFileProcessor
    {
        private readonly ILogger<DynamicFileProcessor> _logger;
        private readonly BlobContainerClient _blobContainerClient;
        private readonly IDbConnection _dbConnection;
        private readonly IServiceScopeFactory _scopeFactory;

        public DynamicFileProcessor(ILogger<DynamicFileProcessor> logger, IConfiguration configuration)
        {
            _logger = logger;
            var storageAccountName = configuration["StorageAccountName"];
            var storageAccessKey = configuration["StorageAccessKey"];
            var connectionString = configuration["ConnectionString"];

            _blobContainerClient = new BlobContainerClient(storageAccountName, storageAccessKey, "mycontainer");
            _dbConnection = new SqlConnection(connectionString);
            _scopeFactory = ServiceProvider.CreateScope();
        }

        public async Task ProcessFileAsync(string fileId)
        {
            var blobClient = _blobContainerClient.GetBlobClient(fileId);
            var metadata = await ReadMetadataAsync(fileId);
            var content = await DownloadFileContentAsync(blobClient);

            // Perform processing operations on content here

            await WriteToDatabaseAsync(metadata, fileId, content);
        }

        private async Task<dynamic> ReadMetadataAsync(string fileId)
        {
            // Query metadata from the database using the fileId
            return await _dbConnection.QueryFirstOrDefaultAsync<dynamic>("SELECT * FROM Files WHERE FileId = @FileId", new { FileId = fileId });
        }

        private async Task<Stream> DownloadFileContentAsync(BlobClient blobClient)
        {
            // Download the file content from Azure Blob Storage
            var response = await blobClient.DownloadAsync();
            return response.Value.ContentStream;
        }

        private async Task WriteToDatabaseAsync(dynamic metadata, string fileId, Stream content)
        {
            // Update or insert metadata and file content into the database
            using (var scope = _scopeFactory.CreateScope())
            {
                var dbContext = scope.ServiceProvider.GetRequiredService<IDbContext>();
                await dbContext.AddOrUpdateFileAsync(metadata, content);
            }
        }
    }
}
