#include <iostream>
#include <forward_list>
#include <functional>
#include <regex>

void insertAfterFirstOccurrence(std::forward_list<std::string>& data, const std::string& target, const std::string& value, const std::function<void(const std::string&)>& callback) {
    // Find the first occurrence of the target and insert the value after it.
    auto pos = std::find_if(data.begin(), data.end(), [target](const std::string& str) { return str == target; });

    if (pos != data.end()) {
        // Insert the value immediately after the first occurrence of the target
        ++pos;
        data.insert(pos, value);

        // Callback for processing the inserted value if provided
        if (callback) callback(value);
    } else {
        // If the target is not found, append the value to the end of the list
        data.push_back(value);
    }
}
