import java.io.*;
import java.util.logging.Logger;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.InvocationTargetException;
import java.lang.ClassCastException;
import java.lang.RuntimeException;
import java.util.concurrent.locks.ReentrantLock;

public class LoadState {
    private static final Logger LOGGER = Logger.getLogger(LoadState.class.getName());
    private String filePath;
    private int expectedVersion;
    private ReentrantLock lock = new ReentrantLock();

    public LoadState(String filePath, int expectedVersion) {
        this.filePath = filePath;
        this.expectedVersion = expectedVersion;
    }

    public MoSTState load() {
        lock.lock();
        try (FileInputStream fis = new FileInputStream(filePath);
             ObjectInputStream ois = new ObjectInputStream(fis)) {
            try {
                Object obj = ois.readObject();
                if (obj instanceof MoSTState state && state.getVersion() == expectedVersion) {
                    return state;
                } else {
                    throw new VersionMismatchException("Loaded version does not match the expected version.");
                }
            } catch (ClassCastException | ClassNotFoundException e) {
                LOGGER.severe("Failed to load object from file: " + e.getMessage());
                throw new RuntimeException(e);
            }
        } finally {
            lock.unlock();
        }
    }

    public static class VersionMismatchException extends Exception {
        private static final long serialVersionUID = -3529861470634887609L;

        public VersionMismatchException(String message) {
            super(message);
        }
    }
}
```

