#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>

// External configuration system function to read size limit
size_t getSizeLimit();

// Thread-safe logging function
void logError(const char *message);

char* dynamicStringProcessor(const char *input, const char *separator) {
    // Trim trailing whitespace and check if string exceeds size limit
    size_t trimmedLength = strlen(trimWhitespace(input));
    if (trimmedLength + strlen(separator) > getSizeLimit()) return NULL;

    // Allocate memory for the new string using malloc
    char *newString = mmap(NULL, trimmedLength + strlen(separator), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (newString == MAP_FAILED) {
        logError("Memory allocation failed");
        return NULL;
    }

    // Copy input string and append separator
    strncpy(newString, trimWhitespace(input), trimmedLength);
    strcat(newString, separator);

    // Return the processed string
    return newString;
}

char* trimWhitespace(const char *input) {
    if (!input || !*input) return "";

    size_t start = 0;
    for (size_t i = 0; input[i] != '\0'; ++i) {
        if (!isspace((unsigned char)input[i])) break;
        start = i + 1;
    }

    size_t end = strlen(input);
    for (size_t i = end - 1; i > start; --i) {
        if (!isspace((unsigned char)input[i])) break;
        end = i;
    }

    char *result = malloc(end - start + 1);
    strncpy(result, input + start, end - start);
    result[end - start] = '\0';

    return result;
}
