#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    pthread_mutex_lock(&log_mutex);
    fprintf(stderr, "[%s]\n", message);
    pthread_mutex_unlock(&log_mutex);
}

char *appendSlashIfWithinLimit(const char *inputStr, size_t sizeLimit, FILE *fd, char *outputBuffer, size_t bufferSize) {
    if (!inputStr || sizeLimit < 0 || !bufferSize) {
        log_message("Invalid input or buffer size.");
        return NULL;
    }

    size_t inputLength = strlen(inputStr);
    if (inputLength > sizeLimit || inputLength + 1 >= bufferSize) {
        log_message("String too long or output buffer not large enough.");
        return NULL;
    }

    // Atomic operations are used for thread safety.
    char *outputPtr = outputBuffer;
    if (inputLength < bufferSize - 1) {
        strcpy(outputPtr, inputStr);
        *(outputPtr + inputLength) = '/';
        return outputPtr;
    } else {
        return NULL;
    }
}

