using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Linq;

public class SqlCommandGenerator
{
    public static IDataReader ExecuteQuery(string sqlTemplate, List<object> parameters)
    {
        using (SqlConnection connection = new SqlConnection("Data Source=MyServer;Initial Catalog=MyDB;Integrated Security=True"))
        {
            connection.Open();
            using (SqlCommand command = new SqlCommand(sqlTemplate, connection))
            {
                int paramIndex = 0;
                foreach (object parameter in parameters)
                {
                    if (parameter is string strParam)
                        command.Parameters.AddWithValue($"@param{paramIndex}", strParam);
                    else
                        command.Parameters.Add(parameter);

                    paramIndex++;
                }

                try
                {
                    return command.ExecuteReader();
                }
                catch (SqlException ex)
                {
                    Console.WriteLine($"Error: {ex.Message}");
                    throw;
                }
            }
        }
    }

    public static void UseTransaction(Action<IDbTransaction> action)
    {
        using (SqlConnection connection = new SqlConnection("Data Source=MyServer;Initial Catalog=MyDB;Integrated Security=True"))
        {
            connection.Open();
            using (SqlTransaction transaction = connection.BeginTransaction())
            {
                try
                {
                    action(transaction);
                    transaction.Commit();
                }
                catch
                {
                    transaction.Rollback();
                    throw;
                }
            }
        }
    }
}
