public async Task<string> ComputeAsync(Stream stream, CancellationToken cancellationToken)
{
    var md5 = MD5.Create();
    await using (var reader = new StreamReader(stream))
    {
        var pipeline = PipeReader.Create(reader);
        while (await pipeline.ReadAsync(cancellationToken)) { }
        return BitConverter.ToString(md5.Hash).Replace("-", "").ToLowerInvariant();
    }
}
