void updateProductInventory(Inventory& inventory, const int& productId, const std::string& productCategory, const int& newQuantity) {
    if (productId <= 0 || productCategory.empty() || newQuantity < 0) {
        throw std::invalid_argument("Invalid input parameters.");
    }

    unique_lock<mutex> lock(inventory.mtx);
    inventory.connected = true; // Ensure we connect to the database only once.
    inventory.connectToDatabase();

    auto it = inventory.data.find(productId);
    if (it == inventory.data.end()) {
        inventory.data[productId] = std::make_pair(productCategory, newQuantity);
    } else {
        it->second.second += newQuantity;
    }

    async(launch::async, [&inventory, productId, productCategory, newQuantity]() mutable {
        inventory.updateDatabase(productId, productCategory, newQuantity);
    });

    lock.unlock(); // Release the lock before logging to avoid blocking other threads.

    auto timestamp = chrono::system_clock::now().time_since_epoch().count();
    logOperation(productId, productCategory, it != inventory.data.end() ? it->second.second : 0, newQuantity, timestamp, "UserID"); // Replace "UserID" with the actual user ID.
}
