struct StateList* find_states(int *states, int num_states, FSA* fsa, int initial_state, int transition_symbol) {
    if (!fsa || !states || num_states <= 0) {
        return NULL;
    }

    struct StateList* state_list = NULL;
    struct StateListNode* current = NULL;

    for (int i = 0; i < num_states; ++i) {
        if (fsa->states[i] == initial_state && fsa->transitions[(initial_state * fsa->num_states) + i]->symbol == transition_symbol) {
            if (!state_list) {
                state_list = malloc(sizeof(struct StateList));
                if (!state_list) {
                    return NULL;
                }
                current = state_list;
                current->state = i;
                current->next = NULL;
            } else {
                current->next = malloc(sizeof(struct StateListNode));
                if (!current->next) {
                    free(state_list);
                    return NULL;
                }
                current = current->next;
                current->state = i;
                current->next = NULL;
            }
        }
    }

    if (!state_list) {
        free(current); // Free any allocated memory in case of failure
        return NULL;
    }

    struct StateListNode* last = state_list;
    while (last->next) {
        last = last->next;
    }
    last->next = malloc(sizeof(struct StateListNode));
    if (!last->next) {
        free(state_list); // Free any allocated memory in case of failure
        return NULL;
    }
    last->next->state = -1; // Mark the end of the list

    FSA* new_fsa = create_fsa(state_list->num_nodes, NULL);
    if (!new_fsa) {
        free(state_list); // Free any allocated memory in case of failure
        return NULL;
    }

    int i = 0;
    struct StateListNode* iter = state_list;
    while (iter) {
        new_fsa->states[i] = iter->state;
        if (!iter->next) break;
        iter = iter->next;
        i++;
    }

    // Update the 'next' pointer of the last state in the original FSA to point to the newly created state list
    if (fsa->states[initial_state] != -1) {
        fsa->transitions[(initial_state * fsa->num_states) + fsa->states[initial_state]] = (void*)new_fsa;
    }

    return state_list;
}
```

