namespace FileHashService
{
    public class FileHashService
    {
        private readonly int _concurrencyLimit = 4;
        private readonly HttpClient _httpClient;
        private readonly string _externalApiUrl;
        private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(5);

        public FileHashService(HttpClient httpClient, string externalApiUrl)
        {
            _httpClient = httpClient;
            _externalApiUrl = externalApiUrl;
        }

        [Obsolete("Use ComputeMD5HashAsync instead")]
        public string ComputeMD5Hash(string filePath) => ComputeMD5HashAsync(filePath).Result;

        public async Task<string> ComputeMD5HashAsync(string filePath)
        {
            if (!File.Exists(filePath))
                throw new FileNotFoundException($"File not found: {filePath}");

            using var md5 = MD5.Create();
            await ProcessFileAsync(md5, filePath).ConfigureAwait(false);
            return BitConverter.ToString(md5.Hash).Replace("-", "").ToLowerInvariant();
        }

        private async Task ProcessFileAsync(MD5 md5, string filePath)
        {
            await using var stream = File.OpenRead(filePath);
            await ComputeMD5HashFromStreamAsync(md5, stream).ConfigureAwait(false);
        }

        public string ComputeMD5HashFromStream(Stream stream)
        {
            if (stream == null)
                throw new ArgumentNullException(nameof(stream));

            using var md5 = MD5.Create();
            return BitConverter.ToString(md5.ComputeHash(stream)).Replace("-", "").ToLowerInvariant();
        }

        private async Task ComputeMD5HashFromStreamAsync(MD5 md5, Stream stream)
        {
            await Task.Factory.StartNew(() =>
            {
                var buffer = new byte[4096];
                int read;

                while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
                    md5.TransformBlock(buffer, 0, read, null, 0);

                md5.TransformFinalBlock(new byte[0], 0, 0);
            }, TaskCreationOptions.DenyChildAttach).ConfigureAwait(false);
        }

        private async Task<string> ComputeMD5HashWithExternalService(string filePath)
        {
            var request = new HttpRequestMessage(HttpMethod.Post, _externalApiUrl);
            request.Content = new StreamContent(File.OpenRead(filePath));

            try
            {
                using var response = await _httpClient.SendAsync(request).ConfigureAwait(false);
                response.EnsureSuccessStatusCode();

                return await response.Content.ReadAsStringAsync().ConfigureAwait(false);
            }
            catch (HttpRequestException ex) when (!ex.Message.Contains("No connection"))
            {
                // Retry on network-related exceptions only
                await Task.Delay(_retryInterval).ConfigureAwait(false);
                return ComputeMD5HashWithExternalService(filePath);
            }
        }
    }
}
