using System;
using System.Diagnostics;
using System.IO;
using Microsoft.Extensions.DependencyInjection;
using Serilog;

namespace YourNamespace
{
    public class DynamicApiRunner
    {
        private readonly string _projectDirectory;
        private Process _apiProcess;

        public DynamicApiRunner(string projectDirectory)
        {
            _projectDirectory = projectDirectory;
        }

        public void Start(string[] arguments)
        {
            if (!File.Exists($"{_projectDirectory}/Startup.cs") || !File.Exists($"{_projectDirectory}/program.cs"))
            {
                Log.Error("Invalid project structure: Missing Startup.cs or program.cs.");
                return;
            }

            try
            {
                _apiProcess = new Process();
                var startInfo = new ProcessStartInfo($"{_projectDirectory}/bin/Debug/netcoreappX.X/YourProjectName.dll", string.Join(" ", arguments))
                {
                    WorkingDirectory = _projectDirectory,
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true,
                    RedirectStandardError = true
                };

                _apiProcess.StartInfo = startInfo;
                _apiProcess.Start();
            }
            catch (Exception ex)
            {
                Log.Error($"Failed to start API: {ex}");
            }
        }

        public void Stop()
        {
            if (_apiProcess != null && !_apiProcess.HasExited)
            {
                _apiProcess.Kill();
                _apiProcess = null;
            }
        }
    }
}
