class MockLTEAPI {
public:
    std::mutex mtx;

    void SimulateDelay(std::function<void()> callback) {
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        callback();
    }

    // Mock API function to simulate receiving data
    NFAPI_CRCIndication GetCRCIndication() {
        std::uniform_int_distribution<uint32_t> crcFlagGen(0, 1);
        return { RxUEInformationTag(), RNTI(), CRCIndicationRel8Tag(crcFlagGen(generator)) };
    }

private:
    std::mt19937 generator;
};

class DynamicCRCList {
public:
    void AddEntry(const NFAPI_CRCIndication& entry) {
        std::lock_guard<std::mutex> lock(dataMutex);
        data.push_back(entry);
    }

    NFAPI_CRCIndication GetEntry(size_t index) const {
        std::lock_guard<std::mutex> lock(dataMutex);
        if (index >= data.size()) throw std::out_of_range("Index out of range");
        return data[index];
    }

    void RemoveEntry(size_t index) {
        std::lock_guard<std::mutex> lock(dataMutex);
        if (index >= data.size()) throw std::out_of_range("Index out of range");
        data.erase(data.begin() + index);
    }

private:
    std::vector<NFAPI_CRCIndication> data;
    mutable std::mutex dataMutex;
};

int main() {
    MockLTEAPI api;
    DynamicCRCList list;

    // Simulate receiving data and adding it to the list
    std::function<void()> addDataCallback = [&]() {
        NFAPI_CRCIndication crcIndication = api.GetCRCIndication();
        list.AddEntry(crcIndication);
