}

public static async Task<IWebsite> AddAndStartWebsiteAsync(string directoryPath, string siteName, string applicationPoolName)
{
    if (string.IsNullOrWhiteSpace(directoryPath))
        throw new ArgumentException("Directory path must not be null or empty.", nameof(directoryPath));
    if (string.IsNullOrWhiteSpace(siteName))
        throw new ArgumentException("Site name must not be null or empty.", nameof(siteName));
    if (string.IsNullOrWhiteSpace(applicationPoolName))
        throw new ArgumentException("Application pool name must not be null or empty.", nameof(applicationPoolName));

    var webConfigPath = Path.Combine(directoryPath, "web.config");
    if (!File.Exists(webConfigPath))
        return null;

    var websiteConfigurationServiceClient = new WebsiteConfigurationServiceClient(new HttpClient());

    // Implement the logic for communicating with the IIS configuration service here.

    try
    {
        await websiteConfigurationServiceClient.AddWebsiteAsync(directoryPath, siteName, applicationPoolName);
        await websiteConfigurationServiceClient.StartWebsiteAsync(siteName);

        return new Website
        {
            DirectoryPath = directoryPath,
            SiteName = siteName,
            ApplicationPoolName = applicationPoolName
        };
    }
    catch (Exception ex)
    {
        Console.WriteLine($"An error occurred while adding and starting the website: {ex.Message}");
        return null;
    }
}
