import json
import copy
import logging
from typing import Dict, Callable, Any

class JSONParser:
    def __init__(self):
        self.factories = {}
        self.logger = logging.getLogger(__name__)

    def to_json(self, data: Any) -> str:
        return json.dumps(data)

    def from_json(self, json_string: str) -> 'JSONParser':
        return JSONParser().create_instance('default', json.loads(json_string))

    def add_factory(self, factory_id: str, factory_function: Callable[[Dict], Any]):
        self.factories[factory_id] = factory_function

    def create_instance(self, factory_id: str, json_dict: Dict) -> 'JSONParser':
        if factory_id not in self.factories:
            raise KeyError(f'Invalid factory ID: {factory_id}')

        try:
            factory_function = self.factories[factory_id]
            return factory_function({k: v for (k, v) in json_dict.items() if k != '__class__'})
        except Exception as e:
            self.logger.error(f'Error creating instance: {e}')
            raise e
