typedef struct PluginPluginData {
    void* handle;
    char name[256];
    int version;
    enum PluginState {PLUGIN_STATE_UNLOADED, PLUGIN_STATE_LOADED, PLUGIN_STATE_ERROR} state;
} PluginData;

// A cache structure to store plugin data and metadata
typedef struct PluginCache {
    sem_t cacheLock; // mutex for concurrent access
    unsigned long long loadCount; // number of times a plugin was loaded since the last invalidation
    time_t lastInvalidated; // timestamp of last cache invalidation
    PluginData* plugins[MAX_PLUGINS]; // array of plugin data pointers
} PluginCache;

// Function prototypes for various library functions
PluginData* loadPlugin(const char* path);
void unloadPlugin(PluginData* plugin);
const PluginData* getPluginByName(const char* name);
void invalidatePluginCache();

// Define a global instance of the plugin cache and initialize it
extern PluginCache g_pluginCache;

// Load plugins at startup or on demand, with caching and configurable cache invalidation policies
void loadPlugins() {
    // Access the configuration database to get plugin paths
    char* pluginPaths[MAX_PLUGINS];
    int numPlugins = getPluginPaths(pluginPaths);

    // Initialize the plugin cache
    sem_init(&g_pluginCache.cacheLock, 0, 1);
    g_pluginCache.loadCount = 0;
    g_pluginCache.lastInvalidated = time(NULL);

    // Load each plugin and store it in the cache
    for (int i = 0; i < numPlugins; ++i) {
        PluginData* plugin = loadPlugin(pluginPaths[i]);
        if (plugin != NULL) {
            addToCache(plugin);
        }
    }
}

// Util functions to manage the plugin cache
void addToCache(PluginData* plugin) {
    // Lock the cache and check for duplicate entries
    sem_wait(&g_pluginCache.cacheLock);
    if (findInCache(plugin->name) == NULL) {
        g_pluginCache.plugins[getNextEmptySlot()] = plugin;
        updatePluginState(plugin, PLUGIN_STATE_LOADED);
    }
    sem_post(&g_pluginCache.cacheLock);
}

PluginData* findInCache(const char* name) {
    // Lock the cache and search for a plugin by its name
    PluginData* result = NULL;
    sem_wait(&g_pluginCache.cacheLock);
    for (int i = 0; i < MAX_PLUGINS; ++i) {
        if (g_pluginCache.plugins[i] != NULL && strcmp(g_pluginCache.plugins[i]->name, name) == 0) {
            result = g_pluginCache.plugins[i];
            break;
        }
    }
    sem_post(&g_pluginCache.cacheLock);
    return result;
}
