#include <string>
#include <chrono>
#include <thread>
#include <mutex>

std::forward_list<std::string> myList;
std::mutex mutex;
int max_attempts = 10;

void dynamicInsert(const std::string& search, const std::string& insert) {
    // Implement the function to dynamically insert a node containing the given string after the first occurrence of another specified string.
    std::unique_lock<std::mutex> lock(mutex);
    auto it = myList.begin();
    int attempts = 0;
    for (; it != myList.end(); ++it) {
        if (*it == search) {
            myList.insert_after(it, insert);
            // Log the successful insertion
            break;
        }
        if (++attempts >= max_attempts) {
            std::cerr << "Insertion attempt failed after " << max_attempts << " attempts" << std::endl;
            return;
        }
    }
}
