```javascript
import { Cache, FileSystemCache } from './cache';
import { JestMock } from './jest-mock';
import fetch from 'node-fetch';
import { parallel, series } from 'async';

class TestRunner {
  constructor(moduleName, testCases, parallel = false, configServiceUrl = null) {
    this.moduleName = moduleName;
    this.testCases = testCases;
    this.parallel = parallel;
    this.configServiceUrl = configServiceUrl || null;
    this.cache = new FileSystemCache(`./test_results/${moduleName}`);
    this.jestMock = new JestMock();
  }

  async run() {
    // Fetch test configurations if provided
    const configs = this.configServiceUrl ? await (await fetch(this.configServiceUrl)).json() : [];
    const tests = this.getTests(configs);

    try {
      // Setup environment
      console.log(`Setting up environment for ${this.moduleName}`);

      // Load the module using import syntax
      const { [this.moduleName]: module } = await import(this.moduleName);

      // Execute tests
      const results = await this.executeTests(tests);

      // Teardown environment
      console.log(`Tearding down environment for ${this.moduleName}`);

      // Summarize the test results
      console.log(`\nSummary:\n`);
      console.log(`Module: ${this.moduleName}\nPassed: ${results.passed}\nFailed: ${results.failed}\n`);
    } catch (error) {
      console.error(`Error while running tests for ${this.moduleName}:`, error);
    } finally {
      // Clean up after each test run to prevent memory leaks
      this.jestMock.resetAll();
      await this.cache.cleanUp();
    }
  }

  getTests(configs) {
    return this.testCases.map((testCase) => {
      const { label, testFunc } = testCase;
      const config = configs.find((c) => c.test === label);
      return { label, testFunc: testFunc.bind(null, config), skip: config?.skip, retry: config?.retry };
    });
  }

  async executeTests(tests) {
    let passed = 0;
    let failed = 0;

    // Execute tests in parallel or sequentially based on the 'parallel' flag
    const executeTest = this.parallel ? series : parallel;

    return executeTest(
      tests.map(async (test) => {
        console.log(`Executing test: ${test.label}`);
        const startTime = Date.now();
        let result;
        try {
          // Set up jest mock before each test
          this.jestMock.reset(this.moduleName, test.label);

          // Execute the test function and handle any errors gracefully
          result = await test.testFunc();
        } catch (error) {
          console.error(`Test '${test.label}' failed with error:`, error);
          failed++;
          throw error;
        } finally {
          const endTime = Date.now();
          const duration = endTime - startTime;
          console.log(`Test '${test.label}' completed in ${duration}ms${result ? ' (passed)' : ' (failed)'}`);

          // Cache the test result based on its outcome and module file modification timestamp
          await this.cache.storeResult(this.moduleName, test.label, result, Date.now());

          if (!test.skip && !result) failed++;
          else passed++;
        }
      })
    );
  }
