import com.google.common.cache.*;

public class UserSessionCache {

    private final Cache<Long, UserSession> userSessionCache;
    private final AuthenticationAPI authenticationAPI;
    private final int ttlSeconds;
    private final RemovalListener<Long, UserSession> removalListener;

    public UserSessionCache(AuthenticationAPI authenticationAPI, int ttlSeconds) {
        this.authenticationAPI = authenticationAPI;
        this.ttlSeconds = ttlSeconds;
        RemovalListener<Long, UserSession> listener = (naturalId, userSession) -> {
            if (!userSession.isExpired()) {
                logSessionEviction(userSession);
            }
        };
        LoadingCache<Long, UserSession> cacheBuilder = CacheBuilder.newBuilder()
                .expireAfterAccess(Duration.ofSeconds(ttlSeconds))
                .removalListener(listener)
                .maximumSize(unlimited())
                .weakValues();
        userSessionCache = cacheBuilder.build(new CacheLoader<Long, UserSession>() {
            @Override
            public UserSession load(Long id) throws Exception {
                UserSession session = validateTokenAndUpdateState(id);
                return session;
            }
        });
    }

    private void logSessionEviction(UserSession session) {
        // Implement a logging mechanism of your choice here.
    }

    private UserSession validateTokenAndUpdateState(Long id) {
        boolean validated = authenticationAPI.validateSessionToken(id);
        if (!validated) {
            logSessionValidationFailure(id);
            return new UserSession(id, "", Instant.now(), UserSessionState.INVALID);
        }
        // Update the session state accordingly.
        // ...
        return new UserSession(id, authenticationAPI.getSessionToken(id), Instant.now(), UserSessionState.ACTIVE);
    }

    private void logSessionValidationFailure(Long id) {
        // Implement a logging mechanism of your choice here.
    }

    public UserSession getUserSession(Long id) {
        return userSessionCache.getIfPresent(id);
    }

    public void putUserSession(Long id, UserSession session) {
        userSessionCache.put(id, session);
    }
}
