```csharp
using System;
using System.Data;
using System.Data.SqlClient;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public static class DatabaseQueryExecutor
{
    private static readonly string _connectionString;
    private static SqlConnection _connection;
    private static ILogger<DatabaseQueryExecutor> _logger;

    static DatabaseQueryExecutor()
    {
        // Initialize connection pool and logging system here.
    }

    public static async Task<IDataReader> ExecuteParameterizedQueryAsync(string sqlTemplate, List<object> parameters, string connectionString = null, SqlTransaction transaction = null)
    {
        if (string.IsNullOrEmpty(_connectionString)) _connectionString = connectionString;

        // Ensure the SQL template and parameter list have a matching length.
        if (sqlTemplate.Count(c => c == '@') != parameters.Count)
            throw new ArgumentException("SQL Template and Parameter List must have the same number of placeholders and values.");

        using (var connection = new SqlConnection(_connectionString))
        {
            await using var command = CreateCommand(sqlTemplate, parameters, transaction, connection);

            try
            {
                // Open the connection if it's not already open.
                if (connection.State != ConnectionState.Open) await connection.OpenAsync();

                return await command.ExecuteReaderAsync();
            }
            catch (Exception ex)
            {
                _logger?.LogError(ex, "An error occurred while executing the query.");
                throw;
            }
        }
    }

    private static SqlCommand CreateCommand(string sqlTemplate, List<object> parameters, SqlTransaction transaction = null, SqlConnection connection = null)
    {
        var command = new SqlCommand(sqlTemplate, connection ?? _connection);
        if (transaction != null) command.Transaction = transaction;

        // Bind the parameters to the command.
        for (var i = 0; i < sqlTemplate.Count(c => c == '@'); i++)
            command.Parameters.Add($"@param{i}", parameters[i]);

        return command;
    }
}
```

