#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef void* (*CallbackFunction)(long offset, int key, double probability, Record* record);

struct InitParams {
    size_t num_records;
    long max_offset;
    int min_key, max_key;
    double min_probability, max_probability;
    CallbackFunction callback;
};

static pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;

void* init(void* params) {
    struct InitParams* init_params = params;
    long* offsets = NULL;
    int* keys = NULL;
    double* probabilities = NULL;
    Record* records = NULL;

    // Memory allocation and initialization
    offsets = malloc(init_params->num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    keys = malloc(init_params->num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    probabilities = malloc(init_params->num_records * sizeof(double));
    if (!probabilities) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    records = calloc(init_params->num_records, sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        free(probabilities);
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    // Initialization and validation loop
    pthread_mutex_lock(&init_mutex);
    int valid = 0;
    while (!valid) {
        for (size_t i = 0; i < init_params->num_records; ++i) {
            offsets[i] = rand() % init_params->max_offset;
            keys[i] = rand() % (init_params->max_key - init_params->min_key + 1) + init_params->min_key;
            probabilities[i] = ((double)rand() / RAND_MAX) * (init_params->max_probability - init_params->min_probability) + init_params->min_probability;
        }
        valid = init_params->callback(offsets, keys, probabilities, records);
    }
    pthread_mutex_unlock(&init_mutex);

    return malloc((4 * sizeof(void*)) + (init_params->num_records * sizeof(Record)));
}

void free_arrays(void* arrays) {
    long* offsets = arrays;
    int* keys = offsets + init_params->num_records;
    double* probabilities = keys + init_params->num_records;
    Record* records = probabilities + init_params->num_records;

    free(offsets);
    free(keys);
    free(probabilities);
    free(records);
}
```

