Here's a simplified example of how you could structure your Node.js module following the requirements provided. Please note that this example does not include all aspects such as handling large volumes of commands or external API integration, but it should give you a good starting point.

```javascript
const fs = require('fs');
const { promisify } = require('util');
const chalk = require('chalk');
const dotenv = require('dotenv');
const axios = require('axios');
const commandQueue = new Map();
const maxConcurrency = 5; // Set your desired maximum concurrency limit here

// Load environment variables from .env file and API configuration
dotenv.config();
const config = await axios.get(`${process.env.API_URL}/configuration`).catch(err => {
  console.error(chalk.red("Error fetching configuration:"), err);
});

// Helper function to execute a command and output the result to a file
const execCommand = async (command, args, env) => {
  const id = Date.now(); // Unique ID for this command execution

  if (commandQueue.has(id)) return console.log(`Command with ID ${id} is already running.`);

  commandQueue.set(id, true);

  try {
    const { stdout } = await promisify(require('child_process').exec)(command + ' ' + args.join(' '), { env });
    fs.writeFileSync(`output_${id}.txt`, stdout);
    console.log(chalk.green(`Command with ID ${id} completed successfully. Output saved as output_${id}.txt`));
  } catch (err) {
    console.error(chalk.red(`Error executing command with ID ${id}: `), err);

    // Retry if configuration allows it and the command is not already retrying
    if (config && config.data.retry_on_failure && !commandQueue.get(id)?.retry) {
      setTimeout(() => execCommand(command, args, env), config.data.retry_interval);
      commandQueue.set(id, {...commandQueue.get(id), retry: true});
    } else {
      commandQueue.delete(id);
    }
  } finally {
    // Decrease concurrency count and check if any other commands can start
    commandQueue.set(id, false);
    if (commandQueue.size < maxConcurrency && commandQueue.has('pending')) commandQueue.get('pending')();
  }
};

// Function to add a new command to the queue
const addCommandToQueue = (command, args, env) => {
  if (!command || !args.length) throw new Error("Invalid command or arguments");

  const pendingId = Date.now(); // Unique ID for this command request
  commandQueue.set(pendingId, () => execCommand(command, args, env));

  // Start executing a command if the current concurrency limit is not met
  if (commandQueue.size <= maxConcurrency) commandQueue.get(pendingId)();
};

module.exports = { addCommandToQueue };
```

This example defines an `addCommandToQueue` function that accepts a command, arguments, and environment variables, adds it to a concurrent queue with retry support if configured, and handles logging and error reporting. The module exports this single function for use in other modules or applications.

