Here's a skeleton code for the Python-based Configuration Manager, focusing on key aspects like dynamic loading/saving from an external RESTful API, JSON support with custom types, concurrent processing, error handling, and modular design:

```python
import json
import time
import requests
import threading
from collections import defaultdict
from datetime import datetime
from uuid import UUID, uuid4
from ipaddress import IPv4Address, IPv6Address
import sys

class ConfigurationManager:
    def __init__(self, api_url):
        self.api_url = api_url
        self.tenants = defaultdict(lambda: {})
        self.lock = threading.Lock()

    def _get_config(self, tenant_id):
        # Integration with the external configuration service
        response = requests.get(f"{self.api_url}/{tenant_id}")
        if not response.ok:
            return None
        config_data = response.json()
        custom_types = {"datetime": datetime, "IP address": IPv4Address, "UUID": UUID}
        for key, value in config_data.items():
            if isinstance(value, str) and key in custom_types:
                config_data[key] = custom_types[key](value)
        return config_data

    def load_configs(self):
        with self.lock:
            for tenant_id in self.tenants:
                config = self._get_config(tenant_id)
                if config:
                    self.tenants[tenant_id].update(config)

    def save_config(self, tenant_id, config):
        # Save the configuration to the external RESTful API
        requests.put(f"{self.api_url}/{tenant_id}", json=config)

    def get_config(self, tenant_id, key=None):
        with self.lock:
            config = self.tenants[tenant_id]
            if key:
                return config[key]
            return config

    def set_config(self, tenant_id, key, value):
        with self.lock:
            self.tenants[tenant_id][key] = value
            self.save_config(tenant_id, self.tenants[tenant_id])

    def list_tenants(self):
        return list(self.tenants.keys())

class CommandLineInterface:
    def __init__(self, config_manager):
        self.config_manager = config_manager

    def interactive_mode(self):
        while True:
            command = input("Enter a command (list, get, set, save, load, quit): ").lower()
            if command == "quit":
                break
            args = command.split()
            if len(args) < 2:
                print("Invalid command")
                continue
            action, tenant_id = args[0], args[1]
            if action in ("list", "get", "set"):
                key = None
                if len(args) > 3:
                    key = args[2]
                result = getattr(self.config_manager, action)(tenant_id, key)
                print(result)
            elif action == "save":
                config = {}
                for i, arg in enumerate(args[2:], start=1):
                    if len(arg.split("=")) != 2:
                        print(f"Invalid argument {i}")
                        continue
                    key, value = arg.split("=")
                    config[key] = value
                self.config_manager.set_config(tenant_id, **config)
            elif action == "load":
                self.config_manager.load_configs()
            else:
                print("Invalid command")

    def non_interactive_mode(self):
        for line in sys.stdin:
            command = line.strip().split()
            if not command or command[0] == "quit":
                break
            action, tenant_id = command[0], command[1]
            if len(command) > 3:
                key = command[2]
            result = getattr(self, action)(tenant_id, key)
            print(result)
```

