        if (primaryTheme != null) {
            callback(primaryTheme)
            return
        }

        apiService1.enqueue(object : Callback() {
            override fun onFailure(call: Call, e: IOException) {
                apiService2.enqueue(object : Callback() {
                    override fun onFailure(call: Call, e: IOException) {
                        callback(null)
                    }

                    override fun onResponse(call: Call, response: Response) {
                        val themeJson = response.body!!.string()
                        val themeBitmap = Gson().fromJson(themeJson, Bitmap::class.java)
                        primaryCache.put(key, themeBitmap)
                        callback(themeBitmap)
                    }
                })
            }

            override fun onResponse(call: Call, response: Response) {
                val themeJson = response.body!!.string()
                val themeBitmap = Gson().fromJson(themeJson, Bitmap::class.java)
                primaryCache.put(key, themeBitmap)
                callback(themeBitmap)
            }
        })
