    }
}

class SoftReferenceCache<K, V> {
    private val map = HashMap<K, SoftReference<V>>()

    fun get(key: K): V? {
        return map[key]?.get()
    }

    fun put(key: K, value: V) {
        map[key] = SoftReference(value)
    }
}
