State* traverseFSAToNextState(int *states, int num_states, FSA *fsa, int current_state, int transition_symbol, LoggingSystem *logging_system); {
    pthread_mutex_lock(&fsa->mutex); // Lock the mutex for thread safety

    State* current = &states[current_state];
    State* new_state_list = NULL;
    State* new_state = NULL;

    while (current != NULL) {
        if (fsa_transition_condition(current, transition_symbol)) { // Assuming you have a function to check the transition condition
            if (new_state == NULL) {
                new_state = malloc(sizeof(State));
                if (new_state == NULL) {
                    perror("Out of memory");
                    pthread_mutex_unlock(&fsa->mutex);
                    return NULL;
                }

                // Initialize the new state with necessary data structures for FSA transitions and labels
                new_state->id = fsa_getNextStateId(current, transition_symbol);
                new_state->next = NULL;
            }

            if (new_state_list != NULL) {
                new_state->next = new_state_list;
                new_state_list = new_state;
            } else {
                new_state_list = new_state;
            }

            logStateChange(logging_system, current_state, new_state->id); // Update the logging system with state changes
        }

        current = current->next;
    }

    if (new_state_list != NULL) {
        pthread_mutex_unlock(&fsa->mutex);
        return new_state_list;
    } else {
        perror("No valid transition found for the given state and symbol");
        pthread_mutex_unlock(&fsa->mutex);
        return NULL;
    }
}
