from databases import Database, ConnectionPoolSettings
from aiohttp import ClientSession
import requests
from datetime import datetime

class TemperatureSensorReading:
    def __init__(self, sensor_id, temperature=None):
        self.sensor_id = sensor_id
        self.temperature = temperature or 25.0
        self.last_update = datetime.now()

class SmartBuildingDatabase:
    def __init__(self, url, username, password, max_overflow=0):
        self.engine = create_engine(url, connect_args={"username": username, "password": password}, pool_size=max_overflow)
        self.Connection = sessionmaker(bind=self.engine)

    def add_sensor_reading(self, sensor_reading):
        with self.Connection() as session:
            session.add(sensor_reading)
            session.commit()

class WeatherService:
    def __init__(self, api_key):
        self.api_key = api_key

    async def get_weather_data(self):
        url = "http://api.openweathermap.org/data/2.5/weather?q=London&appid={}"
        response = await ClientSession().get(url.format(self.api_key))
        return response.json()

class TemperatureSensorManager:
    def __init__(self, db, weather_service):
        self.db = db
        self.weather_service = weather_service
        self.cached_weather_data = None
        self.cached_sensor_readings = {}
        self._fallback_temperature = 25.0

    def get_current_weather(self):
        if not self.cached_weather_data:
            asyncio.run(self.refresh_weather_data())
        return self.cached_weather_data

    async def refresh_weather_data(self):
        try:
            data = await self.weather_service.get_weather_data()
            self.cached_weather_data = data
        except Exception as e:
            logging.error(f"Error fetching weather data: {e}")

    def get_sensor_reading(self, sensor_id):
        if sensor_id not in self.cached_sensor_readings:
            with ThreadPoolExecutor() as executor:
                try:
                    future = executor.submit(self._fetch_sensor_data, sensor_id)
                    while not future.done():
                        time.sleep(1)
                    sensor_data = future.result()
                except Exception as e:
                    logging.error(f"Error fetching sensor data for sensor {sensor_id}: {e}")
                    sensor_data = None
            if not sensor_data:
                self.cached_sensor_readings[sensor_id] = TemperatureSensorReading(sensor_id, self._fallback_temperature)
            else:
                self.cached_sensor_readings[sensor_id] = sensor_data
        return self.cached_sensor_readings[sensor_id]

    def _fetch_sensor_data(self, sensor_id):
        with ConnectionPoolSettings(max_size=50, min_size=10).create_for_url("postgresql://user:pass@localhost/db") as pool:
            connection = pool.connect()
            result = connection.execute("SELECT * FROM temperature_sensor_readings WHERE sensor_id={} ORDER BY last_update DESC LIMIT 1".format(sensor_id)).first()
            if not result:
                self.cached_sensor_readings[sensor_id] = TemperatureSensorReading(sensor_id, self._fallback_temperature)
            else:
                self.cached_sensor_readings[sensor_id] = TemperatureSensorReading(result.sensor_id, result.temperature)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    db = SmartBuildingDatabase("postgresql://user:pass@localhost/db", "username", "password")
    weather_service = WeatherService("apikey")
    manager = TemperatureSensorManager(db, weather_service)
