```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using Microsoft.EntityFrameworkCore;

// Assuming you have an existing DbContext named AppDbContext and User model with properties Id, Salt, PasswordHash
public class PasswordManager
{
    private readonly AppDbContext _context;
    private readonly HashAlgorithm _hashAlgorithm;

    public PasswordManager(AppDbContext context)
    {
        _context = context;
        _hashAlgorithm = BCrypt.Net.BCrypt.Create(); // Using BCrypt for hashing
    }

    public async Task StorePasswordAsync(string userId, string password)
    {
        var salt = RandomNumberGenerator.GetBytes(16);
        var passwordWithSalt = Combine(password, salt);
        var hashedPasswordWithSalt = _hashAlgorithm.HashPassword(passwordWithSalt);

        await UsingTransactionAsync(() =>
        {
            var user = await _context.Users.FindAsync(userId);
            if (user == null)
                throw new Exception($"User with ID '{userId}' not found.");

            user.Salt = salt;
            user.PasswordHash = hashedPasswordWithSalt;
            return Task.CompletedTask;
        });
    }

    public async Task<bool> VerifyPasswordAsync(string userId, string password)
    {
        var user = await _context.Users.FindAsync(userId);
        if (user == null)
            throw new Exception($"User with ID '{userId}' not found.");

        var hashedPasswordWithSaltFromDb = Combine(user.PasswordHash, user.Salt);
        return _hashAlgorithm.Verify(password, hashedPasswordWithSaltFromDb);
    }

    public async Task UpdatePasswordAsync(string userId, string newPassword)
    {
        var (oldHashedPasswordWithSalt, salt) = await GetStoredPasswordAsync(userId);
        var newHashedPasswordWithSalt = HashAndSaltNewPassword(newPassword, salt);

        await UsingTransactionAsync(() =>
        {
            var user = await _context.Users.FindAsync(userId);
            if (user == null)
                throw new Exception($"User with ID '{userId}' not found.");

            user.Salt = salt;
            user.PasswordHash = newHashedPasswordWithSalt;
            return Task.CompletedTask;
        });
    }

    private async Task<(byte[] hashedPasswordWithSalt, byte[] salt)> GetStoredPasswordAsync(string userId)
    {
        var user = await _context.Users.FindAsync(userId);
        if (user == null)
            throw new Exception($"User with ID '{userId}' not found.");

        return (user.PasswordHash, user.Salt);
    }

    private byte[] HashAndSaltNewPassword(string password, byte[] salt) => Combine(password, salt).HashPassword(_hashAlgorithm);

    private static T UsingTransactionAsync<T>(Func<Task<T>> action)
    {
        using var transaction = _context.Database.BeginTransaction();
        try
        {
            return await action();
        }
        catch (Exception ex)
        {
            transaction.Rollback();
            throw ex;
        }
    }

    private static byte[] Combine(string first, byte[] second) => Encoding.UTF8.GetBytes($"{first}:{Convert.ToBase64String(second)}");
}
```

This code uses the `BCrypt.Net-3.1` library for hashing and salting, and assumes you have an existing `DbContext` named `AppDbContext` with a user model that contains properties `Id`, `Salt`, and `PasswordHash`. The function handles potential exceptions during database operations and hashing processes by using transactions and catches any exceptions when rolling back the transaction if an error occurs.

The `StorePasswordAsync`, `VerifyPasswordAsync`, and `UpdatePasswordAsync` methods allow for secure password storage, verification, and updating respectively. Note that you will need to replace `BCrypt.Net.BCrypt.Create()` with the desired hash algorithm implementation if needed.

