namespace po = boost::program_options;
namespace fs = boost::filesystem;
using json = nlohmann::json;

struct Config {
    std::string logLevel;
    std::string logFileFormat;
    std::string rotationPolicy;
    std::string outputDir;
};

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help,h", "Display this help message")
        ("config,c", po::value<std::string>(), "Path to the JSON configuration file")
        ("loglevel,l", po::value<std::string>(), "Log level (DEBUG, INFO, WARNING, ERROR)")
        ("file,f", po::value<std::string>(), "Log file name")
        ("output-dir,o", po::value<std::string>(), "Output directory for log files");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 0;
    }

    Config config;
    try {
        json j;
        fs::path p(vm["config"].as<std::string>());
        std::ifstream i(p);
        i >> j;

        config.logLevel = j["logLevel"].get<std::string>();
        config.logFileFormat = j["logFileFormat"].get<std::string>();
        config.rotationPolicy = j["rotationPolicy"].get<std::string>();
        config.outputDir = j["outputDir"].get<std::string>();
    } catch (const fs::filesystem_error& e) {
        std::cerr << "Error reading configuration file: " << e.what() << "\n";
        return 1;
    } catch (const json::exception& e) {
        std::cerr << "Error parsing JSON configuration: " << e.what() << "\n";
        return 1;
    }

    spdlog::set_pattern("%Y-%m-%d %H:%M:%S %z [%^%L%$] %v");
    auto logger = spdlog::rotating_logger("global_logger",
                                          config.outputDir,
                                          std::stoul(config.rotationPolicy),
                                          config.logFileFormat);
    if (!vm["file"].is_not_present()) {
        logger->set_filename(vm["file"].as<std::string>());
    }
    logger->set_level(get_spdlog_level_from_str(config.logLevel));

    spdlog::initializer initializer; // Ensure thread safety

    // Your application logic here...

    return 0;
}

spdlog::level::level_enum get_spdlog_level_from_str(const std::string& level) {
    if (level == "DEBUG") return spdlog::level::debug;
    if (level == "INFO") return spdlog::level::info;
    if (level == "WARNING") return spdlog::level::warn;
    if (level == "ERROR") return spdlog::level::err;
    throw std::runtime_error("Invalid log level: " + level);
}
