```java
package com.example;

import java.time.*;
import java.util.*;
import java.nio.file.*;
import java.sql.*;
import com.opencsv.CSVReader;
import org.apache.commons.compress.utils.IOUtils;

public class BatchLogProcessor {
    private static final int MAX_ARCHIVE_SIZE = 10 * (1024 * 1024); // 10MB
    private static final String[] LOG_FILTERS = {"ERROR", "FATAL"};

    public void process() throws IOException, SQLException {
        List<String> logs = new ArrayList<>();
        CSVReader reader = new CSVReader(new FileReader("logs.csv"));

        String line;
        while ((line = reader.readNext()) != null) {
            String[] logData = line.split(",");

            if (ArrayUtils.contains(LOG_FILTERS, logData[1]) && LocalDateTime.parse(logData[0]).isAfter(LocalDateTime.now().minusHours(24))) {
                logs.add(line);
            }
        }

        if (!logs.isEmpty()) {
            Path archiveFile = Files.createTempFile("log_archive", ".gz");
            try (GZIPOutputStream gzipOut = new GZIPOutputStream(Files.newOutputStream(archiveFile))) {
                for (String log : logs) {
