using System.Globalization;
using System.Compression.GZip;
using OpenSsh;
using MailKit;
using MailKit.Net.Smtp;

namespace BatchLogProcessor
{
    class Program
    {
        static int MAX_ARCHIVE_SIZE = 10 * (1024 * 1024); // 10MB
        static string[] LOG_FILTERS = {"ERROR", "FATAL"};

        static void Main(string[] args)
        {
            var logs = new List<string>();
            using (var reader = new StreamReader("logs.csv"))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    var logData = line.Split(',');

                    if (Array.IndexOf(LOG_FILTERS, logData[1]) >= 0 && DateTime.ParseExact(logData[0], "yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture).AddHours(-24) < DateTime.Now)
                    {
                        logs.Add(line);
                    }
                }
            }

            if (logs.Count > 0)
            {
                using (var archiveFile = File.Create("log_archive.gz"))
                using (var gzipStream = new GZipStream(archiveFile, CompressionLevel.Optimal))
                {
                    foreach (var log in logs)
                    {
                        var bytes = Encoding.UTF8.GetBytes(log);
                        gzipStream.Write(bytes, 0, bytes.Length);
                        gzipStream.WriteByte('\n');
                    }
                }

                if (new FileInfo("log_archive.gz").Length > MAX_ARCHIVE_SIZE)
                {
                    // Notify stakeholders via email
                    SendEmail("Archive exceeds size threshold");
                }
                else
                {
                    using (var client = new SftpClient("remote-server", "username", "password"))
                    {
                        client.Connect();
                        // Upload the archive file to AWS S3 using SFTP
                    }
                }
            }
