    this.db = new sqlite3.Database('./data.db', (err) => {
      if (err) throw err;
      console.log("Connected to SQLite database.");
    });

    // Initialize WebSocket connection
    this.wss = new WebSocket.Server({ port: 8080 });

    // Subscribe to events
    this.wss.on('connection', (ws) => {
      ws.on('message', (data) => this.handleData(JSON.parse(data)));
    });
  }

  async handleData({file, type, priority}) {
    try {
      // Handle large files using streaming approach
      const hash = await hashFile(file);
      // Compress data and send to API (replace with your API calls)
      const response = await axios.post('https://api.example.com/upload', {hash, file});

      // Store data locally and in SQLite database
      this.storeData({file, hash, type, priority});
    } catch (error) {
      console.error(`Error handling data: ${error}`);
    }
  }

  storeData(data) {
    const stmt = this.db.prepare('INSERT INTO data VALUES (?, ?, ?, ?)');
