```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using StackExchange.Redis;
using Microsoft.Extensions.Configuration;
using Microsoft.AspNetCore.WebApi.Client;

namespace FileProcessingService
{
    public class FileProcessingService : IFileProcessingService
    {
        private readonly IConnectionMultiplexer _redis;
        private readonly HttpClient _httpClient;
        private readonly IConfiguration _configuration;

        public FileProcessingService(IConnectionMultiplexer redis, HttpClient httpClient, IConfiguration configuration)
        {
            _redis = redis;
            _httpClient = httpClient;
            _configuration = configuration;
        }

        private IDatabase Cache => _redis.GetDatabase();

        public async Task<Map<string, string>> ProcessFileAsync(string filePath)
        {
            var jsonData = await ReadFileAsStringAsync(filePath);
            return ParseJsonData(jsonData);
        }

        private async Task<string> ReadFileAsStringAsync(string filePath)
        {
            if (!File.Exists(filePath)) throw new FileNotFoundException("The specified file does not exist.", filePath);
            using var reader = new StreamReader(filePath, new UTF8Encoding(false));
            return await reader.ReadToEndAsync();
        }

        private async Task<Map<string, string>> ParseJsonData(string jsonData)
        {
            dynamic parsedData = JsonConvert.DeserializeObject(jsonData);
            var result = new Dictionary<string, string>();
            foreach (var endpoint in _configuration["Endpoints"])
            {
                if (!TryProcessEndpointAsync(endpoint, jsonData, result)) continue;
                break;
            }
            return result;
        }

        private async Task<bool> TryProcessEndpointAsync(string endpointConfig, string jsonData, Dictionary<string, string> results)
        {
            var apiKey = _configuration[$"Endpoints:{endpointConfig}:ApiKey"];
            var cacheKey = $"{endpointConfig}:json_data";
            var processedData = Cache.GetString(cacheKey);

            if (!string.IsNullOrEmpty(processedData))
                results[endpointConfig] = JsonConvert.DeserializeObject<JObject>(processedData)[_configuration[$"Endpoints:{endpointConfig}:key"]].ToString();
            else
            {
                var request = new HttpRequestMessage(HttpMethod.Get, endpointConfig);
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);
                using var response = await _httpClient.SendAsync(request);
                if (!response.IsSuccessStatusCode) return false;

                processedData = await response.Content.ReadAsStringAsync();
                results[endpointConfig] = JsonConvert.DeserializeObject<JObject>(processedData)[_configuration[$"Endpoints:{endpointConfig}:key"]].ToString();

                Cache.KeyExpire(cacheKey, TimeSpan.FromMinutes(_configuration.GetValue<int>("CacheExpiryMinutes")));
                Cache.StringSet(cacheKey, processedData);
            }
            return true;
        }

