2. Node.js Application: `marketDataCollector.js`

```javascript
const config = require('./config');
const axios = require('axios');
const redis = require('redis');
const { Worker, isMainThread } = require('worker_threads');

const client = redis.createClient({ host: config.REDIS_HOST, port: config.REDIS_PORT });
const apiKey = process.env[`API_KEY_${config.API_ENDPOINT}`];

class MarketDataCollector {
  constructor(market, interval) {
    this.market = market;
    this.interval = interval;
  }

  async start() {
    const streamUrl = `${config.API_ENDPOINT}/${this.market}`;
    let lastRequestTime = Date.now();

    function handleStream(data) {
      // Process the data here
      client.set(`last_request_time:${this.market}`);
      this.emit('data', data);
    }

    async function fetchData() {
      if (Date.now() - lastRequestTime < this.interval) return;

      try {
        const response = await axios.get(streamUrl, { headers: { 'Authorization': `Bearer ${apiKey}` } });
        handleStream(response.data);
        lastRequestTime = Date.now();
      } catch (error) {
        console.error(`Error fetching market data for ${this.market}:`, error);
      }
    }

    this._intervalId = setInterval(fetchData, this.interval);

    if (isMainThread) {
      client.on('message', handleStream.bind(this));
      return;
    }

    this.on('data', handleStream.bind(this));
  }

  stop() {
    clearInterval(this._intervalId);
  }
}

// Example usage:
const markets = ['AAPL', 'GOOGL'];
const collectors = [];
markets.forEach(market => collectors.push(new MarketDataCollector(market, config.COLLECTION_INTERVAL)));

collectors.forEach(collector => collector.start());
```

