2. Implement the function for inserting a node after the first occurrence of a specified string:

```cpp
std::forward_list<ForwardListNode>* insertNodeAfter(std::forward_list<ForwardListNode>& list, const std::string& target, const std::string& newData) {
    ForwardListNode* current = list.begin();
    ForwardListNode newNode{newData, nullptr};

    // Iterate through the list and find the node containing target string
    while (current != list.end() && current->data != target) {
        current = current->next;
    }

    if (current == list.end()) {
        // Handle error - target not found
        return nullptr;
    }

    newNode.next = current->next;
    current->next = &newNode;

    return &list;
}
```

