                throw e;
            }
        } catch (InterruptedException e) {
            LOGGER.warn("Interrupted while acquiring lock, retrying.");
        }
    }

    private Lock acquireLock() throws InterruptedException {
        int hashCode = this.getClass().hashCode();
        return LOCKS.get(hashCode % Runtime.getRuntime().availableProcessors());
