// Parse and validate email function
std::mutex email_mutex;
bool parseAndValidateEmail(const std::string& email) {
    std::regex email_regex(R"(([\w\.\-]+)@([\w\-]+\.)+([\w]{2,}))");
    if (std::regex_match(email, email_regex)) {
        size_t at_pos = email.find('@');
        size_t dot_pos = email.find('.', at_pos + 1);
        return at_pos != std::string::npos && dot_pos != std::string::npos &&
               dot_pos - at_pos > 1 && email.size() <= MAX_EMAIL_SIZE;
    }
    return false;
}

// Load and deserialize data from binary file
System::Runtime::Serialization::Formatters::Binary::BinaryFormatter formatter;
std::unique_ptr<MyData> loadFromFile(const std::filesystem::path& path) {
    std::ifstream ifs(path, std::ios::binary | std::ios::ate);
    if (!ifs) return nullptr;
    auto size = ifs.tellg();
    ifs.seekg(0);
    std::vector<char> buffer(size_t(size));
    ifs.read(reinterpret_cast<char*>(buffer.data()), size);
    return formatter.Deserialize<MyData>(std::move(buffer));
}

