public:
    SandeshClient(int maxConcurrentRequests) : m_ioService(), m_queue(maxConcurrentRequests), m_maxRequests(maxConcurrentRequests) {}

    void makeRequest(const std::string& url, const std::function<void(b::beast::http::response<b::beast::http::string_body>)>& callback) {
        if (m_queue.enqueue(callback)) {
            m_threadPool.create_thread([this]() { this->run(); });
