const axios = require('axios');
const _ = require('lodash');
const { promisify } = require('util');
const { PerformanceObserver, recording } = require('web-performance-api');

// Mock external API service response delay function.
function delayApi(url) {
  return new Promise((resolve) => setTimeout(() => resolve({ data: url }), 1000));
}

class Reducer {
  constructor(reducerFunction, concurrency = 4) {
    this.reducerFunction = reducerFunction;
    this.concurrency = concurrency;
  }

  async processArray(array) {
    const tasks = _.chunk(array, this.concurrency).map((chunk) =>
      Promise.all(chunk.map((element) => this.getAccumulatedValue(element)))
    );

    // Using reduce to wait for all chunks' results and combine them using the reducer function.
    return tasks.reduce((acc, cur) => acc.then((prev) => prev.concat(cur)), Promise.resolve([]));
  }

  async getAccumulatedValue(element) {
    try {
      const response = await axios.get(`http://example.com/api/delay/${element}`);
      const value = this.reducerFunction(response.data, this.accumulator);
      this.accumulator = value;
      return value;
    } catch (error) {
      console.error(`Error processing element ${element}:`, error);
      throw error;
    }
  }
}

// Sample reducer function for addition.
function add(acc, val) {
  return acc + val;
}

async function main() {
  // Performance metrics tracking.
  const observer = new PerformanceObserver((list) => {
    list.getEntries().forEach((entry) => console.log(`${entry.name}: ${entry.duration}`));
  });
  recording.start();

  const array = Array(100000).fill(0).map((_, i) => i);
  const reducer = new Reducer(add, 4);

  try {
    const result = await reducer.processArray(array);
    console.log(`Reduced array using concurrency of 4: ${result}`);
  } catch (error) {
    console.error('Error processing array:', error);
  } finally {
    recording.stop();
  }
}

main();
