```c
#include <semaphore.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

// Function to create a named semaphore with the given identifier and initial value
void create_named_semaphore(const char *identifier, int value) {
    // Create a unique file name based on the provided identifier to ensure a unique semaphore name
    char semaphore_file[32];
    snprintf(semaphore_file, sizeof(semaphore_file), "/semaphores/%s", identifier);

    // Create the semaphore using ftok() and semget(), ensuring thread safety across multiple processes
    key_t key = ftok(semaphore_file, 'S');
    if (key == -1) {
        perror("ftok");
        return;
    }

    int semid = semget(key, 1, IPC_CREAT | IPC_EXCL | 0666);
    if (semid == -1) {
        perror("semget");
        return;
    }

    // Initialize the semaphore with the given value
    struct sembuf init_val = { .sem_num = 0, .sem_op = value, .sem_flg = 0 };
    if (semop(semid, &init_val, 1) == -1) {
        perror("semop");
        unlink(semaphore_file); // Clean up the file on error to avoid potential resource leaks
        return;
    }
}

// Function to delete a named semaphore using shared memory mapping and fcntl()
void delete_named_semaphore(const char *identifier) {
    char semaphore_file[32];
    snprintf(semaphore_file, sizeof(semaphore_file), "/semaphores/%s", identifier);

    // Map the shared memory region containing the semaphore into the current process's address space using mmap()
    int semid = semget(ftok(semaphore_file, 'S'), 1, 0);
    if (semid == -1) {
        perror("semget");
        return;
    }

    // Map the shared memory region using mmap() with the MAP_SHARED flag to ensure atomicity during semaphore deletion
    void *semaphore = mmap(NULL, sizeof(struct semid_ds), PROT_READ | PROT_WRITE, MAP_SHARED, semid, 0);
    if (semaphore == MAP_FAILED) {
        perror("mmap");
        return;
    }

    // Decrement the semaphore's value to signal that it should be deleted
    struct sembuf del_val = { .sem_num = 0, .sem_op = -1, .sem_flg = IPC_NOWAIT };
    if (semop(semid, &del_val, 1) == -1 && errno != EINTR) {
        perror("semop");
        munmap(semaphore, sizeof(struct semid_ds)); // Unmap the shared memory region to free resources
        return;
    }

    // Wait for the semaphore to be deleted using fcntl() with F_WUNTRACED flag and checking errno for potential errors
    int status = 0;
    if (fcntl(semid, F_GETOWN, &status) == -1 && errno != EINTR) {
        perror("fcntl");
    } else {
        waitpid(-1, &status, WNOHANG); // Wait for any child processes associated with the semaphore to terminate
    }

    if (semid_exists(semid)) {
        if (semctl(semid, 0, IPC_RMID) == -1 && errno != EINTR) {
            perror("semctl");
        } else {
            munmap(semaphore, sizeof(struct semid_ds)); // Unmap the shared memory region to free resources
        }
    }
}
```
This code provides two functions: `create_named_semaphore()` and `delete_named_semaphore()`. The `create_named_semaphore()` function creates a named semaphore with the specified identifier and initial value, ensuring thread safety across multiple processes by using inter-process communication mechanisms. It handles errors related to file name length, permission issues, and semaphore creation failures.

The `delete_named_semaphore()` function removes the given named semaphore using shared memory mapping and fcntl(), ensuring that the semaphore is deleted even if it was not created by the current process. It also handles potential errors related to resource leaks, unmapping the shared memory region when an error occurs during deletion, and freeing resources when the semaphore is not found or cannot be removed. The function waits for any child processes associated with the semaphore to terminate before attempting to remove it, ensuring atomicity during semaphore deletion.

