```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

static int *arr;
static size_t arrSize = 0;

void handleSignal(int signal) {
    printf("\nExiting gracefully...\n");
    free(arr);
    exit(0);
}

void readIntegers() {
    int num;

    signal(SIGINT, handleSignal); // Register the handler for SIGINT (Ctrl+C)
    while (scanf("%d", &num) == 1) {
        if (arrSize >= arrSize) {
            arr = realloc(arr, sizeof(int) * (2 * arrSize));
        }
        arr[arrSize++] = num;
    }
}

void findLargest() {
    int largest = arr[0];
    size_t i;

    for (i = 1; i < arrSize; ++i) {
        if (largest < arr[i]) {
            largest = arr[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}
```

