using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Newtonsoft.Json;
using NLog;

namespace FileAndMessageSecurityService
{
    public class FileAndMessageSecurityService
    {
        private readonly IConfiguration _configuration;
        private readonly Logger _logger = LogManager.GetCurrentClassLogger();
        private readonly ConcurrentQueue<(string Input, string HashType)> _queue;
        private readonly int _maxDegreeOfParallelism;
        private readonly bool _useExternalService;
        private readonly string _externalServiceUrl;

        public FileAndMessageSecurityService(IConfiguration configuration)
        {
            _configuration = configuration;
            _queue = new ConcurrentQueue<(string Input, string HashType)>();
            _maxDegreeOfParallelism = int.Parse(_configuration["MaxDegreeOfParallelism"]);
            _useExternalService = bool.Parse(_configuration["UseExternalService"]);
            _externalServiceUrl = _configuration["ExternalServiceUrl"];
        }

        public void Enqueue(string input, string hashType)
        {
            _queue.Enqueue((input, hashType));
        }

        public async Task RunAsync()
        {
            var tasks = new ConcurrentQueue<Task>();
            while (true)
            {
                if (_queue.TryDequeue(out var item))
                {
                    var task = Task.Run(() => ProcessItem(item));
                    tasks.Enqueue(task);

                    if (tasks.Count >= _maxDegreeOfParallelism)
                    {
                        await WaitForCompletionAndCleanup(tasks);
                    }
                }
                else
                {
                    await WaitForCompletionAndCleanup(tasks);
                    await Task.Delay(TimeSpan.FromMilliseconds(50));
                }
            }
        }

        private async Task WaitForCompletionAndCleanup(ConcurrentQueue<Task> tasks)
        {
            while (tasks.Any())
            {
                var completedTask = await tasks.Dequeue();
                if (!completedTask.IsCompletedSuccessfully)
                {
                    _logger.Error(completedTask.Exception, "Hash computation failed");
                }
            }
        }

        private string GetHashAlgorithm(string hashType)
        {
            switch (hashType)
            {
                case "MD5":
                    return HashAlgorithmName.MD5;
                case "SHA-256":
                    return HashAlgorithmName.SHA256;
                case "HMAC-SHA256":
                    return HashAlgorithmName.HMACSHA256;
                default:
                    throw new ArgumentException("Invalid hash type");
            }
        }

        private string ProcessItem((string Input, string HashType) item)
        {
            var algorithm = GetHashAlgorithm(item.HashType);
            if (_useExternalService && !string.IsNullOrEmpty(_externalServiceUrl))
            {
                // Implement call to external service API for computation
            }

            if (File.Exists(item.Input))
            {
                using var fileStream = File.OpenRead(item.Input);
                return ComputeHashFromStreamAsync(algorithm, fileStream).Result;
            }

            return ComputeHashFromStringAsync(algorithm, item.Input).Result;
        }

        private async Task<string> ComputeHashFromStreamAsync(HashAlgorithmName algorithm, Stream stream)
        {
            using var hash = HashAlgorithm.Create(algorithm);
            await stream.CopyToAsync(hash.ComputeStream());
            return BitConverter.ToString(hash.Hash).Replace("-", "").ToLowerInvariant();
        }

        private async Task<string> ComputeHashFromStringAsync(HashAlgorithmName algorithm, string input)
        {
            using var hash = HashAlgorithm.Create(algorithm);
            hash.ComputeHash(Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hash.Hash).Replace("-", "").ToLowerInvariant();
        }
    }
}
