import java.util.concurrent.TimeUnit;

public class PaymentGateway {
    private static final Cache<String, Response> cache = CacheBuilder.newBuilder()
                                .expireAfterAccess(1, TimeUnit.HOURS)
                                .maximumSize(1000)
                                .build();

    private static final RateLimiter rateLimiter = RateLimiter.create(1.0); // Adjust this value according to your API rate limit

    public Response processPayment(String paymentMethod, String currency, TransactionRequest request) {
        if (!rateLimiter.tryAcquire()) {
            // Log the retry due to rate limiting
            logRateLimitRetry();
            return Response.newBuilder()
                            .header("Content-Type", "text/plain")
                            .body(Body.create(MediaType.get("text/plain"), "Too many requests, please try again later"))
                            .build();
        }

        String cacheKey = buildCacheKey(paymentMethod, currency);
        Response cachedResponse = cache.getIfPresent(cacheKey);
        if (cachedResponse != null) {
            // Log cache hit
            logCacheHit(cacheKey);
            return cachedResponse;
        }

        OkHttpClient client = new OkHttpClient();
        RequestBody requestBody = buildRequestBody(paymentMethod, currency, request);
        Request requestToGateway = new Request.Builder()
                                .url("https://your-payment-gateway-api.com") // Replace with your payment gateway API URL
                                .post(requestBody)
                                .build();

        long startTime = System.currentTimeMillis();
        try {
            Response response = client.newCall(requestToGateway).execute();
            if (response.isSuccessful()) {
                // Log transaction success and save to cache
                logTransactionSuccess(cacheKey);
                cache.put(cacheKey, response);
                return response;
            } else {
                // Log transaction failure reason
                String errorMessage = "Transaction failed with status code: " + response.code();
                logTransactionError(errorMessage);
                throw new RuntimeException(errorMessage);
            }
        } catch (IOException | InterruptedException | ExecutionException e) {
            // Log network errors and add retry logic as needed
            logNetworkError(e);
            throw e;
        } finally {
            long elapsedTime = System.currentTimeMillis() - startTime;
            // Log transaction latency statistics
            logLatencyStats(elapsedTime);
        }
    }

