```python
import os
import shutil
import time
import subprocess
from multiprocessing import Semaphore
import pickle
import requests
import logging
from time import strftime
from threading import Thread

class Report:
    def __init__(self, script_name, execution_time):
        self.script_name = script_name
        self.execution_time = execution_time

def get_python_scripts(directory):
    python_scripts = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith(".py"):
                python_scripts.append((root, file))
    return python_scripts

def measure_disk_usage(path):
    return shutil.disk_usage(path)['used']

def execute_script(script_path):
    start_time = time.time()
    try:
        subprocess.run(f'python {script_path}', capture_output=True, text=True)
        execution_time = time.time() - start_time
    except Exception as e:
        return Report(script_path, None), f"Error executing script '{script_path}': {str(e)}"
    else:
        return Report(script_path, execution_time)

def serialize_report(reports):
    with open('summary_report.bin', 'wb') as file:
        pickle.dump(reports, file)

def send_to_api(data):
    try:
        response = requests.post("YOUR_API_URL", json=data)
        if response.status_code != 200:
            logging.error(f"Failed to send data to API: {response.text}")
    except Exception as e:
        logging.error(f"Error sending data to API: {str(e)}")

def process_script(script):
    report, message = execute_script(*script)
    if report:
        send_to_api({
            "disk_usage": measure_disk_usage(*script),
            "execution_time": report.execution_time,
            "script_names": [report.script_name]
        })
    else:
        logging.warning(message)

def main(directory):
    if os.path.exists('summary_report.bin'):
        with open('summary_report.bin', 'rb') as file:
            reports = pickle.load(file)
    else:
        reports = []

    semaphore = Semaphore(3)
    python_scripts = get_python_scripts(directory)
    for script in python_scripts:
        semaphore.acquire()
        Thread(target=process_script, args=(script,)).start()

    for _ in range(len(python_scripts)):
        semaphore.release()

    if not reports:
        logging.info("No Python scripts found in the provided directory.")
    else:
        serialize_report(reports)

if __name__ == "__main__":
    main("YOUR_DIRECTORY_PATH")
```

