```javascript
const AWS = require('aws-sdk');
const axios = require('axios');
const { max } = require('lodash');

class AsyncUploader {
  constructor(options) {
    this.s3 = new AWS.S3({ region: options.region });
    this.bucketName = options.bucketName;
    this.partSize = options.partSize || 5 * 1024 * 1024; // 5MB chunks
    this.maxRetries = options.maxRetries || 3;
    this.url = options.url;
    this.progressCallback = options.progressCallback;
    this.key = undefined;
  }

  async upload() {
    try {
      const response = await axios({ url: this.url, responseType: 'stream' });
      const { headers } = response;
      const contentLength = headers['content-length'];
      this.key = `file-${Date.now()}-${Math.floor(Math.random() * 1e6)}`;

      const uploadParams = {
        Bucket: this.bucketName,
        Key: this.key,
        ContentType: headers['content-type'],
        ACL: 'private',
      };

      const s3Stream = this.s3.getSignedUrl('putObject', uploadParams);
      let totalUploadedBytes = 0;
      let currentBuffer = Buffer.alloc(this.partSize);

      for await (const chunk of response.data) {
        const bytesWritten = currentBuffer.write(chunk, 'binary');
        totalUploadedBytes += bytesWritten;
        this.progressCallback && this.progressCallback(totalUploadedBytes, contentLength);

        if (bytesWritten < this.partSize) break;
        currentBuffer = currentBuffer.slice(0, bytesWritten);

        const uploadPartParams = {
          Bucket: this.bucketName,
          Key: this.key,
          PartNumber: Math.ceil(totalUploadedBytes / this.partSize) + 1,
          Body: currentBuffer,
        };

        await this.uploadPart(uploadPartParams);
        currentBuffer = Buffer.alloc(this.partSize);
      }

      if (totalUploadedBytes < contentLength) {
        await this.uploadPart({
          Bucket: this.bucketName,
          Key: this.key,
          PartNumber: max([Math.ceil(totalUploadedBytes / this.partSize), 1]) + 1,
          Body: currentBuffer,
        });
      }
    } catch (error) {
      if (this.maxRetries > 0 && error.response && error.response.status === 503) {
        await new Promise(resolve => setTimeout(resolve, 1000 * Math.min(this.maxRetries - 1, 4)));
        return this.upload(); // Retry if 503 (Service Unavailable) status code is returned and retry limit is not exceeded
      }

      throw error;
    }
  }

  async uploadPart(params) {
    try {
      await this.s3.uploadPart(params).promise();
    } catch (error) {
      if (this.maxRetries > 0 && error.response && error.response.status === 503) {
        await new Promise(resolve => setTimeout(resolve, 1000 * Math.min(this.maxRetries - 1, 4)));
        return this.uploadPart(params); // Retry if 503 (Service Unavailable) status code is returned and retry limit is not exceeded
      }

      throw error;
    }
  }
}
```

