class Aggregator:
    def __init__(self, s3_bucket, initial_params, agg_func):
        self.s3 = boto3.client('s3')
        self.queue = queue.Queue()
        self.params = initial_params
        self.agg_func = agg_func
        self.lock = threading.Lock()
        self.rate_limiter = RateLimiter(10)
        self._load_historical_data(s3_bucket)

    def _load_historical_data(self, s3_bucket):
        try:
            historical_data = self.s3.get_object(Bucket=s3_bucket, Key='aggregation_params.json')['Body'].read().decode('utf-8')
            self.params = json.loads(historical_data)
        except Exception as e:
            print(f'Error loading historical data: {e}')

    def enqueue(self, sensor_data):
        if not self.rate_limiter.acquire():
            print('Rate limit exceeded, queueing data')
            return
        self.queue.put(sensor_data)

    def run(self):
        threading.Thread(target=self._process_data).start()

    @staticmethod
    @wraps(_process_data)
    def _process_data():
        while True:
            if not self.queue.empty():
                data = self.queue.get()
                with self.lock:
                    aggregated_result = self.agg_func(self.params, data)
                    self.params = self._update_params(self.params, data)
                    self._store_results(aggregated_result)

