        except Exception as e:
            print(f'Error storing results: {e}')

class RateLimiter:
    def __init__(self, max_calls):
        self.max_calls = max_calls
        self.semaphore = threading.Semaphore(value=max_calls)

    def acquire(self):
        return self.semaphore.acquire(block=True, timeout=1)

