                    temperature = reading.temperature
                    status = reading.status
                readings.append(TemperatureSensorReading(sensor['id'], temperature, datetime.datetime.now(), status))
        else:
            # Zone not found, log error and return an empty list
            print(f"Zone {zone_id} not found")
            readings = []
        return readings

