    public void handleRequest(JsonObject request) {
        try {
            long requestId = System.currentTimeMillis();
            logRequest(requestId, "Start", request);

            // Retrieve the factory function for the subclass from the registry
            Function<JsonObject, JsonObject> factoryFunction = registry.get(request.getString("id"));

            // Deserialize the nested JSON structures using Jackson and the custom decoder
            JsonObject objectToProcess = Json.createReader(new StringReader(request.getString("data")))
                    .readObject().getJsonObject("data");

            // Create an instance of the subclass using the factory function
            JsonObject result = factoryFunction.apply(objectToProcess);

            // Process the instance as needed, then serialize and return the result
            JsonObject response = Json.createObjectBuilder()
                    .add("id", requestId)
                    .add("timestamp", System.currentTimeMillis())
                    .add("result", result)
                    .build();

            logRequest(requestId, "End", response);
            return response.toString();
        } catch (IllegalArgumentException | JsonProcessingException e) {
            // Handle invalid JSON and other errors here
            logError(e);
            return Json.createObjectBuilder()
                    .add("error", e.getMessage())
                    .build()
                    .toString();
        }
    }

